class ConfigurationSeamTests(ScriptTestCase):
    """docs/runtime.md, "The configuration seam".

    One definition of what runtime.yaml means, on the far side of a process
    boundary. These tests exist because the alternative -- a second reader in
    the scripts, with its own defaults -- shipped once and disagreed with the
    gateway on a valid file.
    """

    def test_the_gateway_is_what_loads_the_configuration(self):
        # The loader's own words reach the terminal unchanged. Nothing here
        # can produce this sentence: it exists only inside the loader.
        self.write_config()
        result = self.run_script(
            "status.ps1", env=self.script_env(LC_STUB_CONFIG_MODE="crash"))
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("the loader refused this file", output)
        self.assert_no_stack_trace(output)

    def test_a_key_only_the_loader_knows_about_is_still_enforced(self):
        # An unknown key is rejected by the loader. A second reader in the
        # scripts would wave it through -- which is exactly how `manage_comfu:
        # true` becomes a mode nobody chose.
        self.write_config()
        text = self.config_path.read_text(encoding="utf-8")
        self.config_path.write_text("runtme:\n  manage_comfy: true\n" + text, encoding="utf-8")
        result = self.run_script("status.ps1")
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("unknown key", output)
        self.assertIn("runtme", output)

    def test_a_setting_only_the_loader_requires_is_still_required(self):
        # identity.display_name is required by the gateway and was optional in
        # the reader the scripts used to carry. The scripts have no opinion now.
        self.write_config()
        text = self.config_path.read_text(encoding="utf-8")
        blanked = text.replace(
            'identity:\n  display_name: "Test PC"\n',
            'identity:\n  display_name: ""\n')
        self.assertNotEqual(text, blanked)
        self.config_path.write_text(blanked, encoding="utf-8")
        result = self.run_script("status.ps1")
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("identity.display_name", output)

    def test_every_field_the_scripts_read_is_in_the_document(self):
        """The seam is a document shape, and both sides must agree on it.

        This is the check that was missing when the scripts consumed
        `manage_comfy` while the gateway published `runtime.manage_comfy`: a
        valid configuration was rejected, and no test noticed because no test
        ever ran the gateway's own loader.
        """
        self.write_config()
        result = subprocess.run(
            [sys.executable, "-m", "localcanvas_gateway", "config",
             "--config", str(self.config_path)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120, env=self.script_env(), cwd=str(REPO),
        )
        self.assertEqual(0, result.returncode, result.stdout + result.stderr)
        document = json.loads(result.stdout)

        wanted = set()
        for path in sorted(list(SCRIPTS.glob("*.ps1")) + list((SCRIPTS / "lib").glob("*.ps1"))):
            text = path.read_text(encoding="utf-8-sig")
            wanted.update(re.findall(r"Get-LcConfigValue\s+-Document\s+\$\w+\s+-Path\s+'([^']+)'", text))
        self.assertTrue(wanted, "no configuration fields are read at all")

        missing = []
        for dotted in sorted(wanted):
            node = document
            for segment in dotted.split("."):
                if not isinstance(node, dict) or segment not in node:
                    missing.append(dotted)
                    break
                node = node[segment]
        self.assertEqual(
            [], missing,
            "the scripts read fields the configuration document does not carry: "
            "{}\nDocument keys: {}".format(missing, sorted(document)))

    def test_a_document_missing_a_field_says_the_two_halves_are_out_of_step(self):
        """The second line of defence, behind the pinned document shape.

        If the gateway ever publishes a document without a field the scripts
        read, they must say so plainly rather than let a null travel into a
        command line.
        """
        self.write_config()
        for dropped in ("comfy.base_url", "runtime.manage_comfy"):
            with self.subTest(field=dropped):
                result = self.run_script(
                    "status.ps1", env=self.script_env(LC_STUB_CONFIG_DROP=dropped))
                output = self.output_of(result)
                self.assertEqual(2, result.returncode, output)
                self.assertIn(dropped, output)
                self.assertIn("out of step", output)
                self.assertIn("setup.ps1", output)
                self.assert_no_stack_trace(output)

    def test_a_document_missing_a_field_stops_start_before_it_launches_anything(self):
        self.write_config()
        result = self.run_script(
            "start.ps1", env=self.script_env(LC_STUB_CONFIG_DROP="comfy.base_url"))
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("out of step", output)
        self.assertFalse(self.comfy_marker.exists())
        self.assertFalse(self.gateway_marker.exists())
        self.assert_no_stack_trace(output)

    def test_a_missing_gateway_is_a_failure_and_never_a_fallback(self):
        self.write_config()
        env = self.script_env()
        env["PYTHONPATH"] = str(self.workspace)  # no localcanvas_gateway anywhere
        result = self.run_script("start.ps1", env=env)
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("gateway is not installed", output)
        self.assertIn("setup.ps1", output)
        self.assert_no_stack_trace(output)
        # No second reader picked up the slack, and nothing was launched.
        self.assertFalse(self.comfy_marker.exists())
        self.assertFalse(self.gateway_marker.exists())
        self.assertIsNone(self.read_pid_file("comfy"))

    def test_a_gateway_without_the_config_command_says_so(self):
        self.write_config()
        result = self.run_script(
            "start.ps1", env=self.script_env(LC_STUB_CONFIG_MODE="absent"))
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("does not provide the configuration command", output)
        self.assertIn("setup.ps1", output)
        self.assertFalse(self.comfy_marker.exists())

    def test_a_document_that_is_not_json_is_reported(self):
        self.write_config()
        result = self.run_script(
            "start.ps1", env=self.script_env(LC_STUB_CONFIG_MODE="garbage"))
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("did not print a JSON document", output)
        self.assert_no_stack_trace(output)


class EndpointOwnershipTests(ScriptTestCase):
    """docs/runtime.md, "Who owns the endpoint and the pairing block"."""

    def gateway_launch_record(self):
        self.assertTrue(self.gateway_marker.exists(), "the gateway was never launched")
        return self.gateway_marker.read_text(encoding="utf-8", errors="replace")

    def test_the_endpoint_is_decided_here_and_handed_down(self):
        self.write_config(gateway_host="0.0.0.0")
        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)

        printed = re.search(r"Endpoint:\s*\n\s*(\S+)", output)
        self.assertIsNotNone(printed, output)
        endpoint = printed.group(1)
        # The gateway was told exactly the endpoint the block printed: it never
        # computes a second answer of its own.
        self.assertIn("endpoint=" + endpoint, self.gateway_launch_record())

    def test_the_pairing_block_is_printed_once(self):
        self.write_config()
        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertEqual(
            1, output.count("localcanvas://connect"),
            "the pairing payload appeared more than once:\n" + output)
        self.assertIn("no_qr=True", self.gateway_launch_record())

    def test_a_qr_failure_is_reported_and_never_faked(self):
        self.write_config()
        result = self.run_script("start.ps1", env=self.script_env(LC_STUB_QR_MODE="fail"))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("QR pairing:", output)
        self.assertIn("unavailable", output)
        # No localcanvas:// URL was invented in place of the one the gateway
        # would not produce.
        self.assertNotIn("localcanvas://", output)


class ManagedModeTests(ScriptTestCase):
    def test_reuses_an_already_healthy_backend(self):
        self.start_backend_stub()
        self.write_config()

        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("reusing it", output)
        self.assertIn("not started by LocalCanvas", output)

        # The tripwire: start.ps1 must not have launched a second backend.
        self.assertFalse(
            self.comfy_marker.exists(),
            "start.ps1 launched a second ComfyUI even though one was healthy",
        )
        # And it must not have claimed ownership of someone else's process.
        self.assertIsNone(self.read_pid_file("comfy"))
        self.assertIsNotNone(self.read_pid_file("gateway"))

    def test_launches_and_waits_on_a_real_probe(self):
        # Unhealthy for a moment, then healthy: only a probe can tell.
        self.write_config(
            comfy_extra_args=[
                "--port", str(self.comfy_port),
                "--launch-marker", str(self.comfy_marker),
                "--ready-after", "1.5",
            ]
        )
        started = time.monotonic()
        result = self.run_script("start.ps1")
        elapsed = time.monotonic() - started
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("Starting ComfyUI...", output)
        self.assertIn(f"ComfyUI ready at http://127.0.0.1:{self.comfy_port}", output)
        self.assertTrue(self.comfy_marker.exists(), "ComfyUI was never launched")

        # It came back as soon as the probe succeeded, not after the timeout.
        self.assertLess(elapsed, 25, "start.ps1 waited far longer than readiness took")

        record = self.read_pid_file("comfy")
        self.assertIsNotNone(record, "no ownership record for a ComfyUI we started")
        # Identity evidence beside the PID -- a PID alone is not proof.
        for key in ("pid", "start_time", "image_path"):
            self.assertIn(key, record)
            self.assertTrue(record[key], f"{key} was recorded empty")

    def test_startup_output_and_endpoint_block(self):
        self.write_config(gateway_host="0.0.0.0")
        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)

        self.assertIn("LocalCanvas", output)
        self.assertIn("[INFO] Configuration loaded", output)
        self.assertIn("[ OK ] Gateway ready", output)
        self.assertIn("[ OK ] LocalCanvas is ready", output)
        for label in ("Endpoint:", "Discovery:", "QR pairing:", "ComfyUI:"):
            self.assertIn(label, output)
        # The gateway advertises and renders; start.ps1 reports what it did.
        self.assertIn("mDNS active", output)
        self.assertIn("localcanvas://connect?endpoint=", output)
        self.assertIn("localhost only", output)
        self.assert_no_stack_trace(output)

    def test_mdns_failure_is_a_warning_not_a_startup_failure(self):
        self.write_config()
        result = self.run_script("start.ps1", env=self.script_env(LC_STUB_GATEWAY_MDNS="fail"))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("[ OK ] LocalCanvas is ready", output)
        self.assertIn("mDNS unavailable", output)
        self.assertIn("QR pairing", output)
        self.assertIn("localcanvas://connect?endpoint=", output)

    def test_readiness_timeout_fails_and_starts_no_gateway(self):
        self.write_config(
            comfy_timeout=3,
            comfy_extra_args=[
                "--port", str(self.comfy_port),
                "--launch-marker", str(self.comfy_marker),
                "--never-ready",
            ],
        )
        result = self.run_script("start.ps1")
        output = self.output_of(result)

        self.assertEqual(3, result.returncode, output)
        self.assertIn("ComfyUI did not become ready within 3s", output)
        self.assertIn(f"Probed: http://127.0.0.1:{self.comfy_port}/system_stats", output)
        self.assertIn("No gateway was started.", output)
        self.assert_no_stack_trace(output)

        # The gateway must not have been started, in any sense of the word.
        self.assertFalse(self.gateway_marker.exists(), "the gateway was launched anyway")
        self.assertIsNone(self.read_pid_file("gateway"))
        self.assertFalse(http_ok(self.gateway_health_url))

    def test_gateway_readiness_timeout_is_reported_and_cleaned_up(self):
        self.start_backend_stub()
        self.write_config(gateway_timeout=3)
        result = self.run_script(
            "start.ps1", env=self.script_env(LC_STUB_GATEWAY_HANG="1")
        )
        output = self.output_of(result)
        self.assertEqual(5, result.returncode, output)
        self.assertIn("gateway did not become ready within 3s", output)
        self.assertIn(f"Probed: http://127.0.0.1:{self.gateway_port}/api/v1/info", output)
        self.assertIsNone(self.read_pid_file("gateway"))
        self.assert_no_stack_trace(output)


# ==========================================================================
# The streams start.ps1 redirects (T-0085)
# ==========================================================================

# The character measured on the test workstation, written as a code point so that
# this file's own encoding cannot be what decides anything below.
UNENCODABLE = "○"

# What the launcher declares for a child it redirects. Named so a failing test
# can say what it expected rather than only that something was not utf-8.
DECLARED_STREAM_ENCODING = "utf-8"

# A non-UTF-8 code page that has no U+25CB: the one measured failing here.
NON_UTF8_ENCODING = "cp1251"

_STREAM_HAZARD = None


def stream_encoding_hazard():
    """What a redirected child of THIS machine does with U+25CB.

    Returns {encoding, died, detail}: the codec a child falls back to when
    nothing declares one for it, whether writing the character then ends the
    process, and what it said while dying.

    Measured by running one, never assumed. The whole of T-0085 is a fact
    about this machine's ANSI code page: a suite that hard-codes the answer
    here passes on the machine it was written on and nowhere else, and a
    guard that cannot fail where it runs is not a guard at all. The tests
    that need the hazard skip loudly when this says there is none.
    """
    global _STREAM_HAZARD
    if _STREAM_HAZARD is not None:
        return _STREAM_HAZARD
    workspace = make_temporary_directory(prefix="lc t0085 probe ")
    try:
        out_path = workspace / "out.log"
        err_path = workspace / "err.log"
        # Nothing declared anywhere: exactly the scenario the card names.
        env = {name: value for name, value in os.environ.items()
               if name not in ("PYTHONIOENCODING", "PYTHONUTF8")}
        with open(out_path, "wb") as out_handle, open(err_path, "wb") as err_handle:
            subprocess.run(
                [sys.executable, str(STUB_COMFY), "--port", str(free_port()),
                 "--report-streams", "--log-unencodable", "both", "--exit-after-log"],
                stdout=out_handle, stderr=err_handle, env=env, timeout=120,
            )
        report = out_path.read_text(encoding="utf-8", errors="replace")
        detail = err_path.read_text(encoding="utf-8", errors="replace")
        found = re.search(r"stdout=(\S+)", report)
        _STREAM_HAZARD = {
            "encoding": found.group(1) if found else "unknown",
            # The name of the exception, verbatim, rather than an exit code:
            # the stub's own deliberate exit is 1 and so is a crash.
            "died": "UnicodeEncodeError" in detail,
            "detail": detail.strip().splitlines()[-1:] or [""],
        }
    finally:
        shutil.rmtree(workspace, ignore_errors=True)
    return _STREAM_HAZARD


def codec_refuses_the_character(name):
    """True / False / None: refuses it, encodes it, or is not on this machine."""
    try:
        codecs.lookup(name)
    except LookupError:
        return None
    try:
        UNENCODABLE.encode(name)
    except UnicodeEncodeError:
        return True
    return False


class ChildStreamEncodingTests(ScriptTestCase):
    """T-0085: a stream start.ps1 redirected is a stream start.ps1 declares.

    Every test here drives the real managed-start path -- ``scripts\\start.ps1``
    itself, launching real children into the real log files under the runtime
    directory. Nothing below calls an encoding helper on its own: what is under
    test is what a *launched process* was given, which is a property of the
    launch and of nothing else.

    The encoding a child would otherwise fall back to is set deliberately for
    each case rather than inherited from whatever shell started this suite --
    a result that depends on which terminal you ran it from is not a result.
    """

    # -- the lever these tests pull ----------------------------------------

    def start_env(self, declared=None, **extra):
        """The environment start.ps1 is given, with the fallback decided here.

        ``declared=None`` leaves nothing at all in the launching process's
        environment, so a child falls back to the machine's own ANSI code
        page -- the exact scenario in the card. A name puts that codec there
        instead, which is what the child would inherit if LocalCanvas declared
        nothing for it.
        """
        env = self.script_env(**extra)
        for name in ("PYTHONIOENCODING", "PYTHONUTF8"):
            env.pop(name, None)
        if declared is not None:
            env["PYTHONIOENCODING"] = declared
        return env

    def noisy_comfy_args(self, where="both", exit_after=False):
        args = ["--port", str(self.comfy_port),
                "--launch-marker", str(self.comfy_marker),
                "--report-streams", "--log-unencodable", where]
        if exit_after:
            args.append("--exit-after-log")
        return args

    def log_bytes(self, name):
        path = self.runtime_dir / name
        self.assertTrue(path.exists(), "{} was never written".format(name))
        return path.read_bytes()

    def log_text(self, name):
        # Strict on purpose: a log that is not the encoding it was declared to
        # be must fail here rather than be repaired by a replacement character.
        return self.log_bytes(name).decode("utf-8")

    def require_the_hazard(self):
        hazard = stream_encoding_hazard()
        if not hazard["died"]:
            self.skipTest(
                "this machine's redirected children encode with {!r}, which can "
                "represent U+25CB, so the failure this test exists to catch "
                "cannot be made to happen here".format(hazard["encoding"]))
        return hazard

    # -- the failure, and the fix ------------------------------------------

    def test_a_child_logging_an_unencodable_character_reaches_ready(self):
        """The card's scenario: nothing declared anywhere in the parent."""
        self.write_config(comfy_extra_args=self.noisy_comfy_args())
        result = self.run_script("start.ps1", env=self.start_env())
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("ComfyUI ready at", output)
        self.assert_no_stack_trace(output)

        # The character, verbatim and as the bytes of the encoding declared
        # for it -- not merely "some non-ASCII arrived".
        self.assertIn("node loaded {}".format(UNENCODABLE).encode("utf-8"),
                      self.log_bytes("comfy.out.log"))
        self.assertIn("node warning {}".format(UNENCODABLE).encode("utf-8"),
                      self.log_bytes("comfy.err.log"))
        self.assertIn("stdout={}".format(DECLARED_STREAM_ENCODING),
                      self.log_text("comfy.out.log"))
        self.assertIn("stderr={}".format(DECLARED_STREAM_ENCODING),
                      self.log_text("comfy.out.log"))

    def test_without_the_declaration_the_same_child_ends_the_launch(self):
        """The control: proof the test above is testing something.

        Run against a copy of the scripts with the one declaration taken out
        of it. The copy is a copy because proving
        what a guard does must never be a way to remove it from the tree the
        rest of the suite is running against.
        """
        hazard = self.require_the_hazard()
        scripts = self.copy_scripts_without_the_declaration()
        self.write_config(comfy_timeout=15, comfy_extra_args=self.noisy_comfy_args())

        result = self.run_script("start.ps1", env=self.start_env(), script_dir=scripts)
        output = self.output_of(result)

        self.assertEqual(3, result.returncode, output)
        self.assertIn("ComfyUI did not become ready", output)
        self.assertIn("exited before it became ready", output)
        # It really was launched, and it really was the encoding that killed
        # it: the child said what it was given before it died on it.
        self.assertTrue(self.comfy_marker.exists(), "ComfyUI was never launched at all")
        self.assertIn("stdout={}".format(hazard["encoding"]),
                      self.log_text("comfy.out.log"))
        self.assertNotIn(UNENCODABLE.encode("utf-8"), self.log_bytes("comfy.out.log"))
        self.assertIn("UnicodeEncodeError", self.log_text("comfy.err.log"))
        # No gateway follows a ComfyUI that never came up.
        self.assertFalse(self.gateway_marker.exists())

    def copy_scripts_without_the_declaration(self):
        """A copy of the scripts that declares no encoding for its children.

        The mutation is the removal of one assignment, and it names no path,
        no interpreter and nothing outside this test's own workspace.
        """
        copied = self.workspace / "scripts without the declaration"
        shutil.copytree(SCRIPTS, copied, ignore=shutil.ignore_patterns("tests"))
        library = copied / "lib" / "Common.ps1"
        original = library.read_text(encoding="utf-8-sig")
        stripped, count = re.subn(
            r"^\s*\$map\['PYTHONIOENCODING'\].*$",
            "    # Removed by the test suite: nothing is declared for the child.",
            original, count=1, flags=re.MULTILINE)
        self.assertEqual(
            1, count,
            "Common.ps1 no longer declares the child's stream encoding where "
            "this test knows to remove it")
        self.assertIsNone(
            re.search(r"\$map\['PYTHONIOENCODING'\]", stripped),
            "the copy still declares an encoding for its children")
        library.write_text(stripped, encoding="utf-8")
        return copied

    # -- the two code pages, each set deliberately -------------------------

    def test_a_non_utf8_encoding_in_the_parent_never_reaches_the_child(self):
        refuses = codec_refuses_the_character(NON_UTF8_ENCODING)
        if refuses is None:
            self.skipTest(
                "{} is not available on this interpreter, so the non-UTF-8 case "
                "cannot be set deliberately here".format(NON_UTF8_ENCODING))
        if not refuses:
            self.skipTest(
                "{} can represent U+25CB on this interpreter, so it cannot stand "
                "in for a code page that cannot".format(NON_UTF8_ENCODING))

        self.write_config(comfy_extra_args=self.noisy_comfy_args())
        result = self.run_script(
            "start.ps1", env=self.start_env(declared=NON_UTF8_ENCODING))
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("ComfyUI ready at", output)
        text = self.log_text("comfy.out.log")
        self.assertIn("stdout={}".format(DECLARED_STREAM_ENCODING), text)
        self.assertNotIn(NON_UTF8_ENCODING, text)
        # What the child inherited is still visible, so this is not passing
        # because the variable never got there.
        self.assertIn("PYTHONIOENCODING='{}'".format(DECLARED_STREAM_ENCODING), text)
        self.assertIn("node loaded {}".format(UNENCODABLE).encode("utf-8"),
                      self.log_bytes("comfy.out.log"))

    def test_a_utf8_encoding_in_the_parent_makes_no_difference(self):
        self.write_config(comfy_extra_args=self.noisy_comfy_args())
        result = self.run_script(
            "start.ps1", env=self.start_env(declared=DECLARED_STREAM_ENCODING))
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("ComfyUI ready at", output)
        self.assertIn("stdout={}".format(DECLARED_STREAM_ENCODING),
                      self.log_text("comfy.out.log"))
        self.assertIn("node loaded {}".format(UNENCODABLE).encode("utf-8"),
                      self.log_bytes("comfy.out.log"))

    # -- both children, not only the one that failed -----------------------

    def test_the_gateway_is_declared_the_same_way_as_comfyui(self):
        self.start_backend_stub()
        self.write_config()
        result = self.run_script("start.ps1", env=self.start_env(
            LC_STUB_GATEWAY_STREAMS="1", LC_STUB_GATEWAY_UNENCODABLE="1"))
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("[ OK ] Gateway ready", output)
        self.assertIn("stdout={}".format(DECLARED_STREAM_ENCODING),
                      self.log_text("gateway.out.log"))
        self.assertIn("starting {}".format(UNENCODABLE).encode("utf-8"),
                      self.log_bytes("gateway.out.log"))
        self.assertIn("starting {}".format(UNENCODABLE).encode("utf-8"),
                      self.log_bytes("gateway.err.log"))

    # -- and nothing but the child -----------------------------------------

    def drive_start_in_process(self, env=None):
        """Run start.ps1 from a PowerShell that then reports on itself.

        The launching process is the one place the "only the child" property
        can be observed from: an environment variable set in it dies with it,
        so a run driven as a black box cannot tell a declaration scoped to the
        child from one made in the parent and left there. This is still the
        real managed-start path -- the real script, the real children -- with
        a caller that says what its own state was before and after.
        """
        report = self.workspace / "launcher state.json"
        capture = self.workspace / "start output.txt"
        driver = self.workspace / "drive start.ps1"
        driver.write_text(
            "[CmdletBinding()] param([string]$Config, [string]$PythonExe)\n"
            "function Get-DriverState {\n"
            "    $outputCp = -1; $inputCp = -1\n"
            "    try { $outputCp = [Console]::OutputEncoding.CodePage } catch { }\n"
            "    try { $inputCp = [Console]::InputEncoding.CodePage } catch { }\n"
            "    $names = @()\n"
            "    foreach ($item in [System.Environment]::GetEnvironmentVariables()"
            ".GetEnumerator()) {\n"
            "        $names += ('{0}={1}' -f $item.Key, $item.Value)\n"
            "    }\n"
            "    return [pscustomobject]@{\n"
            "        ConsoleOutputCodePage = $outputCp\n"
            "        ConsoleInputCodePage = $inputCp\n"
            "        Environment = @($names | Sort-Object)\n"
            "    }\n"
            "}\n"
            "$before = Get-DriverState\n"
            # Captured rather than passed through: what start.ps1 printed must
            # reach this test in the encoding start.ps1 wrote it in, not in
            # whatever code page the console between us happens to be set to.
            # Which console this is is not ours to change (T-0037).
            "$text = (& " + powershell_literal(SCRIPTS / "start.ps1")
            + " -Config $Config -PythonExe $PythonExe *>&1 | Out-String -Width 500)\n"
            "$code = $LASTEXITCODE\n"
            "$after = Get-DriverState\n"
            "Set-Content -Encoding UTF8 -Value $text -LiteralPath "
            + powershell_literal(capture) + "\n"
            "[pscustomobject]@{ ExitCode = $code; Before = $before; After = $after } |"
            " ConvertTo-Json -Depth 5 | Set-Content -Encoding UTF8 -LiteralPath "
            + powershell_literal(report) + "\n",
            encoding="utf-8")
        result = self.run_script("drive start.ps1", env=env, script_dir=self.workspace)
        self.assertTrue(
            report.exists(),
            "the driver never wrote its report: " + self.output_of(result))
        state = json.loads(report.read_text(encoding="utf-8-sig"))
        state["Output"] = capture.read_text(encoding="utf-8-sig")
        return state

    def test_the_declaration_reaches_the_child_and_nothing_else(self):
        self.write_config(comfy_extra_args=self.noisy_comfy_args())
        state = self.drive_start_in_process(env=self.start_env(
            LC_STUB_GATEWAY_STREAMS="1"))

        self.assertEqual(0, state["ExitCode"], state["Output"])
        # First, that there was something to find: the declaration did reach
        # both children. An absence test that never proves the thing was
        # available proves nothing.
        for log in ("comfy.out.log", "gateway.out.log"):
            self.assertIn("stdout={}".format(DECLARED_STREAM_ENCODING),
                          self.log_text(log), log)

        # And then that it reached nothing else. The whole environment, not
        # one name: anything the launch left behind shows up here.
        self.assertEqual(
            state["Before"]["Environment"], state["After"]["Environment"],
            "starting the runtime changed the launching process's environment")
        self.assertEqual(
            [], [entry for entry in state["After"]["Environment"]
                 if entry.upper().startswith(("PYTHONIOENCODING=", "PYTHONUTF8="))],
            "the launching process was left carrying the child's declaration")
        # Nothing was written to a console code page either -- neither by the
        # launch nor by anything it called.
        self.assertEqual(state["Before"]["ConsoleOutputCodePage"],
                         state["After"]["ConsoleOutputCodePage"],
                         "the console's output code page was changed")
        self.assertEqual(state["Before"]["ConsoleInputCodePage"],
                         state["After"]["ConsoleInputCodePage"],
                         "the console's input code page was changed")

    def test_the_failure_report_carries_the_character_the_log_holds(self):
        """A log we declared UTF-8 is a log we read back as UTF-8.

        The tail of the child's error log is what start.ps1 shows a user whose
        ComfyUI died. Read in the machine's ANSI code page -- which is what
        Get-Content defaults to under Windows PowerShell -- the one character
        that caused the failure turns into mojibake inside the report that is
        supposed to explain it.
        """
        self.write_config(
            comfy_timeout=15,
            comfy_extra_args=self.noisy_comfy_args(where="err", exit_after=True))
        state = self.drive_start_in_process(env=self.start_env())

        self.assertEqual(3, state["ExitCode"], state["Output"])
        self.assertIn("exited before it became ready", state["Output"])
        self.assertIn("node warning {}".format(UNENCODABLE), state["Output"])

    # -- the source, anchored to symbols that must exist -------------------

    def test_the_character_asserted_on_is_the_one_that_was_measured(self):
        """The assertions above are worth nothing if this file mis-decoded.

        U+25CB is what the traceback on the test workstation named. Comparing the
        literal in this file against its code point is the only way to know
        that what the tests look for is that character and not a lookalike.
        """
        self.assertEqual(chr(0x25CB), UNENCODABLE)
        self.assertEqual(1, len(UNENCODABLE))
        # And it is genuinely outside the code page that fails here.
        self.assertTrue(codec_refuses_the_character(NON_UTF8_ENCODING) is not False)

    def test_the_declaration_is_made_in_one_place_and_never_in_the_parent(self):
        library = (SCRIPTS / "lib" / "Common.ps1").read_text(encoding="utf-8-sig")
        body = powershell_function_body(library, "Get-LcChildEnvironment")
        self.assertIsNotNone(
            body, "Get-LcChildEnvironment is gone; this scan has nothing to anchor to")
        self.assertIn("PYTHONIOENCODING", body)

        offenders = []
        declaring = []
        for path in powershell_sources():
            for number, code, literals, raw in powershell_code_lines(
                    path.read_text(encoding="utf-8-sig")):
                where = "{}:{}: {}".format(path.name, number, raw.strip())
                # Any assignment into this process's own environment, and the
                # two ways a script could reach for a console's code page.
                if re.search(r"\$env:(PYTHONIOENCODING|PYTHONUTF8)\s*=", code, re.I):
                    offenders.append(where + " -- declares the encoding in the parent")
                if re.search(r"\[Console\]::(Output|Input)Encoding\s*=", code, re.I):
                    offenders.append(where + " -- assigns a console's encoding")
                if re.search(r"(?<![\w-])chcp(?:\.com)?(?![\w-])", code, re.I):
                    offenders.append(where + " -- changes a console's code page")
                # A variable name only ever appears as a string literal here,
                # so this half of the scan reads the line with its literals
                # intact -- the offences above are code and are read without.
                if "PYTHONIOENCODING" in literals:
                    declaring.append(where)
        self.assertEqual([], offenders, "\n".join(offenders))
        # The other half: the declaration exists, in exactly one line of code.
        # Without this the scan passes on a tree that declares nothing.
        self.assertEqual(
            1, len(declaring),
            "the child's stream encoding is declared in {} places, not one:\n{}".format(
                len(declaring), "\n".join(declaring)))

    def test_both_readers_of_a_child_log_ask_for_the_encoding_it_was_written_in(self):
        text = (SCRIPTS / "start.ps1").read_text(encoding="utf-8-sig")
        for name in ("Get-LogTail", "Get-LogText"):
            body = powershell_function_body(text, name)
            self.assertIsNotNone(
                body, "{} is gone; this scan has nothing to anchor to".format(name))
            self.assertIn("Get-Content", body, name)
            self.assertRegex(body, r"-Encoding\s+UTF8", name)

    def test_the_terminal_rendering_rule_still_asks_the_stream(self):
        """T-0037's rule is untouched: our own output adapts, never the stream.

        The two are different situations and both must keep their own answer.
        A stream we created for a child is ours to declare; a console we were
        handed is not.
        """
        sync = (SCRIPTS / "sync-workflows.ps1").read_text(encoding="utf-8-sig")
        body = powershell_function_body(sync, "Test-LcTerminalCanWrite")
        self.assertIsNotNone(
            body, "Test-LcTerminalCanWrite is gone; this scan has nothing to anchor to")
        code = "\n".join(line for _, line, _, _ in powershell_code_lines(body))
        self.assertIn("[Console]::OutputEncoding", code, "it no longer asks the stream")
        self.assertIsNone(
            re.search(r"\[Console\]::(Output|Input)Encoding\s*=", code),
            "it now sets the console's encoding instead of asking it")

        # And the library's own console output is still exactly the vocabulary
        # of docs/runtime.md, written to whatever console it was given.
        result = self.run_powershell(
            "$before = [Console]::OutputEncoding.CodePage\n"
            "Write-LcInfo 'one'\n"
            "Write-LcOk 'two'\n"
            "Write-LcWarn 'three'\n"
            "Write-LcFail 'four'\n"
            "Write-LcDetail 'five'\n"
            "Write-LcField -Label 'Six' -Value 'seven'\n"
            "\"codepage $before -> $([Console]::OutputEncoding.CodePage)\"\n")
        self.assertEqual(0, result.returncode, self.output_of(result))
        lines = [line.rstrip() for line in result.stdout.splitlines()]
        self.assertEqual(
            ["[INFO] one", "[ OK ] two", "[WARN] three", "[FAIL] four",
             "       five", "", "       Six:", "       seven"],
            lines[:8], result.stdout)
        page = re.search(r"codepage (\d+) -> (\d+)", result.stdout)
        self.assertIsNotNone(page, result.stdout)
        self.assertEqual(page.group(1), page.group(2),
                         "printing changed the console's code page")


class RedirectedChildLaunchTests(ScriptTestCase):
    """The launch mechanism itself, as opposed to the decision it carries.

    Start-LcRedirectedChild makes the CreateProcess call Start-Process makes
    underneath, because only that can give a child an environment of its own
    (lib\\Common.ps1). That is the heaviest piece of new code in these scripts,
    and the class above tests what it *declares* rather than how it *launches*.
    These four are the net under the launch: every handle it opens is closed
    again, a launcher path with a space in it is one path, the child outlives
    the process that started it, and a launch that fails leaves nothing behind
    -- neither a process nor a hold on a log.
    """

    # -- every handle it opens, it closes ----------------------------------

    LAUNCHES = 20

    def test_repeated_launches_release_every_handle_but_the_one_they_keep(self):
        """Handles are the thing a hand-rolled CreateProcess gets wrong.

        Five are opened per launch: stdin, stdout, stderr, the process and its
        primary thread. Four must be closed, and exactly one -- the process
        handle -- is kept on purpose, so that Windows cannot hand the child's
        process id to anything else while the script that started it is still
        running. So the growth of the launcher's own handle count over N
        launches is N, plus whatever .NET's own Process objects are holding,
        and never the 4N or 5N a missed close would show.
        """
        script = "\n".join([
            "$workspace = {}".format(powershell_literal(self.workspace)),
            "$py = {}".format(powershell_literal(sys.executable)),
            "$line = ConvertTo-LcCommandLine -Arguments @('-c', 'pass')",
            "function Get-HandleCount { (Get-Process -Id $PID).HandleCount }",
            "$before = Get-HandleCount",
            "$launched = @()",
            "for ($i = 0; $i -lt {}; $i++) {{".format(self.LAUNCHES),
            "    $child = Start-LcRedirectedChild -FilePath $py -CommandLine $line `",
            "        -WorkingDirectory $workspace `",
            "        -StandardOutputLog (Join-Path $workspace \"child $i.out.log\") `",
            "        -StandardErrorLog (Join-Path $workspace \"child $i.err.log\")",
            "    $launched += $child.Id",
            "}",
            "Start-Sleep -Milliseconds 800",
            # So that a handle merely awaiting collection is not counted as one
            # that was never released.
            "[GC]::Collect(); [GC]::WaitForPendingFinalizers(); [GC]::Collect()",
            "[pscustomobject]@{",
            "    Before = $before",
            "    After = Get-HandleCount",
            "    Launched = @($launched)",
            "} | ConvertTo-Json -Compress",
        ])
        result = self.run_powershell(script)
        self.assertEqual(0, result.returncode, self.output_of(result))
        measured = json.loads(result.stdout)

        self.assertEqual(self.LAUNCHES, len(measured["Launched"]))
        self.assertEqual(len(set(measured["Launched"])), len(measured["Launched"]),
                         "two launches came back with the same process id")
        growth = measured["After"] - measured["Before"]
        # The lower bound is the retention this code documents: without it the
        # measurement would be about nothing. The upper bound is what makes it
        # a guard -- a single unclosed handle per launch lands above it.
        self.assertGreaterEqual(
            growth, self.LAUNCHES,
            "the process handle this launcher keeps on purpose is not being kept "
            "({} launches, {} more handles)".format(self.LAUNCHES, growth))
        self.assertLessEqual(
            growth, 2 * self.LAUNCHES,
            "the launcher leaked handles: {} launches left {} more handles open, "
            "and it opens five and keeps one".format(self.LAUNCHES, growth))
        # And the children really were started and really ended: the count
        # above must not be a count of launches that did nothing.
        for pid in measured["Launched"]:
            self.assertFalse(self.alive(pid), "a child of this test outlived it")

    # -- a launcher path with a space in it --------------------------------

    def interpreter_reached_through_a_spaced_path(self):
        """This interpreter, named through a directory whose name has a space,
        with a decoy sitting where an unquoted command line would look first.

        The decoy is the whole point. Measured here: with no decoy present,
        quoting argv[0] makes no observable difference at all -- Windows'
        extended image search walks the successive prefixes of an unquoted
        command line (`...\\interpreter.exe`, then `...\\interpreter dir\\python.exe`)
        and gets there anyway, so a test without one passes on unquoted code
        and guards nothing. What quoting actually prevents is the earlier
        prefix being taken, which is what this sets up.

        A junction rather than a copy, because a Python installation is not one
        file. It lives outside the test workspace and is removed with rmdir,
        which unlinks a junction without touching what it points at -- never
        with a recursive delete, which is how a cleanup comes to eat the thing
        it points at.
        """
        # No space before the last component, or the first prefix Windows tries
        # is somewhere up in the system temp directory rather than the decoy,
        # and the decoy stops meaning anything.
        holder = make_temporary_directory(prefix="lct0085launcher")
        link = holder / "interpreter dir"
        decoy = holder / "interpreter.exe"
        self.addCleanup(self.remove_junction, holder, link, decoy)
        if " " in str(holder):
            self.skipTest(
                "this machine's temporary directory has a space in it ({}), so the "
                "decoy cannot be put at the first prefix an unquoted command line "
                "would try".format(holder))
        result = subprocess.run(
            ["cmd", "/c", "mklink", "/J", str(link), str(Path(sys.executable).parent)],
            capture_output=True, text=True, encoding="utf-8", errors="replace")
        executable = link / Path(sys.executable).name
        if result.returncode != 0 or not executable.exists():
            self.skipTest(
                "a directory junction could not be made here, so a launcher path "
                "with a space in it cannot be set up: "
                + ((result.stdout or "") + (result.stderr or "")).strip())
        # Not a program, deliberately: if it is ever reached the launch fails
        # loudly instead of running something.
        decoy.write_bytes(b"this is not a program\n")

        self.assertIn(" ", executable.parent.name, "the junction has no space in it")
        # The decoy really is at the prefix an unquoted command line would try:
        # everything up to the first space, with .exe appended.
        self.assertEqual(
            str(decoy), str(executable).split(" ", 1)[0] + ".exe",
            "the decoy is not where an unquoted argv[0] would look first")
        return executable

    @staticmethod
    def remove_junction(holder, link, decoy):
        # rmdir on a junction removes the junction only. Deliberately not
        # shutil.rmtree anywhere near here: it points at a Python installation.
        try:
            os.unlink(decoy)
        except OSError:
            pass
        for path in (link, holder):
            try:
                os.rmdir(path)
            except OSError:
                pass

    def test_a_launcher_path_with_a_space_in_it_starts_the_child(self):
        """argv[0] is an argument too, and this launcher builds it itself.

        Every other part of the command line goes through ConvertTo-LcArgument
        and is covered by the space in every path this suite uses. The
        executable is the one part Start-Process used to quote for us.
        """
        executable = self.interpreter_reached_through_a_spaced_path()
        self.write_config(comfy_executable=executable)

        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("ComfyUI ready at", output)
        self.assert_no_stack_trace(output)
        # The path really was the spaced one, and the child really ran: with an
        # unquoted argv[0] the decoy beside it is what Windows would launch.
        self.assertIn(executable.parent.name, output,
                      "start.ps1 did not launch through the spaced path")
        self.assertTrue(self.comfy_marker.exists(), "ComfyUI was never launched")
        # And its arguments survived the same trip: the stub parses them, and
        # the marker it wrote is at a path with two spaces in it.
        self.assertIn(" ", str(self.comfy_marker))

    # -- the child outlives the process that started it ---------------------

    def test_the_child_keeps_writing_to_its_log_after_the_launcher_is_gone(self):
        """The redirect is the child's own file handle, not a pipe we hold.

        start.ps1 exits as soon as the runtime is up, and ComfyUI goes on
        logging for hours afterwards. A launcher that handed the child a pipe
        it was pumping itself would pass every readiness test in this file and
        then break exactly here.
        """
        self.write_config(comfy_extra_args=[
            "--port", str(self.comfy_port),
            "--launch-marker", str(self.comfy_marker),
            "--log-every", "0.25",
        ])
        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)

        # run_script returned, so the PowerShell that ran start.ps1 has exited.
        record = self.read_pid_file("comfy")
        self.assertIsNotNone(record)
        self.assertTrue(self.alive(record["pid"]),
                        "the child did not outlive the process that started it")

        log = self.runtime_dir / "comfy.out.log"
        first = self.heartbeats(log)
        self.assertTrue(first, "the child was not writing heartbeats at all")
        self.assertTrue(
            wait_until(lambda: max(self.heartbeats(log), default=0) > max(first), 20),
            "the child's output stopped when the process that started it exited "
            "(last heartbeat {})".format(max(first)))
        self.assertTrue(http_ok(self.comfy_health_url))

    @staticmethod
    def heartbeats(path):
        try:
            text = path.read_bytes().decode("utf-8", "replace")
        except OSError:
            return []
        return [int(found) for found in re.findall(r"^heartbeat (\d+)", text, re.MULTILINE)]

    # -- a launch that fails leaves nothing behind --------------------------

    def test_a_launch_that_fails_leaves_no_process_and_no_hold_on_the_logs(self):
        """The child is created suspended, so a failure has something to strand.

        Reached the way a user would reach it: comfy.launcher.executable naming
        a file that exists -- so start.ps1's own checks pass it -- and is not a
        program. The launch must fail as a launch, saying so, and must leave
        neither a process nor a handle on either log.
        """
        not_a_program = self.workspace / "not a program.txt"
        not_a_program.write_text("this is not an executable\n", encoding="utf-8")
        self.write_config(comfy_executable=not_a_program)

        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn("ComfyUI could not be started", output)
        self.assert_no_stack_trace(output)
        self.assertIsNone(self.read_pid_file("comfy"),
                          "a launch that never happened was recorded as owned")
        self.assertFalse(self.gateway_marker.exists(), "a gateway followed a failed launch")

        # Nothing holds the logs. A child left suspended would be holding both,
        # invisibly, and this is the observation that would show it.
        for name in ("comfy.out.log", "comfy.err.log"):
            path = self.runtime_dir / name
            if path.exists():
                path.unlink()
                self.assertFalse(path.exists(), name)

    def test_a_running_child_does_hold_its_log_so_the_two_checks_above_are_real(self):
        """The control for both absence tests: the observable can say no.

        "The log can be deleted afterwards" only means "nothing was stranded"
        if a process that IS holding the log stops the same delete. A child of
        a successful launch is exactly that process, so this is the same
        observation with the answer the other way round.
        """
        self.write_config()
        result = self.run_script("start.ps1")
        self.assertEqual(0, result.returncode, self.output_of(result))
        record = self.read_pid_file("comfy")
        self.assertIsNotNone(record)
        self.assertTrue(self.alive(record["pid"]))

        log = self.runtime_dir / "comfy.out.log"
        self.assertTrue(log.exists())
        with self.assertRaises(OSError):
            log.unlink()
        self.assertTrue(log.exists(), "the log of a running child was deleted")

    def test_a_launch_that_fails_before_the_child_runs_holds_no_log_either(self):
        """The second failure shape, which start.ps1's own checks never reach.

        A working directory that does not exist: the log files are opened
        before CreateProcess is called, so this is the path on which a
        half-finished launch could leave them held.
        """
        out_log = self.workspace / "held out.log"
        err_log = self.workspace / "held err.log"
        script = "\n".join([
            "try {",
            "    [void](Start-LcRedirectedChild -FilePath {} `".format(
                powershell_literal(sys.executable)),
            "        -CommandLine \"-c 'pass'\" `",
            "        -WorkingDirectory {} `".format(
                powershell_literal(self.workspace / "no such directory")),
            "        -StandardOutputLog {} `".format(powershell_literal(out_log)),
            "        -StandardErrorLog {})".format(powershell_literal(err_log)),
            "    'NO ERROR'",
            "} catch {",
            "    'REFUSED: ' + $_.Exception.Message",
            "}",
        ])
        result = self.run_powershell(script)
        self.assertEqual(0, result.returncode, self.output_of(result))
        self.assertIn("REFUSED:", result.stdout, result.stdout)

        # The PowerShell that ran it has exited, so any handle still on these
        # files belongs to a process that should not exist.
        for path in (out_log, err_log):
            self.assertTrue(path.exists(), "{} was never opened".format(path.name))
            path.unlink()
            self.assertFalse(path.exists(), path.name)


class ExternalModeTests(ScriptTestCase):
    def test_backend_down_fails_cleanly_and_launches_nothing(self):
        self.write_config(manage_comfy=False)
        result = self.run_script("start.ps1")
        output = self.output_of(result)

        self.assertEqual(4, result.returncode, output)
        self.assertIn("ComfyUI is not reachable", output)
        self.assertIn(f"Probed: http://127.0.0.1:{self.comfy_port}/system_stats", output)
        self.assertIn("did not try to start it", output)
        self.assert_no_stack_trace(output)

        self.assertFalse(self.comfy_marker.exists(), "external mode launched ComfyUI")
        self.assertFalse(self.gateway_marker.exists(), "a gateway was started anyway")
        self.assertIsNone(self.read_pid_file("comfy"))
        self.assertIsNone(self.read_pid_file("gateway"))

    def test_backend_up_starts_the_gateway_and_owns_no_backend(self):
        self.start_backend_stub()
        self.write_config(manage_comfy=False)
        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("external mode", output)
        self.assertIn("[ OK ] LocalCanvas is ready", output)
        self.assertFalse(self.comfy_marker.exists())
        self.assertIsNone(self.read_pid_file("comfy"))

    def test_stop_never_terminates_an_external_backend(self):
        stub = self.start_backend_stub()
        self.write_config(manage_comfy=False)
        self.assertEqual(0, self.run_script("start.ps1").returncode)

        result = self.run_script("stop.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("LocalCanvas never stops it", output)
        self.assertIsNone(stub.poll(), "stop.ps1 terminated an external ComfyUI")
        self.assertTrue(http_ok(self.comfy_health_url))


class StopTests(ScriptTestCase):
    def test_a_seam_failure_never_stops_it_stopping_what_it_owns(self):
        """stop.ps1 answers to the ownership records, not to the configuration.

        A gateway one version out of step publishes a document without a field
        the scripts read. Everything else may degrade; stopping what LocalCanvas
        started may not, or a skew leaves the user's processes running with no
        way to stop them.
        """
        for dropped in ("runtime.manage_comfy", "comfy.base_url"):
            with self.subTest(field=dropped):
                self.write_config()
                self.assertEqual(0, self.run_script("start.ps1").returncode)
                self.assertIsNotNone(self.read_pid_file("comfy"))
                self.assertIsNotNone(self.read_pid_file("gateway"))

                result = self.run_script(
                    "stop.ps1", env=self.script_env(LC_STUB_CONFIG_DROP=dropped))
                output = self.output_of(result)

                self.assertEqual(0, result.returncode, output)
                self.assertIn("Gateway stopped", output)
                self.assertIn("ComfyUI stopped", output)
                self.assertIsNone(self.read_pid_file("gateway"))
                self.assertIsNone(self.read_pid_file("comfy"))
                self.assertTrue(wait_until(lambda: not http_ok(self.gateway_health_url), 20))
                self.assertTrue(wait_until(lambda: not http_ok(self.comfy_health_url), 20))
                # It said why it could not read the configuration, in words --
                # not by leaking the marker the scripts tag such failures with.
                self.assertIn("out of step", output)
                self.assertNotIn("[configuration-seam]", output)
                self.assert_no_stack_trace(output)

    def test_a_seam_failure_does_not_stop_it_reporting_a_reused_backend(self):
        """The other half of the same property, and the branch that reads the mode.

        With nothing of its own to stop, stop.ps1 consults runtime.manage_comfy
        to say what it is leaving alone. Reading it must not be able to abort
        the script: moving that read out of the best-effort block is precisely
        the change this guards against.
        """
        stub = self.start_backend_stub()
        self.write_config()
        self.assertEqual(0, self.run_script("start.ps1").returncode)
        self.assertIsNone(self.read_pid_file("comfy"), "the reused backend was claimed")

        result = self.run_script(
            "stop.ps1", env=self.script_env(LC_STUB_CONFIG_DROP="runtime.manage_comfy"))
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("Gateway stopped", output)
        self.assertIsNone(self.read_pid_file("gateway"))
        self.assertIsNone(stub.poll(), "the reused backend was stopped")
        self.assertNotIn("[configuration-seam]", output)
        self.assert_no_stack_trace(output)

    def test_stops_only_what_it_started_and_leaves_a_reused_backend_alone(self):
        stub = self.start_backend_stub()
        self.write_config()
        self.assertEqual(0, self.run_script("start.ps1").returncode)
        self.assertTrue(wait_until(lambda: http_ok(self.gateway_health_url), 20))

        result = self.run_script("stop.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)

        self.assertIn("Gateway stopped", output)
        self.assertIn("leaving it alone", output)
        self.assertIsNone(stub.poll(), "stop.ps1 killed a ComfyUI it did not start")
        self.assertTrue(http_ok(self.comfy_health_url))
        self.assertTrue(wait_until(lambda: not http_ok(self.gateway_health_url), 20))
        self.assertIsNone(self.read_pid_file("gateway"))

    def test_stops_a_backend_it_did_start(self):
        self.write_config()
        self.assertEqual(0, self.run_script("start.ps1").returncode)
        record = self.read_pid_file("comfy")
        self.assertIsNotNone(record)

        result = self.run_script("stop.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("ComfyUI stopped", output)
        self.assertTrue(wait_until(lambda: not http_ok(self.comfy_health_url), 20))
        self.assertIsNone(self.read_pid_file("comfy"))

    def test_cleans_a_stale_pid_file(self):
        self.write_config()
        self.write_pid_file(
            "comfy",
            {
                "pid": self.dead_pid(),
                "role": "comfy",
                "start_time": "2020-01-01T00:00:00.0000000Z",
                "image_path": r"C:\nowhere\python.exe",
                "owned_by": "localcanvas",
            },
        )
        result = self.run_script("stop.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("stale PID file removed", output)
        self.assertIsNone(self.read_pid_file("comfy"))

    def test_a_nonsense_pid_file_is_a_broken_record_not_a_crash(self):
        self.write_config()
        self.write_pid_file(
            "comfy",
            {"pid": 4294967294, "role": "comfy", "start_time": "", "image_path": ""},
        )
        result = self.run_script("stop.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("unusable PID file removed", output)
        self.assertIsNone(self.read_pid_file("comfy"))
        self.assert_no_stack_trace(output)

    def test_a_recycled_pid_is_not_treated_as_ours(self):
        # The PID is live and is a python.exe -- but it is NOT the process
        # LocalCanvas started, and the recorded start time proves it. The
        # executable agrees, so what disagrees is a reading of a clock: refused
        # all the same, and the record is kept rather than destroyed on the
        # strength of it (T-0088).
        stub = self.start_backend_stub()
        self.write_config()
        record = {
            "pid": stub.pid,
            "role": "comfy",
            "start_time": "2020-01-01T00:00:00.0000000Z",
            "image_path": sys.executable,
            "owned_by": "localcanvas",
        }
        self.write_pid_file("comfy", record)
        result = self.run_script("stop.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("could not prove it owns PID {}".format(stub.pid), output)
        self.assertIn("2020-01-01T00:00:00", output)
        self.assertIsNone(stub.poll(), "stop.ps1 signalled a process it had not verified")
        self.assertEqual(record, self.read_pid_file("comfy"))

    def test_an_unrecorded_image_path_is_not_treated_as_ours(self):
        # Evidence that was never recorded proves nothing. An empty image path
        # counts against ownership, never neutrally -- and, just as much, never
        # as proof that the process belongs to somebody else.
        stub = self.start_backend_stub()
        self.write_config()
        record = {
            "pid": stub.pid,
            "role": "comfy",
            "start_time_utc_ticks": self.process_start_ticks(stub.pid),
            "image_path": "",
        }
        self.write_pid_file("comfy", record)
        result = self.run_script("stop.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("could not prove it owns PID {}".format(stub.pid), output)
        self.assertIsNone(stub.poll(), "a process whose ownership was unproven was signalled")
        self.assertEqual(record, self.read_pid_file("comfy"))

    def test_a_mismatched_image_path_is_not_treated_as_ours(self):
        stub = self.start_backend_stub()
        self.write_config()
        # Start time is right; the image path is somebody else's.
        started_at = time.time()
        self.write_pid_file(
            "comfy",
            {
                "pid": stub.pid,
                "role": "comfy",
                "start_time": time.strftime(
                    "%Y-%m-%dT%H:%M:%S.0000000Z", time.gmtime(started_at)
                ),
                "image_path": r"C:\Windows\System32\notepad.exe",
                "owned_by": "localcanvas",
            },
        )
        result = self.run_script("stop.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("NOT the process LocalCanvas started", output)
        self.assertIsNone(stub.poll())
        # Proved to be a different program: that record describes a process
        # that no longer exists, so removing it is right.
        self.assertIsNone(self.read_pid_file("comfy"))


class ProcessIdentityTests(ScriptTestCase):
    """T-0088: what a process IS, read from the process and not its modules.

    Nothing in this class starts, stops or signals anything. Every case is a
    read, and the only PID it names besides its own stub is the Windows System
    process, which it reads and never touches.
    """

    def test_the_identity_of_a_live_process_is_the_executable_it_runs(self):
        stub = self.start_backend_stub()
        identity = self.process_identity(stub.pid)

        self.assertTrue(identity["Readable"], identity["Reason"])
        # Verbatim, against the interpreter this suite is running on -- not
        # "contains python", which a module path would satisfy just as well.
        self.assertEqual(sys.executable, identity["ExecutablePath"])
        self.assertTrue(
            identity["ExecutablePath"].lower().endswith(".exe"),
            "the identity read returned {!r}, which is not an executable "
            "at all".format(identity["ExecutablePath"]))
        self.assertFalse(identity["ExecutablePath"].lower().endswith(".dll"))
        # The same read carries the rest of the evidence, from one query.
        self.assertIn(str(STUB_COMFY), identity["CommandLine"])
        self.assertAlmostEqual(
            self.process_start_ticks(stub.pid) / 10_000_000,
            identity["StartTimeUtcTicks"] / 10_000_000,
            delta=1.0,
            msg="the identity's start time disagrees with the process's own")

    def test_an_identity_that_cannot_be_read_is_said_to_be_unreadable(self):
        """A live process whose identity this machine will not disclose.

        PID 4 is the Windows System process: it is always running, it is never
        LocalCanvas's, and its executable cannot be read by anyone. It is the
        one case where "the process exists but I cannot say what it is" can be
        exercised for real rather than simulated -- which is the case that
        deleted an ownership record and leaked a ComfyUI.
        """
        result = self.run_powershell(
            "[bool](Get-Process -Id 4 -ErrorAction SilentlyContinue)")
        self.assertEqual("True", result.stdout.strip(), self.output_of(result))

        identity = self.process_identity(4)
        self.assertFalse(
            identity["Readable"],
            "PID 4's executable was reported as {!r}".format(identity["ExecutablePath"]))
        self.assertEqual("", identity["ExecutablePath"])
        self.assertEqual(0, identity["StartTimeUtcTicks"])
        self.assertIn("PID 4", identity["Reason"])


class OwnershipDecisionTests(ScriptTestCase):
    """The five situations an ownership record can be in, one test each.

    Driven straight at Resolve-LcOwnedProcess, in a runtime directory of the
    test's own: the decision is what is under test, and deciding it signals
    nothing. Ownership is PID + start time + executable identity, and the
    verdict distinguishes *proved not ours* from *not proved ours*.
    """

    def owned_record(self, pid, **overrides):
        record = {
            "pid": pid,
            "role": "comfy",
            "start_time_utc_ticks": self.process_start_ticks(pid),
            "image_path": sys.executable,
            "owned_by": "localcanvas",
        }
        record.update(overrides)
        return record

    def test_a_matching_pid_start_time_and_executable_is_ours(self):
        stub = self.start_backend_stub()
        verdict = self.resolve_ownership(self.owned_record(stub.pid))
        self.assertEqual("running", verdict["State"], verdict["Reason"])

    def test_a_pid_that_names_no_process_is_stale(self):
        verdict = self.resolve_ownership(self.owned_record_for_dead_pid())
        self.assertEqual("stale", verdict["State"], verdict["Reason"])
        self.assertIn("not running", verdict["Reason"])

    def owned_record_for_dead_pid(self):
        pid = self.dead_pid()
        return {
            "pid": pid,
            "role": "comfy",
            "start_time_utc_ticks": 637000000000000000,
            "image_path": sys.executable,
            "owned_by": "localcanvas",
        }

    def test_the_pid_alone_is_never_enough(self):
        """The PID matches and nothing else does. That is not ownership.

        This is the shape of PID reuse, and the one a "just stop the PID in the
        file" implementation gets wrong.
        """
        stub = self.start_backend_stub()
        verdict = self.resolve_ownership(self.owned_record(
            stub.pid,
            start_time_utc_ticks=637000000000000000,
            image_path=r"C:\nowhere at all\python.exe"))
        self.assertNotEqual("running", verdict["State"], verdict["Reason"])
        self.assertEqual("mismatch", verdict["State"], verdict["Reason"])

    def test_the_executable_is_compared_whole_and_not_by_its_file_name(self):
        """Two python.exe in two directories are two different programs.

        The name proves nothing: this machine has more than one interpreter,
        and any ComfyUI is somebody's python.exe.
        """
        stub = self.start_backend_stub()
        elsewhere = str(Path(r"C:\another install") / Path(sys.executable).name)
        self.assertEqual(
            Path(sys.executable).name, Path(elsewhere).name,
            "this test only means something if the two file names are equal")
        verdict = self.resolve_ownership(
            self.owned_record(stub.pid, image_path=elsewhere))
        self.assertEqual("mismatch", verdict["State"], verdict["Reason"])
        self.assertIn(elsewhere, verdict["Reason"])
        self.assertIn(sys.executable, verdict["Reason"])

    def test_a_start_time_that_disagrees_is_refused_and_the_record_is_kept(self):
        stub = self.start_backend_stub()
        verdict = self.resolve_ownership(
            self.owned_record(stub.pid, start_time_utc_ticks=637000000000000000))
        self.assertEqual("unproven", verdict["State"], verdict["Reason"])
        self.assertIn("2019-07-29T12:26:40", verdict["Reason"])

    def test_an_identity_that_cannot_be_read_is_unproven_and_never_a_mismatch(self):
        """The central distinction: not proved ours is not proved NOT ours.

        PID 4 is live and unreadable, which is exactly the situation the old
        code called a mismatch -- and a mismatch is what stop.ps1 deleted the
        record for.
        """
        verdict = self.resolve_ownership({
            "pid": 4,
            "role": "comfy",
            "start_time_utc_ticks": 637000000000000000,
            "image_path": sys.executable,
            "owned_by": "localcanvas",
        })
        self.assertEqual("unproven", verdict["State"], verdict["Reason"])
        self.assertIn("PID 4", verdict["Reason"])
        self.assertIsNotNone(verdict["record_after"], "the decision destroyed the record")

    def test_evidence_that_was_never_recorded_is_unproven_in_both_directions(self):
        stub = self.start_backend_stub()
        verdict = self.resolve_ownership(self.owned_record(stub.pid, image_path=""))
        self.assertEqual("unproven", verdict["State"], verdict["Reason"])
        self.assertIn("no image path was recorded", verdict["Reason"])

    def test_a_record_with_no_start_time_at_all_is_unproven(self):
        stub = self.start_backend_stub()
        record = self.owned_record(stub.pid)
        del record["start_time_utc_ticks"]
        verdict = self.resolve_ownership(record)
        self.assertEqual("unproven", verdict["State"], verdict["Reason"])


class OwnershipRecordLifecycleTests(ScriptTestCase):
    """What stop.ps1 does with the record in each of those situations.

    The rule the card exists for: a record is destroyed only when it is proved
    to describe a process that is gone. When ownership merely could not be
    proved, the process is left alone AND the evidence is kept -- deleting it
    is the one irreversible move, and it is what leaked a running ComfyUI.
    """

    def test_an_unprovable_identity_keeps_the_record_and_says_what_is_running(self):
        stub = self.start_backend_stub()
        self.write_config()
        # Ownership that cannot be proved: the evidence was never recorded.
        # The process is alive, is answering, and may well be ours.
        record = {
            "pid": stub.pid,
            "role": "comfy",
            "start_time_utc_ticks": self.process_start_ticks(stub.pid),
            "image_path": "",
            "owned_by": "localcanvas",
        }
        self.write_pid_file("comfy", record)

        result = self.run_script("stop.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)

        # 1. It refused, and said what it refused about.
        self.assertIn("could not prove it owns PID {}".format(stub.pid), output)
        # 2. It named the process that is still running, and did not stop it.
        self.assertIn("PID {} is still running".format(stub.pid), output)
        self.assertIsNone(stub.poll(), "stop.ps1 stopped what it could not prove")
        self.assertTrue(http_ok(self.comfy_health_url))
        # 3. It kept the evidence, unchanged, and said where it is.
        self.assertEqual(record, self.read_pid_file("comfy"))
        self.assertIn(str(self.runtime_dir / "comfy.pid"), output)
        self.assert_no_stack_trace(output)

    def test_a_kept_record_still_stops_the_process_once_it_can_be_proved(self):
        """Why keeping it matters: the next run reclaims the process.

        The record that could not be proved is the same record that proves
        ownership as soon as the missing evidence is there -- which is what
        "unowned forever" took away.
        """
        self.write_config()
        self.assertEqual(0, self.run_script("start.ps1").returncode)
        record = self.read_pid_file("comfy")
        self.assertIsNotNone(record)
        started_pid = record["pid"]

        # Damage the evidence the way an unreadable identity does.
        unprovable = dict(record)
        unprovable["image_path"] = ""
        self.write_pid_file("comfy", unprovable)
        first = self.output_of(self.run_script("stop.ps1"))
        self.assertIn("could not prove it owns PID {}".format(started_pid), first)
        self.assertTrue(self.alive(started_pid))
        self.assertEqual(unprovable, self.read_pid_file("comfy"))

        # The evidence comes back, and the process LocalCanvas started is
        # stopped by an ordinary stop.ps1 -- no new mechanism, no manual kill.
        self.write_pid_file("comfy", record)
        second = self.output_of(self.run_script("stop.ps1"))
        self.assertIn("ComfyUI stopped", second)
        self.assertTrue(wait_until(lambda: not self.alive(started_pid), 20))
        self.assertIsNone(self.read_pid_file("comfy"))

    def test_a_process_localcanvas_started_is_stopped_and_the_record_removed_after(self):
        self.write_config()
        self.assertEqual(0, self.run_script("start.ps1").returncode)
        record = self.read_pid_file("comfy")
        self.assertIsNotNone(record)
        # The record was written from the same identity source the check reads.
        self.assertEqual(sys.executable, record["image_path"])

        output = self.output_of(self.run_script("stop.ps1"))
        self.assertIn("ComfyUI stopped (PID {}".format(record["pid"]), output)
        # Gone, and only then forgotten.
        self.assertTrue(wait_until(lambda: not self.alive(record["pid"]), 20))
        self.assertIsNone(self.read_pid_file("comfy"))

    def test_a_stop_that_cannot_confirm_the_exit_keeps_the_record(self):
        """The property itself, exercised rather than read.

        Windows cannot be asked to refuse a termination, but the outcome can:
        the copy under test has Stop-LcOwnedProcess's body replaced by
        `return 'still-running'`. That is also what disarms it -- the copy
        carries no Stop-Process call anywhere, asserted below before it is
        run, so nothing this test executes can end a process.

        Ownership is fully proved here. The only thing that fails is the
        confirmation that the process exited, and that alone must keep the
        record: a process that did not die and whose evidence was thrown away
        is the leak this card exists to close, reached by a second route.
        """
        stub = self.start_backend_stub()
        self.write_config()
        record = {
            "pid": stub.pid,
            "role": "comfy",
            "start_time_utc_ticks": self.process_start_ticks(stub.pid),
            "image_path": sys.executable,
            "owned_by": "localcanvas",
        }
        self.write_pid_file("comfy", record)
        copied = self.copy_scripts_with_stopping_disabled()

        result = self.run_script("stop.ps1", script_dir=copied)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("did not exit; the ownership record was kept", output)
        self.assertEqual(
            record, self.read_pid_file("comfy"),
            "the record of a process that did not exit was removed")
        self.assertIsNone(stub.poll())
        self.assertTrue(http_ok(self.comfy_health_url))

    def test_the_record_is_removed_only_after_the_exit_is_verified(self):
        """The same property in the source, where the order is decided.

        The test above proves the branch behaves; this one proves the branch is
        still the shape that behaves -- the stop, then the check that it
        exited, then the removal. Comments and strings come out first: a guard
        satisfied by the words `still-running` in a comment between the stop
        and the removal is not a guard, and that is exactly the mutation this
        scan used to survive.

        Anchored on all three symbols -- a renamed branch fails here rather
        than quietly scanning nothing.
        """
        # Comments out, string literals kept: the branch is selected by the
        # string 'running' and the outcome it checks is the string
        # 'still-running', so the strings are the subject here.
        text = "\n".join(line for _, _, line, _ in powershell_code_lines(
            (SCRIPTS / "stop.ps1").read_text(encoding="utf-8-sig")))
        branch = re.search(r"'running'\s*\{(.*?)\n        \}", text, re.DOTALL)
        self.assertIsNotNone(
            branch, "stop.ps1 has no 'running' branch any more; this scan has "
                    "nothing to look at")
        body = branch.group(1)
        for symbol in ("Stop-LcOwnedProcess", "still-running",
                       "Remove-LcOwnedProcessRecord"):
            self.assertIn(
                symbol, body,
                "stop.ps1's 'running' branch no longer contains {}".format(symbol))
        self.assertLess(
            body.index("Stop-LcOwnedProcess"), body.index("still-running"),
            "the exit is not checked after the stop")
        self.assertLess(
            body.index("still-running"), body.index("Remove-LcOwnedProcessRecord"),
            "the ownership record is removed before the exit has been verified")

    def test_external_mode_keeps_an_unprovable_record_and_names_it(self):
        """start.ps1, external mode: the leftover branch.

        It removes a leftover record that proves nothing -- but a record that
        cannot be PROVED is not a record that has been DISPROVED, and the
        process it names is up.
        """
        stub = self.start_backend_stub()
        self.write_config(manage_comfy=False)
        record = self.unprovable_record(stub.pid)
        self.write_pid_file("comfy", record)

        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn(
            "A ComfyUI ownership record names PID {}, and LocalCanvas could not "
            "prove it owns it".format(stub.pid), output)
        self.assertNotIn("Removed a leftover ComfyUI ownership record", output)
        self.assertEqual(record, self.read_pid_file("comfy"))
        self.assertIsNone(stub.poll())

    def test_reusing_a_healthy_backend_keeps_an_unprovable_record(self):
        """start.ps1, managed, the backend already answering: the reuse branch.

        Reuse is still reuse -- no ownership is taken -- and the record that
        could not be proved survives instead of being dropped on the way past.
        """
        stub = self.start_backend_stub()
        self.write_config()
        record = self.unprovable_record(stub.pid)
        self.write_pid_file("comfy", record)

        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("reusing it", output)
        self.assertIn(
            "An ownership record names PID {}, and LocalCanvas could not prove "
            "it owns it".format(stub.pid), output)
        self.assertEqual(record, self.read_pid_file("comfy"))
        self.assertFalse(self.comfy_marker.exists(),
                         "a second ComfyUI was launched beside a healthy one")
        self.assertIsNone(stub.poll())

    def test_launching_beside_an_unprovable_process_says_what_it_left_alone(self):
        """start.ps1, managed, nothing answering: the launch branch.

        A live PID it cannot prove, and no ComfyUI answering. It launches --
        and it must say which process it is leaving behind and that the record
        is about to be replaced, because that record is the last trace of it
        (the replacement itself is T-0090, filed, not fixed here).
        """
        idle = self.start_idle_process()
        self.write_config()
        self.write_pid_file("comfy", self.unprovable_record(idle.pid))

        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn(
            "An ownership record names PID {}, and LocalCanvas could not prove "
            "it owns it".format(idle.pid), output)
        self.assertIn(
            "PID {} is still running and is being left alone.".format(idle.pid),
            output)
        self.assertIn("will replace that record with the new process", output)
        self.assertIsNone(idle.poll(), "start.ps1 stopped a process it could not prove")
        launched = self.read_pid_file("comfy")
        self.assertIsNotNone(launched)
        self.assertNotEqual(idle.pid, launched["pid"])

    def test_an_unprovable_gateway_record_is_not_deleted_either(self):
        """The same rule on the gateway half of start.ps1.

        Nothing about the leak is specific to ComfyUI: a gateway record that
        cannot be proved names a process that may be up and holding a port.
        """
        idle = self.start_idle_process()
        self.write_config()
        self.write_pid_file("gateway", self.unprovable_record(idle.pid, role="gateway"))

        result = self.run_script("start.ps1")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn(
            "A gateway ownership record names PID {}, and LocalCanvas could not "
            "prove it owns it".format(idle.pid), output)
        self.assertIn(
            "PID {} is still running and is being left alone.".format(idle.pid),
            output)
        self.assertIsNone(idle.poll())

    def test_a_reused_backend_is_never_owned_however_well_it_matches(self):
        """The regression that must not happen.

        A ComfyUI LocalCanvas did not start: it holds the configured port, it
        answers the health probe, and it is running the very interpreter
        LocalCanvas would have launched. None of that is ownership.
        """
        stub = self.start_backend_stub()
        self.write_config()
        self.assertTrue(http_ok(self.comfy_health_url))

        started = self.output_of(self.run_script("start.ps1"))
        self.assertIn("reusing it", started)
        self.assertIsNone(
            self.read_pid_file("comfy"),
            "start.ps1 claimed a ComfyUI it did not start")

        # Even the identity check agrees it is what LocalCanvas would run --
        # which is exactly why matching alone must not confer ownership.
        identity = self.process_identity(stub.pid)
        self.assertEqual(sys.executable, identity["ExecutablePath"])

        stopped = self.output_of(self.run_script("stop.ps1"))
        self.assertIn("leaving it alone", stopped)
        self.assertIsNone(stub.poll(), "a reused ComfyUI was stopped")
        self.assertTrue(http_ok(self.comfy_health_url))
        self.assertIsNone(self.read_pid_file("comfy"))


