class SetupTests(ScriptTestCase):
    """setup.ps1's interpreter selection, without building an environment."""

    def run_setup(self, *args, timeout=180, extra_env=None):
        command = [
            PWSH, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
            "-File", str(SCRIPTS / "setup.ps1"),
        ]
        command.extend(args)
        # A clean environment: setup builds the real .venv, and the stub
        # package on PYTHONPATH has no business shadowing what it installs.
        env = {k: v for k, v in os.environ.items() if not k.startswith("LC_STUB_")}
        env.pop("PYTHONPATH", None)
        env["LOCALCANVAS_RUNTIME_DIR"] = str(self.runtime_dir)
        env.update(extra_env or {})
        return subprocess.run(
            command, capture_output=True, text=True,
            encoding="utf-8", errors="replace", timeout=timeout,
            env=env, cwd=str(REPO),
        )

    def test_a_missing_interpreter_is_reported_not_guessed(self):
        missing = str(self.workspace / "not python.exe")
        result = self.run_setup("-PythonExe", missing)
        output = self.output_of(result)
        self.assertEqual(1, result.returncode, output)
        self.assertIn("does not exist", output)
        self.assert_no_stack_trace(output)

    def test_something_that_is_not_python_is_rejected(self):
        impostor = self.workspace / "not really python.cmd"
        impostor.write_text("@echo hello\r\n", encoding="utf-8")
        result = self.run_setup("-PythonExe", str(impostor))
        output = self.output_of(result)
        self.assertEqual(1, result.returncode, output)
        self.assertIn("did not answer as a Python interpreter", output)
        self.assert_no_stack_trace(output)

    def test_no_script_invokes_a_bare_py_or_python(self):
        # docs/runtime.md: `py` resolves to the NEWEST installed version, not a
        # supported one, so an interpreter is only ever chosen by an explicit
        # version selector or by a path. This machine is exactly the case the
        # rule exists for: bare `py` here is 3.14, and the floor is 3.10.
        bare = re.compile(
            r"(?:&|Start-Process\s+(?:-FilePath\s+)?)\s*['\"]?(py|python)(?:\.exe)?['\"]?(?![\w.:\\/-])"
        )
        selector_call = re.compile(r"@\(\s*'py'\s*,\s*([^)]*)\)")
        offenders = []
        selector_calls = 0
        for path in sorted(list(SCRIPTS.glob("*.ps1")) + list((SCRIPTS / "lib").glob("*.ps1"))):
            text = path.read_text(encoding="utf-8-sig")
            for number, line in enumerate(text.splitlines(), start=1):
                if bare.search(line):
                    offenders.append(f"{path.name}:{number}: {line.strip()}")
            for match in selector_call.finditer(text):
                selector_calls += 1
                arguments = match.group(1)
                if "selector" not in arguments and not re.search(r"-3\.\d", arguments):
                    offenders.append(f"{path.name}: `py` called without a version selector")
        self.assertEqual([], offenders)
        self.assertGreater(
            selector_calls, 0,
            "no explicit `py -3.x` selection remains in the scripts at all",
        )

    def test_builds_the_environment_on_the_supported_floor_and_installs_the_gateway(self):
        # The success path, which nothing covered before: reversing the
        # candidate order so that setup picks the NEWEST interpreter instead of
        # the floor used to pass the whole suite.
        require_integration(
            self, "builds a real environment from whichever Pythons `py` finds on this "
            "machine and installs the gateway's dependencies from the package index")
        floor = self.supported_floor()
        venv = self.workspace / "venv under test"
        # The answers are given in advance and the configuration is written in
        # this test's own workspace: the repository's config/local belongs to
        # whoever is running the suite, and nothing here may write in it.
        comfy = self.workspace / "a ComfyUI of the test's own"
        comfy.mkdir()
        (comfy / "main.py").write_text("# not a real ComfyUI\n", encoding="utf-8")
        # In a directory of its own, so that "the configuration was not
        # rewritten" is a statement about the configuration and not about the
        # environment that happens to sit beside it.
        config_directory = self.workspace / "the generated configuration"
        config_directory.mkdir()
        configuration = config_directory / "runtime.yaml"
        answers = [
            "-Config", str(configuration), "-Mode", "External",
            "-ComfyRoot", str(comfy),
            # Never 8188: the confirmation probe is pointed at a port of this
            # test's own, so no ComfyUI on this machine is contacted.
            "-ComfyPort", str(free_port()),
        ]
        result = self.run_setup(
            "-VenvPath", str(venv), "-SkipPipUpgrade", *answers, timeout=420)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assert_repo_config_untouched()
        # The real loader read the generated document and was happy with it --
        # which is the whole "start.ps1 works next" claim, measured.
        self.assertTrue(configuration.is_file(), output)
        self.assertIn("[ OK ] Configuration loads", output)
        self.assertIn("scripts\\start.ps1", output)

        python = venv / "Scripts" / "python.exe"
        self.assertTrue(python.exists(), output)
        version = subprocess.run(
            [str(python), "-c", "import sys;print('%d.%d' % sys.version_info[:2])"],
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=120,
        ).stdout.strip()
        self.assertEqual(
            floor, version,
            "the environment was built on Python {} instead of the supported "
            "floor {}; setup chose an interpreter nobody asked for".format(version, floor))
        self.assertIn("py -" + floor, output)

        # pip actually ran: the gateway is importable from the new environment.
        imported = subprocess.run(
            [str(python), "-c", "import localcanvas_gateway as g;print(g.__file__)"],
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=120,
        )
        self.assertEqual(0, imported.returncode, imported.stdout + imported.stderr)
        self.assertIn("gateway", imported.stdout)

        # And it is idempotent -- in state, and then in what it says. WITH THE
        # PACKAGE INDEX UNREACHABLE (T-0352, F1): before that card this run
        # exited 1 on `Could not find a version that satisfies the requirement
        # setuptools>=61`, because every run re-ran the editable install. The
        # environment itself is compared too -- a reinstall rewrites the
        # gateway's dist-info (RECORD, and every mtime in it), so "nothing was
        # reinstalled" is measured on the files a reinstall changes.
        before = tree_snapshot(config_directory, skip=("__pycache__",))
        environment_before = tree_snapshot(venv, skip=("__pycache__",))
        records = [key for key in environment_before
                   if re.search(r"localcanvas_gateway-[^\\/]+\.dist-info[\\/]RECORD$", key)]
        self.assertEqual(1, len(records), "no installed gateway record to compare")
        again = self.run_setup(
            "-VenvPath", str(venv), "-SkipPipUpgrade", "-Config", str(configuration),
            "-ComfyPort", str(free_port()), timeout=420,
            extra_env={"PIP_INDEX_URL": "http://127.0.0.1:{}/simple".format(free_port())})
        again_output = self.output_of(again)
        self.assertEqual(0, again.returncode, again_output)
        self.assertIn("already present", again_output)
        self.assertIn("nothing to install", again_output)
        self.assertIn("Nothing to change.", again_output)
        difference = snapshot_difference(
            before, tree_snapshot(config_directory, skip=("__pycache__",)))
        self.assertEqual("", difference,
                         "a second run rewrote the configuration: " + difference)
        environment_difference = snapshot_difference(
            environment_before, tree_snapshot(venv, skip=("__pycache__",)))
        self.assertEqual("", environment_difference,
                         "a second run changed the environment: " + environment_difference)

        # And the repair the check exists to trigger, on the real tree (T-0352
        # review, R1): a TRANSITIVE dependency uninstalled -- fastapi's, not
        # the gateway's -- is one reinstall with the reason named, and the
        # run that follows puts it back. Online, as any repair has to be.
        removed = subprocess.run(
            [str(python), "-m", "pip", "uninstall", "-y", "starlette"],
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=300)
        self.assertEqual(0, removed.returncode, removed.stdout + removed.stderr)
        repaired = self.run_setup(
            "-VenvPath", str(venv), "-SkipPipUpgrade", "-Config", str(configuration),
            "-ComfyPort", str(free_port()), timeout=600)
        repaired_output = self.output_of(repaired)
        self.assertEqual(0, repaired.returncode, repaired_output)
        reasons = [line for line in repaired_output.splitlines()
                   if "Reinstalling the LocalCanvas gateway into .venv:" in line]
        self.assertEqual(1, len(reasons), repaired_output)
        self.assertIn("starlette is not installed", reasons[0])
        back = subprocess.run([str(python), "-c", "import starlette"],
                              capture_output=True, text=True, timeout=120)
        self.assertEqual(0, back.returncode, back.stderr)

    def test_recreate_refuses_a_directory_that_is_not_a_virtualenv(self):
        """-Recreate deletes its target recursively; -VenvPath is a string.

        The default is safe and the whole hazard is in the argument: any path
        handed to -VenvPath was deleted, with no check that it was an
        environment at all. A directory that cannot prove it is one -- no
        pyvenv.cfg at its root -- must survive the run untouched, and the
        refusal must name the path and say why.
        """
        target = self.workspace / "not a venv"
        (target / "important").mkdir(parents=True)
        keep = target / "important" / "user data.txt"
        keep.write_text("do not delete me", encoding="utf-8")

        result = self.run_setup("-VenvPath", str(target), "-Recreate", "-SkipPipUpgrade")
        output = self.output_of(result)

        # The directory is the assertion that matters: it is still there, with
        # its contents, byte for byte.
        self.assertTrue(target.is_dir(), "setup deleted a directory that is not a venv")
        self.assertTrue(keep.is_file(), "setup deleted a directory that is not a venv")
        self.assertEqual("do not delete me", keep.read_text(encoding="utf-8"))
        self.assertEqual(1, result.returncode, output)
        self.assertIn(str(target), output, "the refusal did not name the path")
        self.assertIn("pyvenv.cfg", output, "the refusal did not say why")
        self.assertIn("NOTHING has been deleted", output)
        self.assert_no_stack_trace(output)

    def test_recreate_still_rebuilds_a_real_virtualenv(self):
        """The other half: the guard refuses the wrong target, not every one.

        Without this the refusal above would also pass on a setup.ps1 whose
        -Recreate never deleted anything at all.
        """
        require_integration(
            self, "rebuilds a real environment from whichever Pythons `py` finds on this "
            "machine and installs the gateway's dependencies from the package index")
        venv = self.workspace / "venv under test"
        subprocess.run(
            [sys.executable, "-m", "venv", "--without-pip", str(venv)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=300, check=True)
        self.assertTrue((venv / "pyvenv.cfg").is_file(),
                        "the fixture is not a virtualenv, so it proves nothing")
        stale = venv / "left from the old environment.txt"
        stale.write_text("gone after -Recreate", encoding="utf-8")

        comfy = self.workspace / "a ComfyUI of the test's own"
        comfy.mkdir()
        (comfy / "main.py").write_text("# not a real ComfyUI\n", encoding="utf-8")
        result = self.run_setup(
            "-VenvPath", str(venv), "-Recreate", "-SkipPipUpgrade",
            "-Config", str(self.workspace / "generated runtime.yaml"),
            "-Mode", "External", "-ComfyRoot", str(comfy),
            "-ComfyPort", str(free_port()), timeout=600)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("Removing existing environment", output)
        self.assert_repo_config_untouched()
        self.assertFalse(stale.exists(), "the old environment survived -Recreate")
        self.assertTrue((venv / "Scripts" / "python.exe").is_file(), output)

    @staticmethod
    def supported_floor():
        text = (REPO / "gateway" / "pyproject.toml").read_text(encoding="utf-8")
        match = re.search(r"requires-python\s*=\s*[\"']?[^\"'\n]*>=\s*(\d+\.\d+)", text)
        assert match, "no requires-python floor in gateway/pyproject.toml"
        return match.group(1)

    def test_the_supported_floor_comes_from_packaging_metadata(self):
        result = self.run_setup("-PythonExe", str(self.workspace / "not python.exe"))
        output = self.output_of(result)
        self.assertIn("Supported Python: >=", output)
        self.assertIn("gateway/pyproject.toml", output)

    @staticmethod
    def declared_python_specifier(pyproject=None):
        """requires-python as gateway/pyproject.toml declares it, in full."""
        path = pyproject if pyproject is not None else (REPO / "gateway" / "pyproject.toml")
        text = path.read_text(encoding="utf-8")
        match = re.search(
            r"^\s*requires-python\s*=\s*[\"']([^\"']+)[\"']", text, re.MULTILINE)
        assert match, "no requires-python in {}".format(path)
        return match.group(1).strip()

    def test_the_printed_range_is_the_whole_declared_specifier(self):
        """T-0279 B3: half the specifier is worse than none of it.

        Measured from a clean clone (T-0173): setup.ps1 printed "Supported
        Python: >= 3.10" while gateway/pyproject.toml declares ">=3.10,<3.14".
        On the machine that measured it the default `py` is 3.14 -- out of
        range -- so that line told a user their interpreter was supported, and
        pip would have refused it.
        """
        declared = self.declared_python_specifier()
        # Not a vacuous assertion: the declaration carries a ceiling as well as
        # a floor, which is the whole of what the printed line used to drop. If
        # this ever fails, the range has changed shape and this test no longer
        # measures the defect it was written for.
        self.assertIn(
            "<", declared,
            "gateway/pyproject.toml no longer declares a ceiling, so this test would "
            "pass against the floor-only line it exists to catch")

        result = self.run_setup("-PythonExe", str(self.workspace / "not python.exe"))
        output = self.output_of(result)
        self.assertIn(
            "[INFO] Supported Python: {} (from gateway/pyproject.toml)\n".format(declared),
            output)
        # And the line it replaced is gone, not merely joined.
        floor = re.match(r">=\s*(\d+\.\d+)", declared).group(1)
        self.assertNotIn(
            "Supported Python: >= {} (from gateway/pyproject.toml)".format(floor), output)

    def test_the_printed_range_follows_the_metadata_rather_than_a_second_copy(self):
        """The drift this card is about, driven in both directions.

        A COPY of the three files the line needs, in this test's own workspace
        -- setup.ps1, the library it loads and the gateway metadata it reads --
        and nothing here can reach the tracked ones. The declared range in the
        copy is changed to a range this project does not use, and the printed
        line has to follow it; then the line is hard-coded again, which is the
        mutation a review runs, and the assertion above has to notice.

        The copy never builds anything: -PythonExe names a file that does not
        exist, so the run stops right after printing the line.
        """
        copied = self.workspace / "metadata copy"
        (copied / "scripts" / "lib").mkdir(parents=True)
        (copied / "gateway").mkdir(parents=True)
        setup = copied / "scripts" / "setup.ps1"
        shutil.copyfile(SCRIPTS / "setup.ps1", setup)
        shutil.copyfile(SCRIPTS / "lib" / "Common.ps1",
                        copied / "scripts" / "lib" / "Common.ps1")
        pyproject = copied / "gateway" / "pyproject.toml"
        shutil.copyfile(REPO / "gateway" / "pyproject.toml", pyproject)
        self.assertTrue(path_is_inside(setup, self.workspace), setup)
        self.assertFalse(path_is_inside(setup, REPO), setup)

        invented = ">=3.11,<3.99"
        self.assertNotEqual(invented, self.declared_python_specifier())
        pyproject.write_text(
            re.sub(r"^(\s*requires-python\s*=\s*)[\"'][^\"']+[\"']",
                   r'\g<1>"{}"'.format(invented),
                   pyproject.read_text(encoding="utf-8"), count=1, flags=re.MULTILINE),
            encoding="utf-8")
        self.assertEqual(invented, self.declared_python_specifier(pyproject))

        output = self.output_of(self.run_copied_setup(setup))
        self.assertIn(
            "[INFO] Supported Python: {} (from gateway/pyproject.toml)\n".format(invented),
            output)

        # The mutation: the line hard-coded again, in the copy only.
        original = setup.read_text(encoding="utf-8")
        printed = ('        Write-LcInfo "Supported Python: $($floor.Specifier) '
                   '(from gateway/pyproject.toml)"\n')
        self.assertIn(printed, original, "the printed line has moved")
        setup.write_text(
            original.replace(
                printed,
                '        Write-LcInfo "Supported Python: >= $($floor.Major).$($floor.Minor) '
                '(from gateway/pyproject.toml)"\n', 1),
            encoding="utf-8")
        mutated_output = self.output_of(self.run_copied_setup(setup))
        self.assertIn(
            "[INFO] Supported Python: >= 3.11 (from gateway/pyproject.toml)\n",
            mutated_output)
        self.assertNotIn(
            "[INFO] Supported Python: {} (from gateway/pyproject.toml)\n".format(invented),
            mutated_output)

    def run_copied_setup(self, setup, timeout=180):
        """The copied setup.ps1, stopped by an interpreter that does not exist."""
        env = {k: v for k, v in os.environ.items() if not k.startswith("LC_STUB_")}
        env.pop("PYTHONPATH", None)
        env["LOCALCANVAS_RUNTIME_DIR"] = str(self.runtime_dir)
        return subprocess.run(
            [PWSH, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
             "-File", str(setup),
             "-PythonExe", str(self.workspace / "not python.exe")],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=timeout, env=env, cwd=str(REPO))


# ==========================================================================
# setup.ps1 as the first-time entrypoint (T-0321)
# ==========================================================================
#
# The target this section exists to hold: a newcomer who already runs ComfyUI
# types two commands and nothing else.
#
#     pwsh .\scripts\setup.ps1
#     pwsh .\scripts\start.ps1
#
# Measured before the work, on a clean public clone: setup exited 0 printing no
# next step and start then said "Configuration could not be loaded". Getting
# from one to the other took two file copies, seven hand-edited values across
# two files and four more commands. The number these tests hold is **zero
# configuration files edited by hand**.
#
# HOW THE OFFLINE FIXTURE WORKS, and why it is not the real repository.
#
# Almost everything here is about what setup DECIDES -- which questions it
# asks, what it writes, what it refuses, what it leaves alone -- and none of
# those decisions needs a package index. So the fixture is a COPY of the four
# things setup reads (itself, its library, the bootstrap layer's inspection
# helpers and the gateway's packaging metadata), with:
#
#   * a real virtual environment, built offline with `--without-pip`, so the
#     interpreter setup probes is a real interpreter and the version it reads
#     is a real version;
#   * a stand-in gateway package reached by a .pth file, so "can this
#     environment import the gateway, and is it THIS checkout" is a real
#     question with a real answer;
#   * Invoke-VenvPip NEUTERED IN THE COPY: its body is
#     replaced by one that reports success and runs no pip at all, and the copy
#     is then asserted to contain no pip invocation before anything runs it. A
#     test suite that installs packages from the internet on somebody's machine
#     is not a test suite.
#
# Nothing in this section writes inside this repository. The fixtures live in
# the test's own workspace, every path in them contains a space, and
# assert_repo_config_untouched is the tripwire for the one that forgets.


def declared_python_range(pyproject=None):
    """(floor, ceiling_exclusive) as gateway/pyproject.toml declares them."""
    path = pyproject if pyproject is not None else (REPO / "gateway" / "pyproject.toml")
    text = path.read_text(encoding="utf-8")
    match = re.search(r"^\s*requires-python\s*=\s*[\"']([^\"']+)[\"']", text, re.MULTILINE)
    assert match, "no requires-python in {}".format(path)
    declared = match.group(1)
    floor = re.search(r">=\s*(\d+)\.(\d+)", declared)
    ceiling = re.search(r"<(=?)\s*(\d+)\.(\d+)", declared)
    assert floor, declared
    return (
        (int(floor.group(1)), int(floor.group(2))),
        (int(ceiling.group(2)), int(ceiling.group(3)) + (1 if ceiling.group(1) else 0))
        if ceiling else None,
    )


def declared_requirements(pyproject=None):
    """(base, {extra: [...]}) as gateway/pyproject.toml declares them.

    Read HERE, by this suite, and deliberately not through
    scripts/lib/gateway_health.py: the fixture's installed record is written
    from this reading, and the checker then has to agree with it. A fixture
    built by the code under test would agree with anything (T-0182).
    """
    path = pyproject if pyproject is not None else (REPO / "gateway" / "pyproject.toml")
    text = "\n".join(line.split("#", 1)[0] for line in
                     path.read_text(encoding="utf-8").splitlines())
    base = re.search(r"(?ms)^dependencies\s*=\s*\[(.*?)^\]", text)
    assert base, "no dependency list in {}".format(path)
    section = re.search(
        r"(?ms)^\[project\.optional-dependencies\][ \t]*$(.*?)(?=^\[|\Z)", text)
    extras = {}
    if section:
        for found in re.finditer(r"(?m)^([A-Za-z0-9_-]+)\s*=\s*\[([^\]]*)\]", section.group(1)):
            extras[found.group(1)] = toml_strings(found.group(2))
    return toml_strings(base.group(1)), extras


def toml_strings(text):
    """The quoted strings in a TOML array body, either quote style."""
    return [double if double else single
            for double, single in re.findall(r"\"([^\"]*)\"|'([^']*)'", text)]


def declared_gateway_version():
    text = (REPO / "gateway" / "localcanvas_gateway" / "__init__.py").read_text(encoding="utf-8")
    found = re.search(r"(?m)^__version__\s*=\s*[\"']([^\"']+)[\"']", text)
    assert found, "the gateway declares no __version__"
    return found.group(1)


def write_distribution(site, name, version, requires=(), requires_python=None,
                       module=False):
    """An installed-distribution record, as importlib.metadata reads one.

    Only the fields the environment check reads. Nothing is installed: the
    record is the fact under test, and the fixture writes it by hand so each
    test can break exactly one part of it. ``module`` also writes an empty
    importable package named after the distribution, so the check's import
    probe has something to import -- and a test something to take away.
    """
    folder = Path(site) / "{}-{}.dist-info".format(re.sub(r"[-_.]+", "_", name), version)
    folder.mkdir()
    if module:
        package = Path(site) / re.sub(r"[-_.]+", "_", name).lower()
        package.mkdir(exist_ok=True)
        (package / "__init__.py").write_text("", encoding="utf-8")
    lines = ["Metadata-Version: 2.1", "Name: " + name, "Version: " + version]
    if requires_python:
        lines.append("Requires-Python: " + requires_python)
    lines += ["Requires-Dist: " + requirement for requirement in requires]
    (folder / "METADATA").write_text("\n".join(lines) + "\n", encoding="utf-8")
    (folder / "RECORD").write_text("", encoding="utf-8")
    return folder


def requirement_floor(requirement):
    """(name, a version the requirement accepts) for the `name>=X` shape."""
    found = re.match(r"^\s*([A-Za-z0-9][A-Za-z0-9._-]*)\s*(?:>=\s*([0-9][0-9.]*))?", requirement)
    assert found, requirement
    return found.group(1), (found.group(2) or "1.0")


def version_is_supported(version, floor, ceiling):
    if version < floor:
        return False
    return ceiling is None or version < ceiling


def interpreter_version(path):
    result = subprocess.run(
        [str(path), "-c", "import sys; print(*sys.version_info[:2], sep=chr(46))"],
        capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=120)
    if result.returncode != 0:
        return None
    try:
        major, minor = (result.stdout or "").strip().split(".")[:2]
        return (int(major), int(minor))
    except ValueError:
        return None


_SUPPORTED_INTERPRETER = "not looked for yet"


def supported_interpreter():
    """A real interpreter this machine has that is INSIDE the declared range.

    The fixture below builds an environment with it, and setup then has to
    accept that environment -- so it cannot be "whatever runs the suite": on a
    machine whose default Python is newer than the ceiling, that is exactly the
    interpreter setup is supposed to refuse. ``None`` when the machine has
    none, and the tests that need one skip rather than pretend.
    """
    global _SUPPORTED_INTERPRETER
    if _SUPPORTED_INTERPRETER != "not looked for yet":
        return _SUPPORTED_INTERPRETER
    floor, ceiling = declared_python_range()
    found = None
    running = interpreter_version(sys.executable)
    if running and version_is_supported(running, floor, ceiling):
        found = sys.executable
    else:
        last = (ceiling[1] - 1) if ceiling and ceiling[0] == floor[0] else floor[1] + 6
        for minor in range(floor[1], last + 1):
            selector = "-{}.{}".format(floor[0], minor)
            probe = subprocess.run(
                ["py", selector, "-c", "import sys; print(sys.executable)"],
                capture_output=True, text=True, encoding="utf-8",
                errors="replace", timeout=120)
            if probe.returncode == 0 and (probe.stdout or "").strip():
                found = (probe.stdout or "").strip().splitlines()[0]
                break
    _SUPPORTED_INTERPRETER = found
    return found


# The stand-in for the gateway's configuration seam. It is not the loader and
# does not pretend to be one -- what it answers is only ever used to drive the
# BEHAVIOUR of setup, and the real loader's verdict on a generated document is
# asserted separately, by test_a_generated_configuration_loads_in_the_real_loader.
FIXTURE_GATEWAY_MAIN = '''\
"""A stand-in for the gateway's configuration seam, for the test fixture.

It REPORTS the document rather than inventing one: comfy.root and
workflows.registry are read back out of the file that was just written, and a
relative registry is resolved the way the real loader resolves it (two
directories above the configuration file).  That matters because setup now
takes both values from the seam -- a stub that answered with constants would
let a setup which never reads the seam pass.

It is not the loader and does not pretend to be one: whether a generated
document is VALID is asserted separately, against the real load_config.
"""
import json
import os
import re
import sys

if __name__ == "__main__" and len(sys.argv) >= 2 and sys.argv[1] == "config":
    path = sys.argv[sys.argv.index("--config") + 1]
    if not os.path.isfile(path):
        sys.stderr.write("[FAIL] Configuration could not be loaded\\n")
        sys.exit(1)
    text = open(path, encoding="utf-8").read()
    if "runtime:" not in text:
        sys.stderr.write("[FAIL] that file is not a LocalCanvas configuration\\n")
        sys.exit(1)

    def scalar(key):
        found = re.search(r'(?m)^\\s{2}%s:\\s*"([^"]*)"\\s*$' % key, text)
        return found.group(1) if found else None

    repo_root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(path))))

    def resolved(value):
        if not value:
            return None
        value = value.replace("/", os.sep)
        if not os.path.isabs(value):
            value = os.path.join(repo_root, value)
        return os.path.normpath(value)

    port = int(os.environ.get("LC_FIXTURE_COMFY_PORT", "9"))
    print(json.dumps({
        "config_version": 3,
        "runtime": {"manage_comfy": bool(re.search(r"(?m)^\\s{2}manage_comfy:\\s*true", text))},
        "comfy": {"host": "127.0.0.1", "port": port,
                  "base_url": "http://127.0.0.1:%d" % port,
                  "root": resolved(scalar("root"))},
        "workflows": {"registry": resolved(scalar("registry"))},
        "gateway": {"host": "0.0.0.0",
                    "port": int(os.environ.get("LC_FIXTURE_GATEWAY_PORT", "10"))},
    }))
    sys.exit(0)
if __name__ == "__main__":
    sys.stderr.write("unrecognized arguments\\n")
    sys.exit(2)
'''


class BeginnerSetupTests(ScriptTestCase):
    """One command, two questions, a configuration that loads (T-0321)."""

    #: The stand-in seam is told to answer with a port nothing listens on, so
    #: the confirmation probe setup makes is a real probe that finds nothing.
    #: 8188 and 7801 -- ComfyUI's port and the gateway's -- are never contacted
    #: by this suite.
    FIXTURE_COMFY_PORT = "9"

    #: The gateway's REAL loader, run over a document this suite read itself.
    #:
    #: ``localcanvas_gateway.config`` uses PyYAML in exactly one place --
    #: ``_parse``, which turns the file's text into a mapping -- and this suite
    #: installs nothing (T-0312), so that one step is supplied by the reader the
    #: suite already owns: ``_parse_document`` in the stub environment, the
    #: documented subset of YAML every other runtime test reads configuration
    #: through, strict enough to refuse a line it cannot read rather than guess.
    #: NOTHING ELSE is stood in for. The validation, the defaults, the launcher
    #: resolution against ``comfy.root`` and the shape of the document are all
    #: the real loader's, which is the whole point of the test below.
    #:
    #: ``sys.argv[1]`` is that reader's file, ``sys.argv[2]`` the configuration.
    #: The shim goes into ``sys.modules`` before the loader is imported, so an
    #: installed PyYAML is never reached; the interpreter is also given ``-S``
    #: at the call site, which takes site-packages away entirely, so this is
    #: measured on what public CI hands the suite rather than on this machine.
    REAL_LOADER_PROGRAM = "\n".join((
        "import importlib.util, json, sys, types",
        "spec = importlib.util.spec_from_file_location('lc_runtime_yaml_reader', sys.argv[1])",
        "reader = importlib.util.module_from_spec(spec)",
        "spec.loader.exec_module(reader)",
        "shim = types.ModuleType('yaml')",
        "shim.YAMLError = type('YAMLError', (Exception,), {})",
        "shim.safe_load = lambda text: reader._parse_document(sys.argv[2], text)",
        "sys.modules['yaml'] = shim",
        "config = importlib.import_module('localcanvas_gateway.config')",
        "print(json.dumps(config.config_document(config.load_config(sys.argv[2])),"
        " default=str))",
    ))

    # -- the fixture -------------------------------------------------------

    def build_checkout(self, name="a local canvas checkout", declared=None,
                       neuter_pip=True):
        """A copy of what setup reads, in this test's own workspace."""
        root = self.workspace / name
        self.assertTrue(path_is_inside(root, self.workspace), root)
        self.assertFalse(path_is_inside(root, REPO), root)
        (root / "scripts" / "lib").mkdir(parents=True)
        (root / "comfy" / "lib").mkdir(parents=True)
        (root / "gateway" / "localcanvas_gateway").mkdir(parents=True)
        (root / "config" / "local").mkdir(parents=True)

        shutil.copyfile(SCRIPTS / "setup.ps1", root / "scripts" / "setup.ps1")
        for name_ in ("Common.ps1", "gateway_health.py"):
            shutil.copyfile(SCRIPTS / "lib" / name_, root / "scripts" / "lib" / name_)
        for name_ in ("Bootstrap.ps1", "Models.ps1"):
            shutil.copyfile(COMFY / "lib" / name_, root / "comfy" / "lib" / name_)

        metadata = (REPO / "gateway" / "pyproject.toml").read_text(encoding="utf-8")
        if declared is not None:
            metadata = re.sub(
                r"^(\s*requires-python\s*=\s*)[\"'][^\"']+[\"']",
                r'\g<1>"{}"'.format(declared), metadata, count=1, flags=re.MULTILINE)
        (root / "gateway" / "pyproject.toml").write_text(metadata, encoding="utf-8")
        # The checkout's version, where the packaging metadata reads it from
        # (tool.setuptools.dynamic): what the environment check compares the
        # installed record with.
        (root / "gateway" / "localcanvas_gateway" / "__init__.py").write_text(
            "__version__ = \"{}\"\n".format(declared_gateway_version()), encoding="utf-8")
        (root / "gateway" / "localcanvas_gateway" / "__main__.py").write_text(
            FIXTURE_GATEWAY_MAIN, encoding="utf-8")
        # The other entry modules the scripts run (`-m localcanvas_gateway.workflows`
        # and the sync command behind it), empty: the environment check imports
        # them (T-0352), and a fixture without them would be unhealthy for a
        # reason no test is about.
        sync = root / "gateway" / "localcanvas_gateway" / "workflows" / "sync"
        sync.mkdir(parents=True)
        for stub in (sync.parent / "__init__.py", sync.parent / "__main__.py",
                     sync / "__init__.py", sync / "cli.py"):
            stub.write_text("", encoding="utf-8")

        if neuter_pip:
            self.disarm_pip(root)
        return root

    def disarm_pip(self, root):
        """Replace Invoke-VenvPip's body, then prove no pip call is left.

        Proving what a step decides must not be a way to perform it. The copy
        about to be run installs nothing from anywhere, and that is checked
        rather than intended.
        """
        setup = root / "scripts" / "setup.ps1"
        original = setup.read_text(encoding="utf-8-sig")
        stubbed = re.sub(
            r"(?ms)^function Invoke-VenvPip \{.*?^\}",
            "function Invoke-VenvPip {\n"
            "    param([Parameter(Mandatory)][string[]]$Arguments, [switch]$BestEffort)\n"
            "    # Stubbed by the test suite: RECORDS what setup asked pip to do\n"
            "    # (T-0352 counts it) and, deliberately, runs no pip at all.\n"
            "    if ($env:LC_FIXTURE_PIP_LOG) {\n"
            "        Add-Content -LiteralPath $env:LC_FIXTURE_PIP_LOG -Value ($Arguments -join ' ') -Encoding utf8\n"
            "    }\n"
            "    return [pscustomobject]@{ Ok = $true; Said = @() }\n"
            "}",
            original, count=1)
        self.assertNotEqual(
            original, stubbed, "setup.ps1 has no Invoke-VenvPip to stub any more")
        setup.write_text(stubbed, encoding="utf-8")
        armed = sorted(
            path.name for path in root.rglob("*.ps1")
            if re.search(r"-m'\s*,\s*'pip'", path.read_text(encoding="utf-8-sig")))
        self.assertEqual(
            [], armed, "the copy about to be run can still invoke pip: " + str(armed))

    def build_environment(self, root, interpreter=None, name="the venv", healthy=True,
                          extras=()):
        """A real, offline virtual environment with the fixture gateway in it.

        ``healthy`` also writes the installed records a real install would have
        left -- the gateway's own, matching this checkout's pyproject.toml, and
        one per declared dependency at a version its specifier accepts -- so
        setup's environment check answers "nothing to install" (T-0352).
        ``extras`` adds the dependencies of those extras as well.
        """
        interpreter = interpreter or supported_interpreter()
        if interpreter is None:
            self.skipTest(
                "this machine has no Python inside the range gateway/pyproject.toml "
                "declares, so no environment setup would accept can be built")
        venv = root / name
        built = subprocess.run(
            [str(interpreter), "-m", "venv", "--without-pip", str(venv)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=300)
        self.assertEqual(0, built.returncode, built.stdout + built.stderr)
        self.assertTrue((venv / "pyvenv.cfg").is_file(), "the fixture is not a venv")
        self.site_packages(venv).joinpath("zzz-fixture-gateway.pth").write_text(
            str(root / "gateway") + "\n", encoding="utf-8")
        imported = subprocess.run(
            [str(venv / "Scripts" / "python.exe"), "-c",
             "import localcanvas_gateway as g; print(g.__file__)"],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120)
        # The fixture has to be able to do the thing the test is about to watch
        # setup check, or the assertion would be about the fixture (T-0182).
        self.assertEqual(0, imported.returncode, imported.stdout + imported.stderr)
        self.assertTrue(path_is_inside((imported.stdout or "").strip(), root / "gateway"))
        if healthy:
            self.record_installed_gateway(root, venv, extras=extras)
        return venv

    def record_installed_gateway(self, root, venv, extras=()):
        """The records `pip install --editable gateway` leaves, written by hand."""
        site = self.site_packages(venv)
        pyproject = Path(root) / "gateway" / "pyproject.toml"
        base, optional = declared_requirements(pyproject)
        specifier = re.search(
            r"(?m)^\s*requires-python\s*=\s*[\"']([^\"']+)[\"']",
            pyproject.read_text(encoding="utf-8")).group(1)
        version = re.search(
            r"__version__\s*=\s*\"([^\"]+)\"",
            (Path(root) / "gateway" / "localcanvas_gateway" / "__init__.py").read_text(
                encoding="utf-8")).group(1)
        requires = list(base) + [
            '{}; extra == "{}"'.format(requirement, extra)
            for extra, items in optional.items() for requirement in items]
        write_distribution(site, "localcanvas-gateway", version, requires, specifier)
        for requirement in list(base) + [item for extra in extras for item in optional[extra]]:
            write_distribution(site, *requirement_floor(requirement), module=True)
        return site

    def pip_log(self, root):
        """Where the stubbed Invoke-VenvPip of this checkout records its calls."""
        return self.workspace / "{} - pip calls.log".format(Path(root).name)

    def pip_calls(self, root):
        log = self.pip_log(root)
        if not log.exists():
            return []
        return [line.strip() for line in log.read_text(encoding="utf-8-sig").splitlines()
                if line.strip()]

    @staticmethod
    def site_packages(venv):
        return next((Path(venv) / "Lib").glob("site-packages"))

    def make_comfy(self, where, name="My ComfyUI", portable=False,
                   workflows=True, interpreter=True):
        """A ComfyUI on disk: both layouts, and neither of them real.

        Nothing here is ever started, and no ComfyUI of the person running
        these tests is looked for, read or touched.
        """
        comfy = Path(where) / name
        app = (comfy / "ComfyUI") if portable else comfy
        app.mkdir(parents=True)
        (app / "main.py").write_text("# not a real ComfyUI\n", encoding="utf-8")
        (app / "custom_nodes").mkdir()
        (app / "models" / "checkpoints").mkdir(parents=True)
        (app / "models" / "checkpoints" / "a model.safetensors").write_text(
            "pretend weights", encoding="utf-8")
        if interpreter:
            embedded = (comfy / "python_embeded") if portable else (app / "venv" / "Scripts")
            embedded.mkdir(parents=True)
            (embedded / "python.exe").write_text("not a real interpreter", encoding="utf-8")
            (embedded.parent / "Lib" / "site-packages").mkdir(parents=True)
        if workflows:
            folder = app / "user" / "default" / "workflows"
            folder.mkdir(parents=True)
            (folder / "my first workflow.json").write_text(
                '{"nodes": []}', encoding="utf-8")
        return comfy

    def run_setup_in(self, root, *args, env=None, timeout=300, stdin=None,
                     interactive=False):
        """Run the copied setup.ps1.

        ``interactive=True`` drops -NonInteractive, so the host would be
        WILLING to prompt. That is how the other interlock gets tested: a
        Read-Host under -NonInteractive throws, which would hide a setup that
        relies on nothing else.
        """
        environment = {k: v for k, v in os.environ.items() if not k.startswith("LC_STUB_")}
        environment.pop("PYTHONPATH", None)
        environment["LOCALCANVAS_RUNTIME_DIR"] = str(self.runtime_dir)
        environment["LC_FIXTURE_COMFY_PORT"] = self.FIXTURE_COMFY_PORT
        environment["LC_FIXTURE_PIP_LOG"] = str(self.pip_log(root))
        environment.update(env or {})
        command = [PWSH, "-NoProfile", "-ExecutionPolicy", "Bypass"]
        if not interactive:
            command.insert(2, "-NonInteractive")
        command += ["-File", str(Path(root) / "scripts" / "setup.ps1")]
        command.extend(str(argument) for argument in args)
        return subprocess.run(
            command, capture_output=True, text=True, encoding="utf-8",
            errors="replace", timeout=timeout, env=environment,
            stdin=subprocess.DEVNULL if stdin is None else stdin, cwd=str(REPO))

    def ready_checkout(self, **kwargs):
        """The common fixture: a checkout, an environment and a ComfyUI."""
        root = self.build_checkout(**kwargs)
        venv = self.build_environment(root)
        comfy = self.make_comfy(root)
        config = root / "config" / "local" / "runtime.yaml"
        return root, venv, comfy, config

    def setup_arguments(self, venv, config, comfy=None, mode="External"):
        arguments = ["-VenvPath", venv, "-SkipPipUpgrade", "-Config", config]
        if mode:
            arguments += ["-Mode", mode]
        if comfy is not None:
            arguments += ["-ComfyRoot", comfy]
        return arguments

    # -- 1, 2, 6: the environment ------------------------------------------

    def test_a_healthy_environment_is_reused_byte_for_byte(self):
        """"Reused" is a statement about the directory, not about a message.

        A setup that deleted and rebuilt the environment every run would print
        the same [ OK ] line, so the environment itself is what is compared --
        including a file that has no business surviving a rebuild.
        """
        root, venv, comfy, config = self.ready_checkout()
        keepsake = venv / "something the user left here.txt"
        keepsake.write_text("still here", encoding="utf-8")
        before = tree_snapshot(venv, skip=("__pycache__",))

        result = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)

        difference = snapshot_difference(before, tree_snapshot(venv, skip=("__pycache__",)))
        self.assertEqual(
            "", difference,
            "setup changed an environment it said it was reusing: " + difference)
        self.assertTrue(keepsake.is_file())
        self.assert_no_stack_trace(output)

    def test_a_supported_interpreter_is_accepted_and_named(self):
        root, venv, comfy, config = self.ready_checkout()
        result = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        floor, ceiling = declared_python_range()
        version = interpreter_version(venv / "Scripts" / "python.exe")
        self.assertIsNotNone(version, output)
        self.assertTrue(
            version_is_supported(version, floor, ceiling),
            "the fixture built an environment outside the declared range, so this "
            "test would pass whatever setup decided")
        self.assertIn("Python {}.{}".format(*version), output)

    # -- 3: too new, and refused before anything exists --------------------

    def test_an_interpreter_above_the_ceiling_is_refused_before_any_venv(self):
        """T-0282, and the whole reason this half of the card exists.

        Measured on a machine whose only Python was newer than the declared
        ceiling: setup printed the correct range, stamped [ OK ] on the
        interpreter, BUILT THE ENVIRONMENT, upgraded pip inside it, and only
        then did pip refuse. The candidates were generated from the floor by
        offset and the ceiling -- which the library had already parsed -- was
        never consulted.

        Driven deterministically rather than by hoping this machine has an
        out-of-range Python: the copy declares a range the running interpreter
        is outside of, and the assertion is that NO DIRECTORY EXISTS
        afterwards.
        """
        version = interpreter_version(sys.executable)
        self.assertIsNotNone(version)
        # A range that ends below the interpreter about to be offered, and
        # starts below it too -- so the refusal can only be the ceiling's.
        declared = ">=3.0,<{}.{}".format(version[0], version[1])
        root = self.build_checkout(declared=declared)
        venv = root / "the venv that must not appear"

        result = self.run_setup_in(
            root, "-PythonExe", sys.executable, "-VenvPath", venv, "-SkipPipUpgrade")
        output = self.output_of(result)

        self.assertEqual(1, result.returncode, output)
        self.assertFalse(venv.exists(), "setup built a venv on an interpreter pip refuses")
        self.assertEqual({}, tree_snapshot(venv))
        self.assertEqual(
            [], sorted(root.rglob("pyvenv.cfg")),
            "an environment was built somewhere despite the refusal")
        self.assertIn(declared, output, "the refusal did not name the declared range")
        self.assertIn("NOTHING has been created", output)
        self.assert_no_stack_trace(output)

    def test_the_candidate_versions_stop_at_the_declared_ceiling(self):
        """The list `py` is asked for never contains a version pip refuses.

        The other half of the same defect, and the one a machine cannot
        demonstrate on its own: even with the gate fixed, a candidate list that
        runs past the ceiling means setup ASKS this machine for interpreters it
        must not use, and on a machine that has one it finds it. Measured
        before the fix: the list was built from the floor by a hard-coded
        offset of six, so a declared ">=3.10,<3.14" produced -3.10 through
        -3.16 while Get-LcSupportedPythonFloor had parsed the ceiling all
        along.

        Asked of the function as data, across the declaration shapes, because
        the answer is a list and "no version above the ceiling is in it" is a
        statement about that list.
        """
        for declared, expected in (
                (">=3.10,<3.14", ["-3.10", "-3.11", "-3.12", "-3.13"]),
                (">=3.11,<=3.12", ["-3.11", "-3.12"]),
                (">=3.12,<4", ["-3.12", "-3.13", "-3.14", "-3.15", "-3.16",
                               "-3.17", "-3.18"]),
                (">=3.10", ["-3.10", "-3.11", "-3.12", "-3.13", "-3.14",
                            "-3.15", "-3.16"])):
            with self.subTest(declared=declared):
                self.assertEqual(expected, self.candidates_for(declared))

    def candidates_for(self, declared):
        """Get-InterpreterCandidate's answer for one declared range, as data."""
        root = self.build_checkout(
            name="candidates {}".format(re.sub(r"[^\d.]+", " ", declared).strip()),
            declared=declared)
        text = (root / "scripts" / "setup.ps1").read_text(encoding="utf-8-sig")
        function = re.search(r"(?ms)^function Get-InterpreterCandidate \{.*?^\}", text)
        self.assertIsNotNone(function, "Get-InterpreterCandidate has moved")
        driver = root / "ask for the candidates.ps1"
        driver.write_text(
            "Set-StrictMode -Version Latest\n"
            "$ErrorActionPreference = 'Stop'\n"
            ". '{common}'\n".format(common=root / "scripts" / "lib" / "Common.ps1") +
            function.group(0) + "\n"
            "@(Get-InterpreterCandidate -Floor (Get-LcSupportedPythonFloor)) | "
            "ConvertTo-Json -Compress\n",
            encoding="utf-8")
        result = subprocess.run(
            [PWSH, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
             "-File", str(driver)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120, cwd=str(REPO))
        self.assertEqual(0, result.returncode, self.output_of(result))
        return as_list(json.loads(result.stdout))

    def test_a_present_environment_above_the_ceiling_is_a_rebuild_not_a_rerun(self):
        """The wedge that is NOT in T-0282, and the worse half of it.

        With an unsupported .venv already on disk, setup used to wave it
        through -- "[ OK ] Environment already present - reusing it" -- and,
        when anything later failed, advise "run setup again": the one action
        that could never work, because running setup again reuses the same
        environment. -Recreate was never mentioned.

        So: the run must fail, it must say -Recreate, it must not say "run
        setup again", and the environment must still be there afterwards --
        refusing is not a licence to delete.
        """
        interpreter = supported_interpreter()
        if interpreter is None:
            self.skipTest("no interpreter inside the declared range on this machine")
        version = interpreter_version(interpreter)
        root = self.build_checkout(declared=">=3.0,<{}.{}".format(*version))
        venv = root / "the stale venv"
        subprocess.run([str(interpreter), "-m", "venv", "--without-pip", str(venv)],
                       capture_output=True, timeout=300, check=True)
        sentinel = venv / "still here afterwards.txt"
        sentinel.write_text("untouched", encoding="utf-8")
        before = tree_snapshot(venv, skip=("__pycache__",))

        result = self.run_setup_in(root, "-VenvPath", venv, "-SkipPipUpgrade")
        output = self.output_of(result)

        self.assertEqual(1, result.returncode, output)
        self.assertIn("-Recreate", output, "the refusal did not name the way out")
        self.assertNotIn(
            "run scripts\\setup.ps1 again", output.lower().replace("scripts\\setup.ps1", "scripts\\setup.ps1"),
            "the advice is still the one action that cannot work")
        self.assertNotIn("already present - reusing it", output)
        difference = snapshot_difference(before, tree_snapshot(venv, skip=("__pycache__",)))
        self.assertEqual("", difference,
                         "a refusal deleted or changed the environment: " + difference)
        self.assert_no_stack_trace(output)

    # -- 4: no interpreter at all ------------------------------------------

    def test_no_interpreter_in_range_is_an_actionable_error(self):
        """F3 (T-0352): somebody with no Python is told to INSTALL one, first.

        Measured before the card: with no `py` on PATH the whole of the advice
        was "Re-run with -PythonExe ...", which assumes the Python a beginner
        does not have. Two shapes, both with nothing created: no launcher at
        all, and a launcher that finds none of the supported versions. The
        second is made deterministic by declaring, in the copy, a range no
        machine has (`py -3.30` answers "No suitable Python runtime found");
        the words are then derived from THAT range, which is what proves they
        come from the metadata and not from a second copy in the script.
        """
        floor, ceiling = declared_python_range()
        self.assertIsNotNone(ceiling, "the declared range has no ceiling; the words below assume one")
        real = "Python {}.{} to {}.{}".format(floor[0], floor[1], ceiling[0], ceiling[1] - 1)
        for described, declared, words, env in (
                ("no py on PATH", None, real, {"PATH": str(self.workspace)}),
                ("py finds no supported version", ">=3.30,<3.32", "Python 3.30 to 3.31", None)):
            with self.subTest(case=described):
                root = self.build_checkout(name="no python - " + described, declared=declared)
                result = self.run_setup_in(
                    root, "-VenvPath", root / "never built", "-SkipPipUpgrade", env=env)
                output = self.output_of(result)
                self.assertEqual(1, result.returncode, output)
                self.assertFalse((root / "never built").exists(), output)
                self.assertEqual([], sorted(root.rglob("pyvenv.cfg")), output)
                self.assertIn("NOTHING has been created", output)
                install = output.find("Install " + words + " from https://www.python.org/downloads/")
                self.assertGreaterEqual(install, 0, "the error did not say to install Python: " + output)
                alternative = output.find("-PythonExe")
                self.assertGreater(alternative, install,
                                   "-PythonExe came before the advice to install Python")
                self.assert_no_stack_trace(output)

    # -- 5, 14, 17: what setup must not touch ------------------------------

    def test_a_whole_setup_run_changes_nothing_inside_comfyui(self):
        """ComfyUI, its embedded Python and the workflows are read only.

        One assertion over the whole tree, by content hash, which is what makes
        it cover the three rules at once: no dependency installed into
        ComfyUI's interpreter, no workflow file rewritten, and no model
        appearing because somebody ran a setup script.
        """
        root = self.build_checkout()
        venv = self.build_environment(root)
        comfy = self.make_comfy(root, name="A Portable ComfyUI", portable=True)
        config = root / "config" / "local" / "runtime.yaml"
        before = tree_snapshot(comfy)
        self.assertTrue(
            any("python.exe" in key for key in before),
            "the fixture has no embedded interpreter, so it proves nothing")
        self.assertTrue(
            any("safetensors" in key for key in before),
            "the fixture holds no model file, so it proves nothing")
        self.assertTrue(
            any("workflow" in key for key in before),
            "the fixture holds no workflow file, so it proves nothing")

        result = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        difference = snapshot_difference(before, tree_snapshot(comfy))
        self.assertEqual(
            "", difference,
            "setup changed something inside the user's ComfyUI: " + difference)
        self.assert_firewall_untouched()
        self.assert_repo_config_untouched()

    def test_setup_cannot_download_anything_but_its_own_dependencies(self):
        """A source rule, because a download nobody triggers cannot be observed.

        pip fetching the gateway's declared dependencies is the one network
        access this script has, and it goes through .venv's own pip. Anything
        else that can pull bytes off the internet -- or hand the job to the
        bootstrap layer, which CAN download models -- has no business here.
        """
        text = (SCRIPTS / "setup.ps1").read_text(encoding="utf-8-sig")
        code = "\n".join(line for _, line, _, _ in powershell_code_lines(text))
        for forbidden in ("Invoke-WebRequest", "Invoke-RestMethod", "Start-BitsTransfer",
                          "DownloadFile", "WebClient", "HttpClient", "curl.exe",
                          "InstallModels", "AcceptModelDownloads"):
            self.assertNotIn(forbidden, code, "setup.ps1 can now fetch bytes: " + forbidden)
        self.assertNotIn("comfy\\setup.ps1", code)
        self.assertNotIn("comfy/setup.ps1", code)
        # And the one it does have is through the environment's own pip.
        self.assertIn("'-m', 'pip'", text)
        for match in re.finditer(r"-m'\s*,\s*'pip'", text):
            window = text[max(0, match.start() - 200):match.start()]
            self.assertIn("$venvPython", window,
                          "a pip call that is not .venv's own pip")

    def test_setup_addresses_no_process_by_name(self):
        """docs/runtime.md's headline rule, asked of this file specifically.

        The repository-wide lint covers every script; this one is anchored
        here because setup.ps1 now starts external processes of its own, and
        the thing it may never do is look for one by image name.
        """
        text = (SCRIPTS / "setup.ps1").read_text(encoding="utf-8-sig")
        code = "\n".join(line for _, line, _, _ in powershell_code_lines(text))
        for forbidden in ("Stop-Process", "Get-Process", "taskkill", "Wait-Process"):
            self.assertNotIn(forbidden, code, "setup.ps1 now reaches for " + forbidden)
        # The processes it starts are stopped by the probe boundary, which
        # holds the object Start handed back -- never a name.
        library = (SCRIPTS / "lib" / "Common.ps1").read_text(encoding="utf-8-sig")
        body = powershell_function_body(library, "Invoke-LcExecutableProbe")
        self.assertIsNotNone(body)
        self.assertIn("$process.Kill()", body)
        self.assertNotIn("-Name", body)

    # -- 8, 9: ComfyUI that is not there, or is not one --------------------

    def test_a_comfyui_path_that_is_not_one_is_refused_and_nothing_is_written(self):
        root, venv, _comfy, config = self.ready_checkout()
        occupied = root / "a folder of something else"
        occupied.mkdir()
        (occupied / "notes.txt").write_text("mine", encoding="utf-8")
        empty = root / "an empty folder"
        empty.mkdir()
        a_file = root / "a file not a folder.txt"
        a_file.write_text("x", encoding="utf-8")

        for described, candidate in (
                ("nothing there", root / "no ComfyUI here"),
                ("an empty folder", empty),
                ("a folder of other things", occupied),
                ("a file", a_file)):
            with self.subTest(candidate=described):
                result = self.run_setup_in(
                    root, *self.setup_arguments(venv, config, candidate))
                output = self.output_of(result)
                self.assertEqual(1, result.returncode, output)
                self.assertFalse(
                    config.exists(),
                    "a refused ComfyUI path still produced a configuration")
                self.assertIn(str(candidate), output, "the refusal did not name the path")
                self.assertIn("-ComfyRoot", output, "the refusal did not say what to do")
                self.assert_no_stack_trace(output)

    def test_both_comfyui_layouts_are_recognised_and_the_launcher_is_derived(self):
        """F6: the launcher is read off the installation, not shipped.

        config/examples/runtime.example.yaml ships one layout's answer
        (`script: ComfyUI/main.py`), and against the other layout that produces
        a path with ComfyUI\\ComfyUI\\main.py in it -- which the doctor printed.
        Both layouts are therefore driven here, and the two answers must
        differ.
        """
        answers = {}
        for portable in (False, True):
            with self.subTest(portable=portable):
                root = self.build_checkout(
                    name="checkout {}".format("portable" if portable else "plain"))
                venv = self.build_environment(root)
                comfy = self.make_comfy(root, portable=portable)
                config = root / "config" / "local" / "runtime.yaml"
                result = self.run_setup_in(
                    root, *self.setup_arguments(venv, config, comfy, mode="Managed"))
                output = self.output_of(result)
                self.assertEqual(0, result.returncode, output)
                document = config.read_text(encoding="utf-8")
                answers[portable] = document
                script = re.search(r'^\s*script:\s*"([^"]+)"', document, re.MULTILINE)
                executable = re.search(
                    r'^\s*executable:\s*"([^"]+)"', document, re.MULTILINE)
                self.assertIsNotNone(script, document)
                self.assertIsNotNone(executable, document)
                # What matters is the path it RESOLVES to, so that is what is
                # checked -- against the file the fixture actually created.
                resolved = Path(comfy) / script.group(1).replace("/", os.sep)
                self.assertTrue(
                    resolved.is_file(),
                    "the launcher script does not exist: {}".format(resolved))
                self.assertEqual(
                    "main.py", resolved.name)
                self.assertNotIn(
                    "ComfyUI/ComfyUI", script.group(1),
                    "the doubled path is back")
                resolved_exe = Path(comfy) / executable.group(1).replace("/", os.sep)
                self.assertTrue(
                    resolved_exe.is_file(),
                    "the launcher interpreter does not exist: {}".format(resolved_exe))
        self.assertNotEqual(
            answers[False], answers[True],
            "both layouts produced the same launcher, so one of them is wrong")

    def test_managed_mode_will_not_invent_a_launcher_it_has_not_found(self):
        """A ComfyUI with no interpreter beside it.

        The example file offers `executable: "python"` for this case, and the
        gateway resolves a relative launcher path against comfy.root -- so that
        value becomes <root>\\python and names nothing. Refusing, and naming
        external mode, beats writing a file that cannot work.
        """
        root = self.build_checkout()
        venv = self.build_environment(root)
        comfy = self.make_comfy(root, interpreter=False)
        config = root / "config" / "local" / "runtime.yaml"
        result = self.run_setup_in(
            root, *self.setup_arguments(venv, config, comfy, mode="Managed"))
        output = self.output_of(result)
        self.assertEqual(1, result.returncode, output)
        self.assertFalse(config.exists(), output)
        self.assertIn("-Mode External", output)
        self.assert_no_stack_trace(output)

        # And the same installation in external mode is fine, with no launcher.
        result = self.run_setup_in(
            root, *self.setup_arguments(venv, config, comfy, mode="External"))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertTrue(config.is_file(), output)
        self.assertNotIn("launcher:", config.read_text(encoding="utf-8"))

    # -- 10, 11: configuration without a text editor -----------------------

    def test_a_first_run_writes_every_file_the_user_would_have_edited(self):
        """The whole point of the card, measured as files-you-must-edit: 0."""
        root, venv, comfy, config = self.ready_checkout()
        sources = config.parent / "workflow-sources.yaml"
        self.assertFalse(config.exists())
        self.assertFalse(sources.exists())

        result = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)

        self.assertTrue(config.is_file(), "no runtime configuration was written")
        self.assertTrue(sources.is_file(), "no workflow source list was written")
        document = config.read_text(encoding="utf-8")
        # Nothing a beginner has to fill in: no placeholder survived.
        self.assertNotIn("path/to", document)
        self.assertNotIn("TODO", document)
        # The values the audit settled, present and inferred rather than asked.
        self.assertRegex(document, r"(?m)^\s*manage_comfy:\s*false\s*$")
        self.assertRegex(document, r"(?m)^\s*extra_args:\s*\[\]\s*$")
        self.assertRegex(document, r'(?m)^\s*registry:\s*"config/local/workflows"\s*$')
        self.assertRegex(document, r'(?m)^\s*host:\s*"0\.0\.0\.0"\s*$')
        self.assertRegex(document, r"(?m)^\s*port:\s*7801\s*$")
        # The three sections that equal the code's own defaults are absent.
        for absent in ("startup:", "media:", "prompt_translation:"):
            self.assertNotIn(absent, document, absent + " is 27 lines of nothing")
        # The workflow source list points at ComfyUI's own workflow folder, and
        # that folder exists.
        listed = re.search(r'(?m)^\s*-\s*path:\s*"([^"]+)"', sources.read_text(encoding="utf-8"))
        self.assertIsNotNone(listed, sources.read_text(encoding="utf-8"))
        self.assertTrue(Path(listed.group(1)).is_dir(), listed.group(1))
        self.assertTrue(path_is_inside(listed.group(1), comfy), listed.group(1))
        # And the registry directory the gateway needs is there and empty.
        registry = Path(root) / "config" / "local" / "workflows"
        self.assertTrue(registry.is_dir(), "the workflow registry root was not created")
        self.assertEqual([], list(registry.iterdir()))
        # It ends by naming the one command to run next.
        self.assertIn("scripts\\start.ps1", output)

    def test_the_generated_configuration_is_ignored_by_git(self):
        """Asked of git, not of the .gitignore text.

        The generated files carry somebody's real ComfyUI path, so "config/local
        is gitignored" has to be true of the exact names setup writes.
        """
        answered = []
        for name in ("runtime.yaml", "workflow-sources.yaml", "workflows/a definition.yaml",
                     "imported-workflows/a graph.json", "workflow-inventory.json"):
            result = subprocess.run(
                ["git", "check-ignore", "-v", "--no-index",
                 "config/local/" + name],
                capture_output=True, text=True, encoding="utf-8",
                errors="replace", timeout=120, cwd=str(REPO))
            answered.append((name, result.returncode, (result.stdout or "").strip()))
        self.assertEqual(
            [], [item for item in answered if item[1] != 0],
            "git does not ignore what setup writes: {!r}".format(answered))
        # Not vacuous: git does answer, and a tracked file is not ignored.
        control = subprocess.run(
            ["git", "check-ignore", "-v", "--no-index", "scripts/setup.ps1"],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120, cwd=str(REPO))
        self.assertEqual(
            1, control.returncode,
            "git check-ignore calls a tracked file ignored, so this test means nothing")

    def test_a_generated_configuration_loads_in_the_real_loader(self):
        """The generated document, through the gateway's own load_config.

        The fixture's stand-in seam answers whatever it likes, so on its own it
        could not tell a valid document from a plausible one. This reads the
        real loader out of this checkout and gives it the file setup wrote.

        It used to skip where PyYAML was not importable, which read as care and
        was the opposite of it: the one interpreter this most needed to hold on
        is public CI's bare one, and there the test asserted nothing at all --
        while the `import yaml` it probed with was a third-party import in a
        suite that declares none, so the whole runtime-ownership group went red
        (T-0332). The loader's use of PyYAML is one step, and this suite has its
        own reader for that step; see REAL_LOADER_PROGRAM. Everything asserted
        below still comes out of the real loader, and nothing is skipped.
        """
        root, venv, comfy, config = self.ready_checkout()
        result = self.run_setup_in(
            root, *self.setup_arguments(venv, config, comfy, mode="Managed"))
        self.assertEqual(0, result.returncode, self.output_of(result))

        # In a subprocess, from the gateway source tree: this suite refuses to
        # run on an interpreter that carries the gateway, and importing it here
        # would put it in THIS process's sys.modules for every test after.
        read = subprocess.run(
            [sys.executable, "-S", "-c", self.REAL_LOADER_PROGRAM,
             str(STUB_ENV / GATEWAY_PACKAGE / "__main__.py"), str(config)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=180, cwd=str(REPO / "gateway"))
        self.assertEqual(0, read.returncode, read.stdout + read.stderr)
        document = json.loads(read.stdout)

        self.assertTrue(document["runtime"]["manage_comfy"])
        self.assertEqual(7801, document["gateway"]["port"])
        self.assertEqual([], list(document["comfy"]["extra_args"]))
        # The launcher the loader resolved names files that are really there --
        # which is the F6 defect stated as a fact about the disk.
        self.assertTrue(Path(document["comfy"]["launcher"]["script_path"]).is_file())
        self.assertTrue(Path(document["comfy"]["launcher"]["executable_path"]).is_file())
        self.assertEqual(
            Path(document["workflows"]["registry"]),
            Path(root) / "config" / "local" / "workflows")

    # -- 12, 13: run it again ----------------------------------------------

    def test_a_second_run_changes_nothing_and_says_so(self):
        """State first, sentence second.

        Until T-0352 this docstring declared that a second run re-ran
        `pip install --editable` every time, so "Nothing to change." could only
        be a claim about the configuration. It is now a claim about the whole
        checkout: setup asks the environment first and installs nothing into a
        healthy one, which the fixture here is -- and the pip calls are counted
        below as well as the bytes. A `git pull` that adds a dependency is
        still caught: that is an unhealthy environment, and
        test_an_unhealthy_environment_is_reinstalled_and_says_why drives it.
        """
        root, venv, comfy, config = self.ready_checkout()
        first = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
        self.assertEqual(0, first.returncode, self.output_of(first))
        self.assertNotIn("Nothing to change.", self.output_of(first))
        before = tree_snapshot(root, skip=("__pycache__",))

        second = self.run_setup_in(root, "-VenvPath", venv, "-SkipPipUpgrade",
                                   "-Config", config)
        output = self.output_of(second)
        self.assertEqual(0, second.returncode, output)
        # THE STATE, first: the whole checkout -- content, timestamps and the
        # set of names -- is identical. Only then the sentence claiming it.
        difference = snapshot_difference(before, tree_snapshot(root, skip=("__pycache__",)))
        self.assertEqual(
            "", difference, "a second setup run changed something on disk: " + difference)
        # And only then the sentence that claims it.
        self.assertIn("Nothing to change.", output)
        # A second run asks nothing at all: no question was printed.
        self.assertNotIn("Question 1 of 2", output)
        self.assertNotIn("Question 2 of 2", output)
        self.assertEqual([], self.pip_calls(root), "a run on a healthy environment ran pip")

    # -- T-0352: a rerun installs nothing, and needs no network -------------

    def test_a_healthy_environment_is_rerun_with_no_pip_and_no_index(self):
        """F1, as it was measured, stated in what setup asks pip to do.

        The measurement (T-0349): on a fully set-up machine with the package
        index unreachable, the second run died with exit 1 -- `Could not find a
        version that satisfies the requirement setuptools>=61` -- because every
        run re-ran `pip install --editable gateway`, whose isolated build
        environment fetches setuptools from the index. Before this card the
        stubbed pip below recorded `install --upgrade pip` and
        `install --editable <gateway>` on EVERY run; that is the mistake this
        holds to zero.

        The index is pointed at a closed loopback port for the whole test, so
        were anything to reach for it, it would find nothing. The stub runs no
        pip either way; the real, unstubbed offline rerun -- with the dist-info
        RECORD hash and mtimes compared -- is
        SetupTests.test_builds_the_environment_on_the_supported_floor_and_installs_the_gateway,
        an integration test because its first run fetches from the index.
        """
        root, venv, comfy, config = self.ready_checkout()
        offline = {"PIP_INDEX_URL": "http://127.0.0.1:{}/simple".format(free_port()),
                   "PIP_NO_INDEX": "1"}
        first = self.run_setup_in(
            root, "-VenvPath", venv, "-Config", config, "-Mode", "External",
            "-ComfyRoot", comfy, env=offline)
        self.assertEqual(0, first.returncode, self.output_of(first))
        site = self.site_packages(venv)
        before = tree_snapshot(site, skip=("__pycache__",))
        self.assertTrue(any("localcanvas_gateway-" in key for key in before),
                        "the fixture has no installed record, so it proves nothing")

        again = self.run_setup_in(root, "-VenvPath", venv, "-Config", config, env=offline)
        output = self.output_of(again)
        self.assertEqual(0, again.returncode, output)
        self.assertEqual(
            [], self.pip_calls(root),
            "setup ran pip on an environment that needed nothing -- the call that fails offline")
        self.assertEqual("", snapshot_difference(before, tree_snapshot(site, skip=("__pycache__",))))
        self.assertIn("Nothing to change.", output)
        self.assertIn("nothing to install", output)
        self.assertNotIn("Upgrading pip", output)
        self.assertNotIn("Reinstalling", output)
        # Nothing was installed, so nothing is said about how installs ran.
        self.assertNotIn("every install above", output)

    def break_environment(self, how, root, venv):
        """One way an installed environment stops matching this checkout."""
        site = self.site_packages(venv)
        record = next(site.glob("localcanvas_gateway-*.dist-info"))
        if how == "no installed record":
            shutil.rmtree(record)
            return "there is no installed record of localcanvas-gateway"
        if how == "the checkout's version was bumped":
            init = Path(root) / "gateway" / "localcanvas_gateway" / "__init__.py"
            init.write_text("__version__ = \"99.0.0\"\n", encoding="utf-8")
            return "and this checkout is 99.0.0"
        if how == "a declared dependency is missing":
            base, _ = declared_requirements(Path(root) / "gateway" / "pyproject.toml")
            name = requirement_floor(base[-1])[0]
            folder = next(site.glob("{}-*.dist-info".format(re.sub(r"[-_.]+", "_", name))))
            shutil.rmtree(folder)
            return "{} is not installed".format(name.lower())
        if how == "a declared dependency is too old":
            base, _ = declared_requirements(Path(root) / "gateway" / "pyproject.toml")
            name, floor = requirement_floor(base[0])
            folder = next(site.glob("{}-*.dist-info".format(re.sub(r"[-_.]+", "_", name))))
            shutil.rmtree(folder)
            write_distribution(site, name, "0.0.1")
            return "{} 0.0.1 is installed, and the gateway needs >={}".format(name.lower(), floor)
        if how == "the checkout now declares another dependency":
            pyproject = Path(root) / "gateway" / "pyproject.toml"
            text = pyproject.read_text(encoding="utf-8")
            changed = re.sub(r"(?m)^(dependencies\s*=\s*\[)", r'\1\n    "an-added-dependency>=1.0",',
                             text, count=1)
            self.assertNotEqual(text, changed, "the dependency list has moved")
            pyproject.write_text(changed, encoding="utf-8")
            return "now declared: an-added-dependency"
        raise AssertionError(how)

    def test_an_unhealthy_environment_is_reinstalled_and_says_why(self):
        """Each way the check must say "no" -- and each one reinstalls, once.

        A health check that always said "healthy" would pass the test above,
        so this is its other half: every variant here starts from the very
        fixture that test proves healthy, breaks exactly one thing, and must
        produce exactly one `install --editable` and a one-line reason naming
        what it found. No pip upgrade: the environment was not created by
        this run.
        """
        for how in ("no installed record", "the checkout's version was bumped",
                    "a declared dependency is missing", "a declared dependency is too old",
                    "the checkout now declares another dependency"):
            with self.subTest(how=how):
                root = self.build_checkout(name="unhealthy - " + how)
                venv = self.build_environment(root)
                comfy = self.make_comfy(root)
                config = root / "config" / "local" / "runtime.yaml"
                # The control, on the same fixture: healthy until broken.
                control = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
                self.assertEqual(0, control.returncode, self.output_of(control))
                self.assertEqual([], self.pip_calls(root), self.output_of(control))

                said = self.break_environment(how, root, venv)
                result = self.run_setup_in(root, "-VenvPath", venv, "-Config", config)
                output = self.output_of(result)
                self.assertEqual(0, result.returncode, output)
                self.assertEqual(
                    ["install --editable {}".format(root / "gateway")], self.pip_calls(root),
                    "an unhealthy environment was not reinstalled exactly once")
                reason = [line for line in output.splitlines()
                          if "Reinstalling the LocalCanvas gateway into .venv:" in line]
                self.assertEqual(1, len(reason), output)
                self.assertIn(said, reason[0].lower())
                self.assertNotIn("Nothing to change.", output)
                self.assertIn("Setup complete", output)
                self.assertIn("every install above", output)

    def test_a_gateway_imported_from_elsewhere_is_reinstalled_then_refused(self):
        """The provenance rule, now asked BEFORE the install as well as after.

        The check says "no" and names the import; the reinstall is attempted
        (a real one would put this checkout's editable finder in place); and
        the post-install check -- unchanged -- still refuses, because a
        directory on PYTHONPATH outranks anything pip can do.
        """
        root, venv, comfy, config = self.ready_checkout()
        elsewhere = self.workspace / "a stale install"
        (elsewhere / "localcanvas_gateway").mkdir(parents=True)
        (elsewhere / "localcanvas_gateway" / "__init__.py").write_text(
            "__version__ = \"{}\"\n".format(declared_gateway_version()), encoding="utf-8")
        result = self.run_setup_in(
            root, *self.setup_arguments(venv, config, comfy),
            env={"PYTHONPATH": str(elsewhere)})
        output = self.output_of(result)
        self.assertEqual(1, result.returncode, output)
        self.assertEqual(["install --editable {}".format(root / "gateway")], self.pip_calls(root))
        reason = [line for line in output.splitlines() if "Reinstalling" in line]
        self.assertEqual(1, len(reason), output)
        self.assertIn("not this checkout's", reason[0])
        self.assertIn(str(elsewhere).lower(), output.lower())
        self.assertFalse(config.exists(), output)

    def test_dev_installs_the_test_extra_only_when_it_is_missing(self):
        root, venv, comfy, config = self.ready_checkout()
        first = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy), "-Dev")
        output = self.output_of(first)
        self.assertEqual(0, first.returncode, output)
        self.assertEqual(
            ["install --editable {}[test]".format(root / "gateway")], self.pip_calls(root))
        self.assertIn("(the test extra)", output)

        # The extra's dependencies now present: the same -Dev run asks for nothing.
        self.pip_log(root).unlink()
        _, optional = declared_requirements(root / "gateway" / "pyproject.toml")
        for requirement in optional["test"]:
            write_distribution(self.site_packages(venv), *requirement_floor(requirement))
        again = self.run_setup_in(root, "-VenvPath", venv, "-Config", config, "-Dev")
        output = self.output_of(again)
        self.assertEqual(0, again.returncode, output)
        self.assertEqual([], self.pip_calls(root), output)
        self.assertIn("Nothing to change.", output)

    def test_pip_is_upgraded_only_in_an_environment_this_run_created(self):
        """A new environment gets a pip upgrade; one that is already there never does.

        Driven through the real `python -m venv` (offline: ensurepip unpacks
        the wheel the interpreter ships) so the "created" branch is the real
        one. The fixture gateway is reached through PYTHONPATH pointing INTO
        this checkout's gateway/, which the provenance rule accepts.
        """
        root = self.build_checkout()
        comfy = self.make_comfy(root)
        config = root / "config" / "local" / "runtime.yaml"
        venv = root / "a venv this run creates"
        interpreter = supported_interpreter()
        if interpreter is None:
            self.skipTest("no interpreter inside the declared range on this machine")
        reach = {"PYTHONPATH": str(root / "gateway")}
        created = self.run_setup_in(
            root, "-PythonExe", interpreter, "-VenvPath", venv, "-Config", config,
            "-Mode", "External", "-ComfyRoot", comfy, env=reach)
        output = self.output_of(created)
        self.assertEqual(0, created.returncode, output)
        self.assertEqual(
            ["install --upgrade pip", "install --editable {}".format(root / "gateway")],
            self.pip_calls(root), output)

        # Same environment, still no installed record: reinstalled, NOT upgraded.
        self.pip_log(root).unlink()
        again = self.run_setup_in(root, "-VenvPath", venv, "-Config", config, env=reach)
        output = self.output_of(again)
        self.assertEqual(0, again.returncode, output)
        self.assertEqual(
            ["install --editable {}".format(root / "gateway")], self.pip_calls(root), output)

    # -- T-0352 rework: the whole tree, and what actually imports ----------

    def reinstall_reason(self, root, output):
        """The one reason line of a run that reinstalled exactly once."""
        self.assertEqual(
            ["install --editable {}".format(Path(root) / "gateway")], self.pip_calls(root),
            "not exactly one reinstall:\n" + output)
        reasons = [line for line in output.splitlines()
                   if "Reinstalling the LocalCanvas gateway into .venv:" in line]
        self.assertEqual(1, len(reasons), output)
        return reasons[0]

    def assert_healthy_control(self, root, venv, config, comfy=None):
        arguments = (self.setup_arguments(venv, config, comfy) if comfy is not None
                     else ["-VenvPath", venv, "-Config", config])
        control = self.run_setup_in(root, *arguments)
        self.assertEqual(0, control.returncode, self.output_of(control))
        self.assertEqual([], self.pip_calls(root),
                         "the control is not healthy, so the break proves nothing:\n"
                         + self.output_of(control))

    def test_a_missing_transitive_dependency_is_reinstalled(self):
        """R1 of the review: a dependency's dependency is part of "healthy".

        Measured on the first version of this card: `pip uninstall -y starlette`
        (fastapi's dependency, not the gateway's) left setup saying "nothing to
        install", and the configuration check then failed on
        `No module named 'starlette'` on every run -- where main reinstalled.
        The fixture's fastapi record declares starlette, exactly as the real
        one does; its record is taken away and nothing else.
        """
        root, venv, comfy, config = self.ready_checkout()
        site = self.site_packages(venv)
        fastapi = next(site.glob("fastapi-*.dist-info"))
        version = fastapi.name[len("fastapi-"):-len(".dist-info")]
        shutil.rmtree(fastapi)
        write_distribution(site, "fastapi", version, requires=("starlette<1,>=0.40.0",))
        starlette = write_distribution(site, "starlette", "0.40.0", module=True)
        self.assert_healthy_control(root, venv, config, comfy)

        shutil.rmtree(starlette)
        result = self.run_setup_in(root, "-VenvPath", venv, "-Config", config)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        reason = self.reinstall_reason(root, output)
        self.assertIn("starlette is not installed", reason)
        self.assertIn("fastapi", reason, "the reason does not say what needs it")

    def test_a_dependency_whose_files_are_gone_is_reinstalled(self):
        """R1, the other half: a record on disk is not an importable package.

        The package directory is removed and its dist-info left in place --
        the state the review measured with segno, where the record said
        "installed" and `import segno` failed. The fixture's sync entry module
        imports it, as the real gateway's entry modules import their
        dependencies; the check imports the entry modules.
        """
        root, venv, comfy, config = self.ready_checkout()
        site = self.site_packages(venv)
        entry = root / "gateway" / "localcanvas_gateway" / "workflows" / "sync" / "cli.py"
        entry.write_text("import segno\n", encoding="utf-8")
        self.assertTrue((site / "segno" / "__init__.py").is_file(), "the fixture has no segno")
        self.assert_healthy_control(root, venv, config, comfy)

        shutil.rmtree(site / "segno")
        self.assertTrue(any(site.glob("segno-*.dist-info")), "the record went too")
        result = self.run_setup_in(root, "-VenvPath", venv, "-Config", config)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        reason = self.reinstall_reason(root, output)
        self.assertIn("segno", reason)
        self.assertIn("import", reason.lower())
        # A reinstall does not bring back files pip believes are installed
        # (measured on a real environment), so the run says so, with the
        # remedy that does work.
        self.assertIn("still reports", output)
        self.assertIn("setup.ps1 -Recreate", output)

    def test_a_broken_environment_that_breaks_the_configuration_check_names_recreate(self):
        """Where the damage reaches the configuration seam too, the advice follows it.

        Measured on a real environment with segno's files gone: the reinstall
        cannot restore them, and the configuration check -- which runs inside
        the environment -- then failed with "Correct the configuration", the
        advice the review objected to. The fixture's seam imports segno here,
        as the real gateway's __main__ does (through pairing.py).
        """
        root, venv, comfy, config = self.ready_checkout()
        site = self.site_packages(venv)
        main = root / "gateway" / "localcanvas_gateway" / "__main__.py"
        main.write_text("import segno\n" + main.read_text(encoding="utf-8"), encoding="utf-8")
        self.assert_healthy_control(root, venv, config, comfy)

        shutil.rmtree(site / "segno")
        result = self.run_setup_in(root, "-VenvPath", venv, "-Config", config)
        output = self.output_of(result)
        self.assertEqual(1, result.returncode, output)
        self.assertIn("segno", self.reinstall_reason(root, output))
        self.assertIn("Rebuild it: pwsh .\\scripts\\setup.ps1 -Recreate", output)
        self.assertNotIn("Correct the configuration", output)
        self.assert_no_stack_trace(output)

    def test_a_checker_that_cannot_answer_is_a_reinstall_and_never_healthy(self):
        """R2: "cannot decide" is "unhealthy", for every way the check can fail.

        The checker in the copy is replaced by one that misbehaves in one
        way each; the deadline is shortened IN THE COPY for the one that
        never answers, so the test does not wait out the real one.
        """
        cases = (
            ("prints something that is not JSON", "print('this is not json')\n",
             "did not answer"),
            ("prints JSON without the answer", "print('{\"something\": 1}')\n",
             "did not answer"),
            ("exits 3", "import sys\nsys.exit(3)\n", "exited with code 3"),
            ("crashes", "raise RuntimeError('the checker broke')\n", "exited with code 1"),
            ("never answers", "import time\ntime.sleep(60)\n", "did not answer within"),
        )
        for described, program, expected in cases:
            with self.subTest(checker=described):
                root = self.build_checkout(name="checker - " + described)
                venv = self.build_environment(root)
                config = root / "config" / "local" / "runtime.yaml"
                comfy = self.make_comfy(root)
                self.assert_healthy_control(root, venv, config, comfy)

                (root / "scripts" / "lib" / "gateway_health.py").write_text(
                    program, encoding="utf-8")
                setup = root / "scripts" / "setup.ps1"
                text = setup.read_text(encoding="utf-8-sig")
                deadline = "$script:HealthCheckSeconds = "
                self.assertEqual(1, text.count(deadline), "the check's deadline has moved")
                setup.write_text(
                    re.sub(r"(?m)^\$script:HealthCheckSeconds = \d+", "$script:HealthCheckSeconds = 4",
                           text, count=1), encoding="utf-8")

                result = self.run_setup_in(root, "-VenvPath", venv, "-Config", config)
                output = self.output_of(result)
                self.assertEqual(0, result.returncode, output)
                self.assertNotIn("nothing to install", output)
                reason = self.reinstall_reason(root, output)
                self.assertIn(expected, reason)

    def test_requirements_with_markers_and_extras_are_decided(self):
        """R2: a marker or an extra is evaluated, not waved through or refused.

        The copy's pyproject declares a dependency whose marker is true here,
        one whose marker is false here, one requested WITH an extra whose
        record makes that extra pull in a further dependency, and -- in its
        own subtest -- one whose marker names a variable PEP 508 does not
        have, which cannot be decided and so is "unhealthy".
        """
        added = [
            'marker-true-dep>=1.0; python_version >= "3.0"',
            'marker-false-dep>=1.0; python_version < "3.0"',
            'extra-host[feature]>=1.0',
        ]

        def checkout(name, extra_lines):
            root = self.build_checkout(name=name)
            pyproject = root / "gateway" / "pyproject.toml"
            text = pyproject.read_text(encoding="utf-8")
            lines = "".join("\n    '{}',".format(line) for line in extra_lines)
            changed = re.sub(r"(?m)^(dependencies\s*=\s*\[)", lambda m: m.group(1) + lines,
                             text, count=1)
            self.assertNotEqual(text, changed)
            pyproject.write_text(changed, encoding="utf-8")
            venv = self.build_environment(root)
            site = self.site_packages(venv)
            # The fixture recorded every declared name; the false-marker one is
            # then taken away (it would not be installed), and extra-host gets
            # the record that makes [feature] mean something.
            shutil.rmtree(next(site.glob("marker_false_dep-*.dist-info")))
            shutil.rmtree(next(site.glob("extra_host-*.dist-info")))
            write_distribution(site, "extra-host", "1.0", requires=(
                'feature-dep>=2.0; extra == "feature"',
                'unrelated-dep>=1.0; extra == "other"'), module=True)
            write_distribution(site, "feature-dep", "2.0", module=True)
            return root, venv, site, root / "config" / "local" / "runtime.yaml"

        root, venv, site, config = checkout("markers - healthy", added)
        self.assert_healthy_control(root, venv, config, self.make_comfy(root))

        for described, remove, expected in (
                ("the extra's dependency is missing", "feature_dep", "feature-dep is not installed"),
                ("the true marker's dependency is missing", "marker_true_dep",
                 "marker-true-dep is not installed")):
            with self.subTest(case=described):
                self.pip_log(root).unlink(missing_ok=True)
                folder = next(site.glob("{}-*.dist-info".format(remove)))
                kept = self.workspace / ("kept " + folder.name)
                shutil.move(str(folder), str(kept))
                try:
                    result = self.run_setup_in(root, "-VenvPath", venv, "-Config", config)
                    output = self.output_of(result)
                    self.assertEqual(0, result.returncode, output)
                    self.assertIn(expected, self.reinstall_reason(root, output))
                finally:
                    shutil.move(str(kept), str(folder))

        with self.subTest(case="a marker nobody can evaluate"):
            root, venv, site, config = checkout(
                "markers - undecidable", added + ['odd-dep>=1.0; no_such_variable == "x"'])
            result = self.run_setup_in(root, *self.setup_arguments(
                venv, config, self.make_comfy(root)))
            output = self.output_of(result)
            self.assertEqual(0, result.returncode, output)
            self.assertIn("cannot be checked", self.reinstall_reason(root, output))

    def test_the_import_probe_covers_every_module_the_scripts_run(self):
        """The check imports what the scripts run, named from the scripts.

        Every `-m localcanvas_gateway...` target in scripts/ has to be among
        the modules gateway_health.py imports, so a new entry point cannot be
        added without the check learning to import it.
        """
        targets = set()
        for path in sorted(list(SCRIPTS.glob("*.ps1")) + list((SCRIPTS / "lib").glob("*.ps1"))):
            for found in re.finditer(r"'-m',\s*'(localcanvas_gateway[\w.]*)'",
                                     path.read_text(encoding="utf-8-sig")):
                targets.add(found.group(1))
        self.assertIn("localcanvas_gateway", targets, "no entry point found; the scan is broken")
        program = ("import json, sys; sys.path.insert(0, sys.argv[1]); import gateway_health as h; "
                   "print(json.dumps(list(h.RUNTIME_MODULES)))")
        read = subprocess.run([sys.executable, "-S", "-c", program, str(SCRIPTS / "lib")],
                              capture_output=True, text=True, encoding="utf-8",
                              errors="replace", timeout=120, cwd=str(self.workspace))
        self.assertEqual(0, read.returncode, read.stdout + read.stderr)
        probed = set(json.loads(read.stdout))
        for target in sorted(targets):
            with self.subTest(target=target):
                self.assertTrue(target + ".__main__" in probed or target in probed,
                                "{} is run by a script and not imported by the check".format(target))

    def test_the_environment_check_reads_what_this_suite_reads(self):
        """The checker's own reader and version rules, asked as data.

        gateway_health.py reads gateway/pyproject.toml without tomllib (3.10
        has none), so its reading of the REAL file is compared with this
        suite's independent one; and its specifier rules are held to the
        PEP 440 answers for the shapes that matter here.
        """
        program = "\n".join((
            "import json, sys",
            "sys.path.insert(0, sys.argv[1])",
            "import gateway_health as h",
            "t = h.read_pyproject(sys.argv[2])",
            "cases = json.loads(sys.argv[3])",
            "print(json.dumps({'base': t['project']['dependencies'],",
            "  'extras': t['project.optional-dependencies'],",
            "  'python': t['project']['requires-python'],",
            "  'verdicts': [h.satisfies(v, tuple(s.split(','))) for v, s in cases]}))",
        ))
        cases = [
            ("0.110", ">=0.110", True), ("1.0rc1", ">=1.0", False),
            ("1.0.dev1", "<1.0", True), ("1.0.post1", ">1.0", True),
            ("2.0", "<2", False), ("1.11.3", ">=1.11,<2", True),
            ("1.4", "~=1.3", True), ("2.0", "~=1.3", False),
            ("1.2.3", "==1.2.*", True), ("1.3", "!=1.2.*", True),
            ("1.0", "==1", True), ("0.0.32", ">=0.0.7", True),
            ("0.0.6", ">=0.0.7", False), ("not a version", ">=1", None),
            ("3.10.11", "==3.10.*", True), ("3.10", "==3.10.*", True),
            ("3.10.11", "==3.1.*", False), ("3.10.11", "!=3.10.*", False),
            ("3.1.4", "!=3.10.*", True), ("3.10", "==3.*", True),
        ]
        read = subprocess.run(
            [sys.executable, "-S", "-c", program, str(SCRIPTS / "lib"),
             str(REPO / "gateway" / "pyproject.toml"),
             json.dumps([[v, s] for v, s, _ in cases])],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120, cwd=str(self.workspace))
        self.assertEqual(0, read.returncode, read.stdout + read.stderr)
        answer = json.loads(read.stdout)
        base, extras = declared_requirements()
        self.assertEqual(base, answer["base"])
        self.assertEqual(extras, answer["extras"])
        self.assertTrue(answer["python"].startswith(">="), answer["python"])
        self.assertEqual([expected for _, _, expected in cases], answer["verdicts"])

    def test_the_environment_check_evaluates_markers_as_pep_508_does(self):
        """The marker rules the tree walk uses, asked as data (T-0352 rework).

        Every expected value is computed HERE, from the interpreter that runs
        the check (the suite's own, in the subprocess below) -- not written
        down for one machine. None means "cannot be decided", which the check
        turns into a reinstall.
        """
        import platform
        version = sys.version_info[:2]
        cases = [
            ('python_version < "3.11"', [], version < (3, 11)),
            ('python_version >= "3.10"', [], version >= (3, 10)),
            ('"3.8" <= python_version', [], version >= (3, 8)),
            ('python_full_version >= "3.0.0"', [], True),
            ('sys_platform == "win32"', [], sys.platform == "win32"),
            ("sys_platform != 'win32'", [], sys.platform != "win32"),
            ('platform_system == "Windows"', [], platform.system() == "Windows"),
            ('os_name == "nt" or sys_platform == "cygwin"', [],
             os.name == "nt" or sys.platform == "cygwin"),
            ('(os_name == "nt" or sys_platform == "cygwin") and python_version < "3.0"', [], False),
            ('implementation_name == "cpython"', [], sys.implementation.name == "cpython"),
            ('platform_python_implementation != "PyPy"', [],
             platform.python_implementation() != "PyPy"),
            ('python_version in "3.9 3.10 3.11"', [],
             "{}.{}".format(*version) in "3.9 3.10 3.11"),
            ('python_version not in "2.7"', [], "{}.{}".format(*version) not in "2.7"),
            ('extra == "test"', [], False),
            ('extra == "test"', ["test"], True),
            ('extra == "Test_Extra"', ["test-extra"], True),
            ('python_version < "3.0" and extra == "test"', ["test"], False),
            # Wildcards (T-0352 re-review, R3): PEP 440 prefix matching, never
            # a string comparison -- and "3.1.*" is not a prefix of 3.10.
            ('python_version == "{}.{}.*"'.format(*version), [], True),
            ('python_full_version == "{}.{}.*"'.format(*version), [], True),
            ('python_version != "{}.{}.*"'.format(*version), [], False),
            ('python_full_version != "{}.{}.*"'.format(*version), [], False),
            ('python_version == "3.1.*"', [], version[:2] == (3, 1)),
            ('python_full_version == "3.1.*"', [], version[:2] == (3, 1)),
            # No agreed meaning (packaging says False, a flip would say True):
            # not decided, so a reinstall rather than a guess.
            ('"{}.{}.*" == python_version'.format(*version), [], None),
            ('python_version >= "3.10.*"', [], None),
            ('"3.10.*" == "3.10"', [], None),
            ('os_name == "nt.*"', [], None),
            ('no_such_variable == "x"', [], None),
            ('python_version <', [], None),
            ('os_name < "nt"', [], None),
        ]
        program = "\n".join((
            "import json, sys",
            "sys.path.insert(0, sys.argv[1])",
            "import gateway_health as h",
            "cases = json.loads(sys.argv[2])",
            "print(json.dumps([h.marker_applies(m, set(e)) for m, e in cases]))",
        ))
        read = subprocess.run(
            [sys.executable, "-S", "-c", program, str(SCRIPTS / "lib"),
             json.dumps([[m, e] for m, e, _ in cases])],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120, cwd=str(self.workspace))
        self.assertEqual(0, read.returncode, read.stdout + read.stderr)
        answers = json.loads(read.stdout)
        for (marker, extras, expected), answer in zip(cases, answers):
            with self.subTest(marker=marker, extras=extras):
                self.assertEqual(expected, answer)

    def test_a_configuration_the_user_already_has_is_never_rewritten(self):
        """Yours is yours, whatever is in it -- including a value setup dislikes."""
        root, venv, comfy, config = self.ready_checkout()
        config.parent.mkdir(parents=True, exist_ok=True)
        mine = (
            "# my own file, with my own comments\n"
            "runtime:\n  manage_comfy: true\n"
            "comfy:\n  root: \"D:/somewhere else/ComfyUI\"\n"
        )
        config.write_text(mine, encoding="utf-8")
        sources = config.parent / "workflow-sources.yaml"
        sources.write_text("sources:\n  - path: \"D:/my workflows\"\n", encoding="utf-8")
        before = (config.read_bytes(), sources.read_bytes())

        result = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertEqual(
            before, (config.read_bytes(), sources.read_bytes()),
            "setup rewrote configuration that was already there")

    def test_the_refusal_to_overwrite_is_in_the_writer_and_not_only_in_the_caller(self):
        """Two locks on one decision, and the inner one proved on its own.

        The caller decides a file is absent; Write-NewFile checks again before
        it writes a byte. The second check is the one a future edit to the
        caller cannot walk around, so it is driven directly -- with a file that
        is already there, and with one that is not, because a writer that
        refused everything would pass half of this.
        """
        root = self.build_checkout()
        text = (root / "scripts" / "setup.ps1").read_text(encoding="utf-8-sig")
        function = re.search(r"(?ms)^function Write-NewFile \{.*?^\}", text)
        self.assertIsNotNone(function, "Write-NewFile has moved")

        existing = self.workspace / "a file that is already here.yaml"
        existing.write_text("mine", encoding="utf-8")
        fresh = self.workspace / "a file that is not there yet.yaml"

        driver = root / "drive the writer.ps1"
        driver.write_text(
            "Set-StrictMode -Version Latest\n"
            "$ErrorActionPreference = 'Stop'\n"
            ". '{common}'\n".format(common=root / "scripts" / "lib" / "Common.ps1") +
            function.group(0) + "\n"
            "foreach ($target in @({existing}, {fresh})) {{\n".format(
                existing=powershell_literal(existing), fresh=powershell_literal(fresh)) +
            "    try {\n"
            "        Write-NewFile -Path $target -Content 'written by the test'\n"
            "        Write-Host \"WROTE $target\"\n"
            "    } catch { Write-Host \"REFUSED $target\" }\n"
            "}\n",
            encoding="utf-8")
        run = subprocess.run(
            [PWSH, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
             "-File", str(driver)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120, cwd=str(REPO))
        output = self.output_of(run)
        self.assertIn("REFUSED {}".format(existing), output, output)
        self.assertIn("WROTE {}".format(fresh), output, output)
        self.assertEqual("mine", existing.read_text(encoding="utf-8"),
                         "the writer overwrote a file that was already there")
        self.assertEqual("written by the test", fresh.read_text(encoding="utf-8"))

    # -- 7: somebody else's gateway ----------------------------------------

    def test_a_gateway_from_somewhere_else_cannot_pass_for_this_checkout(self):
        """pip saying "installed" is not the same claim as "this is the code".

        A gateway frozen into site-packages by an older `pip install .`, or a
        directory on PYTHONPATH, shadows an editable install silently -- and
        then every script here runs code that is not the code in front of you.
        Both shapes are driven, and both must stop the run.
        """
        root = self.build_checkout()
        venv = self.build_environment(root)
        comfy = self.make_comfy(root)
        config = root / "config" / "local" / "runtime.yaml"

        elsewhere = self.workspace / "a stale install"
        (elsewhere / "localcanvas_gateway").mkdir(parents=True)
        (elsewhere / "localcanvas_gateway" / "__init__.py").write_text(
            "", encoding="utf-8")

        with self.subTest(shadow="PYTHONPATH"):
            result = self.run_setup_in(
                root, *self.setup_arguments(venv, config, comfy),
                env={"PYTHONPATH": str(elsewhere)})
            output = self.output_of(result)
            self.assertEqual(1, result.returncode, output)
            self.assertIn(str(elsewhere), output, "the refusal did not name the impostor")
            self.assertIn(str(root / "gateway"), output)
            self.assertFalse(config.exists(), "it configured anyway")
            self.assert_no_stack_trace(output)

        frozen = self.site_packages(venv) / "localcanvas_gateway"
        frozen.mkdir()
        (frozen / "__init__.py").write_text("", encoding="utf-8")
        # Removed whatever the assertions below do, so the control run at the
        # end is a control and not a second instance of the same shadow.
        self.addCleanup(lambda: shutil.rmtree(frozen, ignore_errors=True))
        with self.subTest(shadow="site-packages"):
            result = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
            output = self.output_of(result)
            self.assertEqual(1, result.returncode, output)
            # Windows hands back its own spelling of the directory, so the
            # comparison is about the path and not about its capitals.
            self.assertIn(str(frozen).lower(), output.lower())
            self.assertFalse(config.exists())
        shutil.rmtree(frozen)

        # The control: with neither shadow in place the same run succeeds, so
        # the two refusals above are about the shadow and not about the fixture.
        result = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
        self.assertEqual(0, result.returncode, self.output_of(result))

    # -- 18: nobody to ask -------------------------------------------------

    def test_a_run_with_nobody_to_ask_exits_instead_of_waiting(self):
        """"Never waits on stdin" is measured as an exit, under a deadline.

        The run is given a standard input that is a pipe which is never
        written to and never closed: a Read-Host that reaches it would sit
        there for ever. If setup waits, this test does not fail with a wrong
        message -- it times out, which is the honest way for a hang to be
        reported.
        """
        root, venv, _comfy, config = self.ready_checkout()
        reader, writer = os.pipe()

        def close_the_pipe():
            for handle in (reader, writer):
                try:
                    os.close(handle)
                except OSError:
                    pass

        self.addCleanup(close_the_pipe)
        started = time.time()
        try:
            # -NonInteractive is NOT passed: this host would happily prompt.
            # The only thing stopping it is setup noticing that its standard
            # input is a pipe, which is the interlock under test.
            result = self.run_setup_in(
                root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", config,
                stdin=reader, timeout=180, interactive=True)
        except subprocess.TimeoutExpired:
            self.fail("setup waited for an answer nobody was there to give")
        elapsed = time.time() - started
        output = self.output_of(result)
        self.assertEqual(1, result.returncode, output)
        self.assertLess(elapsed, 180, output)
        self.assertFalse(config.exists(), "it wrote a configuration it could not ask about")
        self.assertIn("-Mode", output, "it did not say which parameter carries the answer")
        self.assert_no_stack_trace(output)

    def test_the_answers_can_all_be_given_in_advance(self):
        """The same run, fully non-interactive, and it configures."""
        root = self.build_checkout()
        venv = self.build_environment(root)
        comfy = self.make_comfy(root, workflows=False)
        elsewhere = root / "where I keep my workflows"
        elsewhere.mkdir()
        (elsewhere / "a workflow.json").write_text("{}", encoding="utf-8")
        config = root / "config" / "local" / "runtime.yaml"

        result = self.run_setup_in(
            root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", config,
            "-Mode", "External", "-ComfyRoot", comfy,
            "-WorkflowSource", elsewhere, "-ComfyHost", "127.0.0.1",
            "-ComfyPort", self.FIXTURE_COMFY_PORT)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertNotIn("Question 1 of 2", output)
        self.assertNotIn("Question 2 of 2", output)
        sources = (config.parent / "workflow-sources.yaml").read_text(encoding="utf-8")
        self.assertIn(str(elsewhere).replace("\\", "/"), sources)
        self.assertRegex(
            config.read_text(encoding="utf-8"),
            r"(?m)^\s*port:\s*{}\s*$".format(self.FIXTURE_COMFY_PORT))

    def test_external_mode_alone_is_enough_when_nobody_can_be_asked(self):
        """It writes what it safely can, says what it did not get -- AND THE
        STATE IT LEAVES IS RECOVERABLE.

        External mode makes comfy.root optional, so a session that cannot be
        asked question 2 is not refused over it. Managed mode cannot do that,
        and is refused, because the loader requires a root.

        THE LAST THIRD OF THIS TEST IS THE ONE THAT MATTERED (review round 1,
        D1). The first two assertions -- the output, and the two absent keys --
        were all this test made, and a run that leaves an unrecoverable machine
        satisfies both. It did: the whole workflow-sources writer sat inside the
        "no runtime configuration yet" branch, so the advice this very run
        prints named a second run that could not write anything. So the second
        run is performed, and the file it is supposed to produce is asserted to
        exist.
        """
        root, venv, comfy, config = self.ready_checkout()
        sources = config.parent / "workflow-sources.yaml"
        result = self.run_setup_in(
            root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", config,
            "-Mode", "External")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertTrue(config.is_file())
        document = config.read_text(encoding="utf-8")
        self.assertNotIn("root:", document)
        self.assertNotIn("launcher:", document)
        self.assertIn("cannot be asked", output)
        self.assertFalse(sources.exists(), "there was no folder to list yet")
        # D2: the piece that is missing is named in the summary that claims to
        # describe the machine, not left out of it.
        self.assertIn("Workflow sources", output)
        self.assertIn("not configured", output)

        # THE ADVICE, PERFORMED. The run tells the user to come back with
        # -WorkflowSource; this is that run, and it has to work.
        self.assertIn("-WorkflowSource", output)
        workflows = Path(comfy) / "user" / "default" / "workflows"
        self.assertTrue(workflows.is_dir(), "the fixture has no workflow folder")
        before = config.read_bytes()
        recovery = self.run_setup_in(
            root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", config,
            "-WorkflowSource", workflows)
        recovery_output = self.output_of(recovery)
        self.assertEqual(0, recovery.returncode, recovery_output)
        self.assertTrue(
            sources.is_file(),
            "the run this machine was told to make wrote nothing: " + recovery_output)
        self.assertIn(str(workflows).replace("\\", "/"),
                      sources.read_text(encoding="utf-8"))
        self.assertEqual(before, config.read_bytes(),
                         "the recovery run rewrote the runtime configuration")

        managed = root / "config" / "local" / "managed.yaml"
        refused = self.run_setup_in(
            root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", managed,
            "-Mode", "Managed")
        managed_output = self.output_of(refused)
        self.assertEqual(1, refused.returncode, managed_output)
        self.assertFalse(managed.exists())
        self.assertIn("-ComfyRoot", managed_output)

    # -- the source list does not depend on who wrote the runtime config ---

    def test_a_user_who_already_has_a_runtime_config_still_gets_a_source_list(self):
        """The largest of the four states review round 1 found (D1).

        Everybody who followed the README's manual flow already has
        config/local/runtime.yaml and has no workflow-sources.yaml. For them
        the first run of the new setup used to skip the source list entirely --
        the writer lived inside the "no runtime configuration yet" branch -- so
        the card's acceptance criterion, zero hand-edited configuration files,
        failed for every existing user.

        Nothing is passed here but the config: the ComfyUI folder is re-derived
        from the comfy.root THE CONFIGURATION ITSELF NAMES, across the seam,
        which is the only way a run that asked no questions can know it.

        AND THE REGISTRY IS DELIBERATELY NOT WHERE SETUP WOULD HAVE PUT IT
        (review round 2, M1). Every fixture in this class used to name
        config/local/workflows, which is setup's own default -- so "setup uses
        the registry the configuration names" and "setup uses its own default"
        produced identical results, and two mutations that undo the claim
        survived all 28 tests. A registry of the user's own is what tells the
        two apart, and all three consequences of it are asserted below: the
        directory that gets created, the directory that does NOT, and the
        `definitions` the source list is written with.
        """
        root = self.build_checkout()
        venv = self.build_environment(root)
        comfy = self.make_comfy(root)
        config = root / "config" / "local" / "runtime.yaml"
        sources = config.parent / "workflow-sources.yaml"
        # Somewhere of the user's own choosing, with a space in it, and NOT
        # config/local/workflows.
        registry = root / "my curated workflows"
        default_registry = root / "config" / "local" / "workflows"
        self.assertNotEqual(registry, default_registry, "the fixture proves nothing")
        self.assertFalse(registry.exists())
        # A configuration of the kind the old documentation produced.
        config.write_text(
            "runtime:\n  manage_comfy: false\n"
            "comfy:\n"
            '  root: "{}"\n'.format(str(comfy).replace("\\", "/")) +
            '  host: "127.0.0.1"\n  port: 8188\n'
            "workflows:\n"
            '  registry: "{}"\n'.format(str(registry).replace("\\", "/")) +
            "gateway:\n"
            '  host: "0.0.0.0"\n  port: 7801\n'
            "identity:\n"
            '  display_name: "An older install"\n',
            encoding="utf-8")
        before = config.read_bytes()

        result = self.run_setup_in(root, "-VenvPath", venv, "-SkipPipUpgrade",
                                   "-Config", config)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertTrue(
            sources.is_file(),
            "an existing runtime config still hides the workflow source list")
        listing = sources.read_text(encoding="utf-8")
        listed = re.search(r'(?m)^\s*-\s*path:\s*"([^"]+)"', listing)
        self.assertIsNotNone(listed, listing)
        self.assertEqual(
            (Path(comfy) / "user" / "default" / "workflows").resolve(),
            Path(listed.group(1)).resolve(),
            "the folder was not derived from the comfy.root the config names")
        self.assertEqual(before, config.read_bytes(),
                         "the run rewrote a configuration it did not create")

        # THE REGISTRY THE CONFIGURATION NAMES, in both places it reaches.
        self.assertTrue(
            registry.is_dir(),
            "setup did not create the registry the configuration names:\n" + output)
        self.assertFalse(
            default_registry.exists(),
            "setup created its own default registry instead of the configured one")
        definitions = re.search(r'(?m)^\s*definitions:\s*"([^"]+)"', listing)
        self.assertIsNotNone(definitions, listing)
        self.assertEqual(
            registry.resolve(), Path(definitions.group(1)).resolve(),
            "the source list writes its definitions somewhere the runtime "
            "configuration does not read them from")

    def test_workflow_source_is_honoured_on_a_run_that_asks_nothing(self):
        """-WorkflowSource on a run where the configuration already exists.

        It was accepted and silently ignored in that state (review round 1,
        D1), which is worse than refusing it: the run exited 0 and repeated the
        advice to pass the flag it had just discarded.
        """
        root = self.build_checkout()
        venv = self.build_environment(root)
        comfy = self.make_comfy(root)
        elsewhere = root / "where I really keep my workflows"
        elsewhere.mkdir()
        (elsewhere / "a workflow.json").write_text("{}", encoding="utf-8")
        config = root / "config" / "local" / "runtime.yaml"
        sources = config.parent / "workflow-sources.yaml"

        first = self.run_setup_in(
            root, *self.setup_arguments(venv, config, comfy))
        self.assertEqual(0, first.returncode, self.output_of(first))
        # The first run found ComfyUI's own folder, so the source list exists.
        self.assertTrue(sources.is_file())
        kept = sources.read_bytes()

        # A second -WorkflowSource must NOT quietly rewrite it, and must say so.
        again = self.run_setup_in(
            root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", config,
            "-WorkflowSource", elsewhere)
        again_output = self.output_of(again)
        self.assertEqual(0, again.returncode, again_output)
        self.assertEqual(kept, sources.read_bytes(),
                         "-WorkflowSource overwrote a source list that was already there")
        self.assertIn("already there", again_output,
                      "the flag was discarded without a word")

        # And with the list absent, the same flag writes it.
        sources.unlink()
        third = self.run_setup_in(
            root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", config,
            "-WorkflowSource", elsewhere)
        third_output = self.output_of(third)
        self.assertEqual(0, third.returncode, third_output)
        self.assertTrue(sources.is_file(), third_output)
        self.assertIn(str(elsewhere).replace("\\", "/"),
                      sources.read_text(encoding="utf-8"))

    def test_a_workflow_source_that_does_not_exist_is_refused_and_recoverable(self):
        """A path that is not there fails, and the fix it names then works."""
        root = self.build_checkout()
        venv = self.build_environment(root)
        comfy = self.make_comfy(root, workflows=False)
        real = root / "the folder that does exist"
        real.mkdir()
        config = root / "config" / "local" / "runtime.yaml"
        sources = config.parent / "workflow-sources.yaml"

        result = self.run_setup_in(
            root, *self.setup_arguments(venv, config, comfy),
            "-WorkflowSource", root / "no such folder")
        output = self.output_of(result)
        self.assertEqual(1, result.returncode, output)
        self.assertFalse(sources.exists(), output)
        self.assertIn("-WorkflowSource", output)
        self.assert_no_stack_trace(output)

        recovery = self.run_setup_in(
            root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", config,
            "-WorkflowSource", real)
        recovery_output = self.output_of(recovery)
        self.assertEqual(0, recovery.returncode, recovery_output)
        self.assertTrue(sources.is_file(), recovery_output)

    def test_the_status_table_always_says_what_the_workflow_sources_are(self):
        """D2: the summary describes the machine, including what is missing.

        Three states, one row each. Without this, the state that needs the row
        most -- nothing configured -- was the one state that had no row at all.
        """
        root = self.build_checkout()
        venv = self.build_environment(root)
        comfy = self.make_comfy(root)
        config = root / "config" / "local" / "runtime.yaml"
        bare = root / "config" / "local" / "no comfyui.yaml"

        rows = {}
        rows["not configured"] = self.output_of(self.run_setup_in(
            root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", bare,
            "-Mode", "External"))
        rows["created"] = self.output_of(self.run_setup_in(
            root, *self.setup_arguments(venv, config, comfy)))
        rows["present"] = self.output_of(self.run_setup_in(
            root, "-VenvPath", venv, "-SkipPipUpgrade", "-Config", config))

        for state, output in rows.items():
            with self.subTest(state=state):
                row = [line for line in output.splitlines()
                       if line.strip().startswith("Workflow sources")]
                self.assertEqual(1, len(row),
                                 "no Workflow sources row in the {} state:\n{}".format(
                                     state, output))
                self.assertIn(state, row[0])

    # -- 19, 20: paths -----------------------------------------------------

    def test_every_path_in_the_run_contains_a_space(self):
        """The workspace, the checkout, the venv, ComfyUI and the config.

        Not an extra test so much as the guarantee the rest of this class rests
        on: if any of these stopped containing a space, every assertion above
        would quietly stop covering the case that breaks path handling.
        """
        root, venv, comfy, config = self.ready_checkout()
        for described, path in (("workspace", self.workspace), ("checkout", root),
                                ("venv", venv), ("ComfyUI", comfy)):
            self.assertIn(" ", Path(path).name, described + ": " + str(path))
        self.assertIn(" ", str(config), str(config))
        result = self.run_setup_in(root, *self.setup_arguments(venv, config, comfy))
        self.assertEqual(0, result.returncode, self.output_of(result))
        self.assertTrue(config.is_file())

    def test_a_comfyui_on_another_drive_letter_works(self):
        """A different drive letter, made with subst and taken away again.

        The data never leaves this test's own workspace: subst maps a drive
        letter onto a directory, so what is exercised is the letter -- which is
        the thing that breaks path joining -- and not somebody else's disk.
        Nothing is written outside the workspace, and the mapping is removed in
        cleanup whatever the test does.
        """
        letter = self.free_drive_letter()
        if letter is None:
            self.skipTest("no free drive letter to map a second drive onto")
        root, venv, _unused, config = self.ready_checkout()
        elsewhere = self.workspace / "another drive"
        elsewhere.mkdir()
        comfy = self.make_comfy(elsewhere, name="ComfyUI over here")
        mapped = subprocess.run(["subst", "{}:".format(letter), str(elsewhere)],
                                capture_output=True, text=True, shell=True, timeout=60)
        if mapped.returncode != 0:
            self.skipTest("subst is not available here: " + (mapped.stderr or ""))
        self.addCleanup(lambda: subprocess.run(
            ["subst", "{}:".format(letter), "/D"], capture_output=True, shell=True,
            timeout=60))
        on_other_drive = Path("{}:\\".format(letter)) / comfy.name
        self.assertTrue((on_other_drive / "main.py").is_file(),
                        "the mapped drive does not show the fixture")

        result = self.run_setup_in(
            root, *self.setup_arguments(venv, config, on_other_drive))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        document = config.read_text(encoding="utf-8")
        self.assertIn("{}:/".format(letter), document,
                      "the other drive did not reach the configuration")
        sources = (config.parent / "workflow-sources.yaml").read_text(encoding="utf-8")
        self.assertIn("{}:/".format(letter), sources)

    @staticmethod
    def free_drive_letter():
        for letter in "YXWVU":
            if not os.path.exists("{}:\\".format(letter)):
                return letter
        return None


# ==========================================================================
# Strict LAN mode (docs/privacy-security.md)
# ==========================================================================
#
# NOT ONE TEST BELOW APPLIES A FIREWALL RULE, and none can: `enable` and
# `disable` reach the script only through ScriptTestCase.run_strict_lan, which
# refuses them without -Plan. What is tested instead is the decision -- the
# pure rule set computed from a configuration and a described network -- and
# the plan/dry-run path a user gets for free from the same split.


def home_lan_facts(**overrides):
    """An ordinary home network, as the facts document the plan consumes."""
    facts = {
        "interfaces": [
            {"name": "Wi-Fi", "profile": "Private",
             "address": "192.0.2.23", "prefix_length": 24},
        ],
        "default_gateways": ["192.0.2.30"],
        "dns_servers": ["192.0.2.30"],
        "notes": [],
    }
    facts.update(overrides)
    return facts


# Addresses that must never be permitted by any plan of a private network.
PUBLIC_ADDRESSES = ("8.8.8.8", "1.1.1.1", "93.184.216.34", "203.0.113.7",
                    "2606:4700:4700::1111", "2001:4860:4860::8888")


class StrictLanPlanTests(ScriptTestCase):
    """The pure rule set, across configurations and networks.

    Every case here computes a plan for an invented network and asserts
    properties of it. Nothing is read from this machine and nothing is applied,
    so the cases can be as extreme as they like.
    """

    def tearDown(self):
        self.assert_firewall_untouched()

    def test_a_home_lan_partitions_the_address_space(self):
        plan = self.strict_lan_plan(home_lan_facts())
        self.assert_partitions_the_address_space(plan["PermittedV4"], plan["BlockedV4"], 32)
        self.assert_partitions_the_address_space(plan["PermittedV6"], plan["BlockedV6"], 128)

    def test_what_the_lan_needs_is_permitted_and_the_internet_is_not(self):
        plan = self.strict_lan_plan(home_lan_facts())
        permitted = as_list(plan["PermittedV4"]) + as_list(plan["PermittedV6"])
        blocked = as_list(plan["BlockedV4"]) + as_list(plan["BlockedV6"])
        for address in ("127.0.0.1", "192.0.2.23", "192.0.2.30", "192.0.2.255",
                        "169.254.10.9", "224.0.0.251", "255.255.255.255", "::1", "ff02::fb"):
            self.assertTrue(self.contains_address(permitted, address),
                            "{} is not permitted, and the LAN needs it".format(address))
            self.assertFalse(self.contains_address(blocked, address),
                             "{} is permitted and blocked at the same time".format(address))
        for address in PUBLIC_ADDRESSES:
            self.assertTrue(self.contains_address(blocked, address),
                            "{} is not blocked; the Internet is still reachable".format(address))
            self.assertFalse(self.contains_address(permitted, address),
                             "{} is permitted; that is a hole in strict LAN mode".format(address))

    def test_every_rule_is_identifiable_as_localcanvas_own(self):
        plan = self.strict_lan_plan(home_lan_facts())
        self.assertEqual(STRICT_LAN_GROUP, plan["Group"])
        self.assertGreater(len(as_list(plan["Rules"])), 0)
        for rule in as_list(plan["Rules"]):
            self.assertEqual(STRICT_LAN_GROUP, rule["Group"], rule)
            self.assertTrue(rule["Name"].startswith("LocalCanvas-StrictLAN-"), rule)
            self.assertTrue(rule["Reason"].strip(), "a rule with no stated reason: " + rule["Name"])

    def test_the_lan_path_and_the_block_are_both_in_the_rule_set(self):
        plan = self.strict_lan_plan(home_lan_facts())
        rules = as_list(plan["Rules"])
        inbound = [r for r in rules
                   if r["Direction"] == "Inbound" and r["Action"] == "Allow"
                   and str(r["LocalPort"]) == str(plan["GatewayPort"])]
        self.assertTrue(inbound, "no rule lets the phone reach the gateway port")
        self.assertEqual("Private", inbound[0]["Profile"],
                         "the gateway port must be allowed on Private, never Public")
        for direction in ("Outbound", "Inbound"):
            for family in ("IPv4", "IPv6"):
                self.assertTrue(
                    [r for r in rules if r["Action"] == "Block"
                     and r["Direction"] == direction and family in r["Name"]],
                    "no {} {} block rule".format(direction, family))

    def test_what_would_be_applied_is_in_the_plan_and_all_of_it_carries_the_group(self):
        """Reversibility, checked at the parameter set rather than in prose.

        `disable` finds LocalCanvas's rules by one group. A rule created
        without it would be invisible to that and would stay on the machine
        after a disable -- so every parameter set the shim splats is here, and
        every one of them carries the group.
        """
        plan = self.strict_lan_plan(home_lan_facts())
        rules = as_list(plan["Rules"])
        applied = as_list(plan["Apply"])
        self.assertEqual([r["Name"] for r in rules], [a["Name"] for a in applied])
        for entry in applied:
            self.assertEqual(STRICT_LAN_GROUP, entry["Group"], entry)
            self.assertTrue(entry["Name"].startswith("LocalCanvas-StrictLAN-"), entry)
            self.assertEqual("True", str(entry["Enabled"]), entry)
            self.assertIn(entry["Action"], ("Allow", "Block"), entry)
            self.assertTrue(str(entry["Description"]).strip(), entry)

    def test_only_dhcp_is_allowed_to_reach_any_address(self):
        plan = self.strict_lan_plan(home_lan_facts())
        wildcard = [r for r in as_list(plan["Rules"])
                    if r["Action"] == "Allow" and "Any" in as_list(r["RemoteAddress"])]
        self.assertEqual(
            ["LocalCanvas-StrictLAN-Allow-DHCP"], [r["Name"] for r in wildcard],
            "a rule other than DHCP permits any address at all")
        self.assertEqual("68", str(wildcard[0]["LocalPort"]))
        self.assertEqual("67", str(wildcard[0]["RemotePort"]))
        self.assertEqual("UDP", wildcard[0]["Protocol"])

    def test_no_allow_rule_reaches_outside_the_permitted_scopes(self):
        """The invariant that makes the disclosure true.

        Whatever `enable` says it permits is the whole of what it permits: an
        allow rule naming an address outside the printed scopes would be
        permission nobody was told about.
        """
        plan = self.strict_lan_plan(home_lan_facts())
        permitted = as_list(plan["PermittedV4"]) + as_list(plan["PermittedV6"])
        for rule in as_list(plan["Rules"]):
            if rule["Action"] != "Allow":
                continue
            for spec in as_list(rule["RemoteAddress"]):
                if spec == "Any":
                    continue
                first, last, version = address_specification_to_range(spec)
                for edge in (first, last):
                    address = str(ipaddress.ip_address(edge)) if version == 4 else str(
                        ipaddress.IPv6Address(edge))
                    self.assertTrue(
                        self.contains_address(permitted, address),
                        "{} permits {}, which is outside the scopes the plan "
                        "discloses".format(rule["Name"], spec))

    def test_a_resolver_off_the_lan_is_named_as_breakage_not_quietly_permitted(self):
        plan = self.strict_lan_plan(home_lan_facts(dns_servers=["8.8.8.8", "192.0.2.30"]))
        blocked = as_list(plan["BlockedV4"])
        self.assertTrue(self.contains_address(blocked, "8.8.8.8"),
                        "a public resolver was permitted; that is a hole in the feature")
        self.assertTrue(any("8.8.8.8" in w for w in as_list(plan["Warnings"])),
                        "the resolver that will stop working was not mentioned")
        for rule in as_list(plan["Rules"]):
            self.assertNotIn("8.8.8.8", as_list(rule["RemoteAddress"]), rule["Name"])

    def test_a_machine_with_no_lan_says_so_rather_than_planning_one(self):
        plan = self.strict_lan_plan(
            home_lan_facts(interfaces=[], default_gateways=[], dns_servers=[]))
        self.assertEqual([], as_list(plan["LanSubnets"]))
        joined = " ".join(as_list(plan["Warnings"]))
        self.assertIn("No LAN subnet was detected", joined)
        self.assertIn("No default gateway", joined)
        self.assert_partitions_the_address_space(plan["PermittedV4"], plan["BlockedV4"], 32)
        # And an address of the usual LAN is then genuinely blocked, because it
        # is not on any subnet this machine holds.
        self.assertTrue(self.contains_address(as_list(plan["BlockedV4"]), "192.0.2.50"))

    def test_several_subnets_are_all_permitted(self):
        plan = self.strict_lan_plan(home_lan_facts(interfaces=[
            {"name": "Wi-Fi", "profile": "Private", "address": "192.0.2.23", "prefix_length": 24},
            {"name": "Ethernet", "profile": "Private", "address": "198.51.100.7", "prefix_length": 25},
            {"name": "Wi-Fi", "profile": "Private", "address": "2001:db8:5::5", "prefix_length": 64},
        ]))
        permitted = as_list(plan["PermittedV4"]) + as_list(plan["PermittedV6"])
        for address in ("192.0.2.99", "198.51.100.126", "2001:db8:5::ffff"):
            self.assertTrue(self.contains_address(permitted, address), address)
        self.assert_partitions_the_address_space(plan["PermittedV4"], plan["BlockedV4"], 32)
        self.assert_partitions_the_address_space(plan["PermittedV6"], plan["BlockedV6"], 128)
        self.assertTrue(self.contains_address(as_list(plan["BlockedV4"]), "11.0.0.1"))

    def test_a_default_gateway_off_the_subnet_is_permitted_explicitly(self):
        plan = self.strict_lan_plan(home_lan_facts(default_gateways=["198.51.100.17"]))
        self.assertTrue(self.contains_address(as_list(plan["PermittedV4"]), "198.51.100.17"),
                        "the router this machine needs was not permitted")
        self.assertFalse(self.contains_address(as_list(plan["BlockedV4"]), "198.51.100.17"),
                         "Windows applies block rules ahead of allow rules, so a "
                         "permitted address must not also appear in the block")
        # Its neighbours are still blocked: one address was permitted, not a subnet.
        self.assertTrue(self.contains_address(as_list(plan["BlockedV4"]), "198.51.100.18"))

    def test_prefix_lengths_at_both_edges(self):
        for prefix, inside, outside in ((32, "192.0.2.23", "192.0.2.24"),
                                        (31, "192.0.2.22", "192.0.2.24"),
                                        (25, "192.0.2.127", "192.0.2.128"),
                                        (16, "192.0.200.1", "192.1.0.1")):
            with self.subTest(prefix=prefix):
                plan = self.strict_lan_plan(home_lan_facts(interfaces=[
                    {"name": "Wi-Fi", "profile": "Private",
                     "address": "192.0.2.23", "prefix_length": prefix}]))
                self.assert_partitions_the_address_space(
                    plan["PermittedV4"], plan["BlockedV4"], 32)
                self.assertTrue(self.contains_address(as_list(plan["PermittedV4"]), inside))
                self.assertTrue(self.contains_address(as_list(plan["BlockedV4"]), outside))

    def test_a_prefix_of_zero_permits_everything_and_says_nothing_is_blocked(self):
        # The degenerate network: a /0 means the whole Internet is "local".
        # The arithmetic must survive it rather than producing an empty or
        # inverted block, and the result must be visibly all-permitting.
        plan = self.strict_lan_plan(home_lan_facts(interfaces=[
            {"name": "Odd", "profile": "Private", "address": "192.0.2.23", "prefix_length": 0}]))
        self.assertEqual([], as_list(plan["BlockedV4"]))
        self.assert_partitions_the_address_space(plan["PermittedV4"], plan["BlockedV4"], 32)
        # No rule pretends to block what is not blocked, and the plan says so.
        self.assertEqual(
            [], [r for r in as_list(plan["Rules"])
                 if r["Action"] == "Block" and "IPv4" in r["Name"]])
        self.assertTrue(any("block no IPv4 traffic at all" in w
                            for w in as_list(plan["Warnings"])), plan["Warnings"])

    def test_a_public_network_profile_is_reported_as_a_warning(self):
        plan = self.strict_lan_plan(home_lan_facts(interfaces=[
            {"name": "Cafe Wi-Fi", "profile": "Public",
             "address": "192.0.2.23", "prefix_length": 24}]))
        joined = " ".join(as_list(plan["Warnings"]))
        self.assertIn("Public", joined)
        self.assertIn("Cafe Wi-Fi", joined)

    def test_the_gateway_port_and_comfy_binding_come_from_the_configuration(self):
        port = free_port()
        plan = self.strict_lan_plan(home_lan_facts(), gateway_port=port, comfy_host="0.0.0.0")
        self.assertEqual(port, plan["GatewayPort"])
        inbound = [r for r in as_list(plan["Rules"]) if str(r["LocalPort"]) == str(port)]
        self.assertTrue(inbound, "the configured gateway port is not in the rule set")
        self.assertTrue(
            any("not on localhost" in w or "not on localhost" in w.lower()
                for w in as_list(plan["Warnings"])),
            "a ComfyUI off localhost was not mentioned: " + repr(plan["Warnings"]))

    def test_the_same_inputs_always_produce_the_same_plan(self):
        # Purity, checked the only way it can be from outside: twice.
        facts = home_lan_facts()
        first = self.strict_lan_plan(facts)
        second = self.strict_lan_plan(facts)
        self.assertEqual(json.dumps(first, sort_keys=True), json.dumps(second, sort_keys=True))

    def test_a_malformed_network_description_is_reported_not_guessed(self):
        self.write_config()
        for body, expected in (
            ('{"interfaces": [{"name": "x"}]}', "has no 'address'"),
            ('{"interfaces": [{"address": "192.0.2.30"}]}', "has no 'prefix_length'"),
            ('{"interfaces": [{"address": "not an address", "prefix_length": 24}]}',
             "not an IP address"),
            ('{"interfaces": [{"address": "192.0.2.30", "prefix_length": 99}]}',
             "outside 0..32"),
            ("this is not json", "not valid JSON"),
        ):
            with self.subTest(body=body):
                facts_path = self.workspace / "bad facts.json"
                facts_path.write_text(body, encoding="utf-8")
                result = self.run_strict_lan(
                    "enable", "-Plan", "-FactsFile", str(facts_path))
                output = self.output_of(result)
                self.assertEqual(2, result.returncode, output)
                self.assertIn(expected, output)
                self.assert_no_stack_trace(output)

    def test_a_facts_file_that_does_not_exist_is_reported(self):
        self.write_config()
        result = self.run_strict_lan(
            "enable", "-Plan", "-FactsFile", str(self.workspace / "no such facts.json"))
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("does not exist", output)
        self.assert_no_stack_trace(output)


class StrictLanDisclosureTests(ScriptTestCase):
    """"Never silent", and the collateral effect said out loud."""

    def tearDown(self):
        self.assert_firewall_untouched()

    def plan_output(self):
        self.write_config()
        facts_path = self.workspace / "network facts.json"
        facts_path.write_text(json.dumps(home_lan_facts()), encoding="utf-8")
        result = self.run_strict_lan("enable", "-Plan", "-FactsFile", str(facts_path))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        return output

    def test_enable_states_the_permitted_infrastructure_and_why(self):
        """Not just WHAT is permitted -- WHY, for each scope.

        docs/privacy-security.md: `enable` states explicitly which local
        infrastructure traffic it is permitting *and why*. Naming the
        infrastructure is only half of that, and the words "DHCP" and "DNS"
        appear in the rules' own `why:` lines too -- so asserting on those
        alone leaves the per-scope reasons unguarded and the header free to
        promise a "why" that is not printed. Each scope's reason is therefore
        taken from the plan itself and required, verbatim, inside the PERMITTED
        block of the rendered output.
        """
        plan = self.strict_lan_plan(home_lan_facts())
        output = self.plan_output()
        self.assertIn("PERMITTED while strict LAN mode is on, and why:", output)

        block = output.split("PERMITTED while strict LAN mode is on, and why:", 1)[1]
        block = block.split("BLOCKED while strict LAN mode is on:", 1)[0]

        scopes = as_list(plan["Permitted"])
        self.assertGreater(len(scopes), 3, "the plan permits almost nothing; the test is vacuous")
        for scope in scopes:
            reason = str(scope["Reason"]).strip()
            self.assertTrue(reason, "a permitted scope carries no reason at all: " + scope["Label"])
            self.assertIn(scope["Label"], block,
                          "the disclosure does not name the scope: " + scope["Label"])
            self.assertIn(
                reason, block,
                "the disclosure names '{}' but never says why it is permitted".format(
                    scope["Label"]))

        # And the infrastructure the contract names is named, somewhere in the
        # disclosure or in the rules it introduces.
        for expected in ("DHCP", "DNS", "neighbour discovery", "ARP",
                         "Default gateway", "Loopback", "mDNS"):
            self.assertIn(expected, output,
                          "the disclosure does not mention " + expected)

    def test_enable_discloses_the_machine_wide_collateral_effect(self):
        output = self.plan_output()
        lowered = output.lower()
        for expected in ("every application on this pc loses internet access",
                         "browser", "windows update", "machine-level"):
            self.assertIn(expected, lowered,
                          "the collateral effect does not mention " + expected)

    def test_enable_prints_the_actual_rules_and_not_a_summary(self):
        output = self.plan_output()
        self.assertIn("LocalCanvas-StrictLAN-Allow-Gateway-Inbound", output)
        self.assertIn("LocalCanvas-StrictLAN-Block-Outbound-IPv4", output)
        self.assertIn("remote address:", output)
        self.assertIn("profiles:", output)
        self.assertIn("group: " + STRICT_LAN_GROUP, output)

    def test_plan_mode_says_plainly_that_nothing_was_changed(self):
        output = self.plan_output()
        self.assertIn("NOTHING has been changed", output)
        self.assertIn("No firewall rule was created, removed or changed", output)
        self.assert_no_stack_trace(output)


class StrictLanCommandTests(ScriptTestCase):
    """The subcommands, exercised without a rule ever existing.

    Note for anyone reading the suite's own network behaviour: the two live
    `verify` tests below run the real proof step, which attempts a TCP
    connection to a handful of public IP literals and sends nothing. That is
    what `verify` does, and the tests would say nothing about it otherwise.
    Every other test here probes only this machine.
    """

    def tearDown(self):
        self.assert_firewall_untouched()

    def test_status_is_read_only(self):
        self.write_config()
        result = self.run_strict_lan("status")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertFalse(self.runtime_dir.exists(),
                         "status created the runtime state directory just by reporting")
        self.assertFalse(self.comfy_marker.exists())
        self.assertFalse(self.gateway_marker.exists())

    def test_status_reports_the_state_the_owned_rules_and_what_is_permitted(self):
        self.write_config()
        output = self.output_of(self.run_strict_lan("status"))
        self.assertIn("Strict LAN mode:", output)
        self.assertIn("Rules LocalCanvas owns in group '" + STRICT_LAN_GROUP + "'", output)
        self.assertIn("PERMITTED while strict LAN mode is on, and why:", output)
        # status repeats the collateral effect rather than assuming it remembered.
        self.assertIn("every application on this PC loses Internet access", output)

    def test_disable_names_exactly_what_it_would_remove_and_removes_nothing(self):
        self.write_config()
        result = self.run_strict_lan("disable", "-Plan")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("group '" + STRICT_LAN_GROUP + "'", output)
        self.assertIn("Nothing outside that group is read, changed or removed", output)
        self.assertIn("default", output)

    def test_verify_plan_names_both_halves_and_probes_nothing(self):
        self.write_config()
        result = self.run_strict_lan("verify", "-Plan")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("nothing was probed and nothing was changed", output)
        self.assertIn("/api/v1/info", output)
        self.assertIn("1.1.1.1:53", output)
        self.assertIn("require every one of them to fail", output)

    def test_verify_proves_both_halves_or_says_it_did_not(self):
        # Nothing is running and strict mode is off, so the honest verdict is
        # "not proven" -- and a verify that claimed success here would be the
        # exact failure docs/privacy-security.md warns about.
        self.write_config()
        result = self.run_strict_lan("verify", timeout=300)
        output = self.output_of(result)
        self.assertEqual(4, result.returncode, output)
        self.assertIn("Half 1 of 2", output)
        self.assertIn("Half 2 of 2", output)
        self.assertIn("What verify could NOT test", output)
        self.assertIn("NOT proven", output)
        self.assertNotIn("Both halves proven", output)
        self.assert_no_stack_trace(output)

    def test_verify_says_what_it_could_not_test(self):
        self.write_config()
        output = self.output_of(self.run_strict_lan("verify", timeout=300))
        for expected in ("Only outbound TCP was attempted",
                         "cannot tell the two apart",
                         "says nothing about the phone",
                         "custom nodes"):
            self.assertIn(expected, output, "verify did not disclose: " + expected)

    def test_enable_without_elevation_refuses_and_applies_nothing(self):
        self.write_config()
        result = self.run_strict_lan("enable", refusal_path=True)
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn("Administrator", output)
        self.assertIn("NOTHING has been applied", output)
        # The plan was still printed in full before the refusal.
        self.assertIn("LocalCanvas-StrictLAN-Block-Outbound-IPv4", output)
        self.assert_no_stack_trace(output)
        self.assert_firewall_untouched()

    def test_disable_without_elevation_refuses_and_removes_nothing(self):
        self.write_config()
        result = self.run_strict_lan("disable", refusal_path=True)
        output = self.output_of(result)
        # With no rules of ours on this machine there is nothing to remove and
        # disable says so; where there are, it refuses for want of elevation.
        # Either way it changes nothing, which is what is asserted.
        self.assertIn(result.returncode, (0, 3), output)
        self.assert_no_stack_trace(output)
        self.assert_firewall_untouched()

    def described_machine(self, **overrides):
        """A facts file for a machine that is not this one."""
        self.write_config()
        path = self.workspace / "described machine.json"
        path.write_text(json.dumps(home_lan_facts(**overrides)), encoding="utf-8")
        return path

    def test_enable_refuses_when_localcanvas_already_owns_rules(self):
        """The gate that stops a second overlay going on top of the first.

        Reachable in a test only because a described machine may describe the
        rules it already carries (`owned_rules` in the -FactsFile document) --
        the same seam that lets the rule set be planned for a network that is
        not this one, and, like it, one that can never apply anything.
        """
        facts = self.described_machine(owned_rules=[
            {"Name": "LocalCanvas-StrictLAN-Block-Outbound-IPv4",
             "Direction": "Outbound", "Action": "Block", "Enabled": "True"},
            {"Name": "LocalCanvas-StrictLAN-Allow-DHCP",
             "Direction": "Outbound", "Action": "Allow", "Enabled": "True"},
        ])
        result = self.run_strict_lan(
            "enable", "-FactsFile", str(facts), refusal_path=True)
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn("already owns 2 rule(s)", output)
        self.assertIn("Nothing has been changed", output)
        self.assertIn("disable", output)
        # The more specific complaint wins: this run never reached the
        # described-machine refusal, which is what proves the gate itself ran.
        self.assertNotIn("computed from a described network", output)
        self.assert_no_stack_trace(output)
        self.assert_firewall_untouched()

    def test_the_reported_state_follows_the_rules_that_are_present(self):
        plan = self.strict_lan_plan(home_lan_facts())
        names = [rule["Name"] for rule in as_list(plan["Rules"])]
        self.assertGreater(len(names), 3)
        for owned, expected in ((names, "ON"), (names[:2], "PARTIAL"), ([], "OFF")):
            with self.subTest(owned=len(owned)):
                facts = self.described_machine(
                    owned_rules=[{"Name": name, "Enabled": "True"} for name in owned])
                result = self.run_strict_lan("status", "-FactsFile", str(facts))
                output = self.output_of(result)
                self.assertEqual(0, result.returncode, output)
                self.assertIn("Strict LAN mode: " + expected, output)
                self.assertIn(
                    "{} of {} expected".format(len(owned), len(names)), output)

    def test_a_described_state_is_never_reported_as_this_machine(self):
        """Including -- especially -- when the description says "none".

        An EMPTY owned_rules is an answer, not an absence, and it is the case
        that discriminates. `$null -ne $facts.OwnedRules` compares; the trap
        form `$facts.OwnedRules -ne $null` FILTERS an empty array and yields a
        falsy empty result, so the script silently falls back to reading the
        real machine. On a machine that carries no LocalCanvas rules the two
        produce the same OFF state, so no state assertion can tell them apart
        -- but only the honouring form says where the answer came from. That is
        what is asserted here, and why the empty case is in this test.
        """
        for described in ([], [{"Name": "LocalCanvas-StrictLAN-Allow-DHCP",
                                "Enabled": "True"}]):
            with self.subTest(described=len(described)):
                facts = self.described_machine(owned_rules=described)
                output = self.output_of(
                    self.run_strict_lan("status", "-FactsFile", str(facts)))
                self.assertIn(
                    "not from this machine", output,
                    "an owned_rules of {} was not honoured as a description: the "
                    "state was read from this machine instead".format(described))
                self.assertIn("described machine.json", output)

    def test_a_described_rule_without_a_name_is_reported(self):
        self.write_config()
        path = self.workspace / "bad rules.json"
        path.write_text('{"interfaces": [], "owned_rules": [{"Action": "Block"}]}',
                        encoding="utf-8")
        result = self.run_strict_lan("status", "-FactsFile", str(path))
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("owned_rules", output)
        self.assertIn("has no 'Name'", output)
        self.assert_no_stack_trace(output)

    def test_a_plan_computed_from_a_described_network_is_never_applied(self):
        self.write_config()
        facts_path = self.workspace / "network facts.json"
        facts_path.write_text(json.dumps(home_lan_facts()), encoding="utf-8")
        result = self.run_strict_lan(
            "enable", "-FactsFile", str(facts_path), refusal_path=True)
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn("described network", output)
        self.assert_firewall_untouched()

    def test_disable_refuses_a_removal_list_that_came_from_a_description(self):
        """A -FactsFile may name any rule at all, so it may drive no removal.

        `enable` has always refused a plan computed from a described network.
        `disable` did not, and it took the rules to remove straight out of the
        document -- so a foreign rule name, or the single character `*` (which
        Remove-NetFirewallRule MATCHES, not compares), reached the removal.
        Both are asserted here because they are different failures: one takes a
        rule of the user's, the other takes every rule on the machine.
        """
        for described in ("Some Other Product - Allow 443", "*"):
            with self.subTest(name=described):
                facts = self.described_machine(
                    owned_rules=[{"Name": described, "Direction": "Outbound",
                                  "Action": "Block", "Enabled": "True"}])
                result = self.run_strict_lan(
                    "disable", "-FactsFile", str(facts), refusal_path=True)
                output = self.output_of(result)
                self.assertEqual(3, result.returncode, output)
                self.assertIn("described network", output)
                self.assertIn("Nothing has been removed", output)
                self.assertNotIn("removed " + described, output)
                self.assert_no_stack_trace(output)
                self.assert_firewall_untouched()

    def test_disable_plan_says_which_names_removal_would_refuse(self):
        """The printed promise and the enforced behaviour have to agree.

        `disable` prints "all of them in group ... and created by LocalCanvas"
        immediately before removing. It may only say that when it is true of
        the list in front of it.
        """
        facts = self.described_machine(owned_rules=[
            {"Name": "LocalCanvas-StrictLAN-Block-Outbound-IPv4", "Enabled": "True"},
            {"Name": "*", "Enabled": "True"},
        ])
        result = self.run_strict_lan("disable", "-Plan", "-FactsFile", str(facts))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertIn("REFUSED", output)
        self.assertIn("wildcard", output)
        self.assertNotIn("all of them in group", output)
        self.assert_firewall_untouched()

    def test_a_missing_configuration_is_reported_without_a_stack_trace(self):
        result = self.run_strict_lan("status", config=self.workspace / "no such config.yaml")
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("configuration file not found", output)
        self.assert_no_stack_trace(output)

    def test_the_gateway_is_what_loads_the_configuration_here_too(self):
        self.write_config()
        result = self.run_strict_lan(
            "status", env=self.script_env(LC_STUB_CONFIG_MODE="crash"))
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("the loader refused this file", output)


class FirewallTripwireTests(unittest.TestCase):
    """The safety net every strict LAN test in this file stands on.

    The near-miss it exists for. During the fix round for T-0034 a probe
    reached the real Remove-NetFirewallRule with -Name '*', which matches
    rather than compares: it would have deleted every one of this machine's
    firewall rules. LocalCanvas's own group is normally empty, so a tripwire
    that reads only that group would have compared [] with [] and REPORTED
    SUCCESS over a wiped firewall. The only thing that actually stopped it was
    the session not being elevated -- the one safeguard nobody designed for it.

    Nothing here changes a firewall rule, and nothing here needs to: what is
    under test is the READING and the comparison, so the disagreement is
    injected between two snapshots rather than into this machine. You do not
    delete a rule to test a rule-deletion detector.
    """

    WIPED = {"group": [], "named": [], "total": 0}
    INTACT = {"group": [], "named": [], "total": 583}
    # A rule LocalCanvas could have made, but OUTSIDE its group: the one case
    # the group reading cannot see and the name reading can.
    OURS_OUTSIDE_THE_GROUP = STRICT_LAN_RULE_PREFIX + "Stray (LocalCanvas stray rule)"

    def reading(self, **changes):
        snapshot = dict(self.INTACT)
        snapshot.update(changes)
        return snapshot

    def environment(self, enabled):
        """os.environ with the integration variable set or removed, restored after."""
        from unittest import mock

        patch = mock.patch.dict(os.environ)
        patch.start()
        self.addCleanup(patch.stop)
        os.environ.pop(INTEGRATION_VARIABLE, None)
        if enabled:
            os.environ[INTEGRATION_VARIABLE] = "1"

    def test_the_snapshot_counts_this_machines_rules_and_not_only_our_group(self):
        """The one assertion here that reads the real machine."""
        self.assertIsNotNone(_FIREWALL_BEFORE,
                             "the suite ran without reading this machine's firewall")
        self.assertIsInstance(_FIREWALL_BEFORE.get("group"), list)
        self.assertIsInstance(_FIREWALL_BEFORE.get("named"), list,
                              "the rules named as LocalCanvas's were not read")
        total = _FIREWALL_BEFORE.get("total")
        self.assertIsInstance(total, int,
                              "the total number of rules on this machine was not read")
        self.assertGreater(
            total, 0,
            "a Windows machine has firewall rules, so a total of 0 means the total "
            "is not being read at all")
        self.assertGreaterEqual(
            total, len(_FIREWALL_BEFORE["group"]),
            "the total is smaller than LocalCanvas's own group, so it is not a total")
        self.assertGreaterEqual(
            total, len(_FIREWALL_BEFORE["named"]),
            "the total is smaller than the rules named as LocalCanvas's, so it is not a total")

    # A machine's rules, invented: two of Windows' own and one another
    # application added. None of them is LocalCanvas's.
    SIMULATED_MACHINE = [
        {"Name": "CoreNet-DHCP-In", "DisplayName": "Core Networking - DHCP (DHCP-In)",
         "Group": "@FirewallAPI.dll,-25000"},
        {"Name": "RemoteDesktop-UserMode-In-TCP", "DisplayName": "Remote Desktop - User Mode (TCP-In)",
         "Group": "@FirewallAPI.dll,-28752"},
        {"Name": "{00000000-0000-0000-0000-000000000001}", "DisplayName": "Some Game",
         "Group": ""},
    ]
    SIMULATED_UNRELATED = {"Name": "{00000000-0000-0000-0000-000000000002}",
                           "DisplayName": "An installer's rule", "Group": ""}

    def test_the_reader_finds_our_rules_in_a_simulated_rule_list(self):
        """The real reading and filter, over rules nobody has to create.

        One of ours in the group, one displayed as ours under a GUID name, one
        grouped as ours in another case, and three that are not ours at all.
        """
        rules = self.SIMULATED_MACHINE + [
            {"Name": STRICT_LAN_RULE_PREFIX + "Block-Outbound-IPv4", "DisplayName": "Block",
             "Group": STRICT_LAN_GROUP},
            {"Name": "{00000000-0000-0000-0000-000000000003}",
             "DisplayName": "LocalCanvas gateway", "Group": ""},
            {"Name": "Hand-Made", "DisplayName": "hand made", "Group": "localcanvas extras"},
        ]
        snapshot = firewall_snapshot(simulated_rules=rules)
        self.assertEqual({
            "group": [STRICT_LAN_RULE_PREFIX + "Block-Outbound-IPv4"],
            "named": sorted([
                STRICT_LAN_RULE_PREFIX + "Block-Outbound-IPv4 (Block)",
                "{00000000-0000-0000-0000-000000000003} (LocalCanvas gateway)",
                "Hand-Made (hand made)",
            ]),
            "total": 6,
        }, snapshot)

    def test_a_simulated_unrelated_rule_leaves_the_ordinary_run_green(self):
        """T-0074 end to end: two real readings of an invented machine, one rule apart."""
        self.environment(enabled=False)
        before = firewall_snapshot(simulated_rules=self.SIMULATED_MACHINE)
        after = firewall_snapshot(simulated_rules=self.SIMULATED_MACHINE + [self.SIMULATED_UNRELATED])
        self.assertEqual(3, before["total"])
        self.assertEqual(4, after["total"])
        self.assertEqual([None, None], self.drive_the_call_sites(before, after))
        self.assertIn("1 rule was ADDED",
                      firewall_change_description(before, after, compare_total=True))

    def test_a_simulated_localcanvas_rule_still_ends_the_ordinary_run(self):
        """The same two readings, but the rule that appeared is named as ours."""
        self.environment(enabled=False)
        ours = {"Name": STRICT_LAN_RULE_PREFIX + "Stray", "DisplayName": "Stray", "Group": ""}
        before = firewall_snapshot(simulated_rules=self.SIMULATED_MACHINE)
        after = firewall_snapshot(simulated_rules=self.SIMULATED_MACHINE + [ours])
        suite, test = self.drive_the_call_sites(before, after)
        self.assertIn(STRICT_LAN_RULE_PREFIX + "Stray (Stray)", suite or "")
        self.assertIn("THIS TEST CHANGED THIS MACHINE'S FIREWALL", test or "")

    def test_a_mass_deletion_is_reported_although_our_group_never_changes(self):
        """The near-miss itself, as two snapshots, in a run that compares the total."""
        self.assertEqual(self.INTACT["group"], self.WIPED["group"],
                         "the fixture must be one the group comparison cannot see")
        message = firewall_change_description(self.INTACT, self.WIPED, compare_total=True)
        self.assertTrue(message, "the tripwire said nothing about a wiped firewall")
        self.assertIn("583 rules were REMOVED", message)
        self.assertIn("583 -> 0", message)

    def test_the_old_group_only_comparison_would_have_passed_the_same_fixture(self):
        """Why the total had to be added, said as an assertion.

        Compared the way this tripwire compared before -- group against group --
        a wiped firewall and an intact one are equal, and the suite would have
        reported success over a machine with no rules left on it.
        """
        self.assertEqual(self.INTACT["group"], self.WIPED["group"])
        self.assertNotEqual(
            "", firewall_change_description(self.INTACT, self.WIPED, compare_total=True))

    def test_rules_appearing_are_reported_and_counted_too(self):
        self.assertIn("3 rules were ADDED", firewall_change_description(
            self.INTACT, self.reading(total=586), compare_total=True))
        self.assertIn("1 rule was REMOVED", firewall_change_description(
            self.INTACT, self.reading(total=582), compare_total=True))

    def test_a_change_inside_our_own_group_is_still_reported(self):
        """The half that was already there does not go away, in either kind of run."""
        own = STRICT_LAN_RULE_PREFIX + "Block-Outbound-IPv4"
        after = self.reading(group=[own], total=584)
        for compare_total in (False, True):
            with self.subTest(compare_total=compare_total):
                message = firewall_change_description(self.INTACT, after, compare_total)
                self.assertIn(STRICT_LAN_GROUP, message)
                self.assertIn(own, message)
                self.assertIn("appeared", message)
        self.assertIn("1 rule was ADDED",
                      firewall_change_description(self.INTACT, after, compare_total=True))
        self.assertNotIn("ADDED",
                         firewall_change_description(self.INTACT, after, compare_total=False))

    # -- T-0074: another process's rule is not this suite's change ---------

    def test_an_unrelated_rule_appearing_does_not_trip_the_ordinary_run(self):
        """587 -> 591 on T-0055's run: 48 failures from one installer."""
        self.assertEqual("", firewall_change_description(
            self.reading(total=587), self.reading(total=591), compare_total=False))

    def test_an_unrelated_rule_vanishing_does_not_trip_the_ordinary_run(self):
        """604 -> 600 on T-0070's run: the same poisoning in the other direction."""
        self.assertEqual("", firewall_change_description(
            self.reading(total=604), self.reading(total=600), compare_total=False))

    def test_the_same_unrelated_change_still_trips_a_run_that_opted_in(self):
        """The control: the silence above is the choice of comparison, not a blind reader."""
        self.assertIn("4 rules were ADDED", firewall_change_description(
            self.reading(total=587), self.reading(total=591), compare_total=True))

    def test_a_localcanvas_named_rule_outside_the_group_trips_every_run(self):
        after = self.reading(named=[self.OURS_OUTSIDE_THE_GROUP], total=584)
        self.assertEqual(self.INTACT["group"], after["group"],
                         "the fixture must be one the group comparison cannot see")
        for compare_total in (False, True):
            with self.subTest(compare_total=compare_total):
                message = firewall_change_description(self.INTACT, after, compare_total)
                self.assertIn(self.OURS_OUTSIDE_THE_GROUP, message)
                self.assertIn("appeared", message)
                self.assertIn(LOCALCANVAS_RULE_PATTERN, message)

    def test_a_localcanvas_named_rule_vanishing_trips_every_run(self):
        before = self.reading(named=[self.OURS_OUTSIDE_THE_GROUP], total=584)
        for compare_total in (False, True):
            with self.subTest(compare_total=compare_total):
                message = firewall_change_description(before, self.INTACT, compare_total)
                self.assertIn(self.OURS_OUTSIDE_THE_GROUP, message)
                self.assertIn("vanished", message)

    def test_our_rule_is_seen_when_an_unrelated_one_vanishes_at_the_same_moment(self):
        """The total is unchanged here, so only the name reading can see it."""
        after = self.reading(named=[self.OURS_OUTSIDE_THE_GROUP])
        self.assertEqual(self.INTACT["total"], after["total"])
        message = firewall_change_description(self.INTACT, after, compare_total=False)
        self.assertIn(self.OURS_OUTSIDE_THE_GROUP, message)

    def test_the_default_comparison_follows_the_variable(self):
        unrelated = self.reading(total=591)
        self.environment(enabled=False)
        self.assertEqual("", firewall_change_description(self.INTACT, unrelated))
        os.environ[INTEGRATION_VARIABLE] = "0"
        self.assertEqual("", firewall_change_description(self.INTACT, unrelated))
        os.environ[INTEGRATION_VARIABLE] = "1"
        self.assertIn("8 rules were ADDED", firewall_change_description(self.INTACT, unrelated))

    def test_the_run_says_which_comparison_it_makes(self):
        self.environment(enabled=False)
        ordinary = firewall_tripwire_report()
        self.assertIn("NOT compared", ordinary)
        self.assertIn(INTEGRATION_VARIABLE + "=1", ordinary)
        os.environ[INTEGRATION_VARIABLE] = "1"
        opted_in = firewall_tripwire_report()
        self.assertNotIn("NOT compared", opted_in)
        self.assertIn("total rule count", opted_in)

    def test_an_unchanged_firewall_says_nothing(self):
        """Without this the tripwire could 'fire' by never being silent."""
        for compare_total in (False, True):
            with self.subTest(compare_total=compare_total):
                self.assertEqual("", firewall_change_description(
                    self.INTACT, dict(self.INTACT), compare_total))
                self.assertEqual("", firewall_change_description(None, None, compare_total))

    def test_a_firewall_that_stopped_being_readable_is_not_taken_for_unchanged(self):
        for compare_total in (False, True):
            with self.subTest(compare_total=compare_total):
                self.assertTrue(firewall_change_description(self.INTACT, None, compare_total))
                self.assertTrue(firewall_change_description(None, self.INTACT, compare_total))
                self.assertTrue(firewall_change_description(
                    self.reading(group=None), self.INTACT, compare_total))
                # The name reading and the total come from one enumeration, so an
                # unreadable firewall loses both at once.
                self.assertTrue(firewall_change_description(
                    self.reading(named=None, total=None), self.INTACT, compare_total))

    def drive_the_call_sites(self, before, after):
        """Run both call sites that end a run against two injected readings.

        The READER is replaced, never the machine. Returns the two outcomes as
        the exception message, or None where the call site stayed silent.
        """
        module = sys.modules[__name__]
        real_reader = module.firewall_snapshot
        real_before = module._FIREWALL_BEFORE
        module._FIREWALL_BEFORE = dict(before)
        module.firewall_snapshot = lambda: dict(after)
        outcomes = []
        try:
            for call in (tearDownModule, lambda: ScriptTestCase().assert_firewall_untouched()):
                try:
                    call()
                    outcomes.append(None)
                except AssertionError as error:
                    outcomes.append(str(error))
        finally:
            module.firewall_snapshot = real_reader
            module._FIREWALL_BEFORE = real_before
        return outcomes

    def test_the_assertions_the_suite_actually_runs_fire_on_a_wiped_firewall(self):
        """Not the description -- the two call sites that end a run, opted in.

        firewall_snapshot is made to answer with the group unchanged and a total
        of 0, which is exactly what the harness would have seen the instant after
        -Name '*' reached the real cmdlet.
        """
        self.environment(enabled=True)
        suite, test = self.drive_the_call_sites(self.INTACT, self.WIPED)
        self.assertIn("THE SUITE CHANGED THIS MACHINE'S FIREWALL", suite or "")
        self.assertIn("583 rules were REMOVED", suite or "")
        self.assertIn("THIS TEST CHANGED THIS MACHINE'S FIREWALL", test or "")
        self.assertIn("583 rules were REMOVED", test or "")

    def test_the_assertions_the_suite_actually_runs_fire_on_a_localcanvas_rule(self):
        """The ordinary run: a rule named as LocalCanvas's still ends it."""
        self.environment(enabled=False)
        suite, test = self.drive_the_call_sites(
            self.INTACT, self.reading(named=[self.OURS_OUTSIDE_THE_GROUP], total=584))
        self.assertIn("THE SUITE CHANGED THIS MACHINE'S FIREWALL", suite or "")
        self.assertIn(self.OURS_OUTSIDE_THE_GROUP, suite or "")
        self.assertIn("THIS TEST CHANGED THIS MACHINE'S FIREWALL", test or "")
        self.assertIn(self.OURS_OUTSIDE_THE_GROUP, test or "")

    def test_the_assertions_the_suite_actually_runs_ignore_an_unrelated_rule(self):
        """The ordinary run: another process's rule ends neither call site."""
        self.environment(enabled=False)
        self.assertEqual([None, None], self.drive_the_call_sites(
            self.reading(total=604), self.reading(total=600)))

    def test_the_reader_is_put_back_and_still_reads_this_machine(self):
        """The test above monkey-patches a module global; this is the receipt."""
        self.assertIs(sys.modules[__name__].firewall_snapshot, firewall_snapshot)
        self.assertEqual(_FIREWALL_BEFORE, sys.modules[__name__]._FIREWALL_BEFORE)


class StrictLanRemovableNameTests(ScriptTestCase):
    """Every hostile name is decided here, by the function that decides it.

    Test-LcStrictLanRemovableName answers a question about a STRING: it returns
    the reason a name is not LocalCanvas's to remove, or '' when it is. It
    invokes nothing and reads nothing, so '*' -- the one character that would
    ask Windows to delete all of this machine's rules -- can be put in front of
    it at no risk whatever.

    That is why the hostile names live here rather than in the tests of
    Invoke-LcStrictLanRemove below, which drive them into a call path whose one
    statement is a removal. Proving a guard must not require pointing a loaded
    weapon at the machine, and this is the same lesson one level down.
    """

    LIBRARY = SCRIPTS / "lib" / "StrictLan.ps1"
    OWN_PREFIX = STRICT_LAN_RULE_PREFIX

    def reasons(self, names):
        """Test-LcStrictLanRemovableName's verdict on each name, in order.

        '' means removable. Nothing in this session can remove anything: the
        module path is blanked first, so the NetSecurity cmdlets cannot be
        auto-loaded and do not resolve -- and the function under test does not
        call one in any case.
        """
        script = "\n".join([
            "$ErrorActionPreference = 'Stop'",
            "$env:PSModulePath = ''",
            "if (Get-Command Remove-NetFirewallRule -ErrorAction SilentlyContinue) {",
            "    throw 'the removal cmdlet is still reachable in this session' }",
            ". " + powershell_literal(self.LIBRARY),
            "$verdicts = @({})".format(", ".join(
                "(Test-LcStrictLanRemovableName -Name " + powershell_literal(name) + ")"
                for name in names)),
            "ConvertTo-Json -Compress -InputObject @($verdicts)",
        ])
        result = subprocess.run(
            [PWSH, "-NoProfile", "-NonInteractive", "-Command", script],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=180, cwd=str(REPO))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        verdicts = as_list(json.loads(result.stdout))
        self.assertEqual(len(names), len(verdicts), output)
        return verdicts

    def test_the_prefix_these_tests_use_is_the_librarys_own(self):
        """A fixture that drifted from the library would prove nothing at all."""
        self.assertIn(
            "$script:LcStrictLanRulePrefix = '" + self.OWN_PREFIX + "'",
            self.LIBRARY.read_text(encoding="utf-8-sig"),
            "STRICT_LAN_RULE_PREFIX no longer mirrors the library")

    def test_a_wildcard_character_is_refused_even_under_our_own_prefix(self):
        """The prefix check alone does not catch these, which is the point.

        Remove-NetFirewallRule MATCHES on -Name. '*' names every rule on the
        machine; 'LocalCanvas-StrictLAN-*' carries our own prefix and still
        matches far more than it names; '[' opens a character class, which is a
        wildcard with no '*' in sight.
        """
        names = ["*", "?", "[", "a*b",
                 self.OWN_PREFIX + "*", self.OWN_PREFIX + "?",
                 self.OWN_PREFIX + "[BD]lock"]
        for name, reason in zip(names, self.reasons(names)):
            with self.subTest(name=name):
                self.assertIn("wildcard", reason,
                              "a wildcard was not refused as one: " + name)

    def test_an_empty_or_blank_name_is_refused(self):
        """An empty -Name is not a narrower request than '*'; it is a broken one."""
        names = ["", " ", "   "]
        for name, reason in zip(names, self.reasons(names)):
            with self.subTest(name=repr(name)):
                self.assertIn("empty", reason)

    def test_a_name_that_is_not_ours_is_refused(self):
        """This feature overlays the user's policy; it never rewrites it."""
        names = ["Some Other Product - Allow 443",
                 "Core Networking - DNS (UDP-Out)",
                 "LocalCanvas"]
        for name, reason in zip(names, self.reasons(names)):
            with self.subTest(name=name):
                self.assertIn(self.OWN_PREFIX, reason,
                              "a foreign name was not refused for being foreign: " + name)

    def test_the_prefix_is_compared_case_sensitively(self):
        """A Windows rule name is not ours to case-fold.

        'localcanvas-strictlan-...' is a name some other product is free to
        hold, so the comparison in the library is Ordinal and this is refused.
        """
        names = [self.OWN_PREFIX.lower() + "Block-Outbound-IPv4",
                 self.OWN_PREFIX.upper() + "Block-Outbound-IPv4"]
        for name, reason in zip(names, self.reasons(names)):
            with self.subTest(name=name):
                self.assertIn(self.OWN_PREFIX, reason)

    def test_our_own_rule_names_are_accepted(self):
        """Without this the whole class would pass on a function that refused
        everything -- including the rules `disable` has to be able to remove."""
        names = [self.OWN_PREFIX + "Block-Outbound-IPv4",
                 self.OWN_PREFIX + "Allow-DHCP"]
        self.assertEqual(["", ""], self.reasons(names))


class StrictLanRemoveGuardTests(ScriptTestCase):
    """The invariant lives in Invoke-LcStrictLanRemove, not in its caller.

    `disable` now refuses a described network, so the names it passes come
    from this machine's own group. That is ONE caller. What is tested here is
    the guard the next caller gets for free: a name is checked where it is
    used, not where it happened to come from -- which is exactly the hole
    `disable -FactsFile` was.

    What this class does NOT do is hand a wildcard to the removal path in order
    to watch the removal path refuse it. Which names are refused, and why, is
    Test-LcStrictLanRemovableName's answer, and StrictLanRemovableNameTests
    above puts every hostile name to that function directly -- it invokes
    nothing. Here Invoke-LcStrictLanRemove is driven with well-formed names
    only: no wildcard character reaches this call path at all.

    Three independent interlocks stand behind even that:

      * the probe session blanks $env:PSModulePath before anything else, so the
        NetSecurity module cannot be auto-loaded and the real
        Remove-NetFirewallRule does not resolve to a command at all. Shadowing
        is a measurement that the right thing was called; this makes the wrong
        thing impossible to call, and the session proves the cmdlet is gone
        before it goes on;
      * a PowerShell *function* takes precedence over a cmdlet of the same
        name, so the session then defines Remove-NetFirewallRule as a recorder
        BEFORE it dot-sources the library, and proves that shadowing took
        effect before a single name under test is passed in. With
        $ErrorActionPreference = 'Stop', a probe that reached anything else
        would end the run instead of continuing;
      * tearDown re-reads this machine's firewall -- LocalCanvas's own group
        AND the total number of rules on the machine -- and fails if either
        moved.

    Nothing here runs the strict LAN script and nothing here is elevated.
    """

    LIBRARY = SCRIPTS / "lib" / "StrictLan.ps1"
    OWN_PREFIX = STRICT_LAN_RULE_PREFIX
    # A name the guard refuses -- it stops one character short of the prefix --
    # and one that is inert with it: no wildcard character, so it matches
    # nothing rather than everything, and inside LocalCanvas's own naming
    # space, so it can never be some other product's rule.
    REFUSED_BUT_INERT = "LocalCanvas-StrictLAN"

    def tearDown(self):
        self.assert_firewall_untouched()

    def invoke_remove(self, names):
        """Invoke-LcStrictLanRemove with the removal cmdlet recorded, not run."""
        script = "\n".join([
            "$ErrorActionPreference = 'Stop'",
            # Interlock one. Without a module path NetSecurity cannot be
            # auto-loaded, so the real cmdlet is not merely shadowed -- it is
            # not there. If the shadowing below ever silently failed, the call
            # would be command-not-found rather than a firewall change.
            "$env:PSModulePath = ''",
            "if (Get-Command Remove-NetFirewallRule -ErrorAction SilentlyContinue) {",
            "    throw 'the real Remove-NetFirewallRule is still reachable here' }",
            "$script:Calls = @()",
            "function Remove-NetFirewallRule { [CmdletBinding()] param([string]$Name)",
            "    $script:Calls += $Name }",
            # Interlock two: prove the recorder is what that name resolves to
            # before a single name under test is passed in. If anything else
            # answered, this line ends the run.
            "Remove-NetFirewallRule -Name 'recorder self test' -ErrorAction Stop",
            "if ($script:Calls.Count -ne 1) { throw 'the recorder did not shadow the cmdlet' }",
            "$script:Calls = @()",
            ". " + powershell_literal(self.LIBRARY),
            "$r = Invoke-LcStrictLanRemove -Names @({})".format(
                ", ".join(powershell_literal(name) for name in names)),
            "ConvertTo-Json -Compress -Depth 6 -InputObject ([pscustomobject]@{",
            "    ok = [bool]$r.Ok",
            "    removed = @($r.Removed)",
            "    skipped = @($r.Skipped | ForEach-Object { $_.Name })",
            "    reasons = @($r.Skipped | ForEach-Object { $_.Reason })",
            "    called = @($script:Calls) })",
        ])
        result = subprocess.run(
            [PWSH, "-NoProfile", "-NonInteractive", "-Command", script],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=180, cwd=str(REPO))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        document = json.loads(result.stdout)
        return {key: as_list(value) if key != "ok" else value
                for key, value in document.items()}

    def test_localcanvas_own_rules_still_go_through(self):
        """Without this, a guard that refused everything would pass the rest.

        It is also what proves the recorder is reached at all: if it were not,
        `called` would be empty here too and every assertion about a refusal
        would be true of a test that ran nothing.
        """
        own = [self.OWN_PREFIX + "Block-Outbound-IPv4", self.OWN_PREFIX + "Allow-DHCP"]
        answer = self.invoke_remove(own)
        self.assertEqual(own, answer["called"])
        self.assertEqual(own, answer["removed"])
        self.assertEqual([], answer["skipped"])
        self.assertTrue(answer["ok"])

    def test_a_refused_name_never_reaches_the_cmdlet_and_does_not_stop_the_rest(self):
        """The loop, not the refusal: one bad entry must not leave a
        half-removed overlay behind, and must not be removed either.

        The refused name here is well-formed -- no wildcard in it, and inside
        LocalCanvas's own naming space -- so nothing hostile is driven into a
        call path that ends in a removal. Which names are refused, and why, is
        StrictLanRemovableNameTests' subject.
        """
        keep = self.OWN_PREFIX + "Allow-DHCP"
        answer = self.invoke_remove([self.REFUSED_BUT_INERT, keep])
        self.assertEqual([keep], answer["called"],
                         "a name the guard refused was handed to Remove-NetFirewallRule")
        self.assertEqual([keep], answer["removed"])
        self.assertEqual([self.REFUSED_BUT_INERT], answer["skipped"],
                         "the refusal was not reported")
        self.assertTrue(any(self.OWN_PREFIX in reason for reason in answer["reasons"]),
                        answer["reasons"])
        self.assertTrue(answer["ok"])


class MachineWriteLintTests(ScriptTestCase):
    """docs/privacy-security.md: the prior policy is overlaid, never rewritten.

    `disable` restores the previous state by removing LocalCanvas's own rules.
    That only works while LocalCanvas has changed nothing else: no rule of the
    user's edited, disabled or renamed, no profile default action touched, no
    adapter, route, resolver or registry key written. Held by code review
    alone, that stays true until the first convenient exception.
    """

    def test_the_scripts_change_nothing_on_this_machine_but_their_own_rules(self):
        offenders, seen = machine_write_offenders(powershell_sources())
        self.assertEqual([], offenders)
        for name, count in seen.items():
            # Exactly one, in both directions. 0 would mean the lint guards
            # nothing; 2 would mean a SECOND call site, which the file rule and
            # the -Name rule both wave through -- see the fixture below.
            self.assertEqual(
                1, count,
                "{} is called on {} line(s) of the PowerShell sources; there must be "
                "exactly one call site, so that the guard in front of it cannot be "
                "walked around by adding another".format(name, count))

    def test_the_rule_fires_on_every_way_around_it(self):
        """Proved against the mistakes it exists to catch, on a copy.

        Each line is written into a copy of a script, never into one this
        suite runs -- and the forbidden thing here is a firewall change, so
        that distinction is the whole point (see the Incident on T-0003).
        """
        injections = (
            ("Set-NetFirewallProfile -All -DefaultOutboundAction Block",
             "change a firewall profile's default action"),
            ("Set-NetFirewallRule -DisplayName 'Something else' -Enabled False",
             "edit a rule LocalCanvas did not create"),
            ("Disable-NetFirewallRule -DisplayGroup 'Core Networking'",
             "turn off a rule LocalCanvas did not create"),
            ("netsh advfirewall set allprofiles state on",
             "change firewall policy behind the ownership model"),
            ("Set-NetConnectionProfile -InterfaceIndex 7 -NetworkCategory Private",
             "reclassify the user's network"),
            ("New-NetRoute -DestinationPrefix '0.0.0.0/0' -NextHop '192.0.2.1'",
             "change this machine's routing"),
            ("Set-DnsClientServerAddress -InterfaceIndex 7 -ServerAddresses '1.1.1.1'",
             "change which resolver this machine uses"),
            ("Disable-NetAdapter -Name 'Wi-Fi' -Confirm:$false", "change a network adapter"),
            ("Set-ItemProperty -Path 'HKLM:\\SOFTWARE\\X' -Name Y -Value 1",
             "reach into the machine's registry"),
            ("Remove-NetFirewallRule -Group 'LocalCanvas Strict LAN'",
             "without naming them one by one"),
            ("New-NetFirewallRule -DisplayName 'ad hoc' -Direction Outbound -Action Block",
             "other than the parameter set the plan printed"),
        )
        copied = Path(self.workspace) / "scripts copy"
        copied.mkdir()
        original = (SCRIPTS / "status.ps1").read_text(encoding="utf-8")
        for injected, expected in injections:
            with self.subTest(line=injected):
                target = copied / "status.ps1"
                target.write_text(original + "\n" + injected + "\n", encoding="utf-8")
                offenders, _ = machine_write_offenders([target])
                self.assertTrue(offenders, "the lint did not fire on: " + injected)
                self.assertTrue(
                    any(expected in offender for offender in offenders),
                    "fired, but not for the right reason: {!r} -> {}".format(
                        injected, offenders))

    def test_naming_a_forbidden_cmdlet_in_prose_or_a_message_is_not_an_offence(self):
        copied = Path(self.workspace) / "prose"
        copied.mkdir()
        target = copied / "lib" / "StrictLan.ps1"
        target.parent.mkdir()
        target.write_text(
            "<#\n"
            "    Nothing here calls Set-NetFirewallProfile or netsh advfirewall.\n"
            "#>\n"
            "# Never Set-NetFirewallRule: the user's policy is not ours to edit.\n"
            "Write-Host 'The NetSecurity cmdlets (New-NetFirewallRule) are unavailable.'\n"
            "New-NetFirewallRule @parameters -ErrorAction Stop | Out-Null\n"
            "Remove-NetFirewallRule -Name $name -ErrorAction Stop\n",
            encoding="utf-8")
        offenders, seen = machine_write_offenders([target])
        self.assertEqual([], offenders)
        self.assertEqual(1, seen["New-NetFirewallRule"])
        self.assertEqual(1, seen["Remove-NetFirewallRule"])

    def test_a_second_call_site_in_the_permitted_file_is_visible_only_in_the_count(self):
        """The hole the file rule and the -Name rule leave between them.

        FIREWALL_WRITES_ALLOWED confines the two cmdlets to lib/StrictLan.ps1
        and refuses a removal that does not name its rules. Neither objects to
        a SECOND `Remove-NetFirewallRule -Name $x` added INSIDE that file --
        one that never asked Test-LcStrictLanRemovableName, and so has no guard
        in front of it at all. Only "exactly one call site" sees that, which is
        what the lint above now asserts.
        """
        copied = Path(self.workspace) / "second call site"
        target = copied / "lib" / "StrictLan.ps1"
        target.parent.mkdir(parents=True)
        target.write_text(
            "Remove-NetFirewallRule -Name $name -ErrorAction Stop\n"
            "Remove-NetFirewallRule -Name $sneaked -ErrorAction Stop\n"
            "New-NetFirewallRule @parameters -ErrorAction Stop | Out-Null\n",
            encoding="utf-8")
        offenders, seen = machine_write_offenders([target])
        self.assertEqual([], offenders,
                         "the file rule and the -Name rule do not object to it")
        self.assertEqual(2, seen["Remove-NetFirewallRule"],
                         "the count is the only thing that sees the second call site")
        self.assertEqual(1, seen["New-NetFirewallRule"])


class StrictLanSafetyLintTests(ScriptTestCase):
    """The suite must not be a way to do the thing the suite forbids.

    The Incident on T-0003: a change proving a "never kill by name" lint wrote
    the forbidden command into a script this harness executes, and it ran. The
    forbidden thing here is a firewall change, so the rule is that the strict
    LAN script is reached only from a guarded helper, and this holds it.

    T-0294 added the second such helper and widened the lint with it. The
    version-gate class has to start all nine entry scripts, that script among
    them, and the lint used to look for exactly one way of starting a process
    (run_script) -- so a subprocess.run naming STRICT_LAN_SCRIPT would have been
    invisible to it. PROCESS_STARTERS is that hole closed; a second helper is
    allowed, a second route around the helpers is not.
    """

    def test_this_suite_never_runs_the_strict_lan_script_unguarded(self):
        offenders = strict_lan_invocation_offenders(
            Path(__file__).read_text(encoding="utf-8"))
        self.assertEqual([], offenders)

    def test_the_guard_fires_on_the_ways_around_it(self):
        literal = "strict-lan" + ".ps1"
        for injected, expected in (
            ('        self.run_script("' + literal + '", "enable")', "names the script file"),
            ('        result = self.run_script(SCRIPTS / "' + literal + '")',
             "names the script file"),
            ('        self.run_script(' + 'STRICT_LAN' + '_SCRIPT, "enable")',
             "outside run_strict_lan()"),
            # T-0294: the two other ways this file can start a process. Before
            # PROCESS_STARTERS both of these passed the lint.
            ('        subprocess.run([shell, SCRIPTS / ' + 'STRICT_LAN' + '_SCRIPT])',
             "outside run_strict_lan()"),
            ('        refuse_under_windows_powershell(self, SCRIPTS / ' +
             'STRICT_LAN' + '_SCRIPT)', "outside run_strict_lan()"),
        ):
            with self.subTest(line=injected.strip()):
                text = ("def test_something(self):\n" + injected + "\n")
                offenders = strict_lan_invocation_offenders(text)
                self.assertTrue(offenders, "the lint did not fire on: " + injected)
                self.assertTrue(any(expected in offender for offender in offenders),
                                "fired for the wrong reason: {}".format(offenders))

    def test_the_guard_allows_the_helpers_themselves_and_only_those(self):
        for helper in STRICT_LAN_GUARDED_HELPERS:
            with self.subTest(helper=helper):
                text = ("def " + helper + "(self, *extra_args):\n"
                        "    return self.run_script(" + "STRICT_LAN" +
                        "_SCRIPT, *extra_args)\n")
                self.assertEqual([], strict_lan_invocation_offenders(text))
        # And a helper that is not on the list is not excused by looking like one.
        text = ("def run_strict_lan_but_not_really(self):\n"
                "    return self.run_script(" + "STRICT_LAN" + "_SCRIPT)\n")
        self.assertEqual([], strict_lan_invocation_offenders(text),
                         "prefix matching is what the list uses; this is recorded, "
                         "not asserted as desirable")

    def test_both_guarded_helpers_exist_under_those_names(self):
        """The list is a claim about this file, so it is checked against it.

        A helper renamed without the list being updated would leave the lint
        excusing a name nothing answers to, and the real call site unguarded.
        """
        text = Path(__file__).read_text(encoding="utf-8")
        for helper in STRICT_LAN_GUARDED_HELPERS:
            with self.subTest(helper=helper):
                self.assertIn("    def " + helper + "(", text)

    def test_the_helper_refuses_a_subcommand_that_could_change_the_firewall(self):
        with self.assertRaises(AssertionError):
            self.run_strict_lan("enable")
        with self.assertRaises(AssertionError):
            self.run_strict_lan("disable")


# ==========================================================================
# doctor.ps1
# ==========================================================================


class DoctorTests(ScriptTestCase):
    def test_is_read_only(self):
        self.write_config()
        result = self.run_script("doctor.ps1", timeout=300)
        output = self.output_of(result)
        # 2 is a run in which a check could not be made (T-0199). What these
        # two tests are about is what doctor leaves behind, not its verdict,
        # which DoctorExitCodeTests holds.
        self.assertIn(result.returncode, (0, 2, 3), output)
        self.assertFalse(self.runtime_dir.exists(),
                         "doctor created the runtime state directory just by reporting")
        self.assertFalse(self.comfy_marker.exists())
        self.assertFalse(self.gateway_marker.exists())
        self.assertIn("read-only", output)

    def test_an_unprovable_record_is_reported_as_unproved_and_kept(self):
        stub = self.start_backend_stub()
        self.write_config()
        record = self.unprovable_record(stub.pid)
        self.write_pid_file("comfy", record)

        result = self.run_script("doctor.ps1", timeout=300)
        output = self.output_of(result)
        self.assertIn(result.returncode, (0, 2, 3), output)
        self.assertIn(
            "ownership of PID {} could NOT be proved".format(stub.pid), output)
        self.assertIn("the record was kept", output)
        self.assertEqual(record, self.read_pid_file("comfy"))
        self.assertIsNone(stub.poll())

    def test_reports_when_comfyui_is_not_bound_to_localhost(self):
        """The check the whole security posture rests on."""
        self.write_config(comfy_host="0.0.0.0")
        result = self.run_script("doctor.ps1", timeout=300)
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn("[FAIL] ComfyUI binding - NOT bound to localhost", output)
        self.assertIn("no authentication", output)
        self.assert_no_stack_trace(output)

    def test_reports_a_localhost_binding_as_correct(self):
        self.write_config(comfy_host="127.0.0.1")
        output = self.output_of(self.run_script("doctor.ps1", timeout=300))
        self.assertIn("[ OK ] ComfyUI binding - localhost only", output)
        self.assertNotIn("NOT bound to localhost", output)

    def test_reports_a_listen_argument_that_puts_comfyui_on_the_network(self):
        # comfy.host can say 127.0.0.1 while the launch arguments tell ComfyUI
        # to listen on everything. The posture is what ComfyUI actually binds.
        self.write_config(comfy_extra_args=[
            "--port", str(self.comfy_port),
            "--launch-marker", str(self.comfy_marker),
            "--listen", "0.0.0.0",
        ])
        result = self.run_script("doctor.ps1", timeout=300)
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn("--listen 0.0.0.0 puts ComfyUI on the network", output)

    def test_reports_a_missing_python_environment(self):
        self.write_config()
        result = self.run_script(
            "doctor.ps1", python_exe=self.workspace / "no python.exe", timeout=300)
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn("Python environment - missing", output)
        self.assertIn("setup.ps1", output)
        self.assert_no_stack_trace(output)

    def test_reports_a_broken_python_environment(self):
        self.write_config()
        broken = self.workspace / "not python.exe"
        broken.write_text("this is not an executable", encoding="utf-8")
        result = self.run_script("doctor.ps1", python_exe=broken, timeout=300)
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn("Python environment - broken", output)
        self.assert_no_stack_trace(output)

    @staticmethod
    def declared_python_range():
        """(specifier, (floor_major, floor_minor), (ceiling_major, ceiling_minor,
        inclusive)) exactly as gateway/pyproject.toml declares it.

        Read here, out of the metadata, and never written down a second time:
        the whole point of T-0281 is that the doctor's gate and the doctor's
        printed line both come from that one declaration. A test carrying its
        own copy of "3.14" would go on passing on the day the declaration moved
        and the script did not.
        """
        text = (REPO / "gateway" / "pyproject.toml").read_text(encoding="utf-8")
        declared = re.search(
            r"^\s*requires-python\s*=\s*[\"']([^\"']+)[\"']", text, re.MULTILINE)
        assert declared, "no requires-python in gateway/pyproject.toml"
        specifier = declared.group(1).strip()
        floor = re.search(r">=\s*(\d+)\.(\d+)", specifier)
        assert floor, "no floor in " + specifier
        ceiling = re.search(r"<(=?)\s*(\d+)\.(\d+)", specifier)
        return (
            specifier,
            (int(floor.group(1)), int(floor.group(2))),
            None if ceiling is None else (
                int(ceiling.group(2)), int(ceiling.group(3)), ceiling.group(1) == "="),
        )

    def pretend_python(self, name, version):
        """An interpreter that answers the version probe, and nothing else.

        Enough for doctor to reach its verdict on the version before anything
        else is diagnosed -- which is all these three tests are about.
        """
        stub = self.workspace / name
        stub.write_text("@echo off\r\necho {}\r\n".format(version), encoding="ascii")
        return stub

    def test_reports_an_unsupported_python_version(self):
        self.write_config()
        specifier, _floor, _ceiling = self.declared_python_range()
        pretend = self.pretend_python("old python.cmd", "3.7.0")
        result = self.run_script("doctor.ps1", python_exe=pretend, timeout=300)
        output = self.output_of(result)
        self.assertIn(
            "Python 3.7.0, outside the supported range " + specifier, output)
        self.assertNotEqual(0, result.returncode, output)
        self.assert_no_stack_trace(output)

    def test_an_interpreter_at_the_declared_ceiling_does_not_read_as_ok(self):
        """T-0281: the doctor gated on the floor and printed half the range.

        Measured on the machine T-0173 validated from: the default `py` there
        is 3.14, gateway/pyproject.toml declares ">=3.10,<3.14", and a .venv on
        that interpreter was reported "Python environment - Python 3.14.0" with
        "Supported: >= 3.10" -- a verdict pip contradicts at install time. The
        doctor is the check a stranger is told to run, so it said fine over an
        environment that cannot hold the gateway.

        Both versions here are computed FROM the declaration, never written
        down: move the ceiling in gateway/pyproject.toml and this test moves
        with it, while a gate that kept its own copy of the number would fail.
        """
        specifier, floor, ceiling = self.declared_python_range()
        self.assertIsNotNone(
            ceiling,
            "gateway/pyproject.toml no longer declares a ceiling, so this test would "
            "pass against the floor-only gate it exists to catch")
        major, minor, inclusive = ceiling
        # The first version the declaration excludes, and the last it allows.
        refused = "{}.{}.0".format(major, minor + 1 if inclusive else minor)
        allowed_minor = (minor if inclusive else minor - 1)
        self.assertGreaterEqual(
            allowed_minor, floor[1] if major == floor[0] else 0,
            "the declared range has no version inside it below the ceiling, so the "
            "control below would measure nothing: " + specifier)
        allowed = "{}.{}.9".format(major, allowed_minor)

        self.write_config()
        result = self.run_script(
            "doctor.ps1", python_exe=self.pretend_python("new python.cmd", refused),
            timeout=300)
        output = self.output_of(result)
        self.assertNotIn("[ OK ] Python environment", output)
        self.assertIn(
            "[FAIL] Python environment - Python {}, outside the supported range {}".format(
                refused, specifier), output)
        self.assertNotEqual(0, result.returncode, output)
        self.assert_no_stack_trace(output)

        # THE CONTROL, and without it this would pass against a doctor that
        # refuses every interpreter: the same stub, one minor version lower,
        # is inside the declared range and is accepted.
        control = self.run_script(
            "doctor.ps1", python_exe=self.pretend_python("kept python.cmd", allowed),
            timeout=300)
        control_output = self.output_of(control)
        self.assertIn(
            "[ OK ] Python environment - Python " + allowed, control_output)
        self.assertNotIn("outside the supported range", control_output)

    def test_the_reported_supported_range_is_the_whole_declared_specifier(self):
        """The printed half of T-0281, and the same pin B3 put on setup.ps1.

        The line under the passing check said "Supported: >= 3.10" while the
        declaration was ">=3.10,<3.14". It is the declaration itself now, read
        by Get-LcSupportedPythonFloor -- the one reader scripts\\setup.ps1
        prints from -- so the two cannot drift.
        """
        specifier, floor, ceiling = self.declared_python_range()
        self.assertIsNotNone(
            ceiling,
            "gateway/pyproject.toml no longer declares a ceiling, so this test would "
            "pass against the floor-only line it exists to catch")
        self.write_config()
        output = self.output_of(self.run_script("doctor.ps1", timeout=300))
        self.assertIn(
            "Supported: {} (from gateway/pyproject.toml)".format(specifier), output)
        self.assertNotIn(
            "Supported: >= {}.{} (from gateway/pyproject.toml)".format(*floor), output)

    def test_reports_a_missing_comfy_root_and_launcher(self):
        missing = self.workspace / "no such comfy"
        self.write_config(body="\n".join([
            "runtime:", "  manage_comfy: true",
            "comfy:", "  root: " + yaml_path(missing),
            '  host: "127.0.0.1"', "  port: {}".format(self.comfy_port),
            "  launcher:",
            "    executable: " + yaml_path(missing / "python.exe"),
            "    script: " + yaml_path(missing / "main.py"),
            "workflows:", '  registry: "workflows/examples"',
            "gateway:", '  host: "127.0.0.1"', "  port: {}".format(self.gateway_port),
            "identity:", '  display_name: "Test PC"', "",
        ]))
        result = self.run_script("doctor.ps1", timeout=300)
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn("ComfyUI root - does not exist", output)
        self.assertIn("ComfyUI launcher executable - does not exist", output)
        self.assertIn("ComfyUI launcher script - does not exist", output)
        self.assertIn("never searches the machine", output)

    def test_reports_the_whole_checklist(self):
        self.write_config()
        output = self.output_of(self.run_script("doctor.ps1", timeout=300))
        for expected in ("Python environment", "Configuration", "Mode",
                         "ComfyUI binding", "Gateway port", "ComfyUI port",
                         "Gateway", "LAN address", "Endpoint", "mDNS",
                         "Firewall", "Strict LAN mode"):
            self.assertIn(expected, output, "doctor did not report: " + expected)

    def test_reads_configuration_through_the_seam_and_not_a_reader_of_its_own(self):
        self.write_config()
        result = self.run_script(
            "doctor.ps1", env=self.script_env(LC_STUB_CONFIG_MODE="crash"), timeout=300)
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        # A sentence that exists only inside the loader.
        self.assertIn("the loader refused this file", output)
        self.assertIn("could not be diagnosed", output)
        self.assert_no_stack_trace(output)

    def test_a_missing_configuration_is_reported_without_a_stack_trace(self):
        result = self.run_script(
            "doctor.ps1", config=self.workspace / "no such config.yaml", timeout=300)
        output = self.output_of(result)
        self.assertEqual(2, result.returncode, output)
        self.assertIn("configuration file not found", output)
        self.assert_no_stack_trace(output)

    def test_the_ports_report_ownership_rather_than_who_holds_them(self):
        self.write_config()
        output = self.output_of(self.run_script("doctor.ps1", timeout=300))
        self.assertIn("not started by LocalCanvas", output)


# ==========================================================================
# doctor.ps1: the endpoint is probed, not spelled (T-0115)
# ==========================================================================


# A second loopback address. Windows holds the whole of 127.0.0.0/8 on the
# loopback interface, so this one can be bound and connected to, is refused
# promptly when nothing listens, and reaches no network at all. It is how
# these tests build "an endpoint that is not the one the gateway answers on"
# out of nothing but this machine: no real adapter, no real LAN, and nothing
# borrowed from whatever network the machine running the suite happens to be
# attached to.
SECOND_LOOPBACK = "127.0.0.2"

# How much longer a run against a *hung* endpoint may take than the same run
# against a refused one. The probe's own deadline is three seconds and there
# are two probes, so the honest difference is about two; without a deadline
# HttpClient waits a hundred seconds per probe, which is what this measures.
HANG_BUDGET_SECONDS = 25.0

# Anchors in scripts/doctor.ps1 that the tests below inject at or mutate, each
# asserted to occur exactly once before it is used: an anchor that has moved
# makes a replacement silently do nothing, and the test then proves nothing.
#
# The start of the run. A function a copy defines just above it wins over the
# libraries' definitions and over doctor's own, all of which come earlier.
DOCTOR_MAIN = "\ntry {\n    Write-LcBanner\n"
# The one place the warning total the summary and the exit code share is taken.
DOCTOR_UNCLEAN_COUNT = "$unclean = @($checks | Where-Object { $_.Status -eq 'warn' }).Count"


class DoctorEndpointProbeTests(ScriptTestCase):
    """T-0115: doctor said the endpoint was fine while nothing could reach it.

    `[ OK ] Endpoint` was asserted about a URL nothing had contacted, and
    `No problems found` was printed over a check that could not run. Every
    test here builds its own conditions on loopback: the machine's real
    network, its real adapters and whatever tunnels are up on it are never
    part of a fixture, because a test that needs them proves nothing on
    anyone else's machine.
    """

    # -- fixtures ---------------------------------------------------------

    @staticmethod
    def check_block(output, headline):
        """One check's headline and the detail lines indented under it."""
        lines = output.splitlines()
        for index, line in enumerate(lines):
            if not line.startswith(headline):
                continue
            block = [line]
            for following in lines[index + 1:]:
                if not following.startswith("       "):
                    break
                block.append(following)
            return "\n".join(block)
        return ""

    def start_gateway_stub(self, host, port, **stub_env):
        """A gateway the HARNESS owns, answering /api/v1/info on one address.

        Not started through start.ps1: what is under test is what doctor says
        about an endpoint, and LocalCanvas owning the process would change the
        ownership lines rather than the endpoint ones. ``stub_env`` steers the
        stub (LC_STUB_GATEWAY_ALIEN, for one).
        """
        env = self.script_env(**stub_env)
        # Its own tripwire file, so it is never mistaken for a gateway that
        # LocalCanvas launched.
        env["LC_STUB_GATEWAY_MARKER"] = str(self.workspace / "harness gateway.marker")
        process = subprocess.Popen(
            [sys.executable, "-m", "localcanvas_gateway",
             "--config", str(self.config_path),
             "--host", host, "--port", str(port), "--no-qr", "--no-mdns"],
            env=env, cwd=str(REPO),
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        self.owned_stubs.append(process)
        url = "http://{}:{}/api/v1/info".format(host, port)
        self.assertTrue(
            wait_until(lambda: http_ok(url), 30),
            "the harness's own gateway stub never answered at " + url)
        return process

    def start_silent_listener(self, host, port):
        """A socket that completes the handshake and then says nothing.

        What a hung endpoint looks like from outside: connect succeeds from
        the listen backlog, the request goes out, and no byte of a response
        ever comes back. It accepts nothing and writes nothing, so the only
        thing it can do to a client is make it wait.
        """
        listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        listener.bind((host, port))
        listener.listen(8)
        self.addCleanup(listener.close)
        return listener

    def start_local_mdns_responder(self):
        """A responder of this test's own, answering from 127.0.0.1.

        doctor's query carries the QU bit, so a responder answers to the
        ephemeral port the query came from. This one answers that port on
        loopback, which makes the address doctor sees an address that is
        certainly not the LAN address it reports -- Get-LcLanAddress excludes
        127.* by construction. Nothing is sent anywhere but to this machine.

        Returns None when UDP 5353 is already held, which is a fact about the
        machine and not a result.
        """
        listening = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            listening.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            listening.bind(("", 5353))
        except OSError:
            listening.close()
            return None
        try:
            listening.setsockopt(
                socket.IPPROTO_IP, socket.IP_ADD_MEMBERSHIP,
                struct.pack("4s4s", socket.inet_aton("224.0.0.251"),
                            socket.inet_aton("0.0.0.0")))
        except OSError:
            listening.close()
            return None
        listening.settimeout(0.25)
        answering = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        answering.bind(("127.0.0.1", 0))
        stop = threading.Event()

        def serve():
            while not stop.is_set():
                try:
                    query, sender = listening.recvfrom(4096)
                except socket.timeout:
                    continue
                except OSError:
                    return
                if sender[1] == 5353:
                    continue  # another responder's own multicast, not a query
                try:
                    # The header with QR and AA set, and the question echoed
                    # back: enough of an answer for "something replied".
                    answering.sendto(query[:2] + b"\x84\x00" + query[4:],
                                     ("127.0.0.1", sender[1]))
                except OSError:
                    return

        thread = threading.Thread(target=serve, daemon=True)
        thread.start()

        def shut_down():
            stop.set()
            thread.join(timeout=5)
            listening.close()
            answering.close()

        self.addCleanup(shut_down)
        return thread

    # -- the endpoint ------------------------------------------------------

    def test_an_endpoint_that_answers_is_reported_the_way_it_always_was(self):
        """The differential for ordinary use: only the probe's result differs.

        One configuration, one address. The gateway is down for the first run
        and up for the others, and ``[ OK ] Endpoint - <url>`` -- the headline
        doctor printed before this check existed at all -- is printed only
        where the probe answered AND the address is one a phone could use.

        The address is loopback, because nothing in this suite binds a real
        adapter, and a loopback address is not a LAN endpoint (T-0119): run as
        it is, it answers as a warning that says so. The third run is a copy
        of doctor told that this same address is a LAN one, which is the one
        thing that separates it from the [ OK ] line; everything else, the
        probe included, is real.
        """
        port = free_port()
        self.write_config(gateway_host="127.0.0.1", gateway_port=port)
        published = "http://127.0.0.1:{}".format(port)

        quiet = self.output_of(self.run_script("doctor.ps1", timeout=300))
        self.assertNotIn("[ OK ] Endpoint - " + published, quiet)
        self.assertIn("[WARN] Endpoint - {} - nothing answered".format(published), quiet)

        self.start_gateway_stub("127.0.0.1", port)
        answering = self.output_of(self.run_script("doctor.ps1", timeout=300))
        block = self.check_block(answering, "[WARN] Endpoint - " + published)
        self.assertEqual(
            "\n".join([
                "[WARN] Endpoint - " + published,
                "       The gateway answered at {}/api/v1/info.".format(published),
                "       Reachable from this machine only.",
            ]),
            block, answering)
        self.assertNotIn("[ OK ] Endpoint", answering)
        self.assertNotIn("[FAIL] Endpoint", answering)
        self.assert_no_stack_trace(answering)

        copied = self.copy_scripts_with_stopping_disabled()
        doctor = copied / "doctor.ps1"
        original = doctor.read_text(encoding="utf-8-sig")
        self.assertEqual(1, original.count(DOCTOR_MAIN), original)
        declared_lan = original.replace(
            DOCTOR_MAIN,
            "\nfunction Get-LcPublishedEndpoint {{\n"
            "    param($Config, $Endpoints)\n"
            "    # Injected by the test suite: this address, declared a LAN one.\n"
            "    return [pscustomobject]@{{ Url = '{}'; IsLan = $true }}\n"
            "}}\n".format(published) + DOCTOR_MAIN[1:])
        doctor.write_text(declared_lan, encoding="utf-8")
        as_lan = self.output_of(
            self.run_script("doctor.ps1", script_dir=copied, timeout=300))
        self.assertEqual(
            "\n".join([
                "[ OK ] Endpoint - " + published,
                "       The gateway answered at {}/api/v1/info.".format(published),
            ]),
            self.check_block(as_lan, "[ OK ] Endpoint - " + published), as_lan)
        self.assertNotIn("Reachable from this machine only.", as_lan)
        self.assert_no_stack_trace(as_lan)

    def test_a_gateway_that_answers_only_on_loopback_is_a_failure_that_says_so(self):
        """The T-0115 signature, and the two outcomes it has to keep apart.

        Loopback answering while the published address does not is the whole
        diagnosis. Nothing answering anywhere is an ordinary stopped machine.
        The same configuration produces both, so a check that collapsed the
        two would have to report them alike, and it does not.
        """
        if is_elevated():
            self.skipTest(
                "this check has to hold with no elevation at all, and an "
                "elevated session cannot show that")
        port = free_port()
        self.write_config(gateway_host=SECOND_LOOPBACK, gateway_port=port)
        published = "http://{}:{}".format(SECOND_LOOPBACK, port)
        loopback = "http://127.0.0.1:{}".format(port)

        # Nothing is listening on either address. That is not a failure.
        silent = self.run_script("doctor.ps1", timeout=300)
        silent_output = self.output_of(silent)
        self.assertNotIn("[FAIL] Endpoint", silent_output)
        self.assertIn(
            "[WARN] Endpoint - {} - nothing answered".format(published), silent_output)
        self.assertIn(
            "and nothing answered at {}/api/v1/info either.".format(loopback),
            silent_output)

        # Now the gateway answers, and only on loopback.
        self.start_gateway_stub("127.0.0.1", port)
        result = self.run_script("doctor.ps1", timeout=300)
        output = self.output_of(result)
        self.assertEqual(3, result.returncode, output)
        self.assertIn(
            "[FAIL] Endpoint - {} does not answer, though 127.0.0.1 does".format(published),
            output)
        self.assertIn("The gateway answered at {}/api/v1/info.".format(loopback), output)
        self.assertIn(
            "The gateway itself is fine. Something between this network and it is not,",
            output)
        self.assertIn("and a phone given this endpoint will not reach it either.", output)
        # The published address is itself loopback, so the one sentence that
        # says why no phone will reach it belongs here too (T-0119).
        self.assertIn(
            "       and a phone given this endpoint will not reach it either.\n"
            "       Reachable from this machine only.\n", output)
        self.assertNotIn("[WARN] Endpoint", output)
        self.assertNotIn("No problems found", output)
        self.assert_no_stack_trace(output)

    def test_a_failed_endpoint_probe_reports_the_route_that_covers_the_address(self):
        """The evidence that was on the machine all along and never read.

        Get-NetRoute needs no Administrator -- only the firewall table does --
        so the routes covering the published address are reported next to the
        failure. What they should be is not doctor's to say, and it says
        nothing about them beyond what it read.
        """
        if is_elevated():
            self.skipTest(
                "the route table has to be readable WITHOUT elevation, and an "
                "elevated session cannot show that")
        port = free_port()
        self.write_config(gateway_host=SECOND_LOOPBACK, gateway_port=port)
        self.start_gateway_stub("127.0.0.1", port)
        output = self.output_of(self.run_script("doctor.ps1", timeout=300))

        self.assertIn(
            "Routes on this machine that cover {}:".format(SECOND_LOOPBACK), output)
        self.assertIn("127.0.0.0/8 -> interface ", output)
        self.assertIn("route metric ", output)
        self.assertIn("No interface on this machine holds {}.".format(SECOND_LOOPBACK), output)
        self.assertIn(
            "Reported as measured. Doctor reads the route table and changes nothing in it.",
            output)
        # It reports what it measured and stops. An interface's name is a
        # measurement and belongs in the report; a verdict on whatever owns
        # that interface, or an instruction to go and change its settings, is
        # a conclusion this tool has not earned. Scoped to the endpoint check's
        # own block, because an adapter on the machine running this may be
        # named anything at all.
        block = self.check_block(output, "[FAIL] Endpoint")
        self.assertTrue(block, "the endpoint failure printed no detail at all")
        for overreach in ("misconfigur", "uninstall", "disconnect", "turn off",
                          "switch off", "disable", "reconfigure", "settings"):
            self.assertNotIn(
                overreach, block.lower(),
                "doctor named a remedy it has not earned: " + overreach)

    def test_a_hung_endpoint_does_not_hang_the_diagnosis(self):
        """The probe's deadline, measured as a difference rather than claimed.

        The test workstation stalled twenty-one seconds before failing. The
        two runs below differ only in whether the endpoint accepts and then
        says nothing, so everything else doctor does -- reading the firewall
        table above all, which is the slow part -- cancels out of the
        subtraction. Without a deadline the hung run pays a hundred seconds
        per probe and this difference cannot fit in the budget.
        """
        hung_port = free_port()
        self.start_silent_listener(SECOND_LOOPBACK, hung_port)
        self.write_config(gateway_host=SECOND_LOOPBACK, gateway_port=hung_port)
        started = time.monotonic()
        hung = self.output_of(self.run_script("doctor.ps1", timeout=600))
        hung_seconds = time.monotonic() - started

        refused_port = free_port()
        self.write_config(gateway_host=SECOND_LOOPBACK, gateway_port=refused_port)
        started = time.monotonic()
        refused = self.output_of(self.run_script("doctor.ps1", timeout=600))
        refused_seconds = time.monotonic() - started

        self.assertIn(
            "[WARN] Endpoint - http://{}:{} - nothing answered".format(
                SECOND_LOOPBACK, hung_port),
            hung, "the hung endpoint was not reported as unanswered")
        self.assertIn(
            "[WARN] Endpoint - http://{}:{} - nothing answered".format(
                SECOND_LOOPBACK, refused_port),
            refused)
        self.assertLess(
            hung_seconds - refused_seconds, HANG_BUDGET_SECONDS,
            "a hung endpoint cost {:.1f}s against {:.1f}s for a refused one; "
            "the probe has no bounded deadline".format(hung_seconds, refused_seconds))

    # -- the summary -------------------------------------------------------

    def test_a_warning_is_never_summarised_as_a_clean_bill_of_health(self):
        """`No problems found` was printed over a check that could not run.

        The second half of this is the differential that stops the assertion
        being vacuous: the clean bill is still there to be printed, and the
        same run prints it again as soon as the one line that remembers a
        warning is taken out of a copy of the script.
        """
        self.write_config()
        result = self.run_script("doctor.ps1", timeout=300)
        plain = self.output_of(result)
        self.assertIn("[WARN]", plain, "this run produced no warning to summarise")
        if "[FAIL]" in plain:
            self.skipTest(
                "this machine fails a check of its own, so the warning-only "
                "summary is not what is being printed:\n" + plain)
        self.assertNotIn("No problems found.", plain)
        self.assertIn("No failures, but ", plain)
        self.assertIn("did not come back clean - see the [WARN] lines above.", plain)
        self.assertIn("A check that could not be made is not a check that passed.", plain)
        self.assertIn("This run is not a clean bill of health.", plain)
        # And the channel a machine reads says the same thing (T-0199).
        self.assertEqual(2, result.returncode, plain)

        copied = self.copy_scripts_with_stopping_disabled()
        doctor = copied / "doctor.ps1"
        original = doctor.read_text(encoding="utf-8-sig")
        self.assertEqual(1, original.count(DOCTOR_UNCLEAN_COUNT), original)
        forgetful = original.replace(DOCTOR_UNCLEAN_COUNT, "$unclean = 0")
        doctor.write_text(forgetful, encoding="utf-8")

        mutated_result = self.run_script("doctor.ps1", script_dir=copied, timeout=300)
        mutated = self.output_of(mutated_result)
        self.assertIn("[WARN]", mutated, "the copy produced no warning either")
        self.assertIn(
            "[ OK ] No problems found.", mutated,
            "the clean bill of health was never available to be printed, so its "
            "absence above says nothing")
        self.assertEqual(
            0, mutated_result.returncode,
            "the exit code did not follow the count the summary is drawn from, "
            "so the two can disagree:\n" + mutated)

    # -- discovery ---------------------------------------------------------

    def test_mdns_calls_out_an_answer_from_another_address(self):
        """`mDNS works` was true and useless when the answer came from a
        tunnel's address: a phone is handed an address it cannot reach."""
        require_integration(
            self, "sends a real mDNS query on this machine's network, so what answers "
            "depends on the other devices there")
        if self.start_local_mdns_responder() is None:
            self.skipTest("UDP 5353 is already held on this machine, so this "
                          "test cannot decide which responder answers")
        self.write_config()
        output = self.output_of(self.run_script("doctor.ps1", timeout=300))

        lan = re.search(r"\[ OK \] LAN address - (\S+)", output)
        if lan is None:
            self.skipTest("this machine reports no LAN address to compare against")
        plain = re.search(
            r"A responder at (\S+?) answered a query sent to 224\.0\.0\.251:5353\.",
            output)
        called_out = re.search(
            r"A query sent to 224\.0\.0\.251:5353 was answered from (\S+?)\.", output)
        if plain is None and called_out is None:
            self.skipTest("nothing answered the mDNS query on this machine")
        answered = (plain or called_out).group(1)
        if answered == lan.group(1):
            self.skipTest(
                "the answer came from this machine's LAN address, so there is "
                "no mismatch here to call out")

        self.assertIsNone(
            plain,
            "an answer from {} was reported as plain success while the LAN "
            "address is {}".format(answered, lan.group(1)))
        self.assertIn(
            "[WARN] mDNS - the answer came from an address that is not this "
            "machine's LAN address", output)
        self.assertIn(
            "A query sent to 224.0.0.251:5353 was answered from {}.".format(answered),
            output)
        self.assertIn(
            "The LAN address reported above is {}.".format(lan.group(1)), output)
        self.assertNotIn("No problems found", output)

    # -- loopback is not LAN (T-0119) --------------------------------------

    def test_a_loopback_gateway_host_is_not_a_lan_endpoint(self):
        """Get-LcPublishedEndpoint's answer for a gateway bound to one host.

        Every loopback literal is refused as a LAN endpoint, and everything
        else keeps the answer it had -- including a name that merely starts
        like a loopback address, and 128.0.0.1, the first address past
        127.0.0.0/8. Nothing here resolves a name or opens a socket: a host
        that is not a wildcard is answered from the string alone.
        """
        expected = {
            "127.0.0.1": False,
            "127.0.0.2": False,
            "127.255.255.254": False,
            "localhost": False,
            "LocalHost": False,
            "::1": False,
            "0:0:0:0:0:0:0:1": False,
            "128.0.0.1": True,
            "192.0.2.20": True,
            "198.51.100.5": True,
            "fe80::1": True,
            "127.0.0.1.example": True,
            "localhost.example": True,
            "pc.local": True,
        }
        snippet = (
            "$endpoints = [pscustomobject]@{ GatewayBindsAll = $false }\n"
            "$answers = foreach ($name in @(" +
            ", ".join(powershell_literal(host) for host in expected) + ")) {\n"
            "    $config = [pscustomobject]@{ gateway = [pscustomobject]@{ host = $name; port = 7801 } }\n"
            "    $published = Get-LcPublishedEndpoint -Config $config -Endpoints $endpoints\n"
            "    [pscustomobject]@{ host = $name; url = [string]$published.Url; is_lan = [bool]$published.IsLan }\n"
            "}\n"
            "ConvertTo-Json -InputObject @($answers) -Compress\n")
        result = self.run_powershell(snippet)
        self.assertEqual(0, result.returncode, self.output_of(result))
        answers = {item["host"]: item for item in json.loads(result.stdout)}
        self.assertEqual(sorted(expected), sorted(answers), result.stdout)
        for host, is_lan in expected.items():
            with self.subTest(host=host):
                self.assertIs(is_lan, answers[host]["is_lan"], result.stdout)
        # The URL is untouched by the decision: only the claim about it moved.
        self.assertEqual("http://127.0.0.1:7801", answers["127.0.0.1"]["url"])
        self.assertEqual("http://[::1]:7801", answers["::1"]["url"])
        self.assertEqual("http://192.0.2.20:7801", answers["192.0.2.20"]["url"])

    def test_every_loopback_host_nothing_answers_at_is_reachable_from_this_machine_only(self):
        """The branch 127.0.0.1 never takes (T-0119, review round 1).

        127.0.0.1 is the one loopback host whose published URL IS the loopback
        URL doctor compares against, so it takes a branch of its own. Every
        other loopback literal, with nothing listening, lands where nothing
        answered at either address -- and that branch lost the line. Each run
        here is a real doctor over a real refused probe.

        The route lines that follow for an IPv4 address are this machine's own
        and are not asserted; the block is asserted verbatim up to them, and
        whole for the two hosts that have none.
        """
        for host, url_host, has_routes in (
                (SECOND_LOOPBACK, SECOND_LOOPBACK, True),
                ("localhost", "localhost", False),
                ("::1", "[::1]", False)):
            with self.subTest(host=host):
                port = free_port()
                self.write_config(gateway_host=host, gateway_port=port)
                output = self.output_of(self.run_script("doctor.ps1", timeout=300))
                published = "http://{}:{}".format(url_host, port)
                headline = "[WARN] Endpoint - {} - nothing answered".format(published)
                expected = [
                    headline,
                    "       Nothing answered at {}/api/v1/info,".format(published),
                    "       and nothing answered at http://127.0.0.1:{}/api/v1/info either.".format(port),
                    "       That is normal when LocalCanvas is not running. Start it with scripts\\start.ps1.",
                    "       Reachable from this machine only.",
                ]
                block = self.check_block(output, headline).split("\n")
                if has_routes:
                    self.assertEqual(expected, block[:len(expected)], output)
                    self.assertGreater(len(block), len(expected), output)
                else:
                    self.assertEqual(expected, block, output)
                self.assert_no_stack_trace(output)

    def test_a_loopback_gateway_host_is_reported_as_reachable_from_this_machine_only(self):
        """The line T-0119 found was printed only when no LAN address existed.

        gateway.host 127.0.0.1 is the first run. The second binds every
        interface, which publishes this machine's own LAN address -- and a
        probe of an address this machine holds never leaves it -- so the same
        line must be absent there. Nothing listens in either run.
        """
        self.write_config(gateway_host="127.0.0.1")
        loopback = self.output_of(self.run_script("doctor.ps1", timeout=300))
        published = "http://127.0.0.1:{}".format(self.gateway_port)
        block = self.check_block(loopback, "[WARN] Endpoint - " + published)
        self.assertTrue(block, loopback)
        self.assertIn("\n       Reachable from this machine only.", block)

        self.write_config(gateway_host="0.0.0.0")
        wildcard = self.output_of(self.run_script("doctor.ps1", timeout=300))
        headline = re.search(r"^\[(?:WARN| OK |FAIL)\] Endpoint - http://(\S+?):\d+",
                             wildcard, re.MULTILINE)
        self.assertIsNotNone(headline, wildcard)
        if headline.group(1) == "127.0.0.1":
            self.skipTest(
                "this machine has no detected LAN address, so binding every "
                "interface publishes loopback and there is no LAN run to compare")
        block = self.check_block(wildcard, headline.group(0))
        self.assertTrue(block, wildcard)
        self.assertNotIn("Reachable from this machine only.", block)
        self.assertNotIn("Reachable from this machine only.", wildcard)


# ==========================================================================
# A local-only endpoint says WHY it is local-only (T-0224)
# ==========================================================================

NO_LAN_ADDRESS_LINE = (
    "       (no LAN address was detected; this endpoint is reachable from this "
    "machine only)")


#: The start of verify's could-not-test entry that claims a Half 1 probe (T-0257).
HALF_1_WAS_TESTED = (
    "Half 1 was tested from this machine, to this machine's own LAN address.")


def gateway_status_line(family, address, port):
    """The status line /api/v1/info answers on exactly this address, or why not.

    A raw socket of the given family, so which address answered is not left
    to a resolver's order.
    """
    try:
        with socket.socket(family, socket.SOCK_STREAM) as client:
            client.settimeout(10)
            client.connect((address, port))
            client.sendall(b"GET /api/v1/info HTTP/1.0\r\nHost: localhost\r\n\r\n")
            received = b""
            while b"\r\n" not in received:
                chunk = client.recv(4096)
                if not chunk:
                    break
                received += chunk
    except OSError as error:
        return "no answer: {!r}".format(error)
    return received.split(b"\r\n", 1)[0].decode("ascii", "replace")


def loopback_bind_line(host):
    """What start.ps1 and status.ps1 print under a loopback-bound endpoint."""
    return (
        "       (gateway.host is {}, so the gateway is bound to this machine "
        "only; a phone cannot reach it until gateway.host allows it)".format(host))


class LocalOnlyReasonTests(ScriptTestCase):
    """T-0119 made a loopback bind local-only; T-0224 makes it say why.

    Get-LcPublishedEndpoint answers IsLan = $false for two different reasons:
    the gateway is bound to a loopback literal, or it binds every interface
    and this machine has no LAN address to publish. The readers used to give
    the second reason for both, which is false on a machine that has a LAN
    address and simply is not listening on it.

    The one seam used for "no LAN address" is Get-LcLanAddress itself,
    replaced -- in a COPY of the scripts, or by shadowing it in a library
    snippet -- with a function returning a fixed answer. What decides the
    reason is still the real Get-LcPublishedEndpoint, and what prints it is
    the real reader.
    """

    # -- fixtures ---------------------------------------------------------

    def copy_scripts_with_lan_address(self, answer):
        """A copy of the scripts whose Get-LcLanAddress returns ``answer``.

        ``answer`` is None for "this machine has no LAN address", otherwise an
        address from TEST-NET-1 (RFC 5737) that no probe here ever contacts.
        """
        # copy_scripts_with_stopping_disabled always copies to one name, and a
        # test here may need two copies: move each out of the other's way.
        copied = self.copy_scripts_with_stopping_disabled().rename(
            self.workspace / "scripts with LAN address {}".format(
                "none" if answer is None else answer))
        library = copied / "lib" / "Common.ps1"
        original = library.read_text(encoding="utf-8-sig")
        body = "return $null" if answer is None else "return " + powershell_literal(answer)
        replaced, count = re.subn(
            r"(?ms)^function Get-LcLanAddress \{.*?^\}",
            "function Get-LcLanAddress {\n"
            "    # Replaced by the test suite: the detection's answer is fixed.\n"
            "    " + body + "\n"
            "}",
            original)
        self.assertEqual(1, count, "Common.ps1 has no single Get-LcLanAddress to replace")
        library.write_text(replaced, encoding="utf-8")
        return copied

    def endpoint_field(self, output):
        """The `Endpoint:` field: its label line and every line up to the blank."""
        lines = output.splitlines()
        starts = [i for i, line in enumerate(lines) if line == "       Endpoint:"]
        self.assertEqual(1, len(starts), output)
        block = []
        for line in lines[starts[0]:]:
            if not line.strip():
                break
            block.append(line)
        return block

    # -- the decision -----------------------------------------------------

    def test_every_return_path_says_why_the_endpoint_is_or_is_not_local(self):
        """LocalOnlyReason for the three bind shapes, and IsLan beside it.

        Every answer carries the property, on every return path: a reader
        under Set-StrictMode that asks a path which never set it would throw.
        """
        cases = [
            # (gateway.host, binds every interface, Get-LcLanAddress, is_lan, reason)
            ("127.0.0.1", False, None, False, "loopback-bind"),
            ("127.0.0.2", False, "192.0.2.10", False, "loopback-bind"),
            ("localhost", False, "192.0.2.10", False, "loopback-bind"),
            ("LocalHost", False, None, False, "loopback-bind"),
            ("::1", False, "192.0.2.10", False, "loopback-bind"),
            ("192.0.2.10", False, None, True, None),
            ("pc.local", False, "192.0.2.10", True, None),
            ("0.0.0.0", True, None, False, "no-lan-address"),
            ("0.0.0.0", True, "192.0.2.10", True, None),
        ]
        rows = []
        for index, (host, binds_all, lan, _, _) in enumerate(cases):
            rows.append(
                "    @{{ Index = {}; Host = {}; BindsAll = ${}; Lan = {} }}".format(
                    index, powershell_literal(host), "true" if binds_all else "false",
                    "$null" if lan is None else powershell_literal(lan)))
        snippet = (
            "$script:LanAnswer = $null\n"
            "function Get-LcLanAddress { return $script:LanAnswer }\n"
            "$answers = foreach ($case in @(\n" + ",\n".join(rows) + "\n)) {\n"
            "    $script:LanAnswer = $case.Lan\n"
            "    $config = [pscustomobject]@{ gateway = [pscustomobject]@{ host = $case.Host; port = 7801 } }\n"
            "    $endpoints = [pscustomobject]@{ GatewayBindsAll = $case.BindsAll }\n"
            "    $published = Get-LcPublishedEndpoint -Config $config -Endpoints $endpoints\n"
            "    $has = @($published.PSObject.Properties.Name) -contains 'LocalOnlyReason'\n"
            "    [pscustomobject]@{\n"
            "        index = $case.Index; url = [string]$published.Url\n"
            "        is_lan = [bool]$published.IsLan; has_reason = $has\n"
            "        reason = $(if ($has) { $published.LocalOnlyReason } else { 'ABSENT' })\n"
            "    }\n"
            "}\n"
            "ConvertTo-Json -InputObject @($answers) -Compress\n")
        result = self.run_powershell(snippet)
        self.assertEqual(0, result.returncode, self.output_of(result))
        answers = {item["index"]: item for item in json.loads(result.stdout)}
        self.assertEqual(len(cases), len(answers), result.stdout)
        for index, (host, binds_all, lan, is_lan, reason) in enumerate(cases):
            with self.subTest(host=host, binds_all=binds_all, lan=lan):
                answer = answers[index]
                self.assertTrue(answer["has_reason"], result.stdout)
                self.assertIs(is_lan, answer["is_lan"], result.stdout)
                self.assertEqual(reason, answer["reason"], result.stdout)
        # The URL is not part of this decision.
        self.assertEqual("http://127.0.0.1:7801", answers[7]["url"])
        self.assertEqual("http://192.0.2.10:7801", answers[8]["url"])
        self.assertEqual("http://[::1]:7801", answers[4]["url"])

    # -- the readers ------------------------------------------------------

    def test_status_names_a_loopback_bind_and_keeps_the_no_address_sentence(self):
        """status.ps1, which is read-only, over all three shapes.

        The no-address run comes first in the reading order of the assertions
        below for a reason: it is what shows the "no LAN address" line CAN
        print, so its absence under a loopback bind means something.
        """
        self.write_config(gateway_host="0.0.0.0")
        no_address = self.copy_scripts_with_lan_address(None)
        result = self.run_script("status.ps1", script_dir=no_address)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertEqual(
            ["       Endpoint:",
             "       http://127.0.0.1:{}".format(self.gateway_port),
             NO_LAN_ADDRESS_LINE],
            self.endpoint_field(output), output)
        self.assertNotIn("bound to this machine only", output)

        for host, url_host in (("127.0.0.1", "127.0.0.1"), ("::1", "[::1]")):
            with self.subTest(host=host):
                self.write_config(gateway_host=host)
                result = self.run_script("status.ps1")
                output = self.output_of(result)
                self.assertEqual(0, result.returncode, output)
                self.assertEqual(
                    ["       Endpoint:",
                     "       http://{}:{}".format(url_host, self.gateway_port),
                     loopback_bind_line(host)],
                    self.endpoint_field(output), output)
                self.assertNotIn("no LAN address", output)

        self.write_config(gateway_host="0.0.0.0")
        with_address = self.copy_scripts_with_lan_address("192.0.2.10")
        result = self.run_script("status.ps1", script_dir=with_address)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertEqual(
            ["       Endpoint:",
             "       http://192.0.2.10:{}".format(self.gateway_port)],
            self.endpoint_field(output), output)

    def test_start_names_a_loopback_bind_and_keeps_the_no_address_sentence(self):
        """start.ps1's ready block, over a real start of the suite's stubs."""
        self.write_config(gateway_host="0.0.0.0")
        no_address = self.copy_scripts_with_lan_address(None)
        result = self.run_script("start.ps1", script_dir=no_address)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertEqual(
            ["       Endpoint:",
             "       http://127.0.0.1:{}".format(self.gateway_port),
             NO_LAN_ADDRESS_LINE],
            self.endpoint_field(output), output)
        self.assertNotIn("bound to this machine only", output)
        self.assertEqual(0, self.run_script("stop.ps1", timeout=90).returncode)

        # Other loopback hosts (T-0257): with 127.0.0.1 alone, a sentence that
        # hard-coded 127.0.0.1 instead of naming gateway.host would pass.
        # localhost too (T-0263): the suite's gateway stub now binds every
        # address it resolves to, ::1 and 127.0.0.1, as the real gateway does.
        # Bound on IPv4 only it never looked ready -- the readiness probe tries
        # ::1 first, and a refused ::1 connect alone outlasted its 2-second
        # deadline (measured 2.08 s).
        for host in ("127.0.0.1", "127.0.0.2", "localhost"):
            with self.subTest(host=host):
                self.write_config(gateway_host=host)
                result = self.run_script("start.ps1")
                output = self.output_of(result)
                if host == "localhost":
                    # What start.ps1 launched is listening on both addresses.
                    for family, address in ((socket.AF_INET6, "::1"),
                                            (socket.AF_INET, "127.0.0.1")):
                        self.assertEqual(
                            "HTTP/1.0 200 OK",
                            gateway_status_line(family, address, self.gateway_port),
                            "the gateway stub does not answer on {}\n{}".format(address, output))
                self.assertEqual(0, self.run_script("stop.ps1", timeout=90).returncode)
                self.assertEqual(0, result.returncode, output)
                self.assertEqual(
                    ["       Endpoint:",
                     "       http://{}:{}".format(host, self.gateway_port),
                     loopback_bind_line(host)],
                    self.endpoint_field(output), output)
                self.assertNotIn("no LAN address", output)

    def test_verify_gives_a_loopback_bind_as_its_reason_and_does_not_probe_it(self):
        """The strict LAN script's verify, Half 1, as far as an unelevated run reaches.

        verify is read-only, so both runs are real. Strict mode is off here and
        cannot be turned on by this suite, so "proven" is never reachable; what
        is asserted is Half 1's reason, and T-0119's recorded decision that a
        loopback bind is not probed at all -- with a gateway answering at that
        very URL, so a probe would have succeeded had it been made.
        """
        self.write_config(gateway_host="0.0.0.0")
        no_address = self.copy_scripts_with_lan_address(None)
        result = self.run_strict_lan("verify", script_dir=no_address, timeout=300)
        output = self.output_of(result)
        self.assertEqual(4, result.returncode, output)
        lines = output.splitlines()
        self.assertIn("[FAIL] Not proven: this machine has no detected LAN address.", lines)
        self.assertIn(
            "         - The LAN path could not be tested from a LAN address: no LAN "
            "address was detected on this machine, so only loopback was available. "
            "A phone cannot reach a loopback address.", lines)
        self.assertNotIn("bound to this machine only", output)

        # Two loopback spellings (T-0257): with 127.0.0.1 alone, a [FAIL] line
        # that hard-coded 127.0.0.1 instead of naming gateway.host would pass.
        DoctorEndpointProbeTests.start_gateway_stub(self, "127.0.0.1", self.gateway_port)
        for host in ("127.0.0.1", "localhost"):
            with self.subTest(host=host):
                self.write_config(gateway_host=host)
                result = self.run_strict_lan("verify", timeout=300)
                output = self.output_of(result)
                self.assertEqual(4, result.returncode, output)
                lines = output.splitlines()
                self.assertIn(
                    "[FAIL] Not proven: gateway.host is {}, so the gateway is bound "
                    "to this machine only.".format(host), lines)
                self.assertIn(
                    "         - The LAN path could not be tested: gateway.host is {}, "
                    "so the gateway is bound to this machine only and a phone cannot "
                    "reach it until gateway.host allows it.".format(host), lines)
                self.assertNotIn("no LAN address", output)
                self.assertNotIn("no detected LAN address", output)
                # Not probed: neither outcome of a probe was reported.
                self.assertNotIn("answered on this machine's LAN address", output)
                self.assertNotIn("did not answer on the LAN address", output)
                self.assert_no_stack_trace(output)

    def test_verify_says_half_1_was_tested_only_when_it_made_its_probe(self):
        """T-0257: "Half 1 was tested ..." is a claim about a probe.

        It is printed only on the run that made one, whatever the probe's
        outcome. The two probing runs come first: they show the sentence CAN
        print from this very harness, so its absence from the two local-only
        runs after them means something.

        A probe needs a LAN answer, and the one seam used for it is
        Get-LcLanAddress, answering 127.0.0.1 in a copy of the scripts: the
        real Get-LcPublishedEndpoint then publishes a LAN endpoint that the
        probe reaches on loopback, and nothing leaves this machine for Half 1.
        """
        self.write_config(gateway_host="0.0.0.0")
        probing = self.copy_scripts_with_lan_address("127.0.0.1")
        lan_url = "http://127.0.0.1:{}/api/v1/info".format(self.gateway_port)

        # Probe made, nothing answering at that port.
        self.assertFalse(http_ok(lan_url), "something already answers at " + lan_url)
        result = self.run_strict_lan("verify", script_dir=probing, timeout=300)
        output = self.output_of(result)
        self.assertEqual(4, result.returncode, output)
        self.assertIn("[INFO] Half 1 of 2 - the LocalCanvas LAN path: " + lan_url,
                      output.splitlines())
        self.assertIn("did not answer on the LAN address", output)
        self.assertEqual(1, output.count(HALF_1_WAS_TESTED), output)

        # Probe made, and answered.
        DoctorEndpointProbeTests.start_gateway_stub(self, "127.0.0.1", self.gateway_port)
        result = self.run_strict_lan("verify", script_dir=probing, timeout=300)
        output = self.output_of(result)
        self.assertEqual(4, result.returncode, output)
        self.assertIn(
            "[ OK ] The LocalCanvas gateway answered on this machine's LAN address.",
            output.splitlines())
        self.assertEqual(1, output.count(HALF_1_WAS_TESTED), output)

        # Probe made, and something answered that is not LocalCanvas: the
        # third outcome of a probe carries the sentence too (T-0257's review).
        # On a port of its own, so the stub above stays where the loopback run
        # below needs it.
        answering_port = self.gateway_port
        alien_port = free_port()
        self.write_config(gateway_host="0.0.0.0", gateway_port=alien_port)
        alien_url = "http://127.0.0.1:{}/api/v1/info".format(alien_port)
        DoctorEndpointProbeTests.start_gateway_stub(
            self, "127.0.0.1", alien_port, LC_STUB_GATEWAY_ALIEN="1")
        result = self.run_strict_lan("verify", script_dir=probing, timeout=300)
        output = self.output_of(result)
        self.assertEqual(4, result.returncode, output)
        self.assertIn("[INFO] Half 1 of 2 - the LocalCanvas LAN path: " + alien_url,
                      output.splitlines())
        self.assertIn(
            "[FAIL] Not proven: something answered on the LAN address, but it did not "
            "identify itself as a LocalCanvas gateway.", output.splitlines())
        self.assertEqual(1, output.count(HALF_1_WAS_TESTED), output)
        self.write_config(gateway_host="0.0.0.0", gateway_port=answering_port)

        # No probe: this machine has no LAN address.
        no_address = self.copy_scripts_with_lan_address(None)
        result = self.run_strict_lan("verify", script_dir=no_address, timeout=300)
        output = self.output_of(result)
        self.assertEqual(4, result.returncode, output)
        self.assertIn("[FAIL] Not proven: this machine has no detected LAN address.",
                      output.splitlines())
        self.assertNotIn(HALF_1_WAS_TESTED, output)

        # No probe: the gateway is bound to loopback, with the stub answering
        # there all the same.
        self.write_config(gateway_host="127.0.0.1")
        result = self.run_strict_lan("verify", timeout=300)
        output = self.output_of(result)
        self.assertEqual(4, result.returncode, output)
        self.assertIn(
            "[FAIL] Not proven: gateway.host is 127.0.0.1, so the gateway is bound "
            "to this machine only.", output.splitlines())
        self.assertNotIn(HALF_1_WAS_TESTED, output)
        self.assert_no_stack_trace(output)

    # -- a bracketed IPv6 wildcard (T-0257) -------------------------------

    def test_a_bracketed_ipv6_wildcard_is_published_like_the_bare_one(self):
        """gateway.host "[::]" binds what "::" binds, and is published the same.

        The gateway accepts "[::]" (its loader refuses only whitespace), its
        own discovery counts it as a wildcard, and "[::]" resolves to "::". So
        the scripts publish it as the wide bind it is, not as a host a phone
        would be told to type. The real Get-LcEndpoints and the real
        Get-LcPublishedEndpoint decide; only Get-LcLanAddress is fixed. "[::1]"
        is the control: brackets alone do not make an address wide.
        """
        cases = [
            # (gateway.host, Get-LcLanAddress, url, is_lan, reason)
            ("::", None, "http://127.0.0.1:7801", False, "no-lan-address"),
            ("[::]", None, "http://127.0.0.1:7801", False, "no-lan-address"),
            ("::", "192.0.2.10", "http://192.0.2.10:7801", True, None),
            ("[::]", "192.0.2.10", "http://192.0.2.10:7801", True, None),
            ("[::1]", "192.0.2.10", "http://[::1]:7801", False, "loopback-bind"),
        ]
        rows = []
        for index, (host, lan, _, _, _) in enumerate(cases):
            rows.append(
                "    @{{ Index = {}; Host = {}; Lan = {} }}".format(
                    index, powershell_literal(host),
                    "$null" if lan is None else powershell_literal(lan)))
        snippet = (
            "$script:LanAnswer = $null\n"
            "function Get-LcLanAddress { return $script:LanAnswer }\n"
            "$answers = foreach ($case in @(\n" + ",\n".join(rows) + "\n)) {\n"
            "    $script:LanAnswer = $case.Lan\n"
            "    $config = [pscustomobject]@{\n"
            "        comfy = [pscustomobject]@{ host = '127.0.0.1'; base_url = 'http://127.0.0.1:8188' }\n"
            "        gateway = [pscustomobject]@{ host = $case.Host; port = 7801 }\n"
            "    }\n"
            "    $endpoints = Get-LcEndpoints -Config $config\n"
            "    $published = Get-LcPublishedEndpoint -Config $config -Endpoints $endpoints\n"
            "    [pscustomobject]@{\n"
            "        index = $case.Index; url = [string]$published.Url\n"
            "        is_lan = [bool]$published.IsLan; reason = $published.LocalOnlyReason\n"
            "    }\n"
            "}\n"
            "ConvertTo-Json -InputObject @($answers) -Compress\n")
        result = self.run_powershell(snippet)
        self.assertEqual(0, result.returncode, self.output_of(result))
        answers = {item["index"]: item for item in json.loads(result.stdout)}
        self.assertEqual(len(cases), len(answers), result.stdout)
        for index, (host, lan, url, is_lan, reason) in enumerate(cases):
            with self.subTest(host=host, lan=lan):
                answer = answers[index]
                self.assertEqual(url, answer["url"], result.stdout)
                self.assertIs(is_lan, answer["is_lan"], result.stdout)
                self.assertEqual(reason, answer["reason"], result.stdout)


# ==========================================================================
# doctor.ps1: the exit code says what the body says (T-0199), and a check that
# needs Administrator is its own state (T-0120, T-0015)
# ==========================================================================


# Everything doctor diagnoses, from the Python environment to strict LAN mode,
# up to the closing summary. A shape test replaces this region of a copy with
# checks of its own, so the summary and the exit code that run over them are
# the script's real ones.
DOCTOR_DIAGNOSIS = re.compile(
    r"(?ms)^    # -+\n    # The Python environment\n.*?"
    r"^(?=    # The summary accounts for every check)")
DOCTOR_ADMIN_MARK = " - not measured, needs Administrator"


def doctor_body_and_summary(output):
    """scripts/doctor.ps1's output as (body, summary), both lists of lines.

    The summary is the last block of non-blank lines: doctor prints a blank
    line in front of it and none inside it. The body is everything above.
    """
    lines = [line.rstrip() for line in output.splitlines()]
    while lines and not lines[-1]:
        lines.pop()
    if "" not in lines:
        return lines, []
    split = len(lines) - 1 - lines[::-1].index("")
    return lines[:split], lines[split + 1:]


def doctor_summary_for(body):
    """The summary doctor must print over this body, rebuilt from the body.

    Returns (exit code, summary lines). Every number is recounted here from
    the printed checks, never read from the summary it is compared with.
    """
    failed = [line for line in body if line.startswith("[FAIL] ")]
    unclean = [line for line in body if line.startswith("[WARN] ")]
    admin = [line[len("[INFO] "):line.index(DOCTOR_ADMIN_MARK)]
             for line in body
             if line.startswith("[INFO] ") and DOCTOR_ADMIN_MARK in line]
    summary = []
    if admin:
        summary += [
            "[INFO] {} check(s) need Administrator and were not measured: {}.".format(
                len(admin), ", ".join(admin)),
            "       Run doctor.ps1 from an elevated prompt to measure them. "
            "They count neither as warnings nor as problems.",
        ]
    if failed:
        summary.append(
            "[FAIL] {} problem(s) found - see the [FAIL] lines above.".format(len(failed)))
        if unclean:
            summary.append(
                "       {} further check(s) did not come back clean - see the "
                "[WARN] lines above.".format(len(unclean)))
        return 3, summary
    if unclean:
        return 2, summary + [
            "[WARN] No failures, but {} check(s) did not come back clean - see the "
            "[WARN] lines above.".format(len(unclean)),
            "       A check that could not be made is not a check that passed.",
            "       This run is not a clean bill of health.",
        ]
    return 0, summary + ["[ OK ] No problems found."]


class DoctorExitCodeTests(ScriptTestCase):
    """What doctor.ps1 exits with is what it printed.

    T-0115 made the summary honest and left the exit code at 0 over a check
    that could not be made (T-0199). And one check -- the firewall's port
    filters -- can only be read elevated, so it warned on every ordinary run
    and no healthy machine could come back clean (T-0120). It is now a state
    of its own: reported, named in the summary, and counted as neither.
    """

    def doctor_copy(self, diagnosis=None, elevated=False, readable_firewall=False,
                    refused_otherwise=False):
        """A copy of the scripts whose doctor.ps1 has the injections asked for.

        ``diagnosis`` replaces every check with the PowerShell lines given.
        ``elevated`` makes doctor believe its shell is elevated, which is the
        only way this suite reaches that branch: it never elevates.
        ``readable_firewall`` answers the port-filter read the way an elevated
        read would, with one Private-only rule for the gateway port.
        ``refused_otherwise`` makes the port-filter read itself fail for a
        reason that is not a permission, in place of the cmdlet: a function
        of that name is found before the cmdlet is.
        """
        # The shared helper copies to one fixed name; each shape gets its own.
        copies = sorted(self.workspace.glob("doctor copy *"))
        copied = self.copy_scripts_with_stopping_disabled().rename(
            self.workspace / "doctor copy {}".format(len(copies) + 1))
        doctor = copied / "doctor.ps1"
        source = doctor.read_text(encoding="utf-8-sig")
        injected = ""
        if refused_otherwise:
            injected += (
                "function Get-NetFirewallPortFilter {\n"
                "    # Injected by the test suite: a read that fails, and not on a permission.\n"
                "    throw 'Injected failure: the filter table could not be enumerated.'\n"
                "}\n")
        if elevated:
            injected += (
                "function Test-LcElevated {\n"
                "    # Injected by the test suite: an elevated shell, claimed.\n"
                "    return $true\n"
                "}\n")
        if readable_firewall:
            injected += (
                "function Get-GatewayPortRules {\n"
                "    param([int]$Port)\n"
                "    # Injected by the test suite: the read an elevated shell gets.\n"
                "    return [pscustomobject]@{\n"
                "        Readable = $true; NeedsAdministrator = $false; Reason = ''\n"
                "        Rules = @([pscustomobject]@{\n"
                "            DisplayName = 'Injected rule'; Action = 'Allow'; Profile = 'Private' })\n"
                "    }\n"
                "}\n")
        if injected:
            self.assertEqual(1, source.count(DOCTOR_MAIN), source)
            source = source.replace(DOCTOR_MAIN, "\n" + injected + DOCTOR_MAIN[1:])
        if readable_firewall:
            # The injected answer only counts if doctor asks for it by this name.
            self.assertEqual(1, source.count("= Get-GatewayPortRules -Port "), source)
        if diagnosis is not None:
            source, replaced = DOCTOR_DIAGNOSIS.subn(
                "".join("    " + line + "\n" for line in diagnosis) + "\n", source)
            self.assertEqual(1, replaced, "doctor.ps1 has moved its diagnosis region")
        doctor.write_text(source, encoding="utf-8")
        return copied

    def assert_agrees_with_its_body(self, result, expected_code):
        output = self.output_of(result)
        body, summary = doctor_body_and_summary(output)
        counted, expected_summary = doctor_summary_for(body)
        self.assertEqual(
            counted, result.returncode,
            "the body says {} and the exit code says {}\n{}".format(
                counted, result.returncode, output))
        self.assertEqual(expected_code, result.returncode, output)
        self.assertEqual(expected_summary, summary, output)
        self.assert_no_stack_trace(output)
        return body, summary

    def test_the_exit_code_agrees_with_the_body_in_every_shape(self):
        """Each shape is a real run of doctor's own summary over real checks.

        The unelevated firewall shape reads this machine's firewall for real,
        exactly as an ordinary run does. The two elevated shapes cannot be
        reached by elevating -- this suite never does -- so doctor is told it
        is elevated, once over the same failing read and once over a read that
        succeeded. The first differential is the one that matters: the same
        failure, needing Administrator or not, is 0 in one shape and 2 in the
        other.
        """
        port = self.gateway_port
        firewall = "Write-FirewallCheck -Port {}".format(port)
        clean = ["Write-Check -Name 'Injected clean' -Status 'ok' -Value 'measured'",
                 "Write-Check -Name 'Injected fact' -Status 'info' -Value 'stated'"]
        unmade = "Write-Check -Name 'Injected unmade' -Status 'warn' -Value 'could not be checked'"
        failed = "Write-Check -Name 'Injected failure' -Status 'fail' -Value 'measured and wrong'"
        admin_line = ("[INFO] Firewall - not measured, needs Administrator: "
                      "the rules for port {} were not read".format(port))
        shapes = (
            ("every check clean", clean, {}, 0, False),
            ("one check could not be made", clean + [unmade], {}, 2, False),
            ("one check failed", clean + [failed], {}, 3, False),
            ("one failed and one could not be made", clean + [unmade, failed], {}, 3, False),
            ("unelevated, and the firewall is the only check not clean",
             clean + [firewall], {}, 0, True),
            ("unelevated firewall beside a check that could not be made",
             clean + [firewall, unmade], {}, 2, True),
            ("elevated, and the same read failed",
             clean + [firewall], {"elevated": True}, 2, False),
            ("unelevated, and the read failed on something other than a permission",
             clean + [firewall], {"refused_otherwise": True}, 2, False),
            ("elevated, and the rules were read",
             clean + [firewall], {"elevated": True, "readable_firewall": True}, 0, False),
        )
        for name, diagnosis, injections, expected_code, needs_admin in shapes:
            with self.subTest(shape=name):
                reads_for_real = (firewall in diagnosis
                                  and not injections.get("readable_firewall")
                                  and not injections.get("refused_otherwise"))
                if reads_for_real and is_elevated():
                    self.skipTest(
                        "this shape needs the firewall read to be refused, and an "
                        "elevated session is allowed to make it")
                copied = self.doctor_copy(diagnosis=diagnosis, **injections)
                result = self.run_script("doctor.ps1", script_dir=copied, timeout=300)
                body, summary = self.assert_agrees_with_its_body(result, expected_code)
                output = self.output_of(result)
                if needs_admin:
                    self.assertIn(admin_line, body, output)
                    self.assertIn(
                        "[INFO] 1 check(s) need Administrator and were not measured: "
                        "Firewall.", summary, output)
                else:
                    self.assertNotIn(DOCTOR_ADMIN_MARK, output)
                    self.assertNotIn("need Administrator", output)
                if injections.get("readable_firewall"):
                    self.assertIn(
                        "[ OK ] Firewall - port {} is allowed inbound on Private only".format(port),
                        body, output)
                elif injections.get("elevated") or injections.get("refused_otherwise"):
                    self.assertIn(
                        "[WARN] Firewall - the rules for port {} could not be read".format(port),
                        body, output)

    def test_an_ordinary_run_reports_the_firewall_as_needing_administrator(self):
        """The real doctor, unelevated, on this machine: nothing injected.

        Its exit code is whatever this machine earns, and is recounted from its
        own body; what is fixed is that the firewall read is the Administrator
        state and not a warning.
        """
        if is_elevated():
            self.skipTest("an elevated session reads the firewall, so this state "
                          "cannot be produced by it")
        self.write_config()
        result = self.run_script("doctor.ps1", timeout=300)
        output = self.output_of(result)
        body, summary = self.assert_agrees_with_its_body(
            result, doctor_summary_for(doctor_body_and_summary(output)[0])[0])
        self.assertIn(
            "[INFO] Firewall - not measured, needs Administrator: the rules for "
            "port {} were not read".format(self.gateway_port), body, output)
        self.assertNotIn("[WARN] Firewall", output)
        self.assertIn(
            "[INFO] 1 check(s) need Administrator and were not measured: Firewall.",
            summary, output)


# ==========================================================================
# Invoke-LcProbe: what a request that got nothing back is reported as (T-0200)
# ==========================================================================


# Measured on the machine this was written on (T-0200): a connection to a
# loopback port nothing listens on is refused after about 2.05 s, whatever the
# timeout. Below that the probe's own deadline ends the request first and no
# socket error exists anywhere in the exception chain; above it, the refusal
# does. These two sit well clear of it on either side.
PROBE_DEADLINE_BELOW_REFUSAL = 1
PROBE_DEADLINE_ABOVE_REFUSAL = 10


def probe_deadline_sentence(seconds):
    """What Invoke-LcProbe composes when its own deadline ended the request."""
    return "No answer arrived within {} second(s).".format(seconds)


def connection_refused_message():
    """What this machine's socket layer says about a refused connection.

    Asked of PowerShell at run time and never written into this file: the
    sentence is the operating system's and is localized (T-0108), so what a
    test can hold the probe to is "the refusal's own words", not a spelling.
    """
    result = subprocess.run(
        [PWSH, "-NoProfile", "-NonInteractive", "-Command",
         "[System.Net.Sockets.SocketException]::new(10061).Message"],
        capture_output=True, text=True, encoding="utf-8", errors="replace",
        timeout=120)
    message = (result.stdout or "").strip()
    if not message:
        raise AssertionError("PowerShell printed no socket message: " + (result.stderr or ""))
    return message


class ProbeCauseTests(ScriptTestCase):
    """A request cancelled by the probe's own deadline says so (T-0200).

    It used to quote the innermost exception, which for a deadline is "A task
    was canceled." -- the probe's bookkeeping, not what happened on the wire.
    A refusal, where one arrived, is still quoted in the socket layer's words.
    """

    def test_the_deadline_and_the_refusal_are_told_apart(self):
        port = free_port()
        snippet = (
            "$url = 'http://127.0.0.1:{port}/system_stats'\n"
            "$answers = foreach ($seconds in @({below}, 0.5, {above})) {{\n"
            "    $clock = [System.Diagnostics.Stopwatch]::StartNew()\n"
            "    $probe = Invoke-LcProbe -Url $url -TimeoutSeconds $seconds\n"
            "    [pscustomobject]@{{ seconds = [double]$seconds; ok = [bool]$probe.Ok;\n"
            "        error = [string]$probe.Error; elapsed = $clock.Elapsed.TotalSeconds }}\n"
            "}}\n"
            "ConvertTo-Json -InputObject @($answers) -Compress\n").format(
                port=port, below=PROBE_DEADLINE_BELOW_REFUSAL,
                above=PROBE_DEADLINE_ABOVE_REFUSAL)
        result = self.run_powershell(snippet)
        self.assertEqual(0, result.returncode, self.output_of(result))
        below, half, above = json.loads(result.stdout)
        refused = connection_refused_message()

        self.assertFalse(below["ok"], result.stdout)
        self.assertEqual(
            probe_deadline_sentence(PROBE_DEADLINE_BELOW_REFUSAL), below["error"], result.stdout)
        # Written by the probe, so formatted by it: a fraction must not come out
        # in this machine's culture ("0,5") -- the suite runs on one that would.
        self.assertEqual(probe_deadline_sentence("0.5"), half["error"], result.stdout)

        self.assertFalse(above["ok"], result.stdout)
        self.assertEqual(refused, above["error"], result.stdout)
        # The refusal ended that request, not the deadline: otherwise the
        # socket-case assertion above would be about nothing.
        self.assertLess(above["elapsed"], PROBE_DEADLINE_ABOVE_REFUSAL - 1, result.stdout)

    def test_scripts_doctor_quotes_the_deadline_and_the_refusal(self):
        """scripts/doctor.ps1 probes ComfyUI with a 3 s deadline, above the
        refusal: the real script quotes the refusal. A copy whose ComfyUI probe
        deadline is below it quotes the deadline -- the only difference."""
        self.write_config()
        comfy = "http://127.0.0.1:{}".format(self.comfy_port)
        refused = connection_refused_message()

        real = self.output_of(self.run_script("doctor.ps1", timeout=300))
        headline = "[WARN] ComfyUI - not reachable at " + comfy
        self.assertEqual(
            "\n".join([headline, "       " + refused,
                       "       That is normal when LocalCanvas is not running."]),
            self.check_block(real, headline), real)

        copied = self.copy_scripts_with_stopping_disabled()
        doctor = copied / "doctor.ps1"
        source = doctor.read_text(encoding="utf-8-sig")
        anchor = "Invoke-LcProbe -Url $endpoints.ComfyHealthUrl -TimeoutSeconds 3"
        self.assertEqual(1, source.count(anchor), source)
        doctor.write_text(source.replace(
            anchor, "Invoke-LcProbe -Url $endpoints.ComfyHealthUrl -TimeoutSeconds {}".format(
                PROBE_DEADLINE_BELOW_REFUSAL)), encoding="utf-8")
        short = self.output_of(self.run_script("doctor.ps1", script_dir=copied, timeout=300))
        self.assertEqual(
            "\n".join([headline,
                       "       " + probe_deadline_sentence(PROBE_DEADLINE_BELOW_REFUSAL),
                       "       That is normal when LocalCanvas is not running."]),
            self.check_block(short, headline), short)

    def start_silent_listener(self, host, port):
        """Accepts the connection and never answers: the hung endpoint."""
        return DoctorEndpointProbeTests.start_silent_listener(self, host, port)

    def start_not_http_listener(self):
        """Accepts, reads the request, answers with a line that is not HTTP.

        The failure it produces is neither a socket error nor the deadline:
        the connection works and what comes back cannot be parsed. Returns
        the port.
        """
        listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        listener.bind(("127.0.0.1", 0))
        listener.listen(8)
        listener.settimeout(0.25)
        stop = threading.Event()

        def serve():
            while not stop.is_set():
                try:
                    connection, _ = listener.accept()
                except socket.timeout:
                    continue
                except OSError:
                    return
                with connection:
                    try:
                        connection.settimeout(5)
                        connection.recv(4096)
                        connection.sendall(b"NOT HTTP AT ALL\r\n\r\n")
                    except OSError:
                        pass

        thread = threading.Thread(target=serve, daemon=True)
        thread.start()

        def shut_down():
            stop.set()
            thread.join(timeout=5)
            listener.close()

        self.addCleanup(shut_down)
        return listener.getsockname()[1]

    def probe_answers(self, url, deadlines):
        """Invoke-LcProbe against one URL at each deadline, as data."""
        snippet = (
            "$answers = foreach ($seconds in @({deadlines})) {{\n"
            "    $clock = [System.Diagnostics.Stopwatch]::StartNew()\n"
            "    $probe = Invoke-LcProbe -Url '{url}' -TimeoutSeconds $seconds\n"
            "    [pscustomobject]@{{ seconds = [double]$seconds; ok = [bool]$probe.Ok;\n"
            "        error = [string]$probe.Error; elapsed = $clock.Elapsed.TotalSeconds }}\n"
            "}}\n"
            "ConvertTo-Json -InputObject @($answers) -Compress\n").format(
                deadlines=", ".join(str(seconds) for seconds in deadlines), url=url)
        result = self.run_powershell(snippet)
        self.assertEqual(0, result.returncode, self.output_of(result))
        return json.loads(result.stdout), result.stdout

    def test_a_hung_endpoint_is_reported_as_the_deadline(self):
        """Review round 2: a server that accepts and says nothing.

        Its chain carries a SocketException too -- the aborted read, measured
        as OperationAborted under TimeoutException -- so "a socket error is
        quoted" alone quoted the probe's own cancellation in other words. The
        deadline ended this request, and that is what is said.
        """
        port = free_port()
        self.start_silent_listener("127.0.0.1", port)
        answers, raw = self.probe_answers(
            "http://127.0.0.1:{}/system_stats".format(port), [PROBE_DEADLINE_BELOW_REFUSAL, 3])
        for answer in answers:
            with self.subTest(seconds=answer["seconds"]):
                seconds = int(answer["seconds"])
                self.assertFalse(answer["ok"], raw)
                self.assertEqual(probe_deadline_sentence(seconds), answer["error"], raw)
                # It really was the deadline that ended it.
                self.assertGreaterEqual(answer["elapsed"], seconds - 0.2, raw)

    def test_a_failure_that_is_not_the_deadline_is_not_called_one(self):
        """Review round 2: the third branch, "anything else", held by a test.

        A port answered by something that is not HTTP fails at once and for a
        reason of its own. That reason is quoted -- it names the line that
        came back -- and the deadline sentence is nowhere, well before the
        deadline could have been reached.
        """
        port = self.start_not_http_listener()
        answers, raw = self.probe_answers(
            "http://127.0.0.1:{}/system_stats".format(port), [PROBE_DEADLINE_ABOVE_REFUSAL])
        answer = answers[0]
        self.assertFalse(answer["ok"], raw)
        self.assertNotIn("No answer arrived within", answer["error"], raw)
        # The listener's own bytes, quoted back: what came back is named.
        self.assertIn("NOT HTTP AT ALL", answer["error"], raw)
        self.assertLess(answer["elapsed"], PROBE_DEADLINE_ABOVE_REFUSAL / 2, raw)

    def test_scripts_doctor_reports_a_hung_comfyui_as_the_deadline(self):
        """The real scripts/doctor.ps1, its 3 s ComfyUI probe, a silent port.

        RE-AIMED BY T-0294. This drove doctor.ps1 under BOTH shells, because
        under 5.1 the block said "A task was canceled." until T-0250. The script
        is an entry point now and Windows PowerShell 5.1 never reaches its body,
        so the two halves of the claim are measured where each of them lives:

          * the BLOCK -- headline, sentence, follow-up line -- under pwsh, from
            the script, exactly as before;
          * the SENTENCE -- the T-0250 fix itself, which is
            Get-LcProbeFailureCause in scripts/lib/Common.ps1 and not the
            script -- under 5.1, from the helper, against the SAME silent
            listener. That is the half 5.1 ever really covered here, and the
            assertion is that the words the helper hands back under 5.1 are
            character for character the words the block quotes.

        So nothing 5.1 ever measured is lost, and nothing claims the script runs
        there. The script's own 5.1 behaviour -- the refusal -- is asserted
        below, so this test still fails if the gate is taken out and doctor.ps1
        starts answering under 5.1 again with a sentence nobody checked.
        """
        self.write_config()
        self.start_silent_listener("127.0.0.1", self.comfy_port)
        headline = "[WARN] ComfyUI - not reachable at http://127.0.0.1:{}".format(self.comfy_port)
        sentence = probe_deadline_sentence(3)
        # A copy whose only difference is the line that prints the host.
        copied = WindowsPowerShellPythonVersionTests.copy_with_host_line(
            self, "doctor.ps1", DOCTOR_MAIN)
        output = self.output_of(self.run_script(
            "doctor.ps1", script_dir=copied, timeout=300, shell=PWSH))
        self.assertNotRegex(output, r"(?m)^HOST 5\.", output)
        self.assertEqual(
            "\n".join([headline, "       " + sentence,
                       "       That is normal when LocalCanvas is not running."]),
            self.check_block(output, headline), output)

        # The same listener, the same deadline, through the helper alone.
        shell = require_windows_powershell(
            self, "Invoke-LcProbe's deadline sentence for a hung ComfyUI")
        probe = self.run_powershell(
            "Write-Output \"HOST $($PSVersionTable.PSVersion)\"\n"
            "$p = Invoke-LcProbe -Url 'http://127.0.0.1:{}/system_stats' -TimeoutSeconds 3\n"
            "Write-Output \"SAID $($p.Error)\"\n".format(self.comfy_port),
            shell=shell, timeout=180)
        said = self.output_of(probe)
        self.assertEqual(0, probe.returncode, said)
        self.assertRegex(said, r"(?m)^HOST 5\.", said)
        self.assertIn("SAID " + sentence, probe.stdout, said)

        # And the script itself is refused there, rather than answering.
        refuse_under_windows_powershell(
            self, copied / "doctor.ps1", ["-Config", str(self.config_path)],
            cwd=copied, env=self.script_env(),
            what="scripts/doctor.ps1 against a hung ComfyUI, under 5.1")

    @staticmethod
    def check_block(output, headline):
        return DoctorEndpointProbeTests.check_block(output, headline)


# ==========================================================================
# Invoke-LcProbe under Windows PowerShell 5.1 (T-0217)
# ==========================================================================


class WindowsPowerShellProbeTests(ScriptTestCase):
    """The probe answers under Windows PowerShell 5.1, not only under pwsh.

    5.1 does not load System.Net.Http by default, and before T-0217 every probe
    there failed with "Unable to find type [System.Net.Http.HttpClientHandler]."
    -- so every check built on one said nothing answered. The rest of this suite
    drives PWSH, which is exactly why that stayed invisible; every assertion
    here names the shell it ran under and checks what that shell is.
    """

    PROBE_SECONDS = 2

    def probe_snippet(self, answer_url, silent_url):
        return (
            "Write-Output \"HOST $($PSVersionTable.PSVersion)\"\n"
            "$answers = foreach ($case in @(@('answer', '{answer}'), @('silent', '{silent}'))) {{\n"
            "    $clock = [System.Diagnostics.Stopwatch]::StartNew()\n"
            "    $probe = Invoke-LcProbe -Url $case[1] -TimeoutSeconds {seconds}\n"
            "    [pscustomobject]@{{ case = $case[0]; ok = [bool]$probe.Ok;\n"
            "        status = [int]$probe.StatusCode; body = [string]$probe.Body;\n"
            "        error = [string]$probe.Error; elapsed = $clock.Elapsed.TotalSeconds }}\n"
            "}}\n"
            "Write-Output ('JSON ' + (ConvertTo-Json -InputObject @($answers) -Compress))\n"
        ).format(answer=answer_url, silent=silent_url, seconds=self.PROBE_SECONDS)

    def probe_under(self, shell, answer_url, silent_url):
        result = self.run_powershell(
            self.probe_snippet(answer_url, silent_url), shell=shell, timeout=180)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        host = re.search(r"^HOST (\S+)$", result.stdout, re.MULTILINE)
        document = re.search(r"^JSON (.+)$", result.stdout, re.MULTILINE)
        self.assertIsNotNone(host, output)
        self.assertIsNotNone(document, output)
        answers = {item["case"]: item for item in json.loads(document.group(1))}
        return host.group(1), answers, output

    def test_the_probe_gets_a_real_answer_under_windows_powershell(self):
        """A loopback fake answers, and the probe hands back its body.

        Both shells, the pwsh half first as the control that the fixture
        answers at all. The silent listener measures that the deadline still
        ends the request under 5.1, and since T-0250 that it is said as the
        deadline there too (it was "A task was canceled.").
        """
        comfy = FakeComfy()
        self.addCleanup(comfy.close)
        silent_port = free_port()
        DoctorEndpointProbeTests.start_silent_listener(self, "127.0.0.1", silent_port)
        answer_url = comfy.url + "/system_stats"
        silent_url = "http://127.0.0.1:{}/system_stats".format(silent_port)

        pwsh_host, answers, output = self.probe_under(PWSH, answer_url, silent_url)
        self.assertEqual(
            (True, 200, ""),
            (answers["answer"]["ok"], answers["answer"]["status"], answers["answer"]["error"]),
            output)
        self.assertEqual(FAKE_COMFY_SYSTEM, json.loads(answers["answer"]["body"]), output)
        if not pwsh_host.startswith("5."):
            self.assertEqual(
                probe_deadline_sentence(self.PROBE_SECONDS), answers["silent"]["error"], output)

        shell = require_windows_powershell(self, "Invoke-LcProbe against a loopback fake")
        host, answers, output = self.probe_under(shell, answer_url, silent_url)
        self.assertTrue(host.startswith("5."), output)
        answer = answers["answer"]
        self.assertEqual((True, 200, ""), (answer["ok"], answer["status"], answer["error"]), output)
        self.assertEqual(FAKE_COMFY_SYSTEM, json.loads(answer["body"]), output)
        silent = answers["silent"]
        self.assertEqual((False, 0), (silent["ok"], silent["status"]), output)
        self.assertEqual(probe_deadline_sentence(self.PROBE_SECONDS), silent["error"], output)
        self.assertGreaterEqual(silent["elapsed"], self.PROBE_SECONDS - 0.2, output)
        self.assertLess(silent["elapsed"], self.PROBE_SECONDS + 10, output)

    def test_scripts_doctor_runs_end_to_end_under_pwsh_and_is_refused_by_5_1(self):
        """The doctor end to end, against a stub -- nothing replaced.

        RE-AIMED AT THE REFUSAL BY T-0294. This ran the whole doctor under BOTH
        shells and asserted they listed the same checks with the same verdicts,
        which was a promise that 5.1 works. That promise is retired: the script
        is an entry point and the host refuses it there.

        What the 5.1 half of this test really exercised was the helpers --
        Get-LcPythonVersion (T-0248) and Invoke-LcProbe (T-0217) -- and both are
        still measured under 5.1 directly, the probe by the test above and the
        version by WindowsPowerShellPythonVersionTests. So the end-to-end run
        keeps its full assertion under pwsh, and the 5.1 leg becomes the one
        thing that is true there now: the refusal, with nothing of the doctor's
        own printed.
        """
        self.write_config()
        self.start_backend_stub()
        copied = self.copy_scripts_with_stopping_disabled()
        doctor = copied / "doctor.ps1"
        source = doctor.read_text(encoding="utf-8-sig")
        self.assertEqual(1, source.count(DOCTOR_MAIN), source)
        doctor.write_text(source.replace(
            DOCTOR_MAIN,
            "\nWrite-Host \"HOST $($PSVersionTable.PSVersion)\"\n" + DOCTOR_MAIN[1:]),
            encoding="utf-8")
        self.assertNotIn("function Get-LcPythonVersion", doctor.read_text(encoding="utf-8"))
        version = "{}.{}.{}".format(*sys.version_info[:3])

        pwsh_result = self.run_script("doctor.ps1", script_dir=copied, timeout=300, shell=PWSH)
        pwsh_output = self.output_of(pwsh_result)
        self.assertNotRegex(pwsh_output, r"(?m)^HOST 5\.", pwsh_output)
        self.assertIn("[ OK ] Python environment - Python " + version, pwsh_output)
        headline = "[ OK ] ComfyUI - reachable at http://127.0.0.1:{}".format(self.comfy_port)
        self.assertEqual(headline, self.check_block(pwsh_output, headline), pwsh_output)
        self.assertNotIn("[WARN] ComfyUI - not reachable", pwsh_output)
        # End to end: the closing verdict was printed, and the exit code is
        # the one that verdict states.
        verdict = re.search(
            r"(?m)^\[(?: OK |WARN|FAIL)\] (No problems found\.|No failures, but \d+ "
            r"check\(s\) did not come back clean|\d+ problem\(s\) found)", pwsh_output)
        self.assertIsNotNone(verdict, pwsh_output)
        expected_exit = (0 if verdict.group(1).startswith("No problems")
                         else 2 if verdict.group(1).startswith("No failures") else 3)
        self.assertEqual(expected_exit, pwsh_result.returncode, pwsh_output)
        self.assert_no_stack_trace(pwsh_output)

        # The identical copy under 5.1: nothing of the doctor's own is printed,
        # so the run above is measurably the only one that diagnosed anything.
        refused = refuse_under_windows_powershell(
            self, copied / "doctor.ps1", ["-Config", str(self.config_path)],
            cwd=copied, env=self.script_env(), what="scripts/doctor.ps1 end to end, under 5.1")
        refused_output = self.output_of(refused)
        self.assertNotRegex(refused_output, r"(?m)^HOST ", refused_output)
        self.assertNotIn("Python environment", refused_output)
        self.assertEqual([], self.headlines(refused_output), refused_output)

    # What this machine's network says, which two consecutive runs need not
    # agree on: left out of the comparison between the shells.
    NETWORK_CHECKS = ("mDNS", "Network category", "Firewall", "LAN address")

    @classmethod
    def headlines(cls, output):
        """Each check's status and name, without the value that follows them:
        a port may differ between two runs, the verdict may not."""
        found = []
        for line in output.splitlines():
            match = re.match(r"^(\[(?: OK |WARN|FAIL|INFO)\] [^-]*?)(?: - .*)?$", line)
            # The closing counts include the network checks, and are asserted above.
            if not match or "check(s)" in line or "problem(s)" in line:
                continue
            if any(match.group(1)[7:].startswith(name) for name in cls.NETWORK_CHECKS):
                continue
            found.append(match.group(1))
        return found

    @staticmethod
    def check_block(output, headline):
        return DoctorEndpointProbeTests.check_block(output, headline)


class WindowsPowerShellPythonVersionTests(ScriptTestCase):
    """The interpreter's version is read under Windows PowerShell 5.1 too (T-0248).

    Measured before the fix, 5.1.26100.9444: Get-LcPythonVersion answered
    'unknown' for a working 3.10.11, and setup.ps1 said the same interpreter
    "did not answer as a Python interpreter", because the code both passed with
    -c carried double quotes and 5.1 dropped them.

    RE-AIMED BY T-0294, AND THIS IS WHERE THE CLASS'S 5.1 COVERAGE NOW LIVES.
    The defect was in Get-LcPythonVersion, in scripts/lib/Common.ps1 -- a
    dot-sourced helper with no version gate -- and the three scripts below were
    only the places it surfaced. So the helper is still driven under BOTH shells
    by the first test, character for character, and the three script tests keep
    their pwsh assertion whole and assert the refusal under 5.1, which is what
    an entry script does there now. Deleting the gate does not make any of them
    pass: the refusal is asserted, not merely tolerated.
    """

    VERSION = "{}.{}.{}".format(*sys.version_info[:3])

    def both_shells(self, what):
        return (("pwsh", PWSH), ("5.1", require_windows_powershell(self, what)))

    def assert_host(self, name, output):
        if name == "5.1":
            self.assertRegex(output, r"(?m)^HOST 5\.", output)
        else:
            self.assertNotRegex(output, r"(?m)^HOST 5\.", output)

    def copy_with_host_line(self, name, anchor):
        """A copy of the scripts whose ``name`` prints the host first."""
        copied = self.copy_scripts_with_stopping_disabled()
        script = copied / name
        source = script.read_text(encoding="utf-8-sig")
        self.assertEqual(1, source.count(anchor), name)
        script.write_text(source.replace(
            anchor, anchor + "Write-Host \"HOST $($PSVersionTable.PSVersion)\"\n", 1),
            encoding="utf-8")
        return copied

    def test_get_lc_python_version_reads_the_version_under_both_shells(self):
        for name, shell in self.both_shells("Get-LcPythonVersion"):
            with self.subTest(shell=name):
                result = self.run_powershell(
                    "Write-Output \"HOST $($PSVersionTable.PSVersion)\"\n"
                    "Write-Output ('VERSION [' + (Get-LcPythonVersion -PythonExe '{}') + ']')\n"
                    .format(sys.executable), shell=shell)
                output = self.output_of(result)
                self.assertEqual(0, result.returncode, output)
                self.assert_host(name, output)
                self.assertIn("VERSION [{}]".format(self.VERSION), result.stdout, output)

    def test_status_prints_the_interpreter_version_and_5_1_is_refused(self):
        self.write_config()
        copied = self.copy_with_host_line("status.ps1", "\ntry {\n")
        result = self.run_script("status.ps1", script_dir=copied, shell=PWSH)
        output = self.output_of(result)
        self.assert_host("pwsh", output)
        self.assertIn("{} (Python {})".format(sys.executable, self.VERSION), output)
        self.assertNotIn("(Python unknown)", output)

        refused = self.output_of(refuse_under_windows_powershell(
            self, copied / "status.ps1", ["-Config", str(self.config_path)],
            cwd=copied, env=self.script_env(), what="scripts/status.ps1's Interpreter line"))
        self.assertNotIn("Interpreter", refused)
        self.assertNotIn(sys.executable, refused)

    def test_start_prints_the_interpreter_version_and_5_1_is_refused(self):
        """start.ps1's version line, and nothing past it: in external mode with
        nothing listening, the run stops at the ComfyUI check and launches
        nothing.

        Under 5.1 it does not even do that. The two markers are checked after
        BOTH runs, because "the refusal started nothing" is the half of this
        claim that matters most: start.ps1 is the one script whose body launches
        processes.
        """
        self.write_config(manage_comfy=False)
        copied = self.copy_with_host_line("start.ps1", "\ntry {\n    Write-LcBanner\n")
        result = self.run_script("start.ps1", script_dir=copied, shell=PWSH)
        output = self.output_of(result)
        self.assert_host("pwsh", output)
        self.assertNotEqual(0, result.returncode, output)
        self.assertIn("Python: {} (Python {})".format(sys.executable, self.VERSION), output)
        self.assertFalse(self.comfy_marker.exists(), output)
        self.assertFalse(self.gateway_marker.exists(), output)

        def runtime_state():
            return sorted(str(path) for path in self.runtime_dir.rglob("*")) \
                if self.runtime_dir.exists() else ["absent"]

        before = runtime_state()
        refused = self.output_of(refuse_under_windows_powershell(
            self, copied / "start.ps1", ["-Config", str(self.config_path)],
            cwd=copied, env=self.script_env(), what="scripts/start.ps1's Python line"))
        self.assertNotIn("Python:", refused)
        self.assertFalse(self.comfy_marker.exists(), refused)
        self.assertFalse(self.gateway_marker.exists(), refused)
        self.assertEqual(before, runtime_state(), refused)

    def test_setup_reads_the_interpreter_version_and_5_1_is_refused(self):
        """setup.ps1's own probe, against an environment that already exists.

        The environment is built here without pip, so the run reuses it, prints
        the versions it read, and stops at the gateway install: no network, and
        nothing built at the repository's .venv.

        This is the REAL scripts/setup.ps1, not a copy, in both halves -- and
        under 5.1 the whole point is that it is refused before it can decide
        anything about an interpreter or an environment.
        """
        venv = self.workspace / "existing venv"
        subprocess.run(
            [sys.executable, "-m", "venv", "--without-pip", str(venv)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=300, check=True)
        venv_python = venv / "Scripts" / "python.exe"
        self.assertTrue(venv_python.is_file())
        env = {k: v for k, v in os.environ.items() if not k.startswith("LC_STUB_")}
        env.pop("PYTHONPATH", None)
        env["LOCALCANVAS_RUNTIME_DIR"] = str(self.runtime_dir)
        result = subprocess.run(
            [str(PWSH), "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
             "-Command",
             "Write-Host \"HOST $($PSVersionTable.PSVersion)\"; & '{}' -PythonExe '{}' "
             "-VenvPath '{}' -SkipPipUpgrade; exit $LASTEXITCODE".format(
                 SCRIPTS / "setup.ps1", sys.executable, venv)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=300, env=env, cwd=str(REPO))
        output = self.output_of(result)
        self.assert_host("pwsh", output)
        self.assertNotIn("did not answer as a Python interpreter", output)
        self.assertIn("Environment already present - reusing it", output)
        self.assertIn("Version:     Python " + self.VERSION, output)
        self.assertIn("-PythonExe names {} (Python {})".format(
            sys.executable, self.VERSION), output)

        refused = self.output_of(refuse_under_windows_powershell(
            self, SCRIPTS / "setup.ps1",
            ["-PythonExe", sys.executable, "-VenvPath", str(venv), "-SkipPipUpgrade"],
            cwd=REPO, env=env, what="scripts/setup.ps1's interpreter probe"))
        self.assertNotIn("Environment already present", refused)
        self.assertNotIn("Version:", refused)


#: A console of the child's own, with no window on anybody's desktop. The same
#: flag as OWN_CONSOLE further down, asked for an unrelated reason and named
#: for THIS one: what the class below needs is not a code page but a standard
#: input that is a real console handle rather than a pipe, and this is the only
#: way to get one without putting a window on the user's screen for every
#: test in the group. MEASURED: under this flag, with no handle named to
#: subprocess (so python sets no STARTF_USESTDHANDLES and the child inherits
#: the console this flag created), [Console]::IsInputRedirected is False --
#: which is the discriminator T-0294's round-2 review measured and the one this
#: whole class exists to put under test.
REAL_CONSOLE = getattr(subprocess, "CREATE_NO_WINDOW", 0)

#: The two conditions every test in ProbeBoundaryTests runs in.
PROBE_CONDITIONS = ("redirected", "console")


class ProbeBoundaryTests(ScriptTestCase):
    """An external-executable probe is bounded, non-interactive, deterministic.

    WHY THIS CLASS EXISTS, AND WHAT IT MEASURES (T-0299). scripts/doctor.ps1
    asks two questions of an external executable -- the interpreter's version
    and the gateway's reading of the configuration -- and both used to be asked
    with PowerShell's call operator. That operator hands the child THIS
    TERMINAL'S standard input. Under this suite and under CI that input is a
    pipe, so the defect is invisible; a user runs the doctor from a console,
    where the same handle is a keyboard.

    Measured on the development machine, with a copy of an ordinary Windows
    executable that reads standard input standing in for a stale python_exe:

        main, standard input redirected   doctor exits 3 in 1.4 s
        main, standard input a console    banner, then NOTHING for 180 s,
                                          stopped by PID
        this branch, a console            doctor exits 3 in 2.2 s

    WHAT THE CONSOLE CONDITION HERE REPRODUCES FAITHFULLY, and what it only
    approximates, said plainly because the difference is the whole worth of the
    class:

      faithful -- standard input is a real console input handle and not a pipe
        ([Console]::IsInputRedirected is False, asserted in every test below);
        standard output and standard error are real console screen buffers; the
        process has a console of its own, so anything it launches inherits
        console handles. That is the measured discriminator.

      approximated -- the console has no WINDOW. Nobody can type into it, so a
        child that waits for a keystroke waits for one that can never arrive;
        a user at a real terminal could end the wait by pressing Ctrl+C or
        feeding it a line, which this cannot. It is therefore the WORST case of
        the console condition rather than the average one, which is the right
        way round for a test.

      approximated -- there is no terminal application (conhost, Windows
        Terminal) in the process tree, and the console buffer is whatever width
        Windows defaults to rather than one a person chose. Console WIDTH is a
        separate hazard with its own guard in this file
        (ConsoleWidthRefusalTests' pinned captures, T-0294 rework 1); it is not
        this defect's discriminator and this class does not re-measure it.

      approximated -- where a whole script is run rather than a library call,
        the SCRIPT'S OWN OUTPUT is redirected into a file by a wrapper so the
        assertions can read it. Its standard INPUT is untouched and stays the
        console handle, which is the variable under test: the 180-second run
        above was measured through exactly this wrapper, so redirecting the
        output demonstrably does not make the defect go away.
    """

    VERSION = "{}.{}.{}".format(*sys.version_info[:3])
    LIBRARY = SCRIPTS / "lib" / "Common.ps1"

    # -- the two conditions ------------------------------------------------

    @staticmethod
    def stop_tree(pid):
        """Stop one process and everything it started, BY PID.

        `/T` reaches the children of that one process id; nothing here names an
        image, and nothing here searches the process table. Used only when the
        harness's own deadline expires, which on a healthy branch is never.
        """
        subprocess.run(
            ["taskkill", "/PID", str(int(pid)), "/T", "/F"],
            capture_output=True, text=True, encoding="utf-8", errors="replace")

    def run_in(self, condition, script, timeout):
        """Run one PowerShell script in one of the two conditions.

        The argv is IDENTICAL in both, and `-NonInteractive` is deliberately
        not among it: that flag governs PowerShell's own prompting, and passing
        it in one condition and not the other would put a second variable next
        to the one under test. The only difference between the two branches is
        what the three standard handles are.

        Returns (elapsed seconds, exit code or None, harness output, timed out).
        """
        command = [
            PWSH, "-NoProfile", "-NoLogo", "-ExecutionPolicy", "Bypass",
            "-File", str(script)]
        arguments = dict(cwd=str(REPO), env=self.script_env())
        if condition == "redirected":
            arguments.update(
                stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT, text=True,
                encoding="utf-8", errors="replace")
        elif condition == "console":
            # NOT ONE HANDLE MAY BE NAMED HERE. Naming even stdout makes python
            # set STARTF_USESTDHANDLES and fill the other two from its own, and
            # the child's standard input becomes this runner's pipe again --
            # the condition would silently turn back into the other one.
            arguments.update(creationflags=REAL_CONSOLE)
        else:
            raise AssertionError("unknown condition " + condition)

        started = time.monotonic()
        process = subprocess.Popen(command, **arguments)
        timed_out = False
        try:
            output, _ = process.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            timed_out = True
            self.stop_tree(process.pid)
            try:
                output, _ = process.communicate(timeout=60)
            except subprocess.TimeoutExpired:
                output = None
        return (time.monotonic() - started, process.returncode, output or "", timed_out)

    def probe_result(self, condition, snippet, timeout=90):
        """Drive the library in one condition and read `$probe` back as data.

        The snippet is handed a dot-sourced library and must leave its answer
        in `$probe`. The answer travels through a FILE and not through standard
        output, because in the console condition there is no pipe to travel
        through -- which is the point of the condition.
        """
        answer = self.workspace / "probe answer.json"
        script = self.workspace / "drive the probe.ps1"
        script.write_text(
            "Set-StrictMode -Version Latest\n"
            "$ErrorActionPreference = 'Stop'\n"
            ". '{library}'\n"
            "$redirected = [Console]::IsInputRedirected\n"
            "{snippet}\n"
            "$answer = [pscustomobject]@{{ StdinRedirected = $redirected; Probe = $probe }}\n"
            "[System.IO.File]::WriteAllText('{answer}', ($answer | ConvertTo-Json -Depth 8))\n"
            .format(library=self.LIBRARY, snippet=snippet, answer=answer),
            encoding="utf-8")
        elapsed, code, output, timed_out = self.run_in(condition, script, timeout)
        self.assertFalse(
            timed_out,
            "the harness's own {}s deadline expired in the {} condition -- the probe "
            "did not come back at all:\n{}".format(timeout, condition, output))
        self.assertTrue(
            answer.is_file(),
            "the driver wrote no answer (exit {}):\n{}".format(code, output))
        document = json.loads(answer.read_text(encoding="utf-8"))
        # Every test asserts this, in every condition: without it a "console"
        # run that quietly got a pipe would pass and mean nothing.
        self.assertEqual(
            condition == "redirected", bool(document["StdinRedirected"]),
            "the {} condition did not give the child the standard input it "
            "claims to".format(condition))
        document["Elapsed"] = elapsed
        return document

    def doctor_in(self, condition, python_exe, timeout=120, config=None):
        """Run scripts/doctor.ps1 in one condition; return (text, exit, seconds).

        The doctor's own output goes to a file, in BOTH conditions, so the two
        differ in nothing but standard input. Its exit code is written out only
        after the script has finished, so a run that never finishes leaves no
        exit code at all rather than an inherited one.
        """
        log = self.workspace / "doctor output.log"
        stamp = self.workspace / "doctor exit.txt"
        for path in (log, stamp):
            if path.exists():
                path.unlink()
        script = self.workspace / "drive the doctor.ps1"
        script.write_text(
            "& '{doctor}' -Config '{config}' -PythonExe '{python}' *> '{log}'\n"
            "$code = $LASTEXITCODE\n"
            "[System.IO.File]::WriteAllText('{stamp}', \"$code\")\n"
            "exit $code\n".format(
                doctor=SCRIPTS / "doctor.ps1",
                config=config if config is not None else self.config_path,
                python=python_exe, log=log, stamp=stamp),
            encoding="utf-8")
        elapsed, _, output, timed_out = self.run_in(condition, script, timeout)
        self.assertFalse(
            timed_out,
            "scripts/doctor.ps1 did not finish inside {}s in the {} condition; it "
            "was stopped by PID. What it had printed:\n{}".format(
                timeout, condition,
                log.read_text(encoding="utf-8", errors="replace") if log.is_file() else "",
            ))
        text = log.read_text(encoding="utf-8", errors="replace") if log.is_file() else ""
        code = stamp.read_text(encoding="utf-8").strip() if stamp.is_file() else None
        return text, (int(code) if code not in (None, "") else None), elapsed

    # -- the fixtures ------------------------------------------------------

    def a_file_that_is_not_an_executable(self):
        path = self.workspace / "not python.exe"
        path.write_text("this is not an executable", encoding="utf-8")
        return path

    def an_executable_that_reads_standard_input(self):
        """A real console program that ignores its arguments and reads stdin.

        Copied into the workspace under a name of its own: what is under test
        is a python_exe that waits for input, not any particular Windows tool,
        and a copy says so. findstr.exe handed `-c <something>` takes the first
        as its pattern and then reads standard input for ever -- MEASURED here,
        and measured again by every run of the control below, which fails if
        this stops being true.
        """
        source = Path(os.environ.get("SystemRoot", r"C:\Windows")) / "System32" / "findstr.exe"
        if not source.is_file():
            self.skipTest("no {} on this machine to copy".format(source))
        path = self.workspace / "waits for input.exe"
        shutil.copyfile(str(source), str(path))
        return path

    def a_program_that_sleeps(self):
        """python <this> <seconds> <marker> -- sleeps, then writes the marker.

        The marker is how a kill is proved: a probe whose child was really
        stopped leaves no marker, and one that was merely abandoned leaves one
        a few seconds later.
        """
        path = self.workspace / "sleep then mark.py"
        path.write_text(
            "import sys, time\n"
            "time.sleep(float(sys.argv[1]))\n"
            "open(sys.argv[2], 'w', encoding='utf-8').write('finished')\n",
            encoding="utf-8")
        return path

    @staticmethod
    def version_probe(python_exe):
        return "$probe = Get-LcPythonVersionProbe -PythonExe '{}'".format(python_exe)

    # -- 1. a valid interpreter succeeds ----------------------------------

    def test_a_valid_interpreter_answers_in_both_conditions(self):
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                document = self.probe_result(
                    condition, self.version_probe(sys.executable))
                answer = document["Probe"]
                self.assertEqual(self.VERSION, answer["Version"], answer)
                self.assertEqual("", answer["Failure"], answer)
                self.assertFalse(answer["TimedOut"], answer)
                probe = answer["Probe"]
                self.assertTrue(probe["Started"], probe)
                self.assertTrue(probe["Exited"], probe)
                self.assertEqual(0, probe["ExitCode"], probe)
                self.assertGreater(probe["ProcessId"], 0, probe)
                # And the version really came off the child's standard output,
                # not out of thin air.
                self.assertIn(self.VERSION, probe["StandardOutput"], probe)

    # -- 2. a nonexistent interpreter fails quickly ------------------------

    def test_an_interpreter_that_is_not_there_fails_at_once(self):
        missing = self.workspace / "no python.exe"
        self.assertFalse(missing.exists())
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                document = self.probe_result(
                    condition, self.version_probe(missing), timeout=60)
                answer = document["Probe"]
                self.assertEqual("unknown", answer["Version"], answer)
                probe = answer["Probe"]
                self.assertFalse(probe["Started"], probe)
                self.assertFalse(probe["TimedOut"], probe)
                self.assertTrue(
                    answer["Failure"].startswith("The Python interpreter could not be started:"),
                    answer["Failure"])
                self.assertLess(probe["ElapsedMs"], 5000, probe)

    # -- 3. an existing non-interpreter executable fails quickly -----------

    def test_a_file_that_is_not_an_executable_fails_at_once(self):
        broken = self.a_file_that_is_not_an_executable()
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                document = self.probe_result(
                    condition, self.version_probe(broken), timeout=60)
                answer = document["Probe"]
                self.assertEqual("unknown", answer["Version"], answer)
                probe = answer["Probe"]
                self.assertFalse(probe["Started"], probe)
                self.assertFalse(probe["TimedOut"], probe)
                self.assertTrue(
                    answer["Failure"].startswith("The Python interpreter could not be started:"),
                    answer["Failure"])
                # THE NUMBER THIS CARD IS ABOUT. The same call through the call
                # operator retried the launch through the Windows shell, whose
                # cost is the machine's and was measured at 38,853 ms on this
                # one. Five seconds is far above what the shell-free launch
                # takes (about 60 ms, measured) and far below what the shell
                # route has been seen to.
                self.assertLess(probe["ElapsedMs"], 5000, probe)

    # -- 4. an executable that waits on stdin cannot hang the doctor -------

    def test_the_call_operator_really_does_hang_on_a_console(self):
        """The control, and the fixture's own certificate.

        Everything in the test below is worth nothing if the fixture does not
        actually block, so this drives the OLD shape -- the call operator,
        exactly as scripts/lib/Common.ps1 wrote it before this card -- against
        the same fixture, in both conditions, under a deadline of the harness's
        own. Redirected it must finish; on a console it must NOT, and what is
        left running is stopped by PID.

        Nothing is mutated to run this: the old shape is four words, written
        into the harness's own driver script in the workspace. No file of the
        repository is touched by it.
        """
        waits = self.an_executable_that_reads_standard_input()
        script = self.workspace / "drive the old shape.ps1"
        done = self.workspace / "old shape finished.txt"
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                if done.exists():
                    done.unlink()
                script.write_text(
                    "$ErrorActionPreference = 'Continue'\n"
                    "$PSNativeCommandUseErrorActionPreference = $false\n"
                    "$out = & '{waits}' -c 'import sys' 2>&1\n"
                    "[System.IO.File]::WriteAllText('{done}', \"$out\")\n"
                    .format(waits=waits, done=done),
                    encoding="utf-8")
                _, _, output, timed_out = self.run_in(condition, script, 25)
                if condition == "redirected":
                    self.assertFalse(
                        timed_out,
                        "the fixture blocked even with standard input redirected, so "
                        "it no longer isolates the console condition:\n" + output)
                    self.assertTrue(done.is_file(), output)
                else:
                    self.assertTrue(
                        timed_out,
                        "the call operator came back on a console, so this fixture no "
                        "longer reproduces the defect and the test below proves "
                        "nothing:\n" + output)
                    wrote = done.read_text(encoding="utf-8", errors="replace") \
                        if done.is_file() else ""
                    self.assertFalse(
                        done.is_file(), "it wrote its answer after all: " + wrote)

    def test_an_interpreter_that_waits_for_input_cannot_hold_the_probe(self):
        waits = self.an_executable_that_reads_standard_input()
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                document = self.probe_result(
                    condition, self.version_probe(waits), timeout=60)
                answer = document["Probe"]
                self.assertEqual("unknown", answer["Version"], answer)
                probe = answer["Probe"]
                self.assertTrue(probe["Started"], probe)
                # It came back because standard input was CLOSED, not because a
                # deadline rescued it: a probe that has to be rescued by its own
                # timeout still costs the user the timeout.
                self.assertTrue(probe["Exited"], probe)
                self.assertFalse(probe["TimedOut"], probe)
                self.assertLess(probe["ElapsedMs"], 10000, probe)

    def test_the_doctor_answers_over_an_interpreter_that_waits_for_input(self):
        self.write_config()
        waits = self.an_executable_that_reads_standard_input()
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                text, code, elapsed = self.doctor_in(condition, waits, timeout=90)
                self.assertEqual(3, code, text)
                self.assertIn("Python environment - broken", text)
                self.assertLess(elapsed, 60, text)
                self.assert_no_stack_trace(text)

    # -- 5. a deliberately sleeping probe hits its bound -------------------

    def test_a_probe_that_will_not_finish_hits_its_own_bound(self):
        sleeper = self.a_program_that_sleeps()
        marker = self.workspace / "the sleeper finished.txt"
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                if marker.exists():
                    marker.unlink()
                document = self.probe_result(
                    condition,
                    "$probe = Invoke-LcExecutableProbe -FilePath '{python}' "
                    "-Arguments @('{sleeper}', '120', '{marker}') "
                    "-Component 'The sleeping probe' -TimeoutSeconds 3".format(
                        python=sys.executable, sleeper=sleeper, marker=marker),
                    timeout=90)
                probe = document["Probe"]
                self.assertTrue(probe["Started"], probe)
                self.assertTrue(probe["TimedOut"], probe)
                self.assertFalse(probe["Exited"], probe)
                # The bound is the bound: it waited for it, and not much past it.
                self.assertGreaterEqual(probe["ElapsedMs"], 3000, probe)
                self.assertLess(probe["ElapsedMs"], 45000, probe)
                # And the child was stopped rather than left to finish.
                self.assertFalse(
                    marker.exists(),
                    "the child ran to completion, so nothing was stopped")

    def test_each_probe_carries_the_bound_that_belongs_to_it(self):
        """Two questions, two numbers, and neither wearing the other's.

        "Bounded" is satisfied by one arbitrary number applied everywhere, and
        that is the thing the card forbids: the interpreter printing its own
        version and the gateway importing its whole package are not the same
        wait, and a bound big enough for the second is no bound at all for the
        first. So this asserts the two are different, that the version probe
        really carries the version number -- read off the probe it returns, not
        off the source -- and that each function reaches for its own constant.
        """
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                document = self.probe_result(
                    condition,
                    "$probe = [pscustomobject]@{{\n"
                    "    Version = $script:PythonVersionProbeSeconds\n"
                    "    Config  = $script:ConfigLoaderProbeSeconds\n"
                    "    Carried = (Get-LcPythonVersionProbe -PythonExe '{}').Probe.TimeoutSeconds\n"
                    "}}".format(sys.executable))
                bounds = document["Probe"]
                self.assertGreater(bounds["Version"], 0, bounds)
                self.assertGreater(bounds["Config"], 0, bounds)
                self.assertNotEqual(
                    bounds["Version"], bounds["Config"],
                    "the two probes share one number, which is the bound this card "
                    "refused to add")
                self.assertEqual(
                    bounds["Version"], bounds["Carried"],
                    "the interpreter probe ran under a bound that is not its own")

        # The seam's own bound cannot be read off its answer -- Read-LcConfig
        # returns a configuration, not a probe -- so it is anchored in the
        # source, at the function, which is where a swap would have to be made.
        library = self.LIBRARY.read_text(encoding="utf-8-sig")
        for name, mine, theirs in (
                ("Get-LcPythonVersionProbe",
                 "$script:PythonVersionProbeSeconds", "$script:ConfigLoaderProbeSeconds"),
                ("Read-LcConfig",
                 "$script:ConfigLoaderProbeSeconds", "$script:PythonVersionProbeSeconds")):
            body = powershell_function_body(library, name)
            self.assertIsNotNone(body, name + " is gone; this scan has nothing to anchor to")
            self.assertIn(mine, body, name + " no longer reaches for its own bound")
            self.assertNotIn(theirs, body, name + " reaches for the other probe's bound")

    # -- 6. the timeout kills only the owned probe -------------------------

    def test_the_bound_stops_its_own_child_and_no_other(self):
        """A sibling of the SAME IMAGE, started by the harness, survives.

        This is the property that separates a bounded probe from a cleanup that
        kills by name, and it is the one that has cost this project real damage
        before, so it is proved rather than argued: the sibling here is the very
        same python.exe the probe is about to start and stop.
        """
        sleeper = self.a_program_that_sleeps()
        sibling_marker = self.workspace / "the sibling finished.txt"
        probe_marker = self.workspace / "the probe child finished.txt"
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                for path in (sibling_marker, probe_marker):
                    if path.exists():
                        path.unlink()
                sibling = subprocess.Popen(
                    [sys.executable, str(sleeper), "300", str(sibling_marker)],
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                self.owned_stubs.append(sibling)
                self.assertTrue(
                    wait_until(lambda: self.alive(sibling.pid), 20),
                    "the sibling never started")

                document = self.probe_result(
                    condition,
                    "$probe = Invoke-LcExecutableProbe -FilePath '{python}' "
                    "-Arguments @('{sleeper}', '300', '{marker}') "
                    "-Component 'The owned probe' -TimeoutSeconds 3".format(
                        python=sys.executable, sleeper=sleeper, marker=probe_marker),
                    timeout=90)
                probe = document["Probe"]
                self.assertTrue(probe["TimedOut"], probe)
                self.assertGreater(probe["ProcessId"], 0, probe)
                self.assertNotEqual(sibling.pid, probe["ProcessId"], probe)

                # The one it started is gone ...
                self.assertTrue(
                    wait_until(lambda: not self.alive(probe["ProcessId"]), 20),
                    "the process the probe started, {}, is still running".format(
                        probe["ProcessId"]))
                # ... and the one it did not is untouched, and still WORKING --
                # not merely present in the table, and not finished either.
                self.assertIsNone(
                    sibling.poll(),
                    "a sibling process of the same image was stopped with the probe")
                self.assertTrue(self.alive(sibling.pid))
                self.assertFalse(
                    sibling_marker.exists(), "the sibling is no longer mid-run")
                self.assertFalse(
                    probe_marker.exists(), "the probe's own child was not stopped")

                self.force_terminate(sibling.pid)
                sibling.wait(timeout=30)

    # -- 7. normal doctor behaviour is unchanged ---------------------------

    def test_a_healthy_doctor_run_says_the_same_thing_in_both_conditions(self):
        self.write_config()
        seen = {}
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                text, code, elapsed = self.doctor_in(
                    condition, sys.executable, timeout=180)
                self.assertIsNotNone(code, text)
                self.assertIn("[ OK ] Python environment - Python " + self.VERSION, text)
                self.assertIn("[ OK ] Configuration - loaded and valid", text)
                self.assertNotIn("Python environment - broken", text)
                self.assert_no_stack_trace(text)
                self.assertLess(elapsed, 120, text)
                seen[condition] = (code, doctor_check_headlines(text))
        # Not "each looks plausible" but "the two are the same answer": the
        # check lines and the exit code, compared to each other.
        self.assertEqual(
            seen["redirected"], seen["console"],
            "the doctor answered differently depending on what its standard "
            "input was:\n{!r}\n{!r}".format(seen["redirected"], seen["console"]))

    # -- 8. the diagnostic names the failed component ----------------------

    def test_every_failed_probe_names_the_component_that_failed(self):
        broken = self.a_file_that_is_not_an_executable()
        self.write_config()
        for condition in PROBE_CONDITIONS:
            with self.subTest(condition=condition):
                # The interpreter probe, through the library.
                document = self.probe_result(
                    condition, self.version_probe(broken), timeout=60)
                self.assertIn(
                    "The Python interpreter could not be started:",
                    document["Probe"]["Failure"])

                # The configuration seam, through the library: a different
                # component, named as itself and not as "the probe".
                document = self.probe_result(
                    condition,
                    "$probe = Read-LcConfig -ConfigPath '{config}' -PythonExe '{broken}'"
                    .format(config=self.config_path, broken=broken),
                    timeout=60)
                seam = document["Probe"]
                self.assertFalse(seam["Ok"], seam)
                self.assertIn(
                    "The gateway's configuration loader could not be started:",
                    seam["What"])
                self.assertIn("localcanvas_gateway config", " ".join(seam["Detail"]))

                # A deadline names it too, and says what was done about it.
                document = self.probe_result(
                    condition,
                    "$probe = Invoke-LcExecutableProbe -FilePath '{python}' "
                    "-Arguments @('{sleeper}', '120', '{marker}') "
                    "-Component 'The named component' -TimeoutSeconds 2".format(
                        python=sys.executable, sleeper=self.a_program_that_sleeps(),
                        marker=self.workspace / "never written.txt"),
                    timeout=90)
                self.assertIn(
                    "The named component did not answer within 2 seconds and was "
                    "stopped", document["Probe"]["Failure"])

                # And the doctor prints the sentence rather than keeping it.
                text, code, _ = self.doctor_in(condition, broken, timeout=90)
                self.assertEqual(3, code, text)
                self.assertIn("[FAIL] Python environment - broken", text)
                self.assertIn("The Python interpreter could not be started:", text)
                self.assert_no_stack_trace(text)

    # -- 9. the sentence names a directory somebody chose (T-0307) ---------

    def test_the_probe_names_the_directory_localcanvas_chose(self):
        """A diagnostic that names a directory is asserting something.

        .NET's own sentence for a launch that did not happen reads "An error
        occurred trying to start process '<exe>' with working directory
        '<dir>'", and <dir> is ProcessStartInfo's when one is set and the
        HOSTING PROCESS's .NET current directory when it is not -- which is
        where pwsh was STARTED, not where the user has since Set-Location'd.
        Observed by the clean-clone release validation: the doctor's sentence
        named a directory that had nothing to do with the failure.

        So the host here is started somewhere else entirely, and the two
        halves are checked: the directory the probe GAVE the child, which is
        state, and the sentence, which must not carry the inherited one.
        """
        broken = self.a_file_that_is_not_an_executable()
        elsewhere = self.workspace / "where the shell happened to start"
        elsewhere.mkdir()

        answer = self.probe_from(elsewhere, broken)
        self.assertFalse(answer["Started"], answer)
        self.assertEqual(
            Path(REPO).resolve(), Path(answer["WorkingDirectory"]).resolve(),
            "the probe did not choose a working directory of its own")
        self.assertNotIn(
            str(elsewhere), answer["Failure"],
            "the sentence names the directory the shell was started in")
        self.assertIn("working directory", answer["Failure"].lower())
        self.assertIn(str(REPO).lower(), answer["Failure"].lower())

        # The control, which is what stops this passing on a probe that simply
        # never names a directory: asked for one explicitly, it uses that one.
        chosen = self.probe_from(elsewhere, broken, working_directory=elsewhere)
        self.assertEqual(
            Path(elsewhere).resolve(), Path(chosen["WorkingDirectory"]).resolve())
        self.assertIn(str(elsewhere), chosen["Failure"])

    def probe_from(self, start_directory, executable, working_directory=None):
        """Invoke-LcExecutableProbe, from a host started in ``start_directory``."""
        driver = self.workspace / "ask the probe.ps1"
        extra = ""
        if working_directory is not None:
            extra = " -WorkingDirectory {}".format(powershell_literal(working_directory))
        driver.write_text(
            "Set-StrictMode -Version Latest\n"
            "$ErrorActionPreference = 'Stop'\n"
            ". {}\n".format(powershell_literal(self.LIBRARY)) +
            "$probe = Invoke-LcExecutableProbe -FilePath {} ".format(
                powershell_literal(executable)) +
            "-Component 'The Python interpreter' -TimeoutSeconds 5" + extra + "\n"
            "[pscustomobject]@{\n"
            "    Started = [bool]$probe.Started\n"
            "    WorkingDirectory = [string]$probe.WorkingDirectory\n"
            "    Failure = [string]$probe.Failure\n"
            "} | ConvertTo-Json -Compress\n",
            encoding="utf-8")
        result = subprocess.run(
            [PWSH, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
             "-File", str(driver)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120, cwd=str(start_directory))
        self.assertEqual(0, result.returncode, self.output_of(result))
        return json.loads(result.stdout)


def doctor_check_headlines(text):
    """Every "[TAG] Name - value" headline the doctor printed, in order.

    The doctor's detail lines carry this machine's paths and this run's ports;
    its headlines carry its verdict. Comparing two runs by their headlines is
    comparing the answers rather than the transcripts.
    """
    return [
        line.strip() for line in text.splitlines()
        if re.match(r"^\[(?:INFO| OK |WARN|FAIL)\]\s", line)
    ]


class ProbeDeadlineWindowsPowerShellTests(ScriptTestCase):
    """The probe's deadline is said as the deadline under 5.1 too (T-0250).

    .NET Framework's HttpClient ends a request at its Timeout with a bare
    TaskCanceledException -- no TimeoutException beneath it, which is what the
    sentence was keyed on -- so under 5.1 every probe deadline was quoted as
    "A task was canceled.". A bare cancellation is now the deadline only when
    the probe's own clock says the deadline had come.
    """

    def both_shells(self, what):
        return (("pwsh", PWSH), ("5.1", require_windows_powershell(self, what)))

    def test_the_deadline_and_the_refusal_are_told_apart_under_both_shells(self):
        """A silent listener at two deadlines, a refused port below and above
        the refusal time. The refusal's words are asked of the same process
        that probed, because this machine's 5.1 changes language between runs;
        what is asserted verbatim is LocalCanvas's own sentence."""
        silent = free_port()
        DoctorEndpointProbeTests.start_silent_listener(self, "127.0.0.1", silent)
        refused = free_port()
        cases = (
            ("silent", silent, 1), ("silent", silent, 3),
            ("refused", refused, PROBE_DEADLINE_BELOW_REFUSAL),
            ("refused", refused, PROBE_DEADLINE_ABOVE_REFUSAL))
        snippet = (
            "Write-Output \"HOST $($PSVersionTable.PSVersion)\"\n"
            "$answers = foreach ($case in @({cases})) {{\n"
            "    $clock = [System.Diagnostics.Stopwatch]::StartNew()\n"
            "    $probe = Invoke-LcProbe -Url ('http://127.0.0.1:' + $case[1] + '/system_stats') "
            "-TimeoutSeconds $case[2]\n"
            "    [pscustomobject]@{{ case = $case[0]; seconds = [double]$case[2]; ok = [bool]$probe.Ok;\n"
            "        error = [string]$probe.Error; elapsed = $clock.Elapsed.TotalSeconds }}\n"
            "}}\n"
            # The socket layer's words for this refusal, read off a plain request
            # in the same process: the language they come in changes between runs.
            "try {{ $h = [System.Net.Http.HttpClientHandler]::new(); $h.UseProxy = $false\n"
            "    [void][System.Net.Http.HttpClient]::new($h).GetAsync("
            "'http://127.0.0.1:{refused}/system_stats').GetAwaiter().GetResult()\n"
            "}} catch {{ for ($e = $_.Exception; $e; $e = $e.InnerException) {{\n"
            "    if ($e -is [System.Net.Sockets.SocketException]) {{ Write-Output ('REFUSAL ' + $e.Message); break }} }} }}\n"
            "Write-Output ('JSON ' + (ConvertTo-Json -InputObject @($answers) -Compress))\n"
        ).format(cases=", ".join("@('{}', {}, {})".format(*case) for case in cases), refused=refused)
        for name, shell in self.both_shells("Invoke-LcProbe's deadline sentence"):
            with self.subTest(shell=name):
                result = self.run_powershell(snippet, shell=shell, timeout=180)
                output = self.output_of(result)
                self.assertEqual(0, result.returncode, output)
                if name == "5.1":
                    self.assertRegex(output, r"(?m)^HOST 5\.", output)
                else:
                    self.assertNotRegex(output, r"(?m)^HOST 5\.", output)
                refusal = re.search(r"^REFUSAL (.+)$", result.stdout, re.MULTILINE).group(1).strip()
                answers = json.loads(
                    re.search(r"^JSON (.+)$", result.stdout, re.MULTILINE).group(1))
                for answer, (case, _port, seconds) in zip(answers, cases):
                    self.assertFalse(answer["ok"], output)
                    if case == "silent" or seconds == PROBE_DEADLINE_BELOW_REFUSAL:
                        self.assertEqual(probe_deadline_sentence(seconds), answer["error"], output)
                        self.assertGreaterEqual(answer["elapsed"], seconds - 0.2, output)
                    else:
                        # The refusal ended it, well before the deadline, and it
                        # is quoted in the socket layer's own words.
                        self.assertLess(answer["elapsed"], seconds - 1, output)
                        self.assertEqual(refusal, answer["error"], output)
                        self.assertNotIn("No answer arrived", answer["error"], output)

    def cause_of(self, shell, cases):
        """Get-LcProbeFailureCause over built exception chains, as data."""
        snippet = (
            "Write-Output \"HOST $($PSVersionTable.PSVersion)\"\n"
            "function Wrap($inner) {{ [System.Management.Automation.MethodInvocationException]::new('wrapped', $inner) }}\n"
            "function Bare {{ [System.Threading.Tasks.TaskCanceledException]::new() }}\n"
            "$answers = [ordered]@{{}}\n"
            "{cases}"
            "Write-Output ('CANCELED ' + (Bare).Message)\n"
            "Write-Output ('JSON ' + ($answers | ConvertTo-Json -Compress))\n"
        ).format(cases="".join(
            "$answers['{}'] = Get-LcProbeFailureCause -Exception ({}) -TimeoutSeconds 3{}\n".format(
                key, exception, "" if elapsed is None else " -ElapsedSeconds {}".format(elapsed))
            for key, exception, elapsed in cases))
        result = self.run_powershell(snippet, shell=shell)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        canceled = re.search(r"^CANCELED (.+)$", result.stdout, re.MULTILINE).group(1).strip()
        return (json.loads(re.search(r"^JSON (.+)$", result.stdout, re.MULTILINE).group(1)),
                canceled, output)

    def test_a_bare_cancellation_is_the_deadline_only_when_the_deadline_had_come(self):
        """Each condition of the rule on its own, with a 3-second deadline.

        The elapsed values are fixed, not derived from the tolerance, so that
        widening the tolerance or dropping the clock is caught: 2.95 s is the
        deadline, 2.85 s and 0.05 s -- a cancellation that came early, from
        anything but the deadline -- are not.
        """
        deadline = probe_deadline_sentence(3)
        cases = (
            ("at the deadline", "Wrap (Bare)", 3.004),
            ("just inside the tolerance", "Wrap (Bare)", 2.95),
            ("outside the tolerance", "Wrap (Bare)", 2.85),
            ("long before it", "Wrap (Bare)", 0.05),
            ("no clock at all", "Wrap (Bare)", None),
            ("something beneath it", "Wrap ([System.Threading.Tasks.TaskCanceledException]::new("
             "'x', [System.IO.IOException]::new('under')))", 3.004),
            ("not a cancellation", "Wrap ([System.Net.Http.HttpRequestException]::new('other'))", 3.004),
            ("a TimeoutException, as pwsh has", "Wrap ([System.Threading.Tasks.TaskCanceledException]::new("
             "'x', [System.TimeoutException]::new('t')))", 0.05),
        )
        expected = {
            "at the deadline": deadline,
            "just inside the tolerance": deadline,
            "outside the tolerance": "CANCELED",
            "long before it": "CANCELED",
            "no clock at all": "CANCELED",
            "something beneath it": "under",
            "not a cancellation": "other",
            "a TimeoutException, as pwsh has": deadline,
        }
        for name, shell in self.both_shells("Get-LcProbeFailureCause's deadline rule"):
            with self.subTest(shell=name):
                answers, canceled, output = self.cause_of(shell, cases)
                if name == "5.1":
                    self.assertRegex(output, r"(?m)^HOST 5\.", output)
                self.assertEqual(
                    {key: (canceled if value == "CANCELED" else value)
                     for key, value in expected.items()},
                    answers, output)


# ==========================================================================
# doctor.ps1: "normal" only when nothing answered (T-0239)
# ==========================================================================


#: An HTTP service answering that it failed: an HTTP answer, with an error status.
HTTP_500_ANSWER = (b"HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/plain\r\n"
                   b"Content-Length: 5\r\nConnection: close\r\n\r\nerror")


class DoctorAnsweredPortTests(ScriptTestCase):
    """"That is normal when LocalCanvas is not running" -- only when it is true.

    It followed every failed probe, including one where something answered on
    the port and was not what was asked for. Something IS running there then,
    and the report now says so. Invoke-LcProbe's Answered is the decision, and
    Test-LcProbeAnswered is where it is made.

    T-0266: only a complete answer line that is not HTTP is "something else".
    A connection that ends before a complete answer -- closed without a byte,
    or with the body cut short -- is no answer, in both shells.

    ONE SHAPE IS LEFT UNASSERTED ON PURPOSE, because the two shells report it
    differently and neither report can be changed from here: bytes that are
    not HTTP with no line ending, and then a close. Measured 2026-09-17, pwsh
    7.6.6 and Windows PowerShell 5.1.26100.9444, ten runs each:
        pwsh: HttpRequestException (ResponseEnded) -> HttpIOException (ResponseEnded)
              -- the same chain and message as a close without a byte
        5.1:  HttpRequestException -> WebException (ServerProtocolViolation)
    so it is no answer under pwsh and something else under 5.1. That is the
    runtimes' limit, recorded in Test-LcProbeAnswered, and not a behaviour this
    suite holds either shell to.
    """

    NOT_HTTP = b"NOT HTTP AT ALL\r\n\r\n"
    #: Complete headers, and a body that ends 97 bytes short of its length.
    TRUNCATED_BODY = (b"HTTP/1.1 200 OK\r\nContent-Length: 100\r\nConnection: close\r\n"
                      b"\r\nabc")

    def start_listener(self, behaviour, host="127.0.0.1", port=0):
        """A loopback listener that takes each request and then misbehaves.

        ``not-http`` answers with a line that is not HTTP, ``close`` hangs up
        without a byte, ``reset`` hangs up with a RST, ``http-500`` answers
        HTTP 500 -- an HTTP service saying it failed -- and ``truncated-body``
        sends complete headers and cuts the body short. Returns the port.

        Each connection is read up to the end of the request headers before
        anything else happens. A close with the request left unread is not a
        clean close (measured, closing before reading anything: a
        SocketException ConnectionAborted or ConnectionReset in 10 of 10 runs
        under each shell), which is how "a hang-up" once measured as "a reset"
        under load when a single read did not take the whole request.
        """
        listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        listener.bind((host, port))
        listener.listen(8)
        listener.settimeout(0.25)
        stop = threading.Event()

        def serve():
            while not stop.is_set():
                try:
                    connection, _ = listener.accept()
                except socket.timeout:
                    continue
                except OSError:
                    return
                try:
                    connection.settimeout(5)
                    request = b""
                    while b"\r\n\r\n" not in request:
                        chunk = connection.recv(4096)
                        if not chunk:
                            break
                        request += chunk
                    if behaviour == "not-http":
                        connection.sendall(self.NOT_HTTP)
                    elif behaviour == "http-500":
                        connection.sendall(HTTP_500_ANSWER)
                    elif behaviour == "truncated-body":
                        connection.sendall(DoctorAnsweredPortTests.TRUNCATED_BODY)
                    elif behaviour == "reset":
                        connection.setsockopt(
                            socket.SOL_SOCKET, socket.SO_LINGER, struct.pack("ii", 1, 0))
                except OSError:
                    pass
                finally:
                    connection.close()

        thread = threading.Thread(target=serve, daemon=True)
        thread.start()

        def shut_down():
            stop.set()
            thread.join(timeout=5)
            listener.close()

        self.addCleanup(shut_down)
        return listener.getsockname()[1]

    def probe_error(self, url):
        """What Invoke-LcProbe says about ``url`` right now, asked of the shell
        the doctor runs in: the not-HTTP sentence is the runtime's, not ours."""
        result = self.run_powershell(
            "$p = Invoke-LcProbe -Url '{}' -TimeoutSeconds 3\n"
            "Write-Output ('ERROR ' + $p.Error)\n".format(url))
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        error = re.search(r"^ERROR (.+)$", result.stdout, re.MULTILINE)
        self.assertIsNotNone(error, output)
        # Something came back, and it is quoted: not the refusal, not the deadline.
        self.assertIn("NOT HTTP AT ALL", error.group(1), output)
        return error.group(1).rstrip()

    @staticmethod
    def block(output, headline):
        return DoctorEndpointProbeTests.check_block(output, headline).split("\n")

    def test_the_decision_over_real_answers_in_both_shells(self):
        """Invoke-LcProbe's Answered against each shape, under pwsh and 5.1.

        The status code is the third field: it is what tells an HTTP answer with
        an error status (the service answering, and saying it failed) from an
        answer that is not HTTP at all (something else answering).

        A hang-up without a byte and a body cut short are no answer (T-0266);
        so is https asked of a port that speaks plain HTTP, where pwsh used to
        say answered and 5.1 did not (measured: pwsh HttpRequestException
        (SecureConnectionError) -> AuthenticationException, 5.1
        HttpRequestException -> WebException (SendFailure) -> IOException).
        """
        comfy = FakeComfy()
        self.addCleanup(comfy.close)
        silent = free_port()
        DoctorEndpointProbeTests.start_silent_listener(self, "127.0.0.1", silent)
        cases = (
            ("an HTTP answer", comfy.url + "/system_stats", "True|True|200"),
            ("an HTTP 404", comfy.url + "/no-such-thing", "True|False|404"),
            ("an HTTP 500",
             "http://127.0.0.1:{}/x".format(self.start_listener("http-500")), "True|False|500"),
            ("bytes that are not HTTP",
             "http://127.0.0.1:{}/x".format(self.start_listener("not-http")), "True|False|0"),
            ("a hang-up without a byte",
             "http://127.0.0.1:{}/x".format(self.start_listener("close")), "False|False|0"),
            ("complete headers and a body cut short",
             "http://127.0.0.1:{}/x".format(self.start_listener("truncated-body")),
             "False|False|0"),
            ("https asked of a plain HTTP port",
             "https://" + comfy.url[len("http://"):] + "/system_stats", "False|False|0"),
            ("a reset", "http://127.0.0.1:{}/x".format(self.start_listener("reset")), "False|False|0"),
            ("a refusal", "http://127.0.0.1:{}/x".format(free_port()), "False|False|0"),
            ("silence past the deadline", "http://127.0.0.1:{}/x".format(silent), "False|False|0"),
        )
        snippet = "Write-Output \"HOST $($PSVersionTable.PSVersion)\"\n" + "".join(
            "$p = Invoke-LcProbe -Url '{}' -TimeoutSeconds 3\n"
            "Write-Output \"CASE {} $($p.Answered)|$($p.Ok)|$($p.StatusCode)\"\n".format(url, index)
            for index, (_name, url, _expected) in enumerate(cases))
        expected = ["CASE {} {}".format(index, answer)
                    for index, (_name, _url, answer) in enumerate(cases)]
        shells = [("pwsh", PWSH)]
        if WINDOWS_POWERSHELL is not None:
            shells.append(("powershell", require_windows_powershell(
                self, "Invoke-LcProbe's Answered over real answers")))
        for name, shell in shells:
            with self.subTest(shell=name):
                result = self.run_powershell(snippet, shell=shell, timeout=180)
                output = self.output_of(result)
                self.assertEqual(0, result.returncode, output)
                self.assertEqual(expected, re.findall(r"(?m)^CASE \d+ \S+$", result.stdout),
                                 "\n".join(name for name, _url, _answer in cases) + "\n" + output)
                if name == "powershell":
                    self.assertRegex(result.stdout, r"(?m)^HOST 5\.", output)
        if WINDOWS_POWERSHELL is None:
            self.skipTest("powershell.exe is not on PATH, so the Windows PowerShell 5.1 "
                          "half of this test was NOT measured by this run")

    def test_each_rule_of_the_decision_on_its_own(self):
        """Test-LcProbeAnswered over exception chains built to isolate one rule.

        The rule has two halves (T-0266): an HTTP failure with nothing beneath
        it is a status line refused (pwsh), and a WebException says yes only
        for ServerProtocolViolation (5.1). The "yes" lines are what each half
        accepts, the websocket handshake's chains among them (T-0259); each
        "no" is a chain that looks like an HTTP failure and carries something
        beneath it that is not an answer, so widening either half turns its
        own lines into a "yes".
        """
        http = "[System.Net.Http.HttpRequestException]::new('x', {})"
        web = "[System.Net.WebException]::new('y', [System.Net.WebExceptionStatus]::{})"
        chains = (
            ("an HTTP failure and nothing beneath it",
             "[System.Net.Http.HttpRequestException]::new('x')", "True"),
            ("5.1's protocol violation", http.format(web.format("ServerProtocolViolation")), "True"),
            ("pwsh's websocket handshake refused as not HTTP",
             "[System.Net.WebSockets.WebSocketException]::new('w', "
             "[System.Net.Http.HttpRequestException]::new('x'))", "True"),
            ("5.1's websocket handshake: a protocol violation and no HTTP failure",
             "[System.Net.WebSockets.WebSocketException]::new('w', {})".format(
                 web.format("ServerProtocolViolation")), "True"),
            ("5.1's connection closed without a response",
             http.format(web.format("ConnectionClosed")), "False"),
            ("5.1's websocket handshake on a closed connection",
             "[System.Net.WebSockets.WebSocketException]::new('w', {})".format(
                 web.format("ConnectionClosed")), "False"),
            ("5.1's unresolved name", http.format(web.format("NameResolutionFailure")), "False"),
            ("a response that ended: an I/O failure beneath",
             http.format("[System.IO.IOException]::new('y')"), "False"),
            ("the deadline", http.format("[System.TimeoutException]::new('y')"), "False"),
            ("a cancellation",
             http.format("[System.Threading.Tasks.TaskCanceledException]::new('y')"), "False"),
            ("a socket error", http.format("[System.Net.Sockets.SocketException]::new(10054)"),
             "False"),
            ("a TLS handshake that failed",
             http.format("[System.Security.Authentication.AuthenticationException]::new('y')"),
             "False"),
            ("a websocket failure with nothing HTTP in it",
             "[System.Net.WebSockets.WebSocketException]::new('w')", "False"),
            ("not an HTTP failure", "[System.InvalidOperationException]::new('x')", "False"),
        )
        snippet = "".join(
            "Write-Output \"CASE {} $(Test-LcProbeAnswered -Exception ({}))\"\n".format(index, chain)
            for index, (_name, chain, _expected) in enumerate(chains))
        result = self.run_powershell(snippet)
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertEqual(
            ["CASE {} {}".format(index, answer) for index, (_n, _c, answer) in enumerate(chains)],
            re.findall(r"(?m)^CASE \d+ \S+$", result.stdout),
            "\n".join(name for name, _chain, _answer in chains) + "\n" + output)

    def test_an_answered_port_is_something_else_and_never_normal(self):
        """ComfyUI's port answers 404, the gateway's answers with bytes that are
        not HTTP: the ComfyUI, Gateway and single-address Endpoint checks.

        The 404 is an HTTP answer with an error status, so it is the service on
        that port answering with an error, and not "something else" (T-0251's
        review note on T-0239's sites)."""
        self.write_config(gateway_host="127.0.0.1")
        comfy_port, gateway_port = self.comfy_port, self.gateway_port
        refusing_comfy = FakeComfy(port=comfy_port, system=None)
        self.addCleanup(refusing_comfy.close)
        self.start_listener("not-http", port=gateway_port)
        gateway = "http://127.0.0.1:{}".format(gateway_port)
        not_http = self.probe_error(gateway + "/api/v1/info")

        output = self.output_of(self.run_script("doctor.ps1", timeout=300))
        self.assertEqual([
            "[WARN] ComfyUI - not reachable at http://127.0.0.1:{}".format(comfy_port),
            "       HTTP 404",
            "       The service on port {} answered with an error.".format(comfy_port),
        ], self.block(output, "[WARN] ComfyUI - "), output)
        self.assertEqual([
            "[WARN] Gateway - not reachable at " + gateway,
            "       " + not_http,
            "       Something else is answering on port {}.".format(gateway_port),
        ], self.block(output, "[WARN] Gateway - "), output)
        self.assertEqual([
            "[WARN] Endpoint - {} - no gateway answered".format(gateway),
            "       The answer at {}/api/v1/info was not the gateway's: {}".format(gateway, not_http),
            "       Something else is answering on port {}.".format(gateway_port),
            "       Reachable from this machine only.",
        ], self.block(output, "[WARN] Endpoint - "), output)
        self.assertNotIn("That is normal", output)
        self.assert_no_stack_trace(output)

    def test_an_answer_at_one_of_two_addresses_is_something_else_too(self):
        """The two-address Endpoint branch: 127.0.0.2 refuses, 127.0.0.1 answers
        with bytes that are not HTTP. The Gateway and ComfyUI checks here probe
        addresses nothing listens on, so they keep "normal" -- in the same run."""
        port = free_port()
        self.write_config(gateway_host=SECOND_LOOPBACK, gateway_port=port)
        self.start_listener("not-http", port=port)
        loopback = "http://127.0.0.1:{}".format(port)
        published = "http://{}:{}".format(SECOND_LOOPBACK, port)
        not_http = self.probe_error(loopback + "/api/v1/info")
        refused = connection_refused_message()

        output = self.output_of(self.run_script("doctor.ps1", timeout=300))
        expected = [
            "[WARN] Endpoint - {} - no gateway answered".format(published),
            "       Nothing answered at {}/api/v1/info.".format(published),
            "       The answer at {}/api/v1/info was not the gateway's: {}".format(loopback, not_http),
            "       Something else is answering on port {}.".format(port),
            "       Reachable from this machine only.",
        ]
        block = self.block(output, "[WARN] Endpoint - ")
        self.assertEqual(expected, block[:len(expected)], output)
        self.assertNotIn("That is normal when LocalCanvas is not running. Start it", "\n".join(block))
        self.assertEqual([
            "[WARN] Gateway - not reachable at " + published,
            "       " + refused,
            "       That is normal when LocalCanvas is not running. Start it with scripts\\start.ps1.",
        ], self.block(output, "[WARN] Gateway - "), output)
        self.assertEqual([
            "[WARN] ComfyUI - not reachable at http://127.0.0.1:{}".format(self.comfy_port),
            "       " + refused,
            "       That is normal when LocalCanvas is not running.",
        ], self.block(output, "[WARN] ComfyUI - "), output)
        self.assert_no_stack_trace(output)

    def test_an_http_error_is_the_service_answering_with_an_error(self):
        """An HTTP 500 is the service answering and saying it failed: never
        "normal", and never "something else" either. ComfyUI's and the
        gateway's ports both answer 500; then the two-address Endpoint branch,
        where the published address refuses and loopback answers 500."""
        self.write_config(gateway_host="127.0.0.1")
        comfy_port, gateway_port = self.comfy_port, self.gateway_port
        self.start_listener("http-500", port=comfy_port)
        self.start_listener("http-500", port=gateway_port)
        gateway = "http://127.0.0.1:{}".format(gateway_port)

        output = self.output_of(self.run_script("doctor.ps1", timeout=300))
        self.assertEqual([
            "[WARN] ComfyUI - not reachable at http://127.0.0.1:{}".format(comfy_port),
            "       HTTP 500",
            "       The service on port {} answered with an error.".format(comfy_port),
        ], self.block(output, "[WARN] ComfyUI - "), output)
        self.assertEqual([
            "[WARN] Gateway - not reachable at " + gateway,
            "       HTTP 500",
            "       The service on port {} answered with an error.".format(gateway_port),
        ], self.block(output, "[WARN] Gateway - "), output)
        self.assertEqual([
            "[WARN] Endpoint - {} - answered with an error".format(gateway),
            "       The answer at {}/api/v1/info was HTTP 500.".format(gateway),
            "       The service on port {} answered with an error.".format(gateway_port),
            "       Reachable from this machine only.",
        ], self.block(output, "[WARN] Endpoint - "), output)
        self.assertNotIn("Something else", output)
        self.assertNotIn("That is normal", output)
        self.assert_no_stack_trace(output)

        port = free_port()
        self.write_config(gateway_host=SECOND_LOOPBACK, gateway_port=port)
        self.start_listener("http-500", port=port)
        loopback = "http://127.0.0.1:{}".format(port)
        published = "http://{}:{}".format(SECOND_LOOPBACK, port)
        output = self.output_of(self.run_script("doctor.ps1", timeout=300))
        expected = [
            "[WARN] Endpoint - {} - answered with an error".format(published),
            "       Nothing answered at {}/api/v1/info.".format(published),
            "       The answer at {}/api/v1/info was HTTP 500.".format(loopback),
            "       The service on port {} answered with an error.".format(port),
            "       Reachable from this machine only.",
        ]
        block = self.block(output, "[WARN] Endpoint - ")
        self.assertEqual(expected, block[:len(expected)], output)
        self.assertNotIn("Something else", "\n".join(block))
        self.assert_no_stack_trace(output)

    def test_a_closed_port_is_still_normal(self):
        """The control: nothing listens anywhere, and every one of the three
        checks keeps the sentence, verbatim."""
        self.write_config(gateway_host="127.0.0.1")
        gateway = "http://127.0.0.1:{}".format(self.gateway_port)
        refused = connection_refused_message()
        output = self.output_of(self.run_script("doctor.ps1", timeout=300))
        self.assertEqual([
            "[WARN] ComfyUI - not reachable at http://127.0.0.1:{}".format(self.comfy_port),
            "       " + refused,
            "       That is normal when LocalCanvas is not running.",
        ], self.block(output, "[WARN] ComfyUI - "), output)
        self.assertEqual([
            "[WARN] Gateway - not reachable at " + gateway,
            "       " + refused,
            "       That is normal when LocalCanvas is not running. Start it with scripts\\start.ps1.",
        ], self.block(output, "[WARN] Gateway - "), output)
        self.assertEqual([
            "[WARN] Endpoint - {} - nothing answered".format(gateway),
            "       Nothing answered at {}/api/v1/info.".format(gateway),
            "       That is normal when LocalCanvas is not running. Start it with scripts\\start.ps1.",
            "       Reachable from this machine only.",
        ], self.block(output, "[WARN] Endpoint - "), output)
        self.assertNotIn("Something else is answering", output)
        self.assert_no_stack_trace(output)

    def test_a_hang_up_is_nothing_answering_and_5_1_never_gets_that_far(self):
        """T-0266: a port that takes the request and closes without a byte.

        Nothing answered there, so each check keeps its sentence for nothing
        answering -- never "something else". Two runs, so the three kinds of
        answer sit side by side in the same doctor: first ComfyUI's port hangs
        up while the gateway's answers with a line that is not HTTP, then
        ComfyUI's answers HTTP 500 while the gateway's hangs up.

        RE-AIMED BY T-0294. Both runs used to be made under 5.1 as well, and
        the localized runtime line was the awkward part of that. What 5.1 was
        really covering is the DECISION -- Invoke-LcProbe's Answered and
        Test-LcProbeAnswered, in scripts/lib/Common.ps1 -- and that is measured
        under both shells directly, over the same listeners, by
        test_the_decision_over_real_answers_in_both_shells above. Here the
        doctor's rendering is asserted under pwsh, and 5.1 gets the one thing
        that is true of an entry script there: the refusal.
        """
        self.write_config(gateway_host="127.0.0.1")
        comfy_port, gateway_port = self.comfy_port, self.gateway_port
        gateway = "http://127.0.0.1:{}".format(gateway_port)
        start_it = "       That is normal when LocalCanvas is not running. Start it with scripts\\start.ps1."
        copied = self.copy_scripts_with_stopping_disabled()
        doctor = copied / "doctor.ps1"
        source = doctor.read_text(encoding="utf-8-sig")
        self.assertEqual(1, source.count(DOCTOR_MAIN), source)
        doctor.write_text(source.replace(
            DOCTOR_MAIN, "\nWrite-Host \"HOST $($PSVersionTable.PSVersion)\"\n" + DOCTOR_MAIN[1:]),
            encoding="utf-8")
        shells = (("pwsh", PWSH),)

        def runtime_line(block, index, output):
            self.assertTrue(block[index].startswith("       ") and block[index].strip(), output)

        # Run 1: ComfyUI's port hangs up; the gateway's is not HTTP.
        self.start_listener("close", port=comfy_port)
        self.start_listener("not-http", port=gateway_port)
        for name, shell in shells:
            with self.subTest(shell=name, run="comfy hangs up"):
                result = self.run_script("doctor.ps1", script_dir=copied, timeout=300, shell=shell)
                output = self.output_of(result)
                self.assert_host(name, output)
                comfy = self.block(output, "[WARN] ComfyUI - ")
                self.assertEqual(3, len(comfy), output)
                self.assertEqual(
                    "[WARN] ComfyUI - not reachable at http://127.0.0.1:{}".format(comfy_port),
                    comfy[0], output)
                runtime_line(comfy, 1, output)
                self.assertEqual("       That is normal when LocalCanvas is not running.",
                                 comfy[2], output)
                block = self.block(output, "[WARN] Gateway - ")
                self.assertEqual(3, len(block), output)
                self.assertEqual("[WARN] Gateway - not reachable at " + gateway, block[0], output)
                self.assertEqual(
                    "       Something else is answering on port {}.".format(gateway_port),
                    block[2], output)
                endpoint = self.block(output, "[WARN] Endpoint - ")
                self.assertEqual(4, len(endpoint), output)
                self.assertEqual("[WARN] Endpoint - {} - no gateway answered".format(gateway),
                                 endpoint[0], output)
                self.assertTrue(endpoint[1].startswith(
                    "       The answer at {}/api/v1/info was not the gateway's: ".format(gateway)),
                    output)
                self.assertEqual(
                    ["       Something else is answering on port {}.".format(gateway_port),
                     "       Reachable from this machine only."], endpoint[2:], output)
                self.assert_exit_code_is_the_verdict(result, output)

        # Run 2, on two fresh ports: ComfyUI's answers HTTP 500; the gateway's
        # hangs up.
        self.comfy_port = free_port()
        self.write_config(gateway_host="127.0.0.1", gateway_port=free_port())
        comfy_port, gateway_port = self.comfy_port, self.gateway_port
        gateway = "http://127.0.0.1:{}".format(gateway_port)
        self.start_listener("http-500", port=comfy_port)
        self.start_listener("close", port=gateway_port)
        for name, shell in shells:
            with self.subTest(shell=name, run="gateway hangs up"):
                result = self.run_script("doctor.ps1", script_dir=copied, timeout=300, shell=shell)
                output = self.output_of(result)
                self.assert_host(name, output)
                self.assertEqual([
                    "[WARN] ComfyUI - not reachable at http://127.0.0.1:{}".format(comfy_port),
                    "       HTTP 500",
                    "       The service on port {} answered with an error.".format(comfy_port),
                ], self.block(output, "[WARN] ComfyUI - "), output)
                block = self.block(output, "[WARN] Gateway - ")
                self.assertEqual(3, len(block), output)
                self.assertEqual("[WARN] Gateway - not reachable at " + gateway, block[0], output)
                runtime_line(block, 1, output)
                self.assertEqual(start_it, block[2], output)
                self.assertEqual([
                    "[WARN] Endpoint - {} - nothing answered".format(gateway),
                    "       Nothing answered at {}/api/v1/info.".format(gateway),
                    start_it,
                    "       Reachable from this machine only.",
                ], self.block(output, "[WARN] Endpoint - "), output)
                self.assertNotIn("Something else", output)
                self.assert_exit_code_is_the_verdict(result, output)

        # The same copy, the same listeners, under Windows PowerShell 5.1: no
        # block at all, because no check was made.
        refused = self.output_of(refuse_under_windows_powershell(
            self, copied / "doctor.ps1", ["-Config", str(self.config_path)],
            cwd=copied, env=self.script_env(),
            what="scripts/doctor.ps1 against a hang-up, under 5.1"))
        for absent in ("[WARN] ComfyUI - ", "[WARN] Gateway - ", "[WARN] Endpoint - ",
                       "Something else", "HOST "):
            self.assertNotIn(absent, refused)

    def assert_host(self, name, output):
        if name == "5.1":
            self.assertRegex(output, r"(?m)^HOST 5\.", output)
        else:
            self.assertRegex(output, r"(?m)^HOST [67]\.", output)

    def assert_exit_code_is_the_verdict(self, result, output):
        """The exit code is the one the printed body earns, with none of the
        three probe checks a [FAIL]: they warn, whatever answered."""
        body, summary = doctor_body_and_summary(output)
        counted, expected_summary = doctor_summary_for(body)
        self.assertEqual(counted, result.returncode, output)
        self.assertEqual(expected_summary, summary, output)
        for check in ("ComfyUI", "Gateway", "Endpoint"):
            self.assertNotIn("[FAIL] {} - ".format(check), output)
        self.assert_no_stack_trace(output)


# ==========================================================================
# sync-workflows.ps1 -- the thin front end over the curator engine
# ==========================================================================


SYNC_SCRIPT = "sync-workflows.ps1"
# A console of the child's own. A pwsh that inherits this one and assigns
# [Console]::OutputEncoding calls SetConsoleOutputCP on it, and the change
# outlives the child: measured here, cp866 became us-ascii for every later
# process in the run. The tests that need a chosen encoding therefore give the
# child its own console, and check afterwards that this one is untouched.
OWN_CONSOLE = getattr(subprocess, "CREATE_NO_WINDOW", 0)
# Mirrors gateway/localcanvas_gateway/workflows/sync/engine.py::DRY_RUN_NOTICE,
# and scripts/tests/stubenv/localcanvas_gateway/workflows/__main__.py. Written
# as an escape so this file stays ASCII: the character itself is what has to
# come out of the script, and comparing against an escape is how a test proves
# it survived the trip rather than proving two files were saved the same way.
DRY_RUN_NOTICE = "Dry run \u2014 no files changed."
# The same sentence for a console whose code page has no em dash -- cp437,
# cp866 and cp1251 all lack one, and this repository's rule (pairing.py) is
# that the text adapts to the stream and the stream is never adapted to the
# text. Which of the two a run prints is not a matter of taste, so the test
# below asks this machine which one it has to be.
DRY_RUN_NOTICE_ASCII = "Dry run - no files changed."
# Mirrors scripts/tests/stubenv/.../workflows/__main__.py, which in turn
# mirrors the real engine's own sentences. Asserted whole rather than by a
# keyword: what these tests are about is that the engine's words reach the
# terminal unedited, and half a sentence would pass for a script that
# summarised them.
LOCKED_REASON = ("input 'ckpt_name' names a file of weights to load; which "
                 "file loads is what the workflow *is*, not how it generates.")
TECHNICAL_REASON = ("input 'mask' on node 12 is a matte the graph uses "
                    "internally, not a picture a user chooses.")
# The engine's sentence about a definition a dry run did not write.
DRY_RUN_DEFINITION_NOTICE = "a dry run writes nothing, so this was not written."
# Mirrors the stub's REWRITTEN_NOTICE, which mirrors ...sync/engine.py (T-0253).
STUB_REWRITTEN_NOTICE = (
    "this workflow file has not changed, but this importer now reads it "
    "differently, so its definition was written again. Kept from the file: "
    "its name, its translation setting, and every presentation key, field "
    "label and help line you wrote. Everything else was generated again from "
    "the workflow -- the list of fields and each field's type, section, "
    "default, choices, limits and bindings -- so an edit you made to any of "
    "those was replaced."
)
# The script's two closing sentences for an engine exit 2 (T-0225): the first
# for every cause found before anything is written, the second for an
# inventory that could not be written after the run wrote its files -- which
# the engine marks with the line in STUB_INVENTORY_NOT_WRITTEN_MARKER.
SYNC_NOTHING_WRITTEN = "No file was written."
SYNC_INVENTORY_NOT_WRITTEN = (
    "The inventory was not written, but definitions, imported workflow graphs "
    "and conversion snapshots this run wrote may already be on disk. The next "
    "successful sync will record them.")
# Mirrors the stub, which mirrors ...sync/engine.py::INVENTORY_NOT_WRITTEN_MARKER.
STUB_INVENTORY_NOT_WRITTEN_MARKER = "[INVENTORY_NOT_WRITTEN]"
# The engine's sentence about what a dry run did with what it converted.
DRY_RUN_CONVERSION_NOTICE = (
    "a dry run converts in order to see what would import, and keeps none of "
    "it: nothing was remembered and nothing was written.")


def console_can_write_em_dash():
    """Can a redirected pwsh on THIS machine put an em dash on its stdout?

    Asked of a real PowerShell, the same way the script asks. The encoding a
    native host writes with is the machine's, and a hard-coded answer here
    would make the assertion below pass on the machine it was written on and
    nowhere else.
    """
    script = ("$e = [Console]::OutputEncoding; "
              "if ($e.GetString($e.GetBytes([string][char]0x2014)) -eq "
              "[string][char]0x2014) { 'yes' } else { 'no' }")
    result = subprocess.run(
        [PWSH, "-NoProfile", "-NonInteractive", "-Command", script],
        capture_output=True, text=True, encoding="utf-8", errors="replace",
        timeout=120,
    )
    return (result.stdout or "").strip() == "yes"



class WorkflowSyncTests(ScriptTestCase):
    """The script renders what the engine said, and decides nothing itself.

    Everything that reads a workflow is in the gateway, where pytest holds it.
    What is testable only from out here is the seam: which arguments the script
    passes, which exit code it turns each answer into, and that the engine's own
    words reach the terminal without being reworded or replaced by a PowerShell
    stack trace.
    """

    def setUp(self):
        super().setUp()
        # A runtime configuration as well, so the inherited teardown's stop.ps1
        # has one to read. The sync reads its own file, which is a different one
        # on purpose: runtime.yaml is what the gateway needs to serve, and this
        # is what a one-off command needs to read a folder.
        self.write_config()
        self.sync_config = self.workspace / "workflow sources.yaml"
        self.sync_config.write_text("sources: []\n", encoding="utf-8")
        # The runtime configuration the script hands the engine, for the one
        # thing the engine needs out of it: the ComfyUI address an editor-format
        # workflow is converted through. write_config() above wrote it. The
        # script never reads it -- there is one definition of what runtime.yaml
        # means and it is on the Python side of the seam (docs/runtime.md).
        self.runtime_config = self.config_path
        self.sync_marker = self.workspace / "sync arguments.log"

    def run_sync(self, *extra_args, mode=None, config=None, **kwargs):
        env = self.script_env(
            LC_STUB_SYNC_MARKER=str(self.sync_marker),
            LC_STUB_SYNC_MODE=mode,
        )
        return self.run_script(
            SYNC_SCRIPT,
            "-RuntimeConfig", str(self.runtime_config),
            *extra_args,
            config=config if config is not None else self.sync_config,
            env=env,
            **kwargs,
        )

    def engine_arguments(self):
        """Every argv the engine was invoked with, as lists."""
        if not self.sync_marker.exists():
            return []
        return [
            json.loads(line)
            for line in self.sync_marker.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]

    # -- the dry run -------------------------------------------------------

    def test_dry_run_prints_the_notice_and_asks_the_engine_for_a_dry_run(self):
        result = self.run_sync("-DryRun")
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        # Which form is neither the script's choice nor this test's: it is
        # whichever one this machine's console encoding can actually carry.
        expected = (DRY_RUN_NOTICE if console_can_write_em_dash()
                    else DRY_RUN_NOTICE_ASCII)
        self.assertIn(expected, result.stdout.splitlines(), output)
        self.assertEqual(
            [["--config", str(self.sync_config),
              "--runtime-config", str(self.runtime_config), "--dry-run"]],
            self.engine_arguments())
        self.assert_no_stack_trace(output)

    def run_sync_under_output_encoding(self, expression, *extra_args, mode=None):
        """Run the script in a host whose output encoding is chosen by the test.

        The point of the two forms of the notice is a decision, and a decision
        can only be tested where the two branches differ. On this machine's own
        code page they do not: cp866 has no em dash but best-fits one to a
        hyphen, so a script that never asked the stream would print exactly what
        a script that asked would. Under us-ascii the same character becomes a
        question mark, and the difference is visible.

        The child gets a console of ITS OWN (OWN_CONSOLE), and that is not a
        detail. Measured on this machine: a pwsh that inherits this console and
        sets [Console]::OutputEncoding calls SetConsoleOutputCP on it, and every
        later child of this suite then sees us-ascii instead of cp866 -- the
        suite would have changed the terminal the user is sitting in front
        of. With its own console the same assignment reproduces the same
        behaviour inside the child and leaves this one at whatever it was; the
        tripwire below is checked around every call, so a future edit that drops
        the flag fails here rather than surprising somebody later.
        """
        before = self.console_output_encoding()
        inner = "; ".join([
            "[Console]::OutputEncoding = " + expression,
            "& {} -Config {} -PythonExe {}{}".format(
                powershell_literal(str(SCRIPTS / SYNC_SCRIPT)),
                powershell_literal(str(self.sync_config)),
                powershell_literal(sys.executable),
                (" " + " ".join(extra_args)) if extra_args else ""),
            "exit $LASTEXITCODE",
        ])
        result = subprocess.run(
            [PWSH, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
             "-Command", inner],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=180, cwd=str(REPO), creationflags=OWN_CONSOLE,
            env=self.script_env(
                LC_STUB_SYNC_MARKER=str(self.sync_marker),
                LC_STUB_SYNC_MODE=mode,
            ),
        )
        self.assertEqual(
            before, self.console_output_encoding(),
            "THIS TEST CHANGED THIS TERMINAL'S OUTPUT CODE PAGE. Every later "
            "child of this suite, and the shell it was started from, now "
            "encodes with something nobody chose.")
        return result

    @staticmethod
    def console_output_encoding():
        """What a plain child of this console encodes its output with.

        Asked of a child that inherits this console, because that is exactly
        what leaks: the code page is the console's, not the process's, and
        reading it from inside this Python would not see the change at all.
        """
        result = subprocess.run(
            [PWSH, "-NoProfile", "-NonInteractive", "-Command",
             "[Console]::OutputEncoding.WebName"],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120,
        )
        return (result.stdout or "").strip()

    def test_a_terminal_that_cannot_draw_an_em_dash_gets_the_sentence_anyway(self):
        """us-ascii turns an em dash into a question mark; asking is what avoids it.

        This is the test the guard can fail: a script that printed
        $report.notice regardless would put "Dry run ? no files changed." in
        front of the user here.
        """
        result = self.run_sync_under_output_encoding(
            "[System.Text.ASCIIEncoding]::new()", "-DryRun")
        printed = [line for line in result.stdout.splitlines()
                   if line.startswith("Dry run")]

        self.assertEqual(0, result.returncode, self.output_of(result))
        self.assertEqual([DRY_RUN_NOTICE_ASCII], printed, self.output_of(result))
        self.assertNotIn("?", printed[0])

    def test_a_terminal_that_can_draw_one_gets_the_sentence_the_contract_names(self):
        """The other branch, so the choice is a choice and not a constant."""
        result = self.run_sync_under_output_encoding(
            "[System.Text.UTF8Encoding]::new($false)", "-DryRun")
        printed = [line for line in result.stdout.splitlines()
                   if line.startswith("Dry run")]

        self.assertEqual(0, result.returncode, self.output_of(result))
        self.assertEqual([DRY_RUN_NOTICE], printed, self.output_of(result))

    def test_running_under_a_chosen_encoding_does_not_change_this_console(self):
        """The interlock on the two tests above, stated as a test of its own.

        Neither the script nor this suite may leave the terminal encoding with
        something nobody chose. The script never sets one at all -- the lint
        below holds that -- and the two tests above set one only inside a
        console of their own.
        """
        before = self.console_output_encoding()
        self.assertTrue(before, "this console's output encoding could not be read")
        self.run_sync_under_output_encoding("[System.Text.ASCIIEncoding]::new()",
                                            "-DryRun")
        after = self.console_output_encoding()
        self.assertEqual(before, after)
        # And the reading is not passing because it always says the same thing:
        # inside its own console the child really did change its own.
        self.assertNotEqual("us-ascii", after)

    def test_no_script_ever_changes_the_terminals_encoding(self):
        offenders = []
        for path in powershell_sources():
            for number, code, _literals, raw in powershell_code_lines(
                    path.read_text(encoding="utf-8-sig")):
                if re.search(r"\[Console\]::(Output|Input)Encoding\s*=", code):
                    offenders.append("{}:{}: {}".format(path.name, number, raw.strip()))
                if re.search(r"(?<![\w-])chcp(?![\w-])", code):
                    offenders.append("{}:{}: {}".format(path.name, number, raw.strip()))
        self.assertEqual([], offenders)
        # And the lint is not passing because nothing reads the encoding either.
        self.assertIn(
            "[Console]::OutputEncoding",
            (SCRIPTS / SYNC_SCRIPT).read_text(encoding="utf-8-sig"),
            "the sync script no longer asks the stream what it can carry")

    def test_the_notice_is_never_written_as_a_question_mark_or_as_mojibake(self):
        """The failure the two forms exist to prevent, asserted directly.

        A script that pushed the em dash through regardless would put either a
        replacement character or two bytes of a cp866 word in front of the
        user. Both are visible from here, and neither is allowed.
        """
        result = self.run_sync("-DryRun")
        printed = [line for line in result.stdout.splitlines()
                   if line.startswith("Dry run")]

        self.assertEqual(1, len(printed), self.output_of(result))
        self.assertIn(printed[0], (DRY_RUN_NOTICE, DRY_RUN_NOTICE_ASCII))
        self.assertNotIn("\ufffd", printed[0])
        self.assertNotIn("?", printed[0])

    def test_without_the_switch_nothing_asks_for_a_dry_run_and_nothing_says_so(self):
        """The other half of the test above, and it is not vacuous.

        That test shows the sentence does get printed, so this one showing it
        absent is a statement about the switch rather than about a script that
        never prints it at all.
        """
        result = self.run_sync()
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertNotIn(DRY_RUN_NOTICE, output)
        self.assertNotIn("Dry run", output)
        self.assertEqual(
            [["--config", str(self.sync_config),
              "--runtime-config", str(self.runtime_config)]],
            self.engine_arguments())

    def test_the_config_path_reaches_the_engine_with_its_spaces_intact(self):
        self.assertIn(" ", str(self.sync_config))
        self.run_sync("-DryRun")

        argv = self.engine_arguments()[0]
        self.assertEqual(str(self.sync_config), argv[argv.index("--config") + 1])

    # -- what each answer becomes ------------------------------------------

    def test_a_workflow_that_needs_attention_is_reported_in_the_engines_words(self):
        result = self.run_sync(mode="attention")
        output = self.output_of(result)

        self.assertEqual(3, result.returncode, output)
        self.assertIn("NEEDS_API_EXPORT", output)
        self.assertIn("scripts\start.ps1", output)
        self.assertIn("sample workflow.json", output)
        self.assert_no_stack_trace(output)

    def test_a_clean_run_exits_zero_and_says_where_the_inventory_is(self):
        result = self.run_sync()
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("[ OK ]", output)
        self.assertIn("inventory.json", output)
        self.assert_no_stack_trace(output)

    def test_a_fatal_configuration_problem_exits_two_in_the_engines_words(self):
        result = self.run_sync(mode="fatal")
        output = self.output_of(result)

        self.assertEqual(2, result.returncode, output)
        self.assertIn("no workflow sources configuration here", output)
        self.assertIn("workflow-sources.example.yaml", output)
        self.assertIn("No file was written.", output)
        self.assert_no_stack_trace(output)

    def test_a_missing_source_list_names_setup_and_no_yaml_to_edit(self):
        """F4 (T-0352): no source list yet is answered with one command.

        Before the card this reached the engine, whose sentence says to copy
        config/examples/workflow-sources.example.yaml and edit the path in it
        -- measured on a clean clone. The script now answers ABSENCE itself,
        with the exit code the engine would have used, before the engine runs.
        """
        for explicit in (False, True):
            with self.subTest(explicit_config=explicit):
                absent = self.workspace / "no source list here {}.yaml".format(explicit)
                if explicit:
                    result = self.run_sync(config=absent)
                else:
                    # The default location, resolved by the script itself from
                    # the checkout: asked of a copy so nothing is read from, or
                    # written to, the repository's own config\local.
                    result = self.run_copied_sync_without_config()
                output = self.output_of(result)
                self.assertEqual(2, result.returncode, output)
                self.assertIn(
                    "pwsh .\\scripts\\setup.ps1 -WorkflowSource '<your workflow folder>'", output)
                self.assertNotIn("workflow-sources.example.yaml", output)
                self.assertNotIn("Copy", output)
                self.assertIn("No file was written.", output)
                self.assertEqual([], self.engine_arguments(), "the engine ran anyway")
                self.assertEqual(explicit, "without -Config" in output, output)
                self.assert_no_stack_trace(output)

    def run_copied_sync_without_config(self):
        """sync-workflows.ps1 with no -Config, from a copy of the scripts.

        The script's default is <its checkout>\\config\\local\\workflow-sources.yaml;
        in the repository that is the checkout's own file. The copy's
        checkout has no config\\local at all, so the default is absent by
        construction -- and the engine, were it reached, is the test double.
        """
        copied = self.workspace / "a checkout with no source list"
        self.assertFalse(path_is_inside(copied, REPO), copied)
        (copied / "scripts" / "lib").mkdir(parents=True)
        shutil.copyfile(SCRIPTS / SYNC_SCRIPT, copied / "scripts" / SYNC_SCRIPT)
        shutil.copyfile(SCRIPTS / "lib" / "Common.ps1", copied / "scripts" / "lib" / "Common.ps1")
        self.assertFalse((copied / "config" / "local" / "workflow-sources.yaml").exists())
        env = self.script_env(LC_STUB_SYNC_MARKER=str(self.sync_marker))
        return subprocess.run(
            [PWSH, "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass",
             "-File", str(copied / "scripts" / SYNC_SCRIPT),
             "-PythonExe", sys.executable,
             "-RuntimeConfig", str(self.runtime_config)],
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=180, env=env, cwd=str(REPO))

    def test_a_fatal_problem_is_a_different_exit_code_from_one_bad_workflow(self):
        fatal = self.run_sync(mode="fatal")
        attention = self.run_sync(mode="attention")

        self.assertEqual(2, fatal.returncode, self.output_of(fatal))
        self.assertEqual(3, attention.returncode, self.output_of(attention))

    def test_each_kind_of_fatal_problem_closes_with_the_sentence_true_for_it(self):
        """T-0225: "nothing was written" only where nothing was.

        An inventory the engine could not write is an exit 2 like a missing
        configuration, but it comes after the definitions, imported graphs and
        conversion snapshots were written. The engine marks that block with a
        line of its own, and the script's closing sentence follows it.
        """
        # The fixture first: only the inventory block carries the marker line.
        # A configuration failure about the inventory SETTING names the
        # inventory without it, and a missing source folder whose path holds
        # the token carries it inside a longer line, never as a line of its own.
        blocks = {}
        for mode in ("fatal", "inventory-setting", "token-in-path", "inventory"):
            engine = subprocess.run(
                [sys.executable, "-m", "localcanvas_gateway.workflows",
                 "sync", "--config", str(self.sync_config)],
                capture_output=True, text=True, encoding="utf-8",
                errors="replace", timeout=120, cwd=str(REPO),
                env=self.script_env(LC_STUB_SYNC_MODE=mode))
            self.assertEqual(2, engine.returncode, self.output_of(engine))
            blocks[mode] = [line.strip() for line in engine.stderr.splitlines()]
        self.assertNotIn(STUB_INVENTORY_NOT_WRITTEN_MARKER, blocks["fatal"])
        self.assertNotIn(STUB_INVENTORY_NOT_WRITTEN_MARKER,
                         blocks["inventory-setting"])
        self.assertIn("inventory", " ".join(blocks["inventory-setting"]))
        self.assertNotIn(STUB_INVENTORY_NOT_WRITTEN_MARKER,
                         blocks["token-in-path"])
        self.assertIn(STUB_INVENTORY_NOT_WRITTEN_MARKER,
                      " ".join(blocks["token-in-path"]),
                      "the fixture's path holds no token; this tests nothing")
        self.assertIn(STUB_INVENTORY_NOT_WRITTEN_MARKER, blocks["inventory"],
                      "the fixture carries no marker; this tests nothing")

        cases = (
            ("fatal", SYNC_NOTHING_WRITTEN, SYNC_INVENTORY_NOT_WRITTEN),
            ("inventory-setting", SYNC_NOTHING_WRITTEN,
             SYNC_INVENTORY_NOT_WRITTEN),
            ("token-in-path", SYNC_NOTHING_WRITTEN,
             SYNC_INVENTORY_NOT_WRITTEN),
            ("inventory", SYNC_INVENTORY_NOT_WRITTEN, SYNC_NOTHING_WRITTEN),
        )
        for mode, said, not_said in cases:
            with self.subTest(mode=mode):
                result = self.run_sync(mode=mode)
                output = self.output_of(result)
                self.assertEqual(2, result.returncode, output)
                lines = [line.strip() for line in output.splitlines()]
                self.assertIn(said, lines, output)
                self.assertNotIn(not_said, lines, output)
                self.assertNotIn(" ".join(not_said.split()),
                                 " ".join(output.split()), output)
                self.assert_no_stack_trace(output)
        # And the engine's own words still reach the terminal as it wrote them.
        self.assertIn(STUB_INVENTORY_NOT_WRITTEN_MARKER, lines, output)
        self.assertIn("was left as it was", output)

    # -- what the run decided ----------------------------------------------

    def stub_document(self, mode=None, no_convert=False):
        """The document the stub prints, read the way the script reads it.

        Run directly rather than through the script, because these assertions
        are about the FIXTURE: a test that shows the script survives a document
        without the new keys says nothing unless that document really lacks
        them, and a test that shows it prints no conversion block says nothing
        unless the document's counts really are all zero.
        """
        arguments = [
            sys.executable, "-m", "localcanvas_gateway.workflows",
            "sync", "--config", str(self.sync_config),
        ]
        if no_convert:
            arguments.append("--no-convert")
        result = subprocess.run(
            arguments,
            capture_output=True, text=True, encoding="utf-8", errors="replace",
            timeout=120, cwd=str(REPO),
            env=self.script_env(LC_STUB_SYNC_MODE=mode),
        )
        return json.loads(result.stdout)

    def test_the_run_says_where_the_definitions_went(self):
        """The half of the card as filed: the files the run generated.

        A user who runs this reads the inventory line and then nothing at all
        about the definitions -- which is what the run was for.
        """
        result = self.run_sync()
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("Definitions: " + os.path.join("C:\\", "definitions"), output)
        self.assertIn("1 written, 0 not written", output)
        self.assert_no_stack_trace(output)

    def test_each_workflow_says_where_its_own_definition_went(self):
        result = self.run_sync()
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("Definition: " +
                      os.path.join("C:\\", "definitions", "portrait.yaml"), output)
        self.assert_no_stack_trace(output)

    def test_a_dry_run_says_where_the_definitions_would_have_gone(self):
        """The other branch of the same two lines, so neither is a constant."""
        result = self.run_sync("-DryRun")
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("0 written, 0 not written", output)
        self.assertIn(os.path.join("C:\\", "definitions", "portrait.yaml") +
                      " (not written)", output)
        # The engine's own sentence about why, not one composed out here.
        self.assertIn(DRY_RUN_DEFINITION_NOTICE, output)

    def test_a_definition_written_again_says_why_in_the_engines_words(self):
        """T-0253: the sentence T-0246 added is printed like skipped/problem.

        A curator whose edited default was just replaced by a rewrite is told
        so here, under the definition's own line -- and a document without the
        key, from an engine older than that, prints nothing in its place.
        """
        rewritten = self.stub_document(mode="rewritten")
        plain = self.stub_document()
        said = [w["definition"].get("rewritten") for w in rewritten["workflows"]]
        self.assertIn(STUB_REWRITTEN_NOTICE, said,
                      "the fixture carries no rewritten sentence; this tests nothing")
        for workflow in plain["workflows"]:
            if workflow.get("definition") is not None:
                self.assertNotIn("rewritten", workflow["definition"])

        result = self.run_sync(mode="rewritten")
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        flat = " ".join(output.split())
        self.assertIn(" ".join(STUB_REWRITTEN_NOTICE.split()), flat)
        self.assert_no_stack_trace(output)

        result = self.run_sync()
        output = self.output_of(result)
        self.assertEqual(0, result.returncode, output)
        self.assertNotIn("written again", output)
        self.assertNotIn("PropertyNotFoundStrict", output)
        self.assert_no_stack_trace(output)

    def test_a_control_that_was_locked_is_named_with_its_reason(self):
        """The half raised in T-0054's review: 'not exposed' made visible.

        Node, input and the whole sentence the judgement composed -- that is
        what lets a reader tell a control that was recognised and
        deliberately locked from one the importer never saw.
        """
        result = self.run_sync()
        output = self.output_of(result)

        self.assertEqual(0, result.returncode, output)
        self.assertIn("Not exposed: node 4 input 'ckpt_name' [weights_file]", output)
        self.assertIn(LOCKED_REASON, output)
        self.assertIn("Not exposed: node 12 input 'mask' [technical_media]", output)
        self.assertIn(TECHNICAL_REASON, output)
        self.assert_no_stack_trace(output)

    def test_a_control_the_user_will_see_is_not_printed_as_not_exposed(self):
        """The negative control for the test above.

        The stub's document carries an exposed control as well, so a script
        that printed the whole inventory under that heading would pass the
        test above and be wrong. Its node and input are the ones checked.
        """
        document = self.stub_document()
        exposed = [control for control in document["workflows"][0]["controls"]
                   if control["section"] == "main"]
        self.assertEqual([("6", "text")],
                         [(c["node"], c["input"]) for c in exposed],
                         "the stub no longer carries an exposed control")

        output = self.output_of(self.run_sync())
        not_exposed = [line for line in output.splitlines() if "Not exposed:" in line]
        self.assertTrue(not_exposed, output)
        for line in not_exposed:
            self.assertNotIn("node 6 input 'text'", line)

    def test_the_locked_inventory_is_printed_without_being_asked_for(self):
        """No switch guards it: whoever reviews an import has to read it.

        Both halves: the script takes no parameter that could hide it, and a
        plain run with no arguments at all really does print it.
        """
        text = (SCRIPTS / SYNC_SCRIPT).read_text(encoding="utf-8-sig")
        self.assertIn("Not exposed:", text,
                      "the script no longer prints the locked inventory; "
                      "this test scans nothing")
        parameters = re.findall(r"^\s*\[(?:string|switch)\]\$(\w+)", text, re.MULTILINE)
        # RegenerateLabels (T-0116) changes what a run writes into labels and
        # help, and hides nothing the report prints.
        self.assertEqual(
            ["Config", "RuntimeConfig", "PythonExe", "NoConvert", "DryRun",
             "RegenerateLabels"],
            parameters)

        output = self.output_of(self.run_sync())
        self.assertIn("Not exposed: node 4 input 'ckpt_name' [weights_file]", output)

    # -- what ComfyUI converted --------------------------------------------

    def test_the_conversion_summary_is_the_engines_numbers_and_not_the_scripts(self):
        """The counts and the ComfyUI identity are rendered, not recomputed.

        Nothing here adds up a total of its own: the script prints four numbers
        the engine put in the document. A script that counted the workflows
        itself would disagree with the engine the first time a state was added.
        """
        result = self.run_sync(mode="attention")
        output = self.output_of(result)

        self.assertEqual(3, result.returncode, output)
        self.assertIn("Converted by ComfyUI", output)
        self.assertIn(
            "1 converted, 0 reused from an earlier run, 0 refused, "
            "1 not attempted", output)
        self.assertIn("ComfyUI 0.0.0-stub, frontend 0.0.0-stub, 3 node types",
                      output)
        self.assert_no_stack_trace(output)

    def test_a_dry_run_says_it_kept_none_of_what_it_converted(self):
        """Both halves, so the sentence is a decision and not a constant.

        "1 converted" printed under a dry run reads, to anybody, as a snapshot
        written -- which is the one thing a dry run promises it did not do. So
        the engine writes the sentence that says otherwise, this prints it
        verbatim, and a run that is not a dry run must not print it.
        """
        dry = self.output_of(self.run_sync("-DryRun"))
        self.assertIn(DRY_RUN_CONVERSION_NOTICE, dry)

        wet = self.output_of(self.run_sync())
        self.assertNotIn(DRY_RUN_CONVERSION_NOTICE, wet)
        self.assertIn("Converted by ComfyUI", wet)

    def test_a_conversion_failure_shows_its_category_and_the_engines_sentence(self):
        """The deterministic token, and the words that say what to do.

        The category is what somebody quotes in a bug report; the sentence is
        what they act on. Both, and neither instead of the other.
        """
        output = self.output_of(self.run_sync(mode="attention"))

        self.assertIn("[COMFY_UNREACHABLE]", output)
        self.assertIn("scripts\start.ps1", output)
        self.assertIn("was not converted", output)

    def test_a_folder_that_needed_no_conversion_says_nothing_about_one(self):
        """Both halves, so this is about the condition and not about the run.

        A user with a folder of API exports, or one who asked for -NoConvert,
        must not read a line about a capability they never used. The condition
        the script tests is "are all four counts zero", and a mutation replacing
        it with `$true` prints the block for everybody -- so the zero case has
        to be produced and looked at, not merely described here.

        The fixture check comes first, because the assertion below says nothing
        unless the document really does carry four zeroes.
        """
        quiet_document = self.stub_document(no_convert=True)
        self.assertEqual(
            {"converted": 0, "reused": 0, "failed": 0, "unavailable": 0},
            quiet_document["conversion"]["counts"])
        self.assertIsNone(quiet_document["conversion"]["comfy"])
        for entry in quiet_document["workflows"]:
            self.assertIsNone(entry["conversion"], entry["id"])

        quiet = self.output_of(self.run_sync("-NoConvert"))
        self.assertIn("--no-convert", str(self.engine_arguments()))
        self.assertIn("[ OK ]", quiet)
        self.assertNotIn("Converted by ComfyUI", quiet)
        self.assertNotIn("0 converted", quiet)
        self.assert_no_stack_trace(quiet)

        # The other half: the same script, a document with a non-zero count,
        # and the block is printed. Without this the assertion above would pass
        # for a script that never prints it at all.
        loud_document = self.stub_document()
        self.assertEqual(1, loud_document["conversion"]["counts"]["converted"])
        loud = self.output_of(self.run_sync())
        self.assertIn("Converted by ComfyUI", loud)

    def test_no_convert_reaches_the_engine_and_dry_run_still_can(self):
        """Two switches, and each arrives as its own flag."""
        self.run_sync("-NoConvert", "-DryRun")

        argv = self.engine_arguments()[0]
        self.assertIn("--no-convert", argv)
        self.assertIn("--dry-run", argv)
        self.assertEqual(str(self.runtime_config),
                         argv[argv.index("--runtime-config") + 1])

    def test_regenerate_labels_reaches_the_engine_and_5_1_reaches_nothing(self):
        """-RegenerateLabels arrives as --regenerate-labels, and only when given (T-0116).

        The whole argv is compared, so the flag is neither dropped nor added to
        a run that did not ask. The script decides nothing about the flag: what
        it means is the engine's, which gateway/tests holds.

        RE-AIMED BY T-0294. This ran every case twice, "under both shells
        README.md supports", because a switch the 5.1 host binds differently is
        invisible to pwsh. README supports one shell now, and the switch binding
        is the entry script's own parameter block -- there is no helper under
        this to re-aim at, because sync-workflows.ps1 is a thin front end and
        the flag never leaves it until the engine sees it. So the pass-through
        is measured under pwsh, whole, and the 5.1 case becomes the refusal:
        the engine is not reached at all, which the marker file proves rather
        than the exit code.
        """
        base = ["--config", str(self.sync_config),
                "--runtime-config", str(self.runtime_config)]
        for switches, expected in (
                (("-RegenerateLabels",), base + ["--regenerate-labels"]),
                (("-RegenerateLabels", "-DryRun"),
                 base + ["--dry-run", "--regenerate-labels"]),
                ((), base)):
            with self.subTest(switches=switches):
                if self.sync_marker.exists():
                    self.sync_marker.unlink()
                result = self.run_sync(*switches, shell=PWSH)
                output = self.output_of(result)
                self.assertEqual(0, result.returncode, output)
                self.assertEqual([expected], self.engine_arguments(), output)
                self.assert_no_stack_trace(output)

        if self.sync_marker.exists():
            self.sync_marker.unlink()
        refuse_under_windows_powershell(
            self, SCRIPTS / SYNC_SCRIPT,
            ["-Config", str(self.sync_config), "-RuntimeConfig", str(self.runtime_config),
             "-PythonExe", sys.executable, "-RegenerateLabels", "-DryRun"],
            cwd=REPO,
            # The SAME environment the runs above had, marker and all: a
            # "nothing was recorded" that came from an unset variable would
            # pass whatever the shell did.
            env=self.script_env(LC_STUB_SYNC_MARKER=str(self.sync_marker)),
            what="the -RegenerateLabels pass-through, under 5.1")
        self.assertEqual([], self.engine_arguments(),
                         "the engine was reached by a run 5.1 was supposed to refuse")

    def test_the_script_starts_no_comfyui_and_names_the_one_command_that_does(self):
        """It renders; it does not manage a process.

        Process ownership lives in scripts/lib/Common.ps1 and is used by
        start.ps1 and stop.ps1 only (docs/runtime.md). A second copy of it here
        is the highest-risk code in this repository duplicated, so the script
        must not carry one -- and the sentence a user gets instead has to name
        the command that does.
        """
        text = (SCRIPTS / SYNC_SCRIPT).read_text(encoding="utf-8-sig")
        for forbidden in ("Start-Process", "Save-LcOwnedProcess",
                          "Resolve-LcOwnedProcess", "Stop-LcOwnedProcess",
                          "Stop-Process", "Wait-LcHttpReady"):
            self.assertNotIn(forbidden, text,
                             "sync-workflows.ps1 has grown process management")
        self.assertIn("scripts\start.ps1", text,
                      "the script no longer names the command that starts ComfyUI")

    # -- an older engine's document ----------------------------------------

    def test_the_older_document_this_is_tested_against_really_lacks_the_keys(self):
        """The fixture check that stops the next test being about nothing."""
        legacy = self.stub_document(mode="legacy")
        current = self.stub_document()

        self.assertNotIn("definitions", legacy)
        self.assertNotIn("conversion", legacy)
