    # -- the engine misbehaving --------------------------------------------

    def test_an_engine_that_prints_nothing_usable_fails_without_a_stack_trace(self):
        for mode, expected in (
            ("garbage", "did not print a JSON document"),
            ("silent", "printed nothing"),
            ("crash", "did not complete"),
        ):
            with self.subTest(mode=mode):
                result = self.run_sync(mode=mode)
                output = self.output_of(result)
                self.assertEqual(1, result.returncode, output)
                self.assertIn(expected, output)
