    def test_a_canvas_that_cannot_be_converted_does_not_stop_the_start(self):
        """No browser: said plainly, with the fix, on the previous catalogue.

        No browser is the machine's problem and not the file's, so the next
        start OFFERS it again (T-0350 decision) -- and
        once the browser is there, accepting imports it.
        """
        self.write_workflow("portrait.json", self.api_graph())
        self.establish_catalogue()
        catalogue = self.catalogue_snapshot()
        self.write_workflow("canvas.json", self.editor_graph())
        sources = self.sources_snapshot()
        refusing = self.sync_env(LC_STUB_SYNC_CONVERT="unavailable")
        console = self.copy_scripts_with_a_console("")

        result = self.run_start(script_dir=console, env=refusing)
        output = self.assert_started(result)

        self.assertIn("Workflows: 1 new", output)
        self.assertEqual(1, len(self.sync_invocations()), self.engine_invocations())
        self.assertIn("[BROWSER_NOT_FOUND]", output)
        self.assertIn("Install Google Chrome or Microsoft Edge", output)
        self.assertIn("some of them need a look", output)
        self.assertIn("pwsh .\\scripts\\sync-workflows.ps1   to try them again", output)
        self.assertNotIn("Start LocalCanvas anyway?", output)
        self.assertEqual(catalogue, self.catalogue_snapshot(),
                         "a canvas that could not be converted changed the catalogue")
        self.assertIsNotNone(self.read_pid_file("gateway"))
        self.assertEqual(sources, self.sources_snapshot())

        # The next start, with a browser this time: offered again, and Y
        # imports it through the one importer.
        self.forget_what_start_did()
        again = self.run_start(script_dir=console)
        output = self.assert_started(again)
        self.assertIn("Workflows: 1 not converted last time", output)
        self.assertIn("Sync workflows now? [Y/n]", output)
        self.assertNotIn("need a look", output)
        self.assertEqual(1, len(self.sync_invocations()), self.engine_invocations())
        self.assertEqual(1, self.conversions_invoked(), self.bridge_contacts())
        self.assertIn("canvas.yaml", self.catalogue_snapshot())
        self.assertEqual(sources, self.sources_snapshot())

        # And the start after that has nothing left to say about it.
        self.forget_what_start_did()
        third = self.run_start(script_dir=console)
        output = self.assert_started(third)
        self.assertIn("Workflows: unchanged", output)
        self.assertNotIn("[Y/n]", output)
        self.assertEqual([], self.sync_invocations())

    def forget_what_start_did(self):
        """Clear the two logs, so what is counted next is the next start only."""
        for log in (self.conversions, self.sync_marker):
            if log.exists():
                log.unlink()

