    def test_the_interactivity_gate_is_a_measurement_and_not_a_constant(self):
        """It says yes at a real console and no anywhere else (T-0322).

        A console of the child's own -- the same REAL_CONSOLE condition
        ProbeBoundaryTests uses, and for the same measured reason -- gives the
        child a standard input that is a console handle rather than a pipe,
        which is the one shape in which somebody could be sitting there.

        NOTHING IS PROMPTED HERE. The decision is read out and written to a
        file, so this can never turn into a wait for a keystroke that nobody
        could supply: the console has no window.
        """
        answer = self.workspace / "the interactivity decision.json"
        script = self.workspace / "ask the gate.ps1"
        script.write_text(
            "Set-StrictMode -Version Latest\n"
            "$ErrorActionPreference = 'Stop'\n"
            ". '{library}'\n"
            "$document = [pscustomobject]@{{\n"
            "    Redirected = [Console]::IsInputRedirected\n"
            "    Interactive = [bool](Test-LcInteractiveSession)\n"
            "}}\n"
            "[System.IO.File]::WriteAllText('{answer}', ($document | ConvertTo-Json))\n"
            .format(library=SCRIPTS / "lib" / "Common.ps1", answer=answer),
            encoding="utf-8")
        # Not one handle may be named: naming even stdout would make python
        # fill the other two from this process's own, and the child's standard
        # input would quietly be a pipe again.
        process = subprocess.Popen(
            [PWSH, "-NoProfile", "-NoLogo", "-ExecutionPolicy", "Bypass",
             "-File", str(script)],
            cwd=str(REPO), env=self.script_env(), creationflags=REAL_CONSOLE)
        self.owned_stubs.append(process)
        process.wait(timeout=120)
        self.assertTrue(answer.is_file(), "the driver wrote no answer")
        document = json.loads(answer.read_text(encoding="utf-8"))
        self.assertFalse(document["Redirected"],
                         "the console condition handed the child a pipe after all")
        self.assertTrue(document["Interactive"],
                        "the gate refuses a session that really is a terminal")

        # And the other half, in the condition every other test here runs in.
        result = self.run_powershell("Test-LcInteractiveSession\n")
        self.assertEqual("False", result.stdout.strip(), self.output_of(result))

